window.H=window.H||{};H[33]={"33회-1차-001":{"한줄":"가식중인 수목은 임시로 심어 둔 동산이어서 토지의 정착물이 아니다.","근거":[{"이론":"토지의 정착물","내용":"정착물은 토지에 고정되어 있고 그 고정 상태로 이용되는 것이 거래상 통념인 물건이다. 일시적으로 심거나 놓아 둔 물건은 정착물이 아니라 동산이다."}],"선지":[{"번호":1,"판정":"-","설명":"구거는 인공 수로로 토지와 한 몸을 이루어 토지의 일부로 취급하는 정착물이다."},{"번호":2,"판정":"-","설명":"다년생 식물은 토지에 뿌리를 내려 계속 자라므로 토지의 정착물이다."},{"번호":3,"판정":"-","설명":"가식중인 수목은 옮겨 심을 목적으로 잠시 묻어 둔 것이라 고정성이 없어 동산이다."},{"번호":4,"판정":"-","설명":"교량은 토지에 고정되어 쓰이는 구조물로 정착물이다."},{"번호":5,"판정":"-","설명":"담장은 토지 위에 고정된 구조물로 정착물이다."}],"개념":[{"종류":"표","제목":"토지의 정착물 구분","머리":["구분","내용","예"],"행":[["토지의 일부로 취급","토지와 한 몸으로 보는 정착물","구거, 교량, 담장, 축대, 도로, 다년생 식물"],["독립 정착물","토지와 별개의 부동산으로 거래","건물, 등기·명인방법을 갖춘 입목"],["준부동산","별도 공시방법으로 부동산처럼 취급","자동차·선박·항공기 등 등기·등록 대상 동산"],["정착물이 아닌 것","임시로 설치하거나 심은 물건(동산)","가식중인 수목, 판자 가건물, 이동식 시설"]]}],"함정":"다년생 식물과 가식중인 수목을 모두 나무로 보아 같은 취급을 하는 오답이 많다. 영구히 뿌리내린 것은 정착물이고, 옮겨 심으려고 임시로 묻은 것은 동산이다."},"33회-1차-005":{"한줄":"가격 효과 −2.5%, 교차 효과 +1.5%, 소득 효과 +5e%를 합해 1%가 되려면 소득탄력성은 0.4다.","근거":[{"이론":"탄력성 공식","내용":"가격탄력성 = 수요량 변화율 ÷ 가격 변화율(절댓값), 소득탄력성 = 수요량 변화율 ÷ 소득 변화율, 교차탄력성 = X재 수요량 변화율 ÷ Y재 가격 변화율. 여러 요인이 함께 변하면 각 효과를 더해 전체 수요량 변화율을 구한다."}],"선지":[{"번호":1,"판정":"-","설명":"0.2를 넣으면 소득 효과가 +1%여서 전체가 −2.5+1.5+1 = 0%가 된다."},{"번호":2,"판정":"-","설명":"−2.5 + 1.5 + 5e = 1 → e = 0.4."},{"번호":3,"판정":"-","설명":"0.6을 넣으면 소득 효과 +3%, 전체 +2%가 된다."},{"번호":4,"판정":"-","설명":"0.8을 넣으면 소득 효과 +4%, 전체 +3%가 된다."},{"번호":5,"판정":"-","설명":"1.0을 넣으면 소득 효과 +5%, 전체 +4%가 된다."}],"개념":[{"종류":"계산","제목":"복합 탄력성 문제","단계":[{"설명":"가격 상승에 따른 수요량 변화(가격탄력성 0.5, 가격 5% 상승, 음의 방향)","식":"−0.5 × 5%","값":"−2.5%"},{"설명":"대체재 가격 상승에 따른 수요량 변화(교차탄력성 0.3, 아파트 5% 상승)","식":"+0.3 × 5%","값":"+1.5%"},{"설명":"소득 상승에 따른 수요량 변화(정상재, 소득탄력성 e)","식":"+e × 5%","값":"+5e %"},{"설명":"전체 수요량 변화율 1%","식":"−2.5 + 1.5 + 5e = 1","값":"e = 0.4"}]},{"종류":"표","제목":"탄력성 부호와 재화 성격","머리":["탄력성","부호","의미"],"행":[["소득탄력성","양(+)","정상재(0~1 필수재, 1 초과 사치재)"],["소득탄력성","음(−)","열등재"],["교차탄력성","양(+)","대체재"],["교차탄력성","음(−)","보완재"]]}],"함정":"가격 상승 효과의 부호를 빼먹고 −2.5 대신 +2.5를 더하면 소득 효과가 −3이 되어 답을 못 찾는다. 가격 상승은 수요량을 줄이는 방향이다."},"33회-1차-007":{"한줄":"회복시장은 하향시장에서 바닥을 지나 가격이 오르기 시작하는 단계로, 시장 주도권이 매수자에서 매도자로 넘어간다.","근거":[{"이론":"부동산경기의 국면별 특징","내용":"회복시장에서는 거래가 늘고 가격이 반등하며 매도자 우위로 바뀐다. 상향시장은 가격 상승·거래 증가, 후퇴시장은 정점 이후 하강 전환, 하향시장은 가격 하락·거래 감소·건축허가 감소, 안정시장은 가격 변동이 작다."}],"선지":[{"번호":1,"판정":"틀림","설명":"상향시장은 가격이 지속 상승하고 거래량이 증가한다."},{"번호":2,"판정":"틀림","설명":"경기가 정점에 도달하는 과정은 상향시장이다. 후퇴시장은 정점을 지나 하강으로 돌아서는 국면이다."},{"번호":3,"판정":"틀림","설명":"하향시장에서는 거래 부진으로 건축허가신청이 감소한다."},{"번호":4,"판정":"옳음","설명":"회복시장에서는 매도자 주도로 바뀌는 경향이 있다."},{"번호":5,"판정":"틀림","설명":"안정시장은 가격 변동이 작아 과거 거래가격을 새 거래가격의 신뢰할 만한 기준으로 활용할 수 있다."}],"개념":[{"종류":"표","제목":"부동산경기 국면별 특징","머리":["국면","가격","거래량","시장 주도","기타"],"행":[["회복시장","저점 후 반등","증가 시작","매수자 → 매도자","과거 거래가격이 하한선(저점) 기준"],["상향시장","지속 상승","증가","매도자","과거 거래가격이 하한선, 건축허가 증가"],["후퇴시장","상승세 둔화, 하락 전환","감소 전환","매도자 → 매수자","과거 거래가격이 상한선(고점) 기준"],["하향시장","지속 하락","감소","매수자","건축허가 감소, 과거 거래가격이 상한선"],["안정시장","보합","안정","균형","과거 거래가격을 신뢰할 수 있는 기준으로 활용"]]}],"함정":"후퇴시장과 상향시장을 바꿔 서술한 선지가 자주 출제된다. 정점 도달은 상향, 정점 통과는 후퇴다."},"33회-1차-054":{"한줄":"악의의 점유자는 수취한 과실을 반환하고 소비한 때에는 그 대가를 보상해야 하므로 1번이 옳다.","근거":[{"법령":"민법","조문":"제201조","원문":"제201조(점유자와 과실) ①선의의 점유자는 점유물의 과실을 취득한다. ②악의의 점유자는 수취한 과실을 반환하여야 하며 소비하였거나 과실로 인하여 훼손 또는 수취하지 못한 경우에는 그 과실의 대가를 보상하여야 한다. ③전항의 규정은 폭력 또는 은비에 의한 점유자에 준용한다."},{"법령":"민법","조문":"제202조","원문":"제202조(점유자의 회복자에 대한 책임) 점유물이 점유자의 책임있는 사유로 인하여 멸실 또는 훼손한 때에는 악의의 점유자는 그 손해의 전부를 배상하여야 하며 선의의 점유자는 이익이 현존하는 한도에서 배상하여야 한다. 소유의 의사가 없는 점유자는 선의인 경우에도 손해의 전부를 배상하여야 한다."},{"법령":"민법","조문":"제203조","원문":"제203조(점유자의 상환청구권) ①점유자가 점유물을 반환할 때에는 회복자에 대하여 점유물을 보존하기 위하여 지출한 금액 기타 필요비의 상환을 청구할 수 있다. 그러나 점유자가 과실을 취득한 경우에는 통상의 필요비는 청구하지 못한다. ②점유자가 점유물을 개량하기 위하여 지출한 금액 기타 유익비에 관하여는 그 가액의 증가가 현존한 경우에 한하여 회복자의 선택에 좇아 그 지출금액이나 증가액의 상환을 청구할 수 있다. ③전항의 경우에 법원은 회복자의 청구에 의하여 상당한 상환기간을 허여할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"악의의 점유자는 수취한 과실을 반환하고, 소비하였거나 과실로 훼손·수취하지 못한 경우에는 그 과실의 대가를 보상해야 한다(제201조 제2항)."},{"번호":2,"판정":"틀림","설명":"폭력 또는 은비에 의한 점유자는 악의의 점유자와 같이 취급한다(제201조 제3항). 과실취득권이 없다."},{"번호":3,"판정":"틀림","설명":"선의의 점유자는 이익이 현존하는 한도에서 배상한다(제202조 본문). 전부 배상은 악의 점유자와 소유의 의사가 없는 점유자다."},{"번호":4,"판정":"틀림","설명":"점유자의 비용상환청구는 점유물을 반환할 때 하는 것이다(제203조). 유익비도 가액의 증가가 현존한 경우에 한해 회복자의 선택에 따라 청구한다(제203조 제2항)."},{"번호":5,"판정":"틀림","설명":"통상의 필요비를 청구하지 못하는 점유자는 과실을 취득한 점유자다(제203조 제1항 단서). 악의 점유자는 과실을 취득하지 못하므로 통상의 필요비도 청구할 수 있다."}],"개념":[{"종류":"표","제목":"점유자와 회복자의 관계","머리":["구분","선의 점유자","악의 점유자(폭력·은비 포함)"],"행":[["과실","취득(제201조 제1항)","수취한 과실 반환, 소비 시 대가 보상(제201조 제2항·제3항)"],["멸실·훼손(점유자 책임)","현존이익 배상(자주점유)","손해 전부 배상(제202조)"],["소유의 의사 없는 점유자","선의여도 손해 전부 배상(제202조)","손해 전부 배상(제202조)"],["필요비","과실 취득 시 통상의 필요비 불가, 특별 필요비는 가능","통상 필요비·특별 필요비 모두 가능"],["유익비","가액 증가가 현존한 경우 회복자 선택에 따라 지출액·증가액","같음(제203조 제2항)"]]},{"종류":"표","제목":"점유보호청구권","머리":["청구권","내용","행사기간"],"행":[["점유회수청구(제204조)","침탈된 물건의 반환·손해배상","침탈을 당한 날부터 1년"],["점유보유청구(제205조)","방해 제거·손해배상","방해가 종료한 날부터 1년. 공사 방해는 공사 착수 후 1년 또는 완성 시까지"],["점유보전청구(제206조)","방해 예방·손해배상 담보","방해받을 염려가 있는 동안"],["본권과의 관계","점유의 소와 본권의 소는 서로 영향 없음(제208조)","-"]]}],"함정":"선의 점유자와 악의 점유자의 책임을 뒤바꾸는 오답이 나온다. 선의의 자주점유자는 현존이익만 배상한다. 필요비는 과실을 취득했는지로 갈리지 선악으로 갈리지 않는다."},"33회-1차-057":{"한줄":"합유물에 관한 원인무효 등기의 말소를 구하는 것은 보존행위여서 합유자 각자가 소를 제기할 수 있으므로 4번이 옳다.","근거":[{"법령":"민법","조문":"제263조","원문":"제263조(공유지분의 처분과 공유물의 사용, 수익) 공유자는 그 지분을 처분할 수 있고 공유물 전부를 지분의 비율로 사용, 수익할 수 있다."},{"법령":"민법","조문":"제186조","원문":"제186조(부동산물권변동의 효력) 부동산에 관한 법률행위로 인한 물권의 득실변경은 등기하여야 그 효력이 생긴다."},{"법령":"민법","조문":"제272조","원문":"제272조(합유물의 처분, 변경과 보존) 합유물을 처분 또는 변경함에는 합유자 전원의 동의가 있어야 한다. 그러나 보존행위는 각자가 할 수 있다."},{"법령":"민법","조문":"제273조","원문":"제273조(합유지분의 처분과 합유물의 분할금지) ①합유자는 전원의 동의없이 합유물에 대한 지분을 처분하지 못한다. ②합유자는 합유물의 분할을 청구하지 못한다."},{"법령":"민법","조문":"제276조","원문":"제276조(총유물의 관리, 처분과 사용, 수익) ①총유물의 관리 및 처분은 사원총회의 결의에 의한다. ②각 사원은 정관 기타의 규약에 좇아 총유물을 사용, 수익할 수 있다."},{"판례":"대법원 1997. 9. 9. 선고 96다16896 판결","요지":"합유물에 대해 원인 무효인 소유권이전등기의 말소를 구하는 것은 보존행위이므로 합유자 각자가 단독으로 청구할 수 있다."},{"판례":"대법원 2012. 4. 12. 선고 2011다107900 판결","요지":"종중이 소유 토지의 매매를 중개한 중개업자에게 중개수수료를 지급하기로 약정하는 것은 총유물 자체의 관리·처분이 아니라 채무부담행위여서 사원총회 결의가 없다는 이유로 무효가 되지 않는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"공유자는 자기 지분을 자유롭게 처분할 수 있다(제263조). 공유자끼리 지분을 교환하는 데 다른 공유자의 동의가 필요 없다."},{"번호":2,"판정":"틀림","설명":"공유지분 포기는 법률행위로 인한 물권변동이므로 등기를 해야 효력이 생긴다(제186조)."},{"번호":3,"판정":"틀림","설명":"합유자는 전원의 동의 없이 합유물에 대한 지분을 처분하지 못한다(제273조 제1항)."},{"번호":4,"판정":"옳음","설명":"합유물의 보존행위는 합유자 각자가 할 수 있다(제272조 단서). 원인무효 등기의 말소 청구는 보존행위다(96다16896)."},{"번호":5,"판정":"틀림","설명":"중개수수료 지급 약정은 총유물의 관리·처분이 아니라 채무부담행위다(2011다107900). 총유물의 관리·처분은 사원총회의 결의로 한다(제276조 제1항)."}],"개념":[{"종류":"표","제목":"합유의 규율","머리":["항목","내용","근거"],"행":[["성립","법률 규정 또는 계약으로 수인이 조합체로서 소유","제271조 제1항"],["처분·변경","합유자 전원의 동의","제272조 본문"],["보존행위","합유자 각자","제272조 단서"],["지분 처분","전원의 동의 없이 불가","제273조 제1항"],["분할 청구","불가","제273조 제2항"],["종료","조합체의 해산 또는 합유물의 양도","제274조 제1항"]]},{"종류":"비교","제목":"합유와 총유","왼쪽":{"이름":"합유(제271조~제274조)","항목":["조합체의 소유","지분이 있으나 전원 동의 없이 처분 불가","보존행위는 각자 가능","처분·변경은 전원 동의"]},"오른쪽":{"이름":"총유(제275조~제277조)","항목":["법인 아닌 사단의 소유","관리·처분은 사원총회 결의","각 사원은 규약에 따라 사용·수익","중개수수료 약정 같은 채무부담행위는 총유물 처분이 아님"]}}],"함정":"합유 지분의 처분과 공유 지분의 처분을 뒤섞은 선지가 많다. 공유는 자유, 합유는 전원 동의다. 총유물 처분에 사원총회 결의가 필요하다는 문장 자체는 맞지만 5번의 중개수수료 약정은 처분이 아니다."},"33회-2차-001":{"한줄":"개업공인중개사인 법인의 사원·임원으로서 공인중개사인 자도 소속공인중개사에 해당하므로 4번이 틀렸다.","근거":[{"법령":"공인중개사법","조문":"제2조제5호","원문":"5. \"소속공인중개사\"라 함은 개업공인중개사에 소속된 공인중개사(개업공인중개사인 법인의 사원 또는 임원으로서 공인중개사인 자를 포함한다)로서 중개업무를 수행하거나 개업공인중개사의 중개업무를 보조하는 자를 말한다."},{"법령":"공인중개사법","조문":"제2조제6호","원문":"6. \"중개보조원\"이라 함은 공인중개사가 아닌 자로서 개업공인중개사에 소속되어 중개대상물에 대한 현장안내 및 일반서무 등 개업공인중개사의 중개업무와 관련된 단순한 업무를 보조하는 자를 말한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"중개의 정의다(법 제2조제1호)."},{"번호":2,"판정":"옳음","설명":"개업공인중개사는 개설등록을 한 자다(법 제2조제4호)."},{"번호":3,"판정":"옳음","설명":"중개업은 타인의 의뢰, 보수, 업을 요소로 한다(법 제2조제3호)."},{"번호":4,"판정":"틀림","설명":"법인의 사원·임원인 공인중개사는 소속공인중개사에 포함된다(법 제2조제5호 괄호)."},{"번호":5,"판정":"옳음","설명":"중개보조원은 공인중개사가 아닌 자로서 현장안내·일반서무 같은 단순 업무를 보조하는 사람이다(법 제2조제6호). 자격자가 단순 보조만 해도 소속공인중개사다."}],"개념":[{"종류":"비교","제목":"소속공인중개사와 중개보조원","왼쪽":{"이름":"소속공인중개사","항목":["공인중개사 자격 있음","중개업무를 수행하거나 보조(법 제2조제5호)","중개행위에 쓸 인장을 등록관청에 등록(법 제16조제1항)","해당 중개행위에 대해 확인·설명서와 거래계약서에 서명 및 날인(법 제25조제4항, 제26조제2항)","고용 신고일 전 1년 이내 실무교육(법 제34조제2항)"]},"오른쪽":{"이름":"중개보조원","항목":["자격 없음","현장안내·일반서무 등 단순 업무만 보조(법 제2조제6호)","인장등록 의무 없음","서명 및 날인 의무 없음","고용 신고일 전 1년 이내 직무교육(법 제34조제3항), 3시간 이상 4시간 이하(영 제28조제2항)"]}},{"종류":"표","제목":"중개보조원에 대한 규율","머리":["사항","내용","근거·제재"],"행":[["고용 인원","개업공인중개사와 소속공인중개사를 합한 수의 5배 초과 금지","법 제15조제3항. 위반 시 등록취소(법 제38조제1항제5호의2), 1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제5호의2)"],["신분 고지","현장안내 등을 할 때 중개의뢰인에게 중개보조원임을 미리 알려야 함","법 제18조의4. 위반 시 500만원 이하 과태료(법 제51조제2항제1호의4)"],["표시·광고","중개보조원에 관한 사항은 명시 금지","법 제18조의2제1항"],["행위의 귀속","소속공인중개사·중개보조원의 업무상 행위는 고용한 개업공인중개사의 행위로 봄","법 제15조제2항"],["결격사유","법 제10조제1항제1호~제11호 해당자는 소속공인중개사·중개보조원이 될 수 없음","법 제10조제2항"]]}],"함정":"법인의 임원·사원인 공인중개사를 \"개업공인중개사도 소속공인중개사도 아닌 사람\"으로 처리하면 4번을 옳다고 읽게 된다. 이 구조는 기출에서 반복해 나온다."},"33회-2차-024":{"한줄":"생태ㆍ경관보전지역은 군사기지 등 제1호 구역이 아니므로 허가 또는 불허가 처분 기간은 15일이다(영 제6조제3항제2호).","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제6조제3항","원문":"③ 제1항에 따른 신청서를 받은 신고관청은 신청서를 받은 날부터 다음 각 호의 구분에 따른 기간 안에 허가 또는 불허가 처분을 해야 한다. … 1. 법 제9조제1항제1호에 따른 구역ㆍ지역의 경우: 30일 2. 제1호 외의 구역ㆍ지역의 경우: 15일"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제9조제1항ㆍ제3항","원문":"① … 다만, 제11조에 따라 토지거래계약에 관한 허가를 받은 경우에는 그러하지 아니하다. … 3. 「자연환경보전법」 제2조제12호에 따른 생태ㆍ경관보전지역 ③ 제1항을 위반하여 체결한 토지취득계약은 그 효력이 발생하지 아니한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제8조제2항ㆍ제3항","원문":"② 외국인등이 상속ㆍ경매, 그 밖에 대통령령으로 정하는 계약 외의 원인으로 대한민국 안의 부동산등을 취득한 때에는 부동산등을 취득한 날부터 6개월 이내에 대통령령으로 정하는 바에 따라 신고관청에 신고하여야 한다. ③ 대한민국 안의 부동산등을 가지고 있는 대한민국국민이나 … 외국인등으로 변경된 경우 그 외국인등이 해당 부동산등을 계속보유하려는 경우에는 외국인등으로 변경된 날부터 6개월 이내에 … 신고관청에 신고하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제5조제2항제4호","원문":"4. 건축물의 신축ㆍ증축ㆍ개축ㆍ재축"}],"선지":[{"번호":1,"판정":"틀림","설명":"허가를 받지 않고 체결한 토지취득계약은 효력이 발생하지 않는다(법 제9조제3항)."},{"번호":2,"판정":"틀림","설명":"건축물 신축은 계약 외의 원인이다. 취득한 날부터 6개월 이내에 신고하며 허가 대상이 아니다(법 제8조제2항, 영 제5조제2항제4호)."},{"번호":3,"판정":"틀림","설명":"토지거래계약허가를 받으면 토지취득허가는 받지 않아도 된다(법 제9조제1항 단서)."},{"번호":4,"판정":"틀림","설명":"국민이 외국인으로 변경된 후 계속 보유하려면 6개월 이내에 신고한다. 허가가 아니다(법 제8조제3항)."},{"번호":5,"판정":"옳음","설명":"제1호 구역(군사기지 등)이 아닌 생태ㆍ경관보전지역은 15일이다(영 제6조제3항제2호)."}],"개념":[{"종류":"표","제목":"외국인등의 부동산 취득ㆍ보유 신고와 허가","머리":["구분","기한 또는 시기","위반 시","근거"],"행":[["계약으로 취득","계약 체결일부터 60일 이내 신고","300만원 이하 과태료","법 제8조제1항, 제28조제4항"],["계약 외 원인으로 취득(상속, 경매, 환매권 행사, 확정판결, 법인 합병, 신축 등)","취득한 날부터 6개월 이내 신고","100만원 이하 과태료","법 제8조제2항, 영 제5조제2항, 법 제28조제5항"],["국민이 외국인으로 변경되어 계속 보유","변경된 날부터 6개월 이내 신고","100만원 이하 과태료","법 제8조제3항, 제28조제5항"],["허가구역에서 토지 취득","계약 체결 전에 허가","무효, 2년 이하 징역 또는 2천만원 이하 벌금","법 제9조, 제26조제2항"]]},{"종류":"표","제목":"외국인 토지취득허가 구역 (법 제9조제1항)","머리":["호","구역","처리기간"],"행":[["1","군사기지 및 군사시설 보호구역, 국방목적상 제한이 필요한 지역(섬, 군부대주둔지와 인근, 국가중요시설과 인근 등)","30일 (부득이하면 30일 범위에서 연장)"],["2","지정문화유산과 보호물 또는 보호구역","15일"],["2의2","천연기념물등과 보호물 또는 보호구역","15일"],["3","생태ㆍ경관보전지역","15일"],["4","야생생물 특별보호구역","15일"]]}],"함정":"「허가」와 「신고」를 섞은 선지가 셋(2번, 4번)이고, 허가구역에서는 토지거래계약허가를 받으면 취득허가를 따로 받지 않는다는 단서를 빠뜨리면 3번을 고르게 된다. 처리기간은 구역에 따라 30일과 15일로 나뉜다.","개정":"2023.10.4 시행령 개정으로 외국인 토지취득허가 처리기간이 군사기지 등 제1호 구역은 30일, 그 밖의 구역은 15일로 나뉘었다(영 제6조제3항). 이전에는 일률 15일이었다. 선지 3의 법령명은 「문화재보호법」에서 「문화유산의 보존 및 활용에 관한 법률」로 바뀌었다(법 제9조제1항제2호)."},"33회-2차-026":{"한줄":"허가구역 지정의 효력은 공고한 날부터 5일 후에 발생한다(법 제10조제5항).","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"제10조제5항","원문":"⑤ 허가구역의 지정은 제3항에 따라 허가구역의 지정을 공고한 날부터 5일 후에 그 효력이 발생한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제15조제1항","원문":"시장ㆍ군수 또는 구청장은 제11조제1항에 따른 토지거래계약에 관한 허가신청이 있는 경우 다음 각 호의 어느 하나에 해당하는 토지에 대하여 국가, 지방자치단체, 한국토지주택공사, 그 밖에 대통령령으로 정하는 공공기관 또는 공공단체가 그 매수를 원하는 경우에는 이들 중에서 해당 토지를 매수할 자[이하 \"선매자(先買者)\"라 한다]를 지정하여 그 토지를 협의 매수하게 할 수 있다. 1. 공익사업용 토지"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제16조제1항","원문":"제11조제1항에 따른 허가신청에 대하여 불허가처분을 받은 자는 그 통지를 받은 날부터 1개월 이내에 시장ㆍ군수 또는 구청장에게 해당 토지에 관한 권리의 매수를 청구할 수 있다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제10조제6항 / 제11조제3항","원문":"⑥ 국토교통부장관 또는 시ㆍ도지사는 허가구역의 지정 사유가 없어졌다고 인정되거나 … 지체 없이 허가구역의 지정을 해제하거나 지정된 허가구역의 일부를 축소하여야 한다. / 제11조제3항 허가를 받으려는 자는 그 허가신청서에 계약내용과 그 토지의 이용계획, 취득자금 조달계획 등을 적어 시장ㆍ군수 또는 구청장에게 제출하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"공익사업용 토지는 선매 대상이고 한국토지주택공사도 선매자가 될 수 있다(법 제15조제1항)."},{"번호":2,"판정":"옳음","설명":"지정 사유가 없어졌다고 인정되면 지체 없이 해제한다(법 제10조제6항)."},{"번호":3,"판정":"옳음","설명":"불허가 통지를 받은 날부터 1개월 이내에 매수를 청구할 수 있다(법 제16조제1항)."},{"번호":4,"판정":"틀림","설명":"효력은 공고한 날의 다음 날이 아니라 공고한 날부터 5일 후다(법 제10조제5항)."},{"번호":5,"판정":"옳음","설명":"허가신청서에 계약내용, 이용계획, 취득자금 조달계획을 적어 제출한다(법 제11조제3항)."}],"개념":[{"종류":"표","제목":"토지거래허가 후속 제도의 기간","머리":["제도","기간","근거"],"행":[["선매자 지정","허가신청이 있는 날부터 1개월 이내 지정ㆍ통지","법 제15조제2항"],["선매협의","선매자가 지정 통지를 받은 날부터 1개월 이내 종결","법 제15조제2항"],["매수청구","불허가 통지를 받은 날부터 1개월 이내","법 제16조제1항"],["이의신청","처분을 받은 날부터 1개월 이내","법 제13조제1항"],["선매협의 불성립","지체 없이 허가 또는 불허가 결정ㆍ통보","법 제15조제4항"]]},{"종류":"비교","제목":"선매와 불허가 토지 매수청구","왼쪽":{"이름":"선매 (법 제15조)","항목":["허가신청이 있을 때 시장ㆍ군수ㆍ구청장이 선매자를 지정","대상: 공익사업용 토지, 허가받아 취득했으나 이용목적대로 이용하지 않는 토지","선매가격: 감정가격 기준. 신청서 가격이 더 낮으면 그 가격 가능","선매협의가 안 되면 허가 또는 불허가 결정"]},"오른쪽":{"이름":"매수청구 (법 제16조)","항목":["불허가처분을 받은 자가 청구","청구기한: 통지를 받은 날부터 1개월","시장ㆍ군수ㆍ구청장이 매수할 자를 지정","매수가격: 공시지가 기준. 신청서 가격이 더 낮으면 그 가격"]}}],"함정":"효력 발생 시점을 「다음 날」로 바꾼 선지다. 지정 효력은 공고일부터 5일 후이고, 선매와 매수청구에 나오는 1개월 기간과 섞이지 않게 한다."},"33회-2차-007":{"한줄":"변경허가 없이 토지거래계약을 체결한 자는 법 제26조제3항에 따라 2년 이하 징역 또는 토지가격 100분의 30 이하 벌금이다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"제26조제3항","원문":"③ 제11조제1항에 따른 허가 또는 변경허가를 받지 아니하고 토지거래계약을 체결하거나, 속임수나 그 밖의 부정한 방법으로 토지거래계약 허가를 받은 자는 2년 이하의 징역 또는 계약 체결 당시의 개별공시지가에 따른 해당 토지가격의 100분의 30에 해당하는 금액 이하의 벌금에 처한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제28조제1항제3호","원문":"① 다음 각 호의 어느 하나에 해당하는 자에게는 3천만원 이하의 과태료를 부과한다. … 3. 제6조를 위반하여 거래대금 지급을 증명할 수 있는 자료를 제출하지 아니하거나 거짓으로 제출한 자 또는 그 밖의 필요한 조치를 이행하지 아니한 자"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제28조제2항제2호ㆍ제5항제1호","원문":"② … 2. 제4조제1호를 위반하여 개업공인중개사에게 제3조에 따른 신고를 하지 아니하게 하거나 거짓으로 신고하도록 요구한 자 / ⑤ 다음 각 호의 어느 하나에 해당하는 자에게는 100만원 이하의 과태료를 부과한다. 1. 제8조제2항에 따른 취득의 신고를 하지 아니하거나 거짓으로 신고한 자"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제26조제1항","원문":"① 부당하게 재물이나 재산상 이득을 취득하거나 제3자로 하여금 이를 취득하게 할 목적으로 제4조제4호 또는 제5호를 위반하여 거짓으로 제3조 또는 제3조의2에 따라 신고한 자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다."}],"선지":[{"번호":1,"판정":"-","설명":"3천만원 이하 과태료 대상이다(법 제28조제1항제3호)."},{"번호":2,"판정":"-","설명":"법 제26조제3항 대상이다. 허가 없이 계약한 경우와 변경허가 없이 계약한 경우가 같은 항에 있다."},{"번호":3,"판정":"-","설명":"경매 취득은 계약 외의 원인이므로 법 제8조제2항 신고 대상이고, 위반하면 100만원 이하 과태료다(법 제28조제5항제1호)."},{"번호":4,"판정":"-","설명":"법 제4조제1호 위반이며 500만원 이하 과태료다(법 제28조제2항제2호)."},{"번호":5,"판정":"-","설명":"법 제4조제4호 위반이며 3천만원 이하 과태료다(법 제28조제1항제1호). 부당 이득을 얻을 목적이 있으면 법 제26조제1항의 3년 이하 징역 또는 3천만원 이하 벌금이다."}],"개념":[{"종류":"표","제목":"거래신고법 벌칙 (법 제26조)","머리":["항","위반행위","벌칙"],"행":[["제1항","부당 이득 목적으로 제4조제4호ㆍ제5호 위반, 거짓 신고","3년 이하 징역 또는 3천만원 이하 벌금"],["제2항","외국인등이 토지취득허가 없이 계약하거나 부정한 방법으로 허가를 받아 계약","2년 이하 징역 또는 2천만원 이하 벌금"],["제3항","토지거래허가ㆍ변경허가 없이 계약하거나 부정한 방법으로 허가받음","2년 이하 징역 또는 계약 체결 당시 개별공시지가에 따른 토지가격의 100분의 30 이하 벌금"],["제4항","제21조에 따른 허가 취소, 처분 또는 조치명령 위반","1년 이하 징역 또는 1천만원 이하 벌금"]]},{"종류":"표","제목":"거래신고법 과태료 (법 제28조)","머리":["항","대상","금액"],"행":[["제1항","거짓 신고(제4조제4호ㆍ제5호), 거래대금 지급 증명자료 미제출ㆍ거짓 제출","3천만원 이하"],["제2항","신고 미이행(공동신고 거부 포함), 개업공인중개사에 대한 신고 방해 요구 등, 지급 증명자료 외 자료 미제출","500만원 이하"],["제3항","신고를 거짓으로 한 자(제3조제1항~제4항 또는 제4조제2호 위반)","취득가액의 100분의 10 이하"],["제4항","외국인등 계약 취득 신고 미이행ㆍ거짓","300만원 이하"],["제5항","계약 외 취득 신고, 계속보유 신고 미이행ㆍ거짓, 주택 임대차 신고 미이행ㆍ거짓","100만원 이하"]]}],"함정":"과태료와 벌금을 섞어 외우면 안 된다. 허가 없이 토지거래계약을 체결하는 것(제26조제3항)만 징역이 붙고, 신고 의무 위반은 과태료다. 거짓 신고는 이득 목적 여부에 따라 벌금(제26조제1항)과 과태료(제28조제1항)로 갈린다."},"33회-2차-043":{"한줄":"생산녹지지역은 성장관리계획구역에서 건폐율을 30퍼센트 이하 범위까지 완화할 수 있는 녹지지역이다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제75조의3제2항","원문":"성장관리계획구역에서는 제77조제1항에도 불구하고 다음 각 호의 구분에 따른 범위에서 성장관리계획으로 정하는 바에 따라 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 조례로 정하는 비율까지 건폐율을 완화하여 적용할 수 있다. 1. 계획관리지역: 50퍼센트 이하 2. 생산관리지역ㆍ농림지역 및 대통령령으로 정하는 녹지지역: 30퍼센트 이하"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제70조의14제2항","원문":"법 제75조의3제2항제2호에서 \"대통령령으로 정하는 녹지지역\"이란 자연녹지지역과 생산녹지지역을 말한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제75조의3제3항","원문":"성장관리계획구역 내 계획관리지역에서는 제78조제1항에도 불구하고 125퍼센트 이하의 범위에서 성장관리계획으로 정하는 바에 따라 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 조례로 정하는 비율까지 용적률을 완화하여 적용할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제75조의2제1항","원문":"특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 녹지지역, 관리지역, 농림지역 및 자연환경보전지역 중 다음 각 호의 어느 하나에 해당하는 지역의 전부 또는 일부에 대하여 성장관리계획구역을 지정할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제75조의2제2항","원문":"특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 성장관리계획구역을 지정하거나 이를 변경하려면 대통령령으로 정하는 바에 따라 미리 주민과 해당 지방의회의 의견을 들어야 하며, 관계 행정기관과의 협의 및 지방도시계획위원회의 심의를 거쳐야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제70조의13제2항","원문":"특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 제1항에 따른 공고를 한 때에는 성장관리계획구역안을 14일 이상 일반이 열람할 수 있도록 해야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"성장관리계획구역은 녹지지역, 관리지역, 농림지역, 자연환경보전지역에서 지정한다. 공업지역은 포함되지 않는다(법 제75조의2제1항)."},{"번호":2,"판정":"옳음","설명":"생산녹지지역은 영이 정한 녹지지역(자연녹지ㆍ생산녹지)에 해당해 30퍼센트 이하 범위로 건폐율을 완화할 수 있다(법 제75조의3제2항제2호, 영 제70조의14제2항)."},{"번호":3,"판정":"틀림","설명":"용적률 125퍼센트 이하 완화는 계획관리지역에서만 가능하다. 보전관리지역은 해당하지 않는다(법 제75조의3제3항)."},{"번호":4,"판정":"틀림","설명":"성장관리계획구역은 주민ㆍ지방의회 의견 청취, 관계 행정기관 협의, 지방도시계획위원회 심의를 거쳐 지정ㆍ고시한다. 도시ㆍ군관리계획의 결정이 아니다(법 제75조의2제2항ㆍ제5항)."},{"번호":5,"판정":"틀림","설명":"열람 기간은 14일 이상이다(영 제70조의13제2항)."}],"개념":[{"종류":"표","제목":"성장관리계획구역의 완화(법 제75조의3)","머리":["용도지역","건폐율 완화(이하)","용적률 완화(이하)"],"행":[["계획관리지역","50퍼센트","125퍼센트"],["생산관리지역","30퍼센트","-"],["농림지역","30퍼센트","-"],["자연녹지지역ㆍ생산녹지지역","30퍼센트","-"],["보전관리지역ㆍ보전녹지지역 등","완화 없음","완화 없음"]]},{"종류":"흐름","제목":"성장관리계획구역 지정ㆍ계획 수립 절차","단계":[{"이름":"지정 대상 확인","설명":"녹지지역, 관리지역, 농림지역, 자연환경보전지역 중 개발수요가 많아 무질서한 개발이 진행ㆍ예상되는 지역 등(법 제75조의2제1항)"},{"이름":"주민ㆍ지방의회 의견","설명":"주민에게 공고하고 14일 이상 열람(영 제70조의13제2항), 지방의회는 60일 이내 의견 제시(법 제75조의2제3항)"},{"이름":"협의ㆍ심의","설명":"관계 행정기관 협의(30일 이내 의견 제시, 제4항), 지방도시계획위원회 심의"},{"이름":"고시ㆍ열람","설명":"관계 행정기관에 서류 송부, 고시하고 일반 열람(제5항)"},{"이름":"성장관리계획 수립","설명":"기반시설 배치, 건축물 용도ㆍ건폐율ㆍ용적률, 배치ㆍ형태ㆍ색채ㆍ높이, 환경ㆍ경관계획 등(법 제75조의3제1항). 절차는 구역 지정 절차 준용"},{"이름":"재검토","설명":"5년마다 타당성 전반 재검토(법 제75조의3제5항)"}]}],"함정":"선지 3은 용적률 완화가 계획관리지역에만 있다는 점을 놓치게 한다. 선지 2의 ‘생산녹지’는 영 제70조의14제2항이 정한 녹지지역이어서 건폐율 완화가 된다. 선지 4(결정 형식)와 선지 5(7일)는 절차의 형식과 숫자를 바꿔 놓았다."},"33회-2차-059":{"한줄":"시ㆍ도지사와 시장ㆍ군수ㆍ구청장이 인수할 수 없으면 시ㆍ도지사가 국토교통부장관에게 인수자 지정을 요청하며, 한국토지주택공사가 바로 인수하는 규정은 없다.","근거":[{"법령":"도시 및 주거환경정비법 시행령","조문":"제48조제2항","원문":"② 사업시행자가 제1항에 따라 선정된 국민주택규모 주택을 공급하는 경우에는 시ㆍ도지사, 시장ㆍ군수ㆍ구청장 순으로 우선하여 인수할 수 있다. 다만, 시ㆍ도지사 및 시장ㆍ군수ㆍ구청장이 국민주택규모 주택을 인수할 수 없는 경우에는 시ㆍ도지사는 국토교통부장관에게 인수자 지정을 요청해야 한다."},{"법령":"도시 및 주거환경정비법 시행령","조문":"제48조제3항","원문":"③ 국토교통부장관은 제2항 단서에 따라 시ㆍ도지사로부터 인수자 지정 요청이 있는 경우에는 30일 이내에 인수자를 지정하여 시ㆍ도지사에게 통보해야 하며, 시ㆍ도지사는 지체 없이 이를 시장ㆍ군수ㆍ구청장에게 보내어 그 인수자와 국민주택규모 주택의 공급에 관하여 협의하도록 해야 한다."},{"법령":"도시 및 주거환경정비법 시행령","조문":"제48조제1항","원문":"① 사업시행자는 법 제54조제4항에 따라 건설한 국민주택규모 주택 중 법 제55조제1항에 따라 국토교통부장관, 시ㆍ도지사, 시장ㆍ군수ㆍ구청장 또는 토지주택공사등(이하 \"인수자\"라 한다)에 공급해야 하는 국민주택규모 주택을 공개추첨의 방법으로 선정해야 하며, 그 선정결과를 지체 없이 같은 항에 따른 인수자에게 통보해야 한다."},{"법령":"도시 및 주거환경정비법","조문":"제55조제1항","원문":"① 사업시행자는 제54조제4항에 따라 건설한 국민주택규모 주택을 국토교통부장관, 시ㆍ도지사, 시장, 군수, 구청장 또는 토지주택공사등(이하 \"인수자\"라 한다)에 공급하여야 한다."},{"법령":"도시 및 주거환경정비법","조문":"제55조제2항","원문":"② 제1항에 따른 국민주택규모 주택의 공급가격은 「공공주택 특별법」 제50조의4에 따라 국토교통부장관이 고시하는 공공건설임대주택의 표준건축비로 하며, 부속 토지는 인수자에게 기부채납한 것으로 본다."}],"선지":[{"번호":1,"판정":"옳음","설명":"건설한 국민주택규모 주택의 공급 상대방(인수자)은 국토교통부장관, 시ㆍ도지사, 시장, 군수, 구청장 또는 토지주택공사등이다(법 제55조제1항)."},{"번호":2,"판정":"옳음","설명":"인수자에게 공급할 주택은 공개추첨으로 선정하고 결과를 지체 없이 인수자에게 통보한다(영 제48조제1항)."},{"번호":3,"판정":"옳음","설명":"선정된 주택은 시ㆍ도지사, 시장ㆍ군수ㆍ구청장 순으로 우선 인수할 수 있다(영 제48조제2항 본문)."},{"번호":4,"판정":"옳음","설명":"공급가격은 표준건축비로 하고 부속 토지는 인수자에게 기부채납한 것으로 본다(법 제55조제2항)."},{"번호":5,"판정":"틀림","설명":"시ㆍ도지사 및 시장ㆍ군수ㆍ구청장이 인수할 수 없으면 시ㆍ도지사가 국토교통부장관에게 인수자 지정을 요청하고, 국토교통부장관이 30일 이내에 인수자를 지정한다(영 제48조제2항 단서ㆍ제3항)."}],"개념":[{"종류":"흐름","제목":"국민주택규모 주택의 공급ㆍ인수 절차","단계":[{"이름":"건설","설명":"용적률을 정비계획 이상으로 완화받은 사업시행자가 초과용적률의 일정 비율 면적에 국민주택규모 주택을 건설한다(법 제54조제4항)."},{"이름":"인수자 협의","설명":"정비계획상 용적률을 초과하려면 사업시행계획인가 신청 전에 인수자와 협의해 사업시행계획서에 반영한다(법 제55조제3항)."},{"이름":"인수 주택 선정","설명":"공급할 주택을 공개추첨으로 정하고 결과를 지체 없이 인수자에게 통보한다(영 제48조제1항)."},{"이름":"우선 인수","설명":"시ㆍ도지사, 시장ㆍ군수ㆍ구청장 순으로 우선하여 인수할 수 있다(영 제48조제2항 본문)."},{"이름":"인수 불가 시","설명":"시ㆍ도지사가 국토교통부장관에게 인수자 지정을 요청한다(영 제48조제2항 단서)."},{"이름":"인수자 지정","설명":"국토교통부장관이 요청받은 날부터 30일 이내에 지정해 통보하고, 시ㆍ도지사는 지체 없이 시장ㆍ군수ㆍ구청장에게 보내 협의하게 한다(영 제48조제3항)."}]},{"종류":"표","제목":"국민주택규모 주택 건설비율ㆍ공급 조건","머리":["구분","내용","근거"],"행":[["과밀억제권역 재건축사업","초과용적률의 100분의 30 이상 100분의 50 이하, 시ㆍ도조례로 정하는 비율","법 제54조제4항제1호"],["과밀억제권역 재개발사업","초과용적률의 100분의 50 이상 100분의 75 이하, 시ㆍ도조례로 정하는 비율","법 제54조제4항제2호"],["그 밖의 지역 재건축사업","초과용적률의 100분의 50 이하, 시ㆍ도조례로 정하는 비율","법 제54조제4항제3호"],["그 밖의 지역 재개발사업","초과용적률의 100분의 75 이하, 시ㆍ도조례로 정하는 비율","법 제54조제4항제4호"],["공급가격","공공건설임대주택 표준건축비","법 제55조제2항"],["부속 토지","인수자에게 기부채납한 것으로 봄","법 제55조제2항"],["인수 후 활용","임대의무기간 20년 이상의 장기공공임대주택","영 제48조제4항"]]}],"함정":"선지 5는 한국토지주택공사가 최종 인수자로 지정된다는 흐름이 그럴듯해서 고르기 쉽다. 규정은 시ㆍ도지사가 국토교통부장관에게 지정을 요청하는 절차이고, 인수자 범위(법 제55조제1항)에 토지주택공사등이 들어 있는 것과는 별개다. 선지 3은 시ㆍ도지사가 먼저라는 순서가 맞다."},"33회-2차-072":{"한줄":"안전영향평가기관의 검토 항목 중 마지막은 국토교통부장관이 필요하다고 인정하는 사항이며, 지방건축위원회가 결정하는 사항은 없다.","근거":[{"법령":"건축법 시행령","조문":"제10조의3제3항","원문":"③ 법 제13조의2제1항에 따라 허가권자로부터 안전영향평가를 의뢰받은 기관(같은 조 제2항에 따라 지정ㆍ고시된 기관을 말하며, 이하 \"안전영향평가기관\"이라 한다)은 다음 각 호의 항목을 검토하여야 한다. 1. 해당 건축물에 적용된 설계 기준 및 하중의 적정성 2. 해당 건축물의 하중저항시스템의 해석 및 설계의 적정성 3. 지반조사 방법 및 지내력(地耐力) 산정결과의 적정성 4. 굴착공사에 따른 지하수위 변화 및 지반 안전성에 관한 사항 5. 그 밖에 건축물의 안전영향평가를 위하여 국토교통부장관이 필요하다고 인정하는 사항"},{"법령":"건축법 시행령","조문":"제10조의3제1항","원문":"① 법 제13조의2제1항에서 \"초고층 건축물 등 대통령령으로 정하는 주요 건축물\"이란 다음 각 호의 어느 하나에 해당하는 건축물을 말한다. 1. 초고층 건축물 2. 다음 각 목의 요건을 모두 충족하는 건축물 가. 연면적(하나의 대지에 둘 이상의 건축물을 건축하는 경우에는 각각의 건축물의 연면적을 말한다)이 10만 제곱미터 이상일 것 나. 16층 이상일 것"},{"법령":"건축법","조문":"제13조의2제1항","원문":"① 허가권자는 초고층 건축물 등 대통령령으로 정하는 주요 건축물에 대하여 제11조에 따른 건축허가를 하기 전에 건축물의 구조, 지반 및 풍환경(風環境) 등이 건축물의 구조안전과 인접 대지의 안전에 미치는 영향 등을 평가하는 건축물 안전영향평가(이하 \"안전영향평가\"라 한다)를 안전영향평가기관에 의뢰하여 실시하여야 한다."}],"선지":[{"번호":1,"판정":"-","설명":"검토 항목이다. 설계 기준 및 하중의 적정성(영 제10조의3제3항제1호)."},{"번호":2,"판정":"-","설명":"검토 항목이다. 하중저항시스템의 해석 및 설계의 적정성(영 제10조의3제3항제2호)."},{"번호":3,"판정":"-","설명":"검토 항목이다. 지반조사 방법 및 지내력 산정결과의 적정성(영 제10조의3제3항제3호)."},{"번호":4,"판정":"-","설명":"검토 항목이다. 굴착공사에 따른 지하수위 변화 및 지반 안전성(영 제10조의3제3항제4호)."},{"번호":5,"판정":"-","설명":"검토 항목이 아니다. 마지막 항목은 국토교통부장관이 필요하다고 인정하는 사항이다(영 제10조의3제3항제5호)."}],"개념":[{"종류":"흐름","제목":"건축물 안전영향평가 절차","단계":[{"이름":"의뢰","설명":"대상 건축물의 건축주가 건축허가 신청 전에 건축계획서ㆍ기본설계도서 등을 첨부해 허가권자에게 안전영향평가를 의뢰한다(영 제10조의3제2항)."},{"이름":"평가기관 의뢰","설명":"허가권자가 건축허가 전에 안전영향평가기관에 의뢰한다. 평가기관은 국토교통부장관이 공공기관 중에서 지정ㆍ고시한다(법 제13조의2제1항ㆍ제2항)."},{"이름":"검토","설명":"설계 기준ㆍ하중, 하중저항시스템, 지반조사ㆍ지내력, 굴착공사 지하수위ㆍ지반 안전성, 국토교통부장관이 필요하다고 인정하는 사항을 검토한다(영 제10조의3제3항)."},{"이름":"결과 제출","설명":"의뢰받은 날부터 30일 이내에 허가권자에게 제출한다. 부득이하면 20일 범위에서 한 차례 연장한다. 보완 기간과 공휴일ㆍ토요일은 기간에서 뺀다(영 제10조의3제4항ㆍ제5항)."},{"이름":"확정","설명":"건축위원회의 심의를 거쳐 확정한다(법 제13조의2제3항)."},{"이름":"반영ㆍ공개","설명":"건축주는 허가신청 도서에 결과를 반영하고, 곤란하면 근거를 첨부해 재심의를 요청할 수 있다. 허가권자는 심의 결과와 평가 내용을 즉시 공개한다(법 제13조의2제4항ㆍ제6항)."}]},{"종류":"표","제목":"안전영향평가 대상 건축물(영 제10조의3제1항)","머리":["구분","요건"],"행":[["1호","초고층 건축물"],["2호","연면적(하나의 대지에 둘 이상을 건축하면 각각의 연면적)이 10만 제곱미터 이상이고 16층 이상일 것(두 요건 모두)"],["비용","안전영향평가를 의뢰한 자가 부담(영 제10조의3제7항)"]]}],"함정":"선지 5는 위원회를 끌어와 그럴듯하게 만들었다. 건축위원회는 평가 결과를 심의해 확정하는 기관이고(법 제13조의2제3항), 평가기관의 검토 항목을 정하는 기관이 아니다. 다섯 번째 항목은 국토교통부장관이 정한다."},"33회-2차-066":{"한줄":"주택상환사채권에는 발행 기관, 발행 금액, 발행 조건, 상환의 시기와 절차를 적는다.","근거":[{"법령":"주택법 시행규칙","조문":"제33조제1항","원문":"① 영 제83조제2항에서 \"국토교통부령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다. 1. 발행 기관 2. 발행 금액 3. 발행 조건 4. 상환의 시기와 절차"},{"법령":"주택법 시행령","조문":"제84조제1항","원문":"① 법 제80조제1항 후단에서 \"대통령령으로 정하는 기준\"이란 다음 각 호의 기준 모두를 말한다. 1. 법인으로서 자본금이 5억원 이상일 것 2. 「건설산업기본법」 제9조에 따라 건설업 등록을 한 자일 것 3. 최근 3년간 연평균 주택건설 실적이 300호 이상일 것"},{"법령":"주택법","조문":"제80조제2항","원문":"② 주택상환사채를 발행하려는 자는 대통령령으로 정하는 바에 따라 주택상환사채발행계획을 수립하여 국토교통부장관의 승인을 받아야 한다."},{"법령":"주택법 시행령","조문":"제83조제1항","원문":"① 법 제80조제1항에 따른 주택상환사채(이하 \"주택상환사채\"라 한다)는 액면 또는 할인의 방법으로 발행한다."},{"법령":"주택법","조문":"제81조제2항","원문":"② 주택상환사채는 기명증권(記名證券)으로 하고, 사채권자의 명의변경은 취득자의 성명과 주소를 사채원부에 기록하는 방법으로 하며, 취득자의 성명을 채권에 기록하지 아니하면 사채발행자 및 제3자에게 대항할 수 없다."}],"선지":[{"번호":1,"판정":"틀림","설명":"등록사업자는 법인으로서 자본금 5억원 이상이어야 한다(영 제84조제1항제1호)."},{"번호":2,"판정":"옳음","설명":"주택상환사채권에 적을 사항에 발행 기관, 발행 금액, 발행 조건, 상환의 시기와 절차가 포함된다(규칙 제33조제1항제3호)."},{"번호":3,"판정":"틀림","설명":"발행계획의 승인권자는 국토교통부장관이다(법 제80조제2항)."},{"번호":4,"판정":"틀림","설명":"주택상환사채는 액면 또는 할인의 방법으로 발행한다(영 제83조제1항)."},{"번호":5,"판정":"틀림","설명":"주택상환사채는 기명증권으로 한다(법 제81조제2항)."}],"개념":[{"종류":"표","제목":"주택상환사채 발행 요건","머리":["구분","내용","근거"],"행":[["발행 주체","한국토지주택공사, 등록사업자","법 제80조제1항"],["등록사업자 요건","법인으로서 자본금 5억원 이상, 건설업 등록, 최근 3년간 연평균 주택건설 실적 300호 이상, 금융기관 또는 주택도시보증공사의 보증","영 제84조제1항, 법 제80조제1항"],["발행 규모(등록사업자)","최근 3년간 연평균 주택건설 호수 이내","영 제84조제2항"],["발행 방법","액면 또는 할인","영 제83조제1항"],["증권 형태","기명증권, 명의변경은 사채원부에 취득자 성명ㆍ주소 기록","법 제81조제2항"],["권면 기재사항","발행 기관, 발행 금액, 발행 조건, 상환의 시기와 절차(기호ㆍ번호를 붙임)","영 제83조제2항, 규칙 제33조제1항"],["발행자 비치 장부","주택상환사채대장","영 제83조제3항"],["발행계획 승인","국토교통부장관 승인, 대상지역 관할 시ㆍ도지사에게 통보","법 제80조제2항, 영 제85조제3항"]]},{"종류":"흐름","제목":"주택상환사채 발행 절차","단계":[{"이름":"발행계획 수립","설명":"발행계획서에 택지 소유권 등 증명서류, 보증서, 발행대행계약서ㆍ납입금 관리계약서를 첨부한다. 발행대행계약서와 납입금 관리계약서는 모집공고 전까지 제출할 수 있다(영 제85조제1항)."},{"이름":"승인","설명":"국토교통부장관이 승인하고 관할 시ㆍ도지사에게 통보한다(법 제80조제2항, 영 제85조제3항)."},{"이름":"모집공고안 제출","설명":"승인받은 자가 모집 전에 모집공고안을 국토교통부장관에게 제출한다(영 제85조제4항)."},{"이름":"모집 공고","설명":"모집 7일 전까지 일간신문에 1회 이상 공고한다(규칙 제34조제3항)."},{"이름":"발행","설명":"액면 또는 할인으로 발행하고 주택상환사채대장에 적는다(영 제83조)."},{"이름":"상환","설명":"발행 조건에 따라 주택을 건설해 사채권자에게 상환한다(법 제81조제1항)."}]}],"함정":"선지 1의 3억원은 5억원 요건을 낮춰 놓았다. 선지 3은 승인권자를 시ㆍ도지사로 바꿨는데, 시ㆍ도지사는 승인 내용을 통보받는 쪽이다. 선지 4는 ‘액면 또는 할인’에서 하나만 남겼고, 선지 5는 기명증권을 무기명으로 바꿨다. 정답 선지는 권면 기재사항을 묻는 문장이라 시행규칙 제33조를 알아야 고를 수 있다."},"33회-2차-079":{"한줄":"주말ㆍ체험영농을 하려고 소유할 수 있는 농지는 농업진흥지역 외의 농지뿐이다.","근거":[{"법령":"농지법","조문":"제6조제2항제3호","원문":"②제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 농지를 소유할 수 있다. 다만, 소유 농지는 농업경영에 이용되도록 하여야 한다(제2호 및 제3호는 제외한다). 3. 주말ㆍ체험영농을 하려고 제28조에 따른 농업진흥지역 외의 농지를 소유하는 경우"},{"법령":"농지법","조문":"제6조제2항제5호","원문":"②제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 농지를 소유할 수 있다. 다만, 소유 농지는 농업경영에 이용되도록 하여야 한다(제2호 및 제3호는 제외한다). 5. 대통령령으로 정하는 기간 이상 농업경영을 하던 사람이 이농(離農)한 후에도 이농 당시 소유하고 있던 농지를 계속 소유하는 경우"},{"법령":"농지법","조문":"제7조제2항","원문":"②대통령령으로 정하는 기간 이상 농업경영을 한 후 이농한 사람은 이농 당시 소유 농지 중에서 총 1만제곱미터까지만 소유할 수 있다."},{"법령":"농지법 시행령","조문":"제4조","원문":"법 제6조제2항제5호ㆍ법 제7조제2항 및 법 제23조제1항제7호나목에서 \"대통령령으로 정하는 기간\"이란 8년을 말한다."},{"법령":"농지법","조문":"제6조제2항제10호","원문":"②제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 농지를 소유할 수 있다. 다만, 소유 농지는 농업경영에 이용되도록 하여야 한다(제2호 및 제3호는 제외한다). 10. 다음 각 목의 어느 하나에 해당하는 경우 가. 「한국농어촌공사 및 농지관리기금법」에 따른 한국농어촌공사(이하 \"한국농어촌공사\"라 한다)가 같은 법에 따라 농지를 취득하여 소유하는 경우 나. 「농어촌정비법」 제16조ㆍ제25조ㆍ제43조ㆍ제82조 또는 제100조에 따라 농지를 취득하여 소유하는 경우 다. 「공유수면 관리 및 매립에 관한 법률」에 따라 매립농지를 취득하여 소유하는 경우 라. 토지수용으로 농지를 취득하여 소유하는 경우 마. 농림축산식품부장관과 협의를 마치고 「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률」에 따라 농지를 취득하여 소유하는 경우 바. 「공공토지의 비축에 관한 법률」제2조제1호가목에 해당하는 토지 중 같은 법 제7조제1항에 따른 공공토지비축심의위원회가 비축이 필요하다고 인정하는 토지로서 「국토의 계획 및 이용에 관한 법률」 제36조에 따른 계획관리지역과 자연녹지지역 안의 농지를 한국토지주택공사가 취득하여 소유하는 경우. 이 경우 그 취득한 농지를 전용하기 전까지는 한국농어촌공사에 지체 없이 위탁하여 임대하거나 무상사용하게 하여야 한다."}],"선지":[{"번호":1,"판정":"-","설명":"예외에 해당한다. 대통령령 정하는 기간(8년) 이상 농업경영을 하던 사람이 이농한 뒤에도 이농 당시 소유 농지를 계속 소유할 수 있고 상한은 1만제곱미터다(법 제6조제2항제5호, 제7조제2항, 영 제4조)."},{"번호":2,"판정":"-","설명":"예외에 해당한다. 농림축산식품부장관과 협의를 마치고 공익사업법에 따라 취득하는 경우다(법 제6조제2항제10호마목)."},{"번호":3,"판정":"-","설명":"예외에 해당한다. 공유수면 매립법에 따라 매립농지를 취득하는 경우다(법 제6조제2항제10호다목)."},{"번호":4,"판정":"-","설명":"예외에 해당하지 않는다. 주말ㆍ체험영농 목적 소유는 농업진흥지역 외의 농지만 가능하다(법 제6조제2항제3호)."},{"번호":5,"판정":"-","설명":"예외에 해당한다. 초ㆍ중등교육법ㆍ고등교육법에 따른 학교가 연구지ㆍ실습지 등으로 쓰기 위해 취득하는 경우다(법 제6조제2항제2호)."}],"개념":[{"종류":"표","제목":"농지 소유 제한의 예외(법 제6조제2항)","머리":["호","예외 사유","비고"],"행":[["1호","국가나 지방자치단체가 소유","농업경영 이용 요건 적용"],["2호","학교, 공공단체, 농업연구기관, 농업생산자단체, 종묘 등 농업 기자재 생산자가 시험지ㆍ연구지ㆍ실습지ㆍ종묘생산지 등으로 취득","농업경영 이용 요건 제외"],["3호","주말ㆍ체험영농을 하려고 농업진흥지역 외의 농지를 소유","농업경영 이용 요건 제외, 총 1천제곱미터 미만(법 제7조제3항)"],["4호","상속(유증 포함)으로 취득","농업경영을 하지 않으면 총 1만제곱미터까지(법 제7조제1항)"],["5호","8년 이상 농업경영을 하던 사람이 이농 후 이농 당시 소유 농지를 계속 소유","총 1만제곱미터까지(법 제7조제2항, 영 제4조)"],["6호","담보농지 취득","법 제13조제1항"],["7호","농지전용허가를 받거나 전용신고를 한 자가 그 농지를 소유",""],["8호","농지전용협의를 마친 농지를 소유",""],["10호 다목ㆍ라목ㆍ마목","매립농지 취득, 토지수용으로 취득, 농림축산식품부장관과 협의를 마치고 공익사업법에 따라 취득",""]]},{"종류":"표","제목":"농지 소유 상한(법 제7조)","머리":["대상","상한"],"행":[["상속으로 취득하고 농업경영을 하지 않는 사람","상속 농지 중 총 1만제곱미터"],["8년 이상 농업경영 후 이농한 사람","이농 당시 소유 농지 중 총 1만제곱미터"],["주말ㆍ체험영농을 하려는 사람","총 1천제곱미터 미만(세대원 전부가 소유하는 총 면적)"]]}],"함정":"선지 4는 주말ㆍ체험영농이라는 예외 사유가 맞아서 고르기 어렵다. 예외가 인정되는 범위가 농업진흥지역 외로 한정된다는 점이 정답을 가른다. 선지 1은 8년과 1만제곱미터가 모두 맞는 조합이다."},"33회-2차-089":{"한줄":"지적현황측량은 지상건축물 등의 현황을 지형도가 아니라 지적도·임야도에 등록된 경계와 대비하여 표시할 때 한다(영 제18조).","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제23조제1항","원문":"1. 제7조제1항제3호에 따른 지적기준점을 정하는 경우\n2. 제25조에 따라 지적측량성과를 검사하는 경우\n4. 경계점을 지상에 복원하는 경우\n5. 그 밖에 대통령령으로 정하는 경우\n마. 제82조에 따라 바다가 된 토지의 등록을 말소하는 경우\n사. 제84조에 따라 지적공부의 등록사항을 정정하는 경우"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제18조","원문":"법 제23조제1항제5호에서 \"대통령령으로 정하는 경우\"란 지상건축물 등의 현황을 지적도 및 임야도에 등록된 경계와 대비하여 표시하는 데에 필요한 경우를 말한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"지적기준점을 정하는 경우는 지적측량 대상이다(법 제23조제1항제1호)."},{"번호":2,"판정":"옳음","설명":"경계점을 지상에 복원하는 경우는 지적측량 대상이다(법 제23조제1항제4호)."},{"번호":3,"판정":"틀림","설명":"건축물 현황은 지적도·임야도에 등록된 경계와 대비해 표시하는 경우에 지적측량(지적현황측량)을 한다. 지형도 표시는 대상이 아니다(영 제18조)."},{"번호":4,"판정":"옳음","설명":"바다가 된 토지의 등록말소로서 측량이 필요한 경우다(법 제23조제1항제3호마목)."},{"번호":5,"판정":"옳음","설명":"등록사항 정정으로서 측량이 필요한 경우다(법 제23조제1항제3호사목)."}],"개념":[{"종류":"표","제목":"지적측량을 하는 경우(법 제23조제1항)","머리":["구분","내용"],"행":[["지적기준점","지적기준점을 정하는 경우"],["성과 검사","지적측량성과를 검사하는 경우"],["측량이 필요한 토지이동 등","지적공부 복구, 신규등록, 등록전환, 분할, 바다가 된 토지의 등록말소, 축척변경, 등록사항 정정, 도시개발사업 등 시행지역의 토지이동, 지적재조사사업에 따른 토지이동"],["경계점 복원","경계점을 지상에 복원하는 경우"],["지적현황측량(영 제18조)","지상건축물 등의 현황을 지적도·임야도에 등록된 경계와 대비하여 표시하는 데 필요한 경우"],["측량을 하지 않는 경우","합병은 따로 지적측량 없이 경계·면적을 정한다(법 제26조제1항)"]]},{"종류":"표","제목":"지적측량 의뢰(법 제24조제1항)","머리":["구분","내용"],"행":[["의뢰할 자","토지소유자 등 이해관계인"],["의뢰 상대방","지적측량업 등록을 한 자, 한국국토정보공사(지적측량수행자)"],["의뢰 대상 사유","지적기준점, 측량이 필요한 토지이동 등(지적재조사사업은 제외), 경계점 복원, 지적현황측량"],["의뢰 대상이 아닌 것","지적측량성과 검사, 지적재조사사업에 따른 토지이동 측량"]]}],"함정":"지적현황측량의 기준은 지형도가 아니라 지적도·임야도의 등록 경계다. 합병은 측량 없이 경계를 말소하고 면적을 합산하므로 지적측량 대상 열거에서 빠진다."},"33회-2차-117":{"한줄":"특별징수의무자가 세액을 납부하지 않거나 부족하게 납부해도 가산세를 부과하지 않으므로 ④가 틀리다.","근거":[{"법령":"지방세법","조문":"제31조제4항","원문":"특별징수의무자가 징수하였거나 징수할 세액을 제1항 또는 제2항에 따른 기한까지 납부하지 아니하거나 부족하게 납부하더라도 특별징수의무자에게 「지방세기본법」 제56조에 따른 가산세는 부과하지 아니한다."},{"법령":"지방세법","조문":"제27조제4항","원문":"채권금액으로 과세액을 정하는 경우에 일정한 채권금액이 없을 때에는 채권의 목적이 된 것의 가액 또는 처분의 제한의 목적이 된 금액을 그 채권금액으로 본다."},{"법령":"지방세법","조문":"제30조제6항","원문":"지방자치단체의 장은 제5항에 따른 채권자대위자의 신고납부가 있는 경우 납세의무자에게 그 사실을 즉시 통보하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"채권금액이 없으면 채권의 목적이 된 것의 가액 또는 처분 제한의 목적이 된 금액을 채권금액으로 본다(법 제27조제4항)."},{"번호":2,"판정":"옳음","설명":"같은 채권 담보의 둘 이상 저당권은 하나의 등록이고 처음 등록하는 등록관청 소재지가 납세지다(법 제25조제1항제17호)."},{"번호":3,"판정":"옳음","설명":"부동산 등기 등 제1호부터 제14호까지의 납세지가 분명하지 않으면 등록관청 소재지다(법 제25조제1항제18호)."},{"번호":4,"판정":"틀림","설명":"특별징수의무자가 납부기한까지 납부하지 않거나 부족하게 납부해도 가산세를 부과하지 않는다(법 제31조제4항). 특별징수 대상은 특허권ㆍ실용신안권ㆍ디자인권ㆍ상표권 등록(지식재산처장)과 저작권법상 등록(등록기관장)이라서 지상권 등기는 대상도 아니다."},{"번호":5,"판정":"옳음","설명":"채권자대위자가 신고납부하면 자치단체장은 납세의무자에게 즉시 통보한다(법 제30조제6항)."}],"개념":[{"종류":"표","제목":"등록에 대한 등록면허세 납세지(지방세법 제25조제1항)","머리":["등록 종류","납세지"],"행":[["부동산 등기","부동산 소재지"],["선박 등기ㆍ등록","선적항 소재지"],["자동차 등록","자동차관리법상 등록지(사용본거지가 다르면 사용본거지)"],["건설기계 등록","건설기계관리법상 등록지"],["항공기 등록","정치장 소재지"],["법인 등기","등기에 관련되는 본점ㆍ지점 또는 주사무소ㆍ분사무소 소재지"],["상호 등기","영업소 소재지"],["특허권ㆍ실용신안권ㆍ디자인권 등록","등록권자 주소지"],["재산이 둘 이상의 자치단체에 걸쳐 있어 구분 부과가 불가능한 경우","등록관청 소재지"],["같은 채권 담보의 둘 이상 저당권","처음 등록하는 등록관청 소재지"],["납세지가 분명하지 않은 경우","등록관청 소재지"]]},{"종류":"표","제목":"등록면허세 특별징수(지방세법 제31조)","머리":["구분","내용"],"행":[["대상 1","특허권, 실용신안권, 디자인권, 상표권 등록: 지식재산처장이 특별징수(제1항)"],["대상 2","저작권법에 따른 등록: 해당 등록기관의 장이 특별징수(제2항)"],["납부기한","등록일이 속하는 달의 다음 달 말일까지 납세지 관할 자치단체의 장에게 통보하고 납부"],["잘못 징수한 경우","납부 전에 발견하면 특별징수한 세액을 직접 환급, 지방세환급가산금 적용 안 함(제3항)"],["납부 불이행","납부하지 않거나 부족하게 납부해도 특별징수의무자에게 가산세 없음(제4항)"]]}],"함정":"특별징수의무자에게는 가산세가 없다는 규정을 모르면 ④를 맞는 문장으로 읽는다. 지상권 등기는 특별징수 대상 자체가 아니다. 납세지는 부동산 등기가 부동산 소재지이고, 불분명할 때만 등록관청 소재지다."},"33회-2차-113":{"한줄":"부정행위가 아닌 무신고는 무신고납부세액의 100분의 20을 가산세로 부과하므로 ⑤가 옳다.","근거":[{"법령":"국세기본법","조문":"제47조의2제1항","원문":"제1호 외의 경우: 100분의 20"},{"법령":"소득세법","조문":"제114조의2제1항","원문":"취득일 또는 증축일부터 5년 이내에 해당 건물을 양도하는 경우"},{"법령":"소득세법","조문":"제112조","원문":"거주자로서 제106조 또는 제111조에 따라 납부할 세액이 각각 1천만원을 초과하는 자는 대통령령으로 정하는 바에 따라 그 납부할 세액의 일부를 납부기한이 지난 후 2개월 이내에 분할납부할 수 있다."},{"법령":"소득세법 시행령","조문":"제175조","원문":"납부할 세액이 2천만원이하인 때에는 1천만원을 초과하는 금액"}],"선지":[{"번호":1,"판정":"틀림","설명":"건물 신축 후 5년 이내 양도하면서 감정가액ㆍ환산취득가액을 취득가액으로 하면 그 가액의 100분의 5를 가산세로 한다. 3년, 100분의 3은 틀린 수치다(소득세법 제114조의2제1항)."},{"번호":2,"판정":"틀림","설명":"양도소득세는 분할납부만 규정한다. 물납 규정이 없다(소득세법 제112조)."},{"번호":3,"판정":"틀림","설명":"예정신고 산출세액에서 감면세액을 뺀 세액을 납부할 뿐 신고세액공제는 규정하지 않는다(소득세법 제106조제1항)."},{"번호":4,"판정":"틀림","설명":"납부할 세액이 2천만원 이하이면 1천만원을 초과하는 금액을 분납한다. 1천5백만원이면 500만원이다. 100분의 50은 2천만원을 초과할 때의 기준이다(시행령 제175조)."},{"번호":5,"판정":"옳음","설명":"부정행위가 아닌 무신고의 가산세율은 100분의 20이다. 부정행위는 100분의 40이다(국세기본법 제47조의2제1항)."}],"개념":[{"종류":"표","제목":"양도소득세 신고ㆍ납부(소득세법)","머리":["구분","내용"],"행":[["예정신고(부동산 등)","양도일이 속하는 달의 말일부터 2개월 이내(제105조제1항제1호)"],["예정신고(부담부증여의 채무액 부분)","양도일이 속하는 달의 말일부터 3개월 이내(제105조제1항제3호)"],["확정신고","양도한 과세기간의 다음 연도 5월 1일~5월 31일(제110조제1항)"],["확정신고 면제","예정신고를 한 자는 확정신고를 안 할 수 있음. 누진세율 자산을 2회 이상 예정신고하는 등의 경우는 제외(제110조제4항)"],["예정신고 산출세액","(양도차익 - 장기보유특별공제 - 양도소득 기본공제) × 세율(제107조제1항)"],["분할납부","납부할 세액이 1천만원을 초과하면 납부기한이 지난 후 2개월 이내(제112조)"],["무신고가산세","부정행위 외 100분의 20, 부정행위 100분의 40(국세기본법 제47조의2제1항)"],["감정가액ㆍ환산취득가액 가산세","신축ㆍ증축 건물을 취득일 또는 증축일부터 5년 이내 양도하면서 적용하면 그 가액의 100분의 5(제114조의2)"]]},{"종류":"계산","제목":"분할납부 가능 금액(소득세법 시행령 제175조)","단계":[{"설명":"납부할 세액 1,500만원(2천만원 이하): 1천만원 초과 금액","식":"1,500만원 - 1,000만원","값":"500만원"},{"설명":"납부할 세액 3,000만원(2천만원 초과): 세액의 100분의 50 이하","식":"3,000만원 × 50/100","값":"1,500만원"},{"설명":"분납 기한","식":"납부기한이 지난 후 2개월 이내","값":"2개월"}]}],"함정":"분납 100분의 50은 납부할 세액이 2천만원을 넘을 때만 쓴다. 2천만원 이하이면 1천만원을 넘는 금액이 한도다. 신고세액공제와 물납은 양도소득세에 없는 제도라서 나오면 틀린 선지다."},"33회-1차-033":{"한줄":"시장점유 전략은 공급자 측면의 접근이고, 소비자 구매과정에 초점을 두는 것은 고객점유 전략이다.","근거":[{"이론":"부동산 마케팅 전략의 구분","내용":"시장점유 전략(공급자 중심): STP와 4P Mix로 목표시장을 선점하고 점유율을 높인다. 고객점유 전략(소비자 중심): AIDA 모형에 따라 구매의사결정 단계마다 소비자와의 접점을 마련한다. 관계 마케팅: 고객과 지속적 관계를 유지한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"시장점유 전략은 공급자 측면의 접근이다. 수요자(소비자) 측면의 접근은 고객점유 전략이다."},{"번호":2,"판정":"옳음","설명":"적응가격(차별가격) 전략은 같은 제품을 구매자에 따라 다른 가격으로 판매하는 것이다."},{"번호":3,"판정":"옳음","설명":"마케팅믹스는 표적시장에 도달하기 위해 쓰는 마케팅 요소의 조합이다."},{"번호":4,"판정":"옳음","설명":"시장세분화는 수요자 집단을 인구·경제적 특성 등으로 나누고 그 시장에서 판매지향점을 분명히 하는 전략이다."},{"번호":5,"판정":"옳음","설명":"고객점유 전략은 구매의사결정 과정(AIDA)의 각 단계에서 소비자와 접점을 마련하고 정보의 강약을 조절한다."}],"개념":[{"종류":"표","제목":"마케팅 전략 3종","머리":["구분","시장점유 전략","고객점유 전략","관계 마케팅"],"행":[["관점","공급자 중심","소비자 중심","고객과 공급자의 장기 관계"],["도구","STP, 4P Mix","AIDA 모형","고객 관리, 사후 서비스"],["목표","목표시장 선점, 점유율 확대","구매 단계별 심리 접점 확보","재구매, 구전 효과"],["핵심 단어","세분화·표적시장·포지셔닝","주의·관심·욕망·행동","지속적 관계"]]},{"종류":"흐름","제목":"AIDA 구매의사결정 단계","단계":[{"이름":"주의(Attention)","설명":"광고 등으로 소비자의 눈길을 끈다"},{"이름":"관심(Interest)","설명":"상품 정보를 제공해 흥미를 일으킨다"},{"이름":"욕망(Desire)","설명":"구입하고 싶은 마음이 생기게 한다"},{"이름":"행동(Action)","설명":"계약·구매로 이어지게 한다"}]}],"함정":"공급자 측면과 수요자 측면을 맞바꾼 ① 한 곳만 틀렸다. 시장점유 = 공급자, 고객점유 = 소비자다. 나머지 선지는 정의 그대로다."},"33회-1차-058":{"한줄":"저당권은 1필 토지의 일부에 설정할 수 없다. 나머지 권리는 토지의 일부를 목적으로 할 수 있다.","근거":[{"법령":"부동산등기법","조문":"제69조제6호","원문":"6. 지상권설정의 범위가 토지의 일부인 경우에는 그 부분을 표시한 도면의 번호"},{"법령":"부동산등기법","조문":"제72조제1항제6호","원문":"6. 전세권설정이나 전전세의 범위가 부동산의 일부인 경우에는 그 부분을 표시한 도면의 번호"},{"법령":"부동산등기법","조문":"제74조제7호","원문":"7. 임차권설정 또는 임차물전대의 범위가 부동산의 일부인 때에는 그 부분을 표시한 도면의 번호"},{"이론":"일물일권주의","내용":"물권의 객체는 독립한 하나의 물건이다. 1필 토지의 일부는 독립성이 없어 소유권과 저당권의 객체가 되지 못한다. 용익권은 일부를 사용·수익하는 권리라 일부에 설정할 수 있고, 점유권은 사실상 지배가 미치는 부분에 인정된다."}],"선지":[{"번호":1,"판정":"옳음","설명":"저당권은 1필 토지의 일부를 객체로 할 수 없다. 일부에 설정하려면 분필 후 설정한다."},{"번호":2,"판정":"틀림","설명":"전세권은 부동산 일부에 설정할 수 있고 그 부분을 표시한 도면의 번호를 등기한다(부동산등기법 제72조 제1항 제6호)."},{"번호":3,"판정":"틀림","설명":"지상권은 토지의 일부에 설정할 수 있다(부동산등기법 제69조 제6호)."},{"번호":4,"판정":"틀림","설명":"임차권은 부동산 일부에 설정할 수 있다(부동산등기법 제74조 제7호)."},{"번호":5,"판정":"틀림","설명":"점유권은 사실상 지배가 미치는 부분에 성립하므로 토지의 일부에 대해서도 인정된다."}],"개념":[{"종류":"표","제목":"1필 토지의 일부에 성립 가능한 권리","머리":["권리","일부 성립","근거"],"행":[["소유권","불가(분필 후 가능)","일물일권주의"],["저당권","불가","일물일권주의, 등기사항에 일부 도면 없음(부동산등기법 제75조)"],["지상권","가능","부동산등기법 제69조 제6호"],["지역권(승역지)","가능","부동산등기법 제70조 제5호"],["전세권","가능","부동산등기법 제72조 제1항 제6호"],["임차권","가능","부동산등기법 제74조 제7호"],["점유권","가능","사실상 지배의 범위"]]}],"함정":"임차권을 채권이라 일부에 못 한다고 보거나, 전세권을 담보물권 성격 때문에 저당권과 같이 취급하는 경우가 많다. 전세권은 용익물권으로서 일부 설정이 가능하고 등기도 도면으로 한다."},"33회-1차-069":{"한줄":"증여는 당사자 일방이 무상으로 재산을 수여한다는 의사표시에 상대방이 승낙하면 성립하는 낙성계약이다.","근거":[{"법령":"민법","조문":"제554조","원문":"제554조(증여의 의의) 증여는 당사자 일방이 무상으로 재산을 상대방에 수여하는 의사를 표시하고 상대방이 이를 승낙함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제563조","원문":"제563조(매매의 의의) 매매는 당사자 일방이 재산권을 상대방에게 이전할 것을 약정하고 상대방이 그 대금을 지급할 것을 약정함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제664조","원문":"제664조(도급의 의의) 도급은 당사자 일방이 어느 일을 완성할 것을 약정하고 상대방이 그 일의 결과에 대하여 보수를 지급할 것을 약정함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제618조","원문":"제618조(임대차의 의의) 임대차는 당사자 일방이 상대방에게 목적물을 사용, 수익하게 할 것을 약정하고 상대방이 이에 대하여 차임을 지급할 것을 약정함으로써 그 효력이 생긴다."}],"선지":[{"번호":1,"판정":"틀림","설명":"매매는 합의만으로 성립하는 낙성계약이다(제563조)."},{"번호":2,"판정":"틀림","설명":"교환은 서로 재산권을 이전하는 유상·쌍무계약이다(제596조, 제567조)."},{"번호":3,"판정":"옳음","설명":"증여는 의사표시의 합치로 성립하는 낙성·무상·편무계약이다(제554조)."},{"번호":4,"판정":"틀림","설명":"도급은 일의 완성과 보수 지급의 합의만으로 성립하는 낙성계약이다(제664조)."},{"번호":5,"판정":"틀림","설명":"임대차는 사용·수익 제공과 차임 지급이 서로 대가관계에 있는 쌍무계약이다(제618조)."}],"개념":[{"종류":"표","제목":"계약의 분류","머리":["계약","쌍무/편무","유상/무상","낙성/요물"],"행":[["매매","쌍무","유상","낙성"],["교환","쌍무","유상","낙성"],["임대차","쌍무","유상","낙성"],["도급","쌍무","유상","낙성"],["증여","편무","무상","낙성"],["사용대차","편무","무상","낙성"]]},{"종류":"표","제목":"분류의 실익","머리":["분류","적용되는 규정"],"행":[["쌍무계약","동시이행항변권(제536조), 위험부담(제537조·제538조)"],["유상계약","매매 규정 준용(제567조), 매도인 담보책임"],["무상계약","증여자의 담보책임 경감(제559조)"],["낙성계약","합의로 성립"],["요물계약","계약금계약처럼 금전 교부가 성립요건(판례)"]]}],"함정":"증여를 서면이 없으면 성립하지 않는 계약으로 오해하기 쉽다. 서면이 없는 증여는 각 당사자가 해제할 수 있을 뿐 성립은 합의만으로 한다(제555조). 요물계약의 대표 사례는 판례가 인정하는 계약금계약이다."},"33회-1차-078":{"한줄":"가등기담보권은 피담보채권과 함께라면 제3자에게 양도할 수 있다.","근거":[{"법령":"가등기담보 등에 관한 법률","조문":"제2조제2호","원문":"2. \"채무자등\"이란 다음 각 목의 자를 말한다. 가. 채무자 나. 담보가등기목적 부동산의 물상보증인(物上保證人) 다. 담보가등기 후 소유권을 취득한 제삼자"},{"법령":"가등기담보 등에 관한 법률","조문":"제1조","원문":"이 법은 차용물(借用物)의 반환에 관하여 차주(借主)가 차용물을 갈음하여 다른 재산권을 이전할 것을 예약할 때 그 재산의 예약 당시 가액(價額)이 차용액(借用額)과 이에 붙인 이자를 합산한 액수를 초과하는 경우에 이에 따른 담보계약(擔保契約)과 그 담보의 목적으로 마친 가등기(假登記) 또는 소유권이전등기(所有權移轉登記)의 효력을 정함을 목적으로 한다."},{"법령":"가등기담보 등에 관한 법률","조문":"제12조제1항","원문":"① 담보가등기권리자는 그 선택에 따라 제3조에 따른 담보권을 실행하거나 담보목적부동산의 경매를 청구할 수 있다. 이 경우 경매에 관하여는 담보가등기권리를 저당권으로 본다."},{"법령":"가등기담보 등에 관한 법률","조문":"제3조제1항","원문":"① 채권자가 담보계약에 따른 담보권을 실행하여 그 담보목적부동산의 소유권을 취득하기 위하여는 그 채권(債權)의 변제기(辨濟期) 후에 제4조의 청산금(淸算金)의 평가액을 채무자등에게 통지하고, 그 통지가 채무자등에게 도달한 날부터 2개월(이하 \"청산기간\"이라 한다)이 지나야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"물상보증인과 담보가등기 후 소유권을 취득한 제3자도 채무자등에 포함된다(제2조 제2호). 제3자도 설정자가 될 수 있다."},{"번호":2,"판정":"틀림","설명":"채권자가 통지한 청산금 평가액은 채권자를 구속하므로 그 금액을 다툴 수 없다(판례). 채무자등은 실제 가액이 더 크다고 다툴 수 있다."},{"번호":3,"판정":"틀림","설명":"이 법은 차용물 반환채권(소비대차) 담보에 적용된다(제1조). 공사대금채권을 담보하는 가등기는 적용 대상이 아니다(판례)."},{"번호":4,"판정":"옳음","설명":"가등기담보권은 피담보채권과 함께 양도할 수 있고, 가등기는 부기등기로 이전한다(판례)."},{"번호":5,"판정":"틀림","설명":"담보가등기권리자는 담보권 실행 대신 경매를 청구할 수 있다(제12조 제1항)."}],"개념":[{"종류":"흐름","제목":"가등기담보 실행(귀속청산)","단계":[{"이름":"변제기 도래","설명":"채무의 변제기가 지남"},{"이름":"청산금 통지","설명":"변제기 후 청산금 평가액을 채무자등에게 통지, 부동산 평가액과 채권액 명시(제3조)"},{"이름":"청산기간","설명":"통지가 도달한 날부터 2개월(제3조 제1항)"},{"이름":"청산금 지급","설명":"가등기는 청산기간 후 본등기 청구, 청산금 지급과 본등기·인도는 동시이행(제4조)"},{"이름":"소유권 취득","설명":"소유권이전등기를 마친 경우 청산기간 후 청산금을 지급한 때(제4조 제2항)"}]},{"종류":"표","제목":"가등기담보법 주요 규정","머리":["구분","내용","근거"],"행":[["적용 대상","차용물 반환채권 담보, 예약 당시 가액이 차용액+이자 초과","제1조"],["채무자등","채무자, 물상보증인, 담보가등기 후 소유권 취득 제3자","제2조 제2호"],["불리한 특약","청산 규정에 어긋나는 채무자 불리 특약은 무효","제4조 제4항"],["후순위권리자","청산금에 대해 통지 평가액 범위에서 권리 행사","제5조"],["말소청구","청산금채권을 변제받을 때까지 채무액 지급하고 말소 청구, 변제기 후 10년이 지나면 불가","제11조"],["우선변제","강제경매등에서 저당권으로 보아 우선변제","제13조"]]}],"함정":"2번은 채권자와 채무자의 위치를 바꿔 읽기 쉽다. 통지는 채권자가 한 것이므로 채권자가 그 금액에 스스로 구속된다. 3번은 이 법이 모든 채권 담보에 적용된다고 보는 선지다. 소비대차에서 생긴 채권의 담보만 대상이다."},"33회-1차-079":{"한줄":"명의신탁약정의 무효와 등기의 무효는 제3자에게 대항하지 못하므로, 丁이 약정을 알고 있었더라도 소유권을 취득한다.","근거":[{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조","원문":"① 명의신탁약정은 무효로 한다. ② 명의신탁약정에 따른 등기로 이루어진 부동산에 관한 물권변동은 무효로 한다. 다만, 부동산에 관한 물권을 취득하기 위한 계약에서 명의수탁자가 어느 한쪽 당사자가 되고 상대방 당사자는 명의신탁약정이 있다는 사실을 알지 못한 경우에는 그러하지 아니하다. ③ 제1항 및 제2항의 무효는 제3자에게 대항하지 못한다."},{"판례":"대법원 판례(계약명의신탁)","요지":"계약명의신탁에서 매도인이 선의이면 수탁자가 소유권을 취득하고, 신탁자는 수탁자에게 매수자금 상당의 부당이득반환만 청구할 수 있으며 토지 자체의 이전등기를 청구하지 못한다. 매수자금 반환채권은 토지에 관하여 생긴 채권이 아니어서 유치권이 성립하지 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"명의신탁약정은 무효다(제4조 제1항)."},{"번호":2,"판정":"옳음","설명":"계약명의신탁에서 상대방(丙)이 약정을 모르면 물권변동이 유효하다(제4조 제2항 단서). 乙이 소유권을 취득한다."},{"번호":3,"판정":"옳음","설명":"신탁자는 부동산 자체가 아니라 매수자금 상당의 부당이득반환만 청구할 수 있다(판례)."},{"번호":4,"판정":"옳음","설명":"매수자금 반환채권은 토지에 관해 생긴 채권이 아니어서 유치권이 성립하지 않는다(판례)."},{"번호":5,"판정":"틀림","설명":"무효는 제3자에게 대항하지 못한다(제4조 제3항). 丁이 악의여도 소유권을 취득한다."}],"개념":[{"종류":"표","제목":"명의신탁 유형별 효력","머리":["유형","약정","물권변동","결과"],"행":[["양자간 등기명의신탁","무효","무효","소유권은 신탁자에게 남음, 말소 청구 가능"],["3자간 등기명의신탁(중간생략형)","무효","무효","소유권은 매도인에게 남음, 신탁자는 매도인을 대위해 수탁자 명의 등기의 말소를 청구"],["계약명의신탁(매도인 선의)","무효","유효","수탁자가 소유권 취득, 신탁자는 매수자금 부당이득 반환 청구"],["계약명의신탁(매도인 악의)","무효","무효","소유권은 매도인에게 남음, 신탁자는 수탁자에게 매수자금 반환 청구"]]},{"종류":"비교","제목":"제4조 제3항의 대항 불능","왼쪽":{"이름":"제3자에게 대항 못 함","항목":["약정 무효","등기에 따른 물권변동 무효","수탁자로부터 취득한 제3자는 선악을 불문하고 보호"]},"오른쪽":{"이름":"특례(제8조)","항목":["종중이 보유한 부동산을 종중 외 명의로 등기","배우자 명의 등기","종교단체 산하 조직의 부동산을 종교단체 명의로 등기","조세포탈·강제집행 면탈·법령상 제한 회피 목적이 없을 때 제4조 적용 배제"]}}],"함정":"5번을 맞다고 읽는 경우가 많다. 악의의 제3자는 보호할 필요가 없다는 일반 법감정 때문이다. 이 법의 무효는 제3자의 선의·악의를 구별하지 않고 대항하지 못한다. 2번은 계약명의신탁에서 상대방의 선의를 요건으로 하는 제4조 제2항 단서에 해당한다."},"33회-2차-006":{"한줄":"중개대상물 표시·광고에는 중개사무소·개업공인중개사 사항을 명시하되 중개보조원 사항은 명시할 수 없다(법 제18조의2 제1항).","근거":[{"법령":"공인중개사법","조문":"제18조의2 제1항","원문":"① 개업공인중개사가 의뢰받은 중개대상물에 대하여 표시ㆍ광고(「표시ㆍ광고의 공정화에 관한 법률」 제2조에 따른 표시ㆍ광고를 말한다. 이하 같다)를 하려면 중개사무소, 개업공인중개사에 관한 사항으로서 대통령령으로 정하는 사항을 명시하여야 하며, 중개보조원에 관한 사항은 명시해서는 아니 된다."},{"법령":"공인중개사법","조문":"제9조 제2항","원문":"②공인중개사(소속공인중개사는 제외한다) 또는 법인이 아닌 자는 제1항에 따라 중개사무소의 개설등록을 신청할 수 없다."},{"법령":"공인중개사법","조문":"제14조 제1항 제3호","원문":"①법인인 개업공인중개사는 다른 법률에 규정된 경우를 제외하고는 중개업 및 다음 각 호에 규정된 업무와 제2항에 규정된 업무 외에 다른 업무를 함께 할 수 없다.\n1. 상업용 건축물 및 주택의 임대관리 등 부동산의 관리대행\n2. 부동산의 이용ㆍ개발 및 거래에 관한 상담\n3. 개업공인중개사를 대상으로 한 중개업의 경영기법 및 경영정보의 제공\n4. 상업용 건축물 및 주택의 분양대행\n5. 그 밖에 중개업에 부수되는 업무로서 대통령령으로 정하는 업무\n3. 개업공인중개사를 대상으로 한 중개업의 경영기법 및 경영정보의 제공"},{"법령":"공인중개사법","조문":"제13조 제2항 제3항","원문":"②개업공인중개사는 천막 그 밖에 이동이 용이한 임시 중개시설물을 설치하여서는 아니된다.\n③제1항에도 불구하고 법인인 개업공인중개사는 대통령령으로 정하는 기준과 절차에 따라 등록관청에 신고하고 그 관할 구역 외의 지역에 분사무소를 둘 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"개설등록은 소속공인중개사를 제외한 공인중개사와 법인만 신청할 수 있다(법 제9조 제2항)."},{"번호":2,"판정":"틀림","설명":"경영기법·경영정보 제공은 법 제14조 제1항 제3호가 허용하는 법인의 겸업 업무다."},{"번호":3,"판정":"틀림","설명":"분사무소는 허가가 아니라 신고 대상이다(법 제13조 제3항)."},{"번호":4,"판정":"틀림","설명":"임시 중개시설물은 설치할 수 없다. 신고로 허용되는 길도 없다(법 제13조 제2항)."},{"번호":5,"판정":"옳음","설명":"표시·광고에 중개보조원 사항은 명시해서는 아니 된다(법 제18조의2 제1항)."}],"개념":[{"종류":"표","제목":"법인인 개업공인중개사의 겸업 범위(법 제14조)","머리":["업무","내용"],"행":[["관리대행","상업용 건축물·주택의 임대관리 등"],["상담","부동산의 이용·개발 및 거래"],["경영기법 제공","개업공인중개사를 대상으로 한 중개업 경영기법·경영정보"],["분양대행","상업용 건축물·주택"],["부수 업무","도배·이사업체 소개 등 주거이전 용역 알선(영 제17조 제2항)"],["경매·공매 대리","권리분석·취득 알선, 매수신청·입찰신청 대리(개업공인중개사 공통)"]]},{"종류":"표","제목":"사무소 설치 규칙","머리":["항목","내용"],"행":[["사무소 수","등록관청 관할 구역 안 1개"],["임시 중개시설물","설치 금지(천막 등)"],["분사무소","법인만, 신고(허가 아님)"],["위반 시","등록취소 가능, 1년 이하 징역 또는 1천만원 이하 벌금"]]}],"함정":"분사무소를 ‘허가’로, 법인의 겸업을 ‘전면 금지’로 알기 쉽다. 법인은 중개업 외에 법 제14조 업무까지만 가능하다."},"33회-2차-009":{"한줄":"비선호시설(1km 이내) 항목은 주거용 [Ⅰ] 서식의 기본 확인사항이고 비주거용 [Ⅱ]에는 없다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"별지 제20호의2서식(비주거용 건축물) Ⅰ. 개업공인중개사 기본 확인사항","원문":"① 대상물건의 표시\n② 권리관계(등기부 기재사항: 소유권에 관한 사항, 소유권 외의 권리사항)\n③ 토지이용계획, 공법상 이용제한 및 거래규제에 관한 사항(토지)\n④ 입지조건\n⑤ 관리에 관한 사항(경비실, 관리주체)\n⑥ 거래예정금액 등\n⑦ 취득 시 부담할 조세의 종류 및 세율"},{"법령":"공인중개사법 시행규칙","조문":"별지 제20호서식(주거용 건축물) Ⅰ. 개업공인중개사 기본 확인사항","원문":"⑥ 관리에 관한 사항(경비실, 관리주체, 관리비)\n⑦ 비선호시설(1km이내)"}],"선지":[{"번호":1,"판정":"-","설명":"①번 대상물건의 표시다. 기본 확인사항이다."},{"번호":2,"판정":"-","설명":"②번 권리관계의 소유권 외의 권리사항이다. 기본 확인사항이다."},{"번호":3,"판정":"-","설명":"비선호시설(1km이내)은 [Ⅰ] 주거용 서식에만 있다."},{"번호":4,"판정":"-","설명":"⑤번 관리에 관한 사항의 관리주체다. 기본 확인사항이다."},{"번호":5,"판정":"-","설명":"②번 권리관계의 소유권에 관한 사항이다. 기본 확인사항이다."}],"개념":[{"종류":"표","제목":"주거용[Ⅰ]과 비주거용[Ⅱ] 기본 확인사항 차이","머리":["항목","주거용[Ⅰ]","비주거용[Ⅱ]"],"행":[["대상물건의 표시","있음","있음"],["권리관계(등기부)","있음","있음"],["임대차 확정일자 부여현황 정보","있음","없음"],["입지조건","있음","있음"],["관리에 관한 사항","경비실·관리주체·관리비","경비실·관리주체"],["비선호시설(1km 이내)","있음","없음"],["거래예정금액 등","있음","있음"],["취득 시 조세","있음","있음"]]},{"종류":"표","제목":"확인·설명의 공통 규칙","머리":["항목","내용"],"행":[["설명 시기","중개가 완성되기 전"],["설명 상대방","권리를 취득하려는 중개의뢰인"],["서명 및 날인","개업공인중개사(법인은 대표자, 분사무소는 책임자) + 해당 중개를 한 소속공인중개사"],["보존","원본·사본 또는 전자문서 3년"],["자료요구 불응","그 사실을 설명하고 확인·설명서에 기재"]]}],"함정":"비주거용에도 입지조건·관리가 있다 보니 주거용 전용 항목(관리비, 비선호시설)까지 있는 것처럼 읽기 쉽다."},"33회-2차-016":{"한줄":"책임준비금의 적립비율은 공제료 수입액의 100분의 10 이상으로 정한다(시행령 제34조제3호). 100분의 20은 틀린 숫자다.","근거":[{"법령":"공인중개사법 시행령","조문":"제34조 제3호","원문":"3. 책임준비금의 적립비율 : 공제사고 발생률 및 공제금 지급액 등을 종합적으로 고려하여 정하되, 공제료 수입액의 100분의 10이상으로 정한다."},{"법령":"공인중개사법","조문":"제42조 제4항 제5항","원문":"④협회는 공제사업을 다른 회계와 구분하여 별도의 회계로 관리하여야 하며, 책임준비금을 다른 용도로 사용하고자 하는 경우에는 국토교통부장관의 승인을 얻어야 한다.\n⑤협회는 대통령령으로 정하는 바에 따라 매년도의 공제사업 운용실적을 일간신문ㆍ협회보 등을 통하여 공제계약자에게 공시하여야 한다."},{"법령":"공인중개사법","조문":"제42조의4","원문":"제42조의4(공제사업 운영의 개선명령) 국토교통부장관은 협회의 공제사업 운영이 적정하지 아니하거나 자산상황이 불량하여 중개사고 피해자 및 공제 가입자 등의 권익을 해칠 우려가 있다고 인정하면 다음 각 호의 조치를 명할 수 있다.\n1. 업무집행방법의 변경\n2. 자산예탁기관의 변경\n3. 자산의 장부가격의 변경\n4. 불건전한 자산에 대한 적립금의 보유\n5. 가치가 없다고 인정되는 자산의 손실 처리\n6. 그 밖에 이 법 및 공제규정을 준수하지 아니하여 공제사업의 건전성을 해할 우려가 있는 경우 이에 대한 개선명령"},{"법령":"공인중개사법 시행령","조문":"제35조","원문":"제35조(공제사업 운용실적의 공시) 협회는 법 제42조제5항에 따라 다음 각 호의 사항을 매 회계연도 종료 후 3개월 이내에 일간신문 또는 협회보에 공시하고 협회의 인터넷 홈페이지에 게시해야 한다.\n1. 결산서인 요약 재무상태표, 손익계산서 및 감사보고서\n2. 공제료 수입액, 공제금 지급액, 책임준비금 적립액\n3. 그 밖에 공제사업의 운용과 관련된 참고사항"}],"선지":[{"번호":1,"판정":"옳음","설명":"공제사업은 다른 회계와 구분해 별도 회계로 관리하고, 책임준비금을 다른 용도로 쓰려면 국토교통부장관의 승인을 받는다(법 제42조제4항)."},{"번호":2,"판정":"틀림","설명":"적립비율은 공제료 수입액의 100분의 10 이상이다(시행령 제34조제3호)."},{"번호":3,"판정":"옳음","설명":"공제사업 운영이 적정하지 않거나 자산상황이 불량해 피해자와 가입자의 권익을 해칠 우려가 있으면 자산예탁기관의 변경을 명할 수 있다(법 제42조의4제2호)."},{"번호":4,"판정":"옳음","설명":"같은 조 제4호가 불건전한 자산에 대한 적립금의 보유를 명할 수 있는 조치로 정한다(법 제42조의4제4호)."},{"번호":5,"판정":"옳음","설명":"운용실적은 일간신문ㆍ협회보 등으로 공제계약자에게 공시한다(법 제42조제5항). 시행령은 매 회계연도 종료 후 3개월 이내에 일간신문 또는 협회보에 공시하고 협회 홈페이지에 게시하도록 한다(시행령 제35조)."}],"개념":[{"종류":"표","제목":"공제사업에 대한 국토교통부장관의 통제 수단","머리":["수단","내용","근거"],"행":[["공제규정 승인","제정ㆍ변경 모두 국토교통부장관 승인","법 제42조제2항"],["책임준비금 전용 승인","다른 용도로 쓰려면 승인","법 제42조제4항"],["개선명령","업무집행방법 변경, 자산예탁기관 변경, 자산 장부가격 변경, 불건전 자산 적립금 보유, 무가치 자산 손실 처리, 그 밖의 개선명령","법 제42조의4"],["임원 제재","공제규정 위반, 개선명령 불이행, 재무건전성 기준 위반 시 임원 징계ㆍ해임 요구 또는 시정명령","법 제42조의5"],["재무건전성","지급여력비율 100분의 100 이상 유지, 구상채권 등 분류와 대손충당금 적립","법 제42조의6, 시행령 제35조의3"],["조사ㆍ검사","국토교통부장관의 요청이 있으면 금융감독원장이 공제사업을 조사ㆍ검사","법 제42조의3"]]},{"종류":"표","제목":"공제 운영위원회 (법 제42조의2, 시행령 제35조의2)","머리":["항목","내용"],"행":[["설치 목적","공제사업 사항 심의, 업무집행 감독"],["위원 수","19명 이내"],["구성","협회 임원, 중개업ㆍ법률ㆍ회계ㆍ금융ㆍ보험ㆍ부동산 전문가, 관계 공무원, 이해관계자"],["일부 위원의 제한","협회 회장과 협회 이사회가 선임한 임원 위원은 전체 위원의 3분의 1 미만"],["임기","선임ㆍ위촉 위원(시행령 제35조의2제2항제3호ㆍ제4호) 2년, 1회 연임 가능"],["의결","재적위원 과반수 출석, 출석위원 과반수 찬성"]]}],"함정":"책임준비금 적립비율 100분의 10을 20으로 바꾼 2번이 답이다. 나머지는 법 제42조제4항과 제42조의4의 개선명령 목록에서 그대로 나온 문장이다. 3번과 4번의 권익 보호 대상이 가입자와 피해자로 다르게 적혀 있어도 법 제42조의4는 둘을 함께 보호 대상으로 적는다.","개정":"협회 명칭이 「공인중개사협회」에서 「한국공인중개사협회」로 법정화되었다(법 제41조제1항, 2026.2.27. 개정). 발문의 명칭만 현행에 맞췄고 정답은 그대로 2번이다."},"33회-2차-021":{"한줄":"자격취소 사유는 금고 이상의 형(집행유예 포함)을 선고받은 경우이고 벌금형은 해당하지 않는다. 300만원 이상 벌금형은 개설등록의 결격사유(법 제10조제1항제11호)다.","근거":[{"법령":"공인중개사법","조문":"제35조 제1항","원문":"①시ㆍ도지사는 공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 그 자격을 취소하여야 한다.\n1. 부정한 방법으로 공인중개사의 자격을 취득한 경우\n2. 제7조제1항의 규정을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도 또는 대여한 경우\n3. 제36조에 따른 자격정지처분을 받고 그 자격정지기간 중에 중개업무를 행한 경우(다른 개업공인중개사의 소속공인중개사ㆍ중개보조원 또는 법인인 개업공인중개사의 사원ㆍ임원이 되는 경우를 포함한다)\n4. 이 법 또는 공인중개사의 직무와 관련하여 「형법」 제114조, 제231조, 제234조, 제347조, 제355조 또는 제356조를 위반하여 금고 이상의 형(집행유예를 포함한다)을 선고받은 경우"},{"법령":"공인중개사법","조문":"제35조 제2항 제3항 제4항","원문":"②시ㆍ도지사는 제1항에 따라 공인중개사의 자격을 취소하고자 하는 경우에는 청문을 실시하여야 한다.\n③제1항에 따라 공인중개사의 자격이 취소된 자는 국토교통부령으로 정하는 바에 따라 공인중개사자격증을 시ㆍ도지사에게 반납하여야 한다.\n④분실 등의 사유로 인하여 제3항에 따라 공인중개사자격증을 반납할 수 없는 자는 제3항에도 불구하고 자격증 반납을 대신하여 그 이유를 기재한 사유서를 시ㆍ도지사에게 제출하여야 한다."},{"법령":"공인중개사법 시행령","조문":"제29조 제3항","원문":"③시ㆍ도지사는 공인중개사의 자격취소처분을 한 때에는 5일 이내에 이를 국토교통부장관과 다른 시ㆍ도지사에게 통보해야 한다."},{"법령":"공인중개사법","조문":"제10조 제11호","원문":"11. 이 법을 위반하여 300만원 이상의 벌금형의 선고를 받고 3년이 지나지 아니한 자"}],"선지":[{"번호":1,"판정":"틀림","설명":"자격취소 사유는 이 법 또는 직무와 관련해 형법 제114조 등을 위반하여 금고 이상의 형을 선고받은 경우다(법 제35조제1항제4호). 300만원 이상 벌금형은 결격사유일 뿐 자격취소 사유가 아니다."},{"번호":2,"판정":"옳음","설명":"자격취소를 받은 자는 자격증을 교부한 시ㆍ도지사에게 반납한다(법 제35조제3항)."},{"번호":3,"판정":"옳음","설명":"취소처분 후 5일 이내에 국토교통부장관과 다른 시ㆍ도지사에게 통보한다(시행령 제29조제3항)."},{"번호":4,"판정":"옳음","설명":"자격을 취소하려면 청문을 실시해야 한다(법 제35조제2항)."},{"번호":5,"판정":"옳음","설명":"부정한 방법으로 자격을 취득한 경우는 필요적 취소 사유다(법 제35조제1항제1호)."}],"개념":[{"종류":"흐름","제목":"공인중개사 자격취소 절차","단계":[{"이름":"취소 사유 발생","설명":"부정한 방법으로 자격 취득, 자격증 양도ㆍ대여 또는 성명 사용 허용, 자격정지 기간 중 중개업무(소속공인중개사ㆍ중개보조원ㆍ법인 임원이 되는 경우 포함), 금고 이상의 형 선고(집행유예 포함) 중 하나다."},{"이름":"청문","설명":"시ㆍ도지사가 자격을 취소하려면 청문을 실시해야 한다(법 제35조제2항)."},{"이름":"취소처분","설명":"자격증을 교부한 시ㆍ도지사가 처분한다. 사무소 소재지 시ㆍ도지사가 다르면 사무소 소재지 시ㆍ도지사가 절차를 모두 이행한 뒤 자격증을 교부한 시ㆍ도지사에게 통보한다(시행령 제29조제1항ㆍ제2항)."},{"이름":"자격증 반납","설명":"처분을 받은 날부터 7일 이내에 자격증을 교부한 시ㆍ도지사에게 반납한다. 분실이면 반납 대신 사유서를 제출한다(법 제35조제3항ㆍ제4항, 시행규칙 제21조)."},{"이름":"통보","설명":"취소처분을 한 때부터 5일 이내에 국토교통부장관과 다른 시ㆍ도지사에게 통보한다(시행령 제29조제3항)."}]},{"종류":"표","제목":"벌금ㆍ금고 형 선고와 자격 관련 효과","머리":["선고 내용","효과","근거"],"행":[["이 법 위반으로 300만원 이상 벌금형","선고 후 3년이 지나지 않으면 개설등록 결격(자격취소는 아님)","법 제10조제1항제11호"],["금고 이상의 실형","집행 종료ㆍ면제 후 3년이 지나지 않으면 결격. 이 법 또는 직무 관련 형법 위반이면 자격취소","법 제10조제1항제4호, 제35조제1항제4호"],["금고 이상의 집행유예","유예기간 만료 후 2년이 지나지 않으면 결격. 이 법 또는 직무 관련 형법 위반이면 자격취소","법 제10조제1항제5호, 제35조제1항제4호"],["자격취소","취소된 후 3년이 지나지 않으면 개설등록 결격","법 제10조제1항제6호"]]}],"함정":"300만원 이상 벌금이라는 숫자는 결격사유 조문(제10조)의 것인데 자격취소 사유로 잘못 옮겨 놓았다. 자격취소는 금고 이상의 형이 기준이다. 나머지 네 선지는 법 제35조와 시행령 제29조의 문언 그대로라 옳다.","개정":"자격취소 후 통보 문언이 「국토교통부장관에게 보고하고 다른 시ㆍ도지사에게 통지」에서 「국토교통부장관과 다른 시ㆍ도지사에게 통보」로 정비되었다(시행령 제29조제3항, 2023.11.16.). 3번의 옳고 그름은 달라지지 않는다."},"33회-2차-036":{"한줄":"1동의 건물의 설치 또는 보존의 흠으로 생긴 손해는 흠이 공용부분에 있는 것으로 추정한다(집합건물법 제6조).","근거":[{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제6조","원문":"제6조(건물의 설치ㆍ보존상의 흠 추정) 전유부분이 속하는 1동의 건물의 설치 또는 보존의 흠으로 인하여 다른 자에게 손해를 입힌 경우에는 그 흠은 공용부분에 존재하는 것으로 추정한다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제5조 제3항","원문":"③ 구분소유자는 그 전유부분이나 공용부분을 보존하거나 개량하기 위하여 필요한 범위에서 다른 구분소유자의 전유부분 또는 자기의 공유(共有)에 속하지 아니하는 공용부분의 사용을 청구할 수 있다. 이 경우 다른 구분소유자가 손해를 입었을 때에는 보상하여야 한다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제18조","원문":"제18조(공용부분에 관하여 발생한 채권의 효력) 공유자가 공용부분에 관하여 다른 공유자에 대하여 가지는 채권은 그 특별승계인에 대하여도 행사할 수 있다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제8조","원문":"제8조(대지공유자의 분할청구 금지) 대지 위에 구분소유권의 목적인 건물이 속하는 1동의 건물이 있을 때에는 그 대지의 공유자는 그 건물 사용에 필요한 범위의 대지에 대하여는 분할을 청구하지 못한다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제13조 제1항 제2항","원문":"① 공용부분에 대한 공유자의 지분은 그가 가지는 전유부분의 처분에 따른다.\n② 공유자는 그가 가지는 전유부분과 분리하여 공용부분에 대한 지분을 처분할 수 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"제6조가 흠의 공용부분 존재를 추정한다."},{"번호":2,"판정":"틀림","설명":"구분소유자는 전유부분이나 공용부분을 보존하거나 개량하기 위해 필요한 범위에서 다른 구분소유자의 전유부분 사용을 청구할 수 있다. 손해를 입은 구분소유자에게는 보상한다(제5조제3항)."},{"번호":3,"판정":"틀림","설명":"공유자가 다른 공유자에 대해 가지는 채권은 그 특별승계인에 대하여도 행사할 수 있다(제18조)."},{"번호":4,"판정":"틀림","설명":"대지공유자는 건물 사용에 필요한 범위의 대지에 대하여 분할을 청구하지 못한다(제8조)."},{"번호":5,"판정":"틀림","설명":"공용부분 지분은 전유부분의 처분에 따르며 분리 처분할 수 없다(제13조제1항ㆍ제2항)."}],"개념":[{"종류":"표","제목":"전유부분과 공용부분ㆍ대지사용권의 일체성","머리":["항목","내용","근거"],"행":[["공용부분 귀속","구분소유자 전원의 공유. 일부공용부분은 그들 구분소유자의 공유","제10조제1항"],["공용부분 지분","전유부분 면적 비율. 전유부분 처분에 따르고 분리 처분 불가","제12조, 제13조"],["공용부분 물권 변동","등기 불필요","제13조제3항"],["대지사용권","전유부분 처분에 따르고 분리 처분 불가(규약으로 달리 정하면 예외). 분리처분금지는 등기해야 선의 제3자에게 대항","제20조"],["대지 분할청구","건물 사용에 필요한 범위의 대지는 분할청구 불가","제8조"],["공용부분 채권","특별승계인에게도 행사 가능","제18조"],["흠 추정","건물의 설치ㆍ보존상 흠은 공용부분에 있는 것으로 추정","제6조"]]},{"종류":"표","제목":"관리인과 관리단집회","머리":["항목","내용","근거"],"행":[["관리인 선임 의무","구분소유자 10인 이상이면 선임","제24조제1항"],["관리인 임기","2년 범위에서 규약으로 정함, 구분소유자일 필요 없음","제24조제2항"],["관리단집회 의결","구분소유자 과반수 및 의결권 과반수","제38조제1항"],["구분소유권 경매 청구 결의","구분소유자 4분의 3 이상 및 의결권 4분의 3 이상","제45조제2항"],["의결권 행사","서면, 전자적 방법 또는 대리인","제38조제2항"]]}],"함정":"다섯 선지 중 네 개가 법 조문의 결론을 반대로 적었다. 구분소유자 간 사용 청구는 가능, 채권은 승계, 대지 분할은 금지, 지분은 전유부분과 일체라는 방향을 한 묶음으로 외운다."},"33회-2차-060":{"한줄":"대의원회에는 조합장만 들어갈 수 있고, 조합장이 아닌 조합임원은 대의원이 될 수 없다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"제46조제3항","원문":"조합장이 아닌 조합임원은 대의원이 될 수 없다."},{"법령":"도시 및 주거환경정비법 시행령","조문":"제40조","원문":"법 제41조제1항에 따라 조합에 두는 이사의 수는 3명 이상으로 하고, 감사의 수는 1명 이상 3명 이하로 한다. 다만, 토지등소유자의 수가 100인을 초과하는 경우에는 이사의 수를 5명 이상으로 한다."},{"법령":"도시 및 주거환경정비법","조문":"제42조제4항","원문":"조합임원은 같은 목적의 정비사업을 하는 다른 조합의 임원 또는 직원을 겸할 수 없다."},{"법령":"도시 및 주거환경정비법","조문":"제43조제5항","원문":"제41조제5항제2호에 따라 시장ㆍ군수등이 전문조합관리인을 선정한 경우 전문조합관리인이 업무를 대행할 임원은 당연 퇴임한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"100인을 초과하면 이사는 5명 이상이다(영 제40조 단서)."},{"번호":2,"판정":"옳음","설명":"임기는 3년 이하이고 연임할 수 있다(법 제41조제4항)."},{"번호":3,"판정":"틀림","설명":"조합장이 아닌 조합임원은 대의원이 될 수 없다(법 제46조제3항). 조합장은 대의원회 의장이 되면서 대의원으로 본다(법 제42조제2항)."},{"번호":4,"판정":"옳음","설명":"같은 목적의 정비사업을 하는 다른 조합의 임원·직원과 겸직할 수 없다(법 제42조제4항)."},{"번호":5,"판정":"옳음","설명":"총회가 조합원 과반수 출석과 출석 과반수 동의로 선정을 요청해 시장·군수등이 전문조합관리인을 선정한 경우, 대행 대상 임원은 당연 퇴임한다(법 제43조제5항, 제41조제5항제2호)."}],"개념":[{"종류":"표","제목":"조합임원의 결격사유(법 제43조제1항)","머리":["구분","결격 사유"],"행":[["행위능력","미성년자·피성년후견인·피한정후견인"],["파산","파산선고를 받고 복권되지 아니한 자"],["실형","금고 이상의 실형 집행이 끝나거나 면제된 날부터 2년이 지나지 아니한 자"],["집행유예","금고 이상의 형의 집행유예 기간 중에 있는 자"],["이 법 위반","이 법을 위반하여 벌금 100만원 이상 형을 선고받고 10년이 지나지 아니한 자"],["인가권자 관련자","조합설립 인가권자인 지방자치단체의 장, 지방의회의원 또는 그 배우자·직계존속·직계비속"]]},{"종류":"흐름","제목":"전문조합관리인 선정","단계":[{"이름":"선정 사유 발생","설명":"조합임원이 직무를 수행할 수 없게 된 때부터 6개월 이상 선임되지 않았거나, 총회가 조합원 과반수 출석과 출석 과반수 동의로 선정을 요청(법 제41조제5항)"},{"이름":"시장·군수등 선정","설명":"시·도조례로 정하는 바에 따라 변호사·회계사·기술사 등 대통령령 요건을 갖춘 자를 선정(법 제41조제5항)"},{"이름":"업무 대행","설명":"전문조합관리인이 조합임원의 업무를 대행"},{"이름":"임원 당연 퇴임","설명":"총회 요청(제2호)에 따라 선정한 경우 전문조합관리인이 업무를 대행할 임원은 당연 퇴임(법 제43조제5항)"}]}],"함정":"임원이면 대의원이 될 수 있다는 문장이 오답이다. 대의원이 되는 임원은 조합장뿐이고 이사·감사는 될 수 없다(법 제46조제3항). 이사 5명 이상은 토지등소유자 100인 초과일 때이고 기본은 3명 이상이다."},"33회-2차-074":{"한줄":"산후조리원은 면적 제한 없이 제1종 근린생활시설이고, 나머지는 1,000㎡이면 면적 요건을 넘거나 채우지 못해 제1종에서 빠진다.","근거":[{"법령":"건축법 시행령","조문":"별표 1 제3호라목","원문":"의원, 치과의원, 한의원, 침술원, 접골원(接骨院), 조산원, 안마원, 산후조리원 등 주민의 진료ㆍ치료 등을 위한 시설"},{"법령":"건축법 시행령","조문":"별표 1 제3호가목·마목·바목","원문":"식품ㆍ잡화ㆍ의류ㆍ완구ㆍ서적ㆍ건축자재ㆍ의약품ㆍ의료기기 등 일용품을 판매하는 소매점으로서 … 바닥면적의 합계가 1천 제곱미터 미만인 것 / 탁구장, 체육도장으로서 … 500제곱미터 미만인 것 / 지역자치센터, 파출소, 지구대, 소방서, 우체국, 방송국, 보건소, 공공도서관, 건강보험공단 사무소 등 … 바닥면적의 합계가 1천 제곱미터 미만인 것"}],"선지":[{"번호":1,"판정":"-","설명":"공연장은 500㎡ 미만일 때만 제2종 근린생활시설이다(별표 1 제4호가목). 1,000㎡이므로 근린생활시설이 아니라 문화 및 집회시설이다."},{"번호":2,"판정":"-","설명":"서적 소매점은 1천㎡ '미만'이어야 제1종이다(별표 1 제3호가목). 1,000㎡는 미만이 아니므로 제1종에서 빠지고 서점으로서 제2종 근린생활시설이 된다(별표 1 제4호라목)."},{"번호":3,"판정":"-","설명":"탁구장은 500㎡ 미만일 때만 제1종이다(별표 1 제3호마목). 1,000㎡는 제2종에도 해당하지 않아 운동시설이다(별표 1 제13호가목)."},{"번호":4,"판정":"-","설명":"파출소 등 공공업무시설은 1천㎡ '미만'이어야 제1종이다(별표 1 제3호바목). 1,000㎡는 업무시설 중 공공업무시설이다(별표 1 제14호가목)."},{"번호":5,"판정":"-","설명":"산후조리원은 바닥면적 제한이 없는 제1종 근린생활시설이다(별표 1 제3호라목)."}],"개념":[{"종류":"표","제목":"제1종 근린생활시설 면적 요건(별표 1 제3호)","머리":["시설","바닥면적 합계 요건"],"행":[["일용품 소매점(식품·잡화·서적 등)","1천㎡ 미만"],["휴게음식점·제과점","300㎡ 미만"],["탁구장·체육도장","500㎡ 미만"],["파출소·우체국·보건소 등 공공업무시설","1천㎡ 미만"],["통신용 시설·전기자동차 충전소","각 1천㎡ 미만"],["금융업소·사무소·부동산중개사무소 등","30㎡ 미만"],["동물병원·동물미용실","300㎡ 미만"],["이용원·미용원·목욕장·세탁소, 의원·한의원·조산원·산후조리원, 마을회관 등","면적 제한 없음"]]},{"종류":"비교","제목":"제1종과 제2종 근린생활시설의 갈림길","왼쪽":{"이름":"제1종 근린생활시설","항목":["소매점 1천㎡ 미만","휴게음식점·제과점 300㎡ 미만","탁구장·체육도장 500㎡ 미만","공공업무시설 1천㎡ 미만","산후조리원 등 진료시설은 면적 제한 없음"]},"오른쪽":{"이름":"제2종 근린생활시설","항목":["서점(제1종에 해당하지 않는 것) 면적 제한 없음","공연장·종교집회장 500㎡ 미만","일반음식점 면적 제한 없음","휴게음식점·제과점 300㎡ 이상","학원·교습소 500㎡ 미만","독서실·기원"]}}],"함정":"서점·탁구장·파출소는 이름만 보면 근린생활시설이다. 1,000㎡이면 소매점 '1천㎡ 미만', 탁구장 '500㎡ 미만', 공공업무시설 '1천㎡ 미만' 요건을 채우지 못한다. 서점은 제1종이 아니라 제2종 근린생활시설이다."},"33회-2차-097":{"한줄":"거래가액은 갑구의 권리자 및 기타사항란에 기록하고, 등기원인란에 기록하지 않는다.","근거":[{"법령":"부동산등기규칙","조문":"제124조제2항","원문":"② 「부동산 거래신고 등에 관한 법률」 제3조제1항에서 정하는 계약을 등기원인으로 하는 소유권이전등기를 신청하는 경우에는 거래가액을 신청정보의 내용으로 등기소에 제공하고, 시장ㆍ군수 또는 구청장으로부터 제공받은 거래계약신고필증정보를 첨부정보로서 등기소에 제공하여야 한다. 이 경우 대법원예규로 정하는 바에 따라 거래부동산이 2개 이상인 경우 또는 거래부동산이 1개라 하더라도 여러 명의 매도인과 여러 명의 매수인 사이의 매매계약인 경우에는 매매목록도 첨부정보로서 등기소에 제공하여야 한다."},{"법령":"부동산등기규칙","조문":"제125조","원문":"제125조(거래가액의 등기방법) 등기관이 거래가액을 등기할 때에는 다음 각 호의 구분에 따른 방법으로 한다. 1. 매매목록의 제공이 필요 없는 경우 : 등기기록 중 갑구의 권리자 및 기타사항란에 거래가액을 기록하는 방법 2. 매매목록이 제공된 경우 : 거래가액과 부동산의 표시를 기록한 매매목록을 전자적으로 작성하여 번호를 부여하고 등기기록 중 갑구의 권리자 및 기타사항란에 그 매매목록의 번호를 기록하는 방법"},{"법령":"부동산등기법","조문":"제68조","원문":"제68조(거래가액의 등기) 등기관이 「부동산 거래신고 등에 관한 법률」 제3조제1항에서 정하는 계약을 등기원인으로 한 소유권이전등기를 하는 경우에는 대법원규칙으로 정하는 바에 따라 거래가액을 기록한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"신고한 거래가액은 신청정보의 내용으로 제공한다(규칙 제124조제2항)."},{"번호":2,"판정":"옳음","설명":"시장·군수·구청장에게서 제공받은 거래계약신고필증정보를 첨부정보로 제공한다(규칙 제124조제2항)."},{"번호":3,"판정":"옳음","설명":"거래부동산이 2개 이상이면 매매목록을 첨부정보로 제공한다(규칙 제124조제2항, 대법원예규)."},{"번호":4,"판정":"옳음","설명":"거래부동산이 1개여도 매도인과 매수인이 각각 여럿이면 매매목록을 제공한다(규칙 제124조제2항)."},{"번호":5,"판정":"틀림","설명":"거래가액은 갑구의 권리자 및 기타사항란에 기록한다. 매매목록이 제공되면 그 매매목록의 번호를 같은 란에 기록한다(규칙 제125조)."}],"개념":[{"종류":"흐름","제목":"매매계약에 따른 소유권이전등기와 거래가액 등기","단계":[{"이름":"매매계약 체결","설명":"부동산 매매계약 등 「부동산 거래신고 등에 관한 법률」 제3조제1항 계약"},{"이름":"거래신고","설명":"거래당사자가 계약 체결일부터 30일 이내에 관할 시장·군수·구청장에게 신고. 개업공인중개사가 계약서를 작성·교부했으면 그 개업공인중개사가 신고(같은 법 제3조)"},{"이름":"신고필증정보 제공","설명":"시장·군수·구청장이 거래계약신고필증정보를 제공"},{"이름":"등기신청","설명":"신청정보에 신고한 거래가액 제공, 첨부정보에 거래계약신고필증정보. 거래부동산이 2개 이상이거나 여러 매도인·매수인이면 매매목록도 제공(규칙 제124조)"},{"이름":"거래가액 기록","설명":"갑구의 권리자 및 기타사항란에 거래가액 기록, 매매목록이 있으면 매매목록 번호를 기록(규칙 제125조)"}]},{"종류":"표","제목":"거래가액 등기 정리","머리":["상황","제공할 정보","등기기록 기록"],"행":[["거래부동산 1개, 매도인·매수인 각 1명","거래가액(신청정보), 거래계약신고필증정보(첨부정보)","갑구 권리자 및 기타사항란에 거래가액"],["거래부동산 2개 이상","위 정보와 매매목록","갑구 권리자 및 기타사항란에 매매목록 번호"],["거래부동산 1개, 매도인·매수인이 여럿","위 정보와 매매목록","갑구 권리자 및 기타사항란에 매매목록 번호"],["거래가액의 의미","「부동산 거래신고 등에 관한 법률」 제3조에 따라 신고한 금액","규칙 제124조제1항"]]}],"함정":"거래가액이 기록되는 곳을 등기원인란으로 착각하게 하는 문항이다. 등기원인란에는 원인과 연월일이 들어가고, 거래가액은 권리자 및 기타사항란에 들어간다. 매매목록이 필요한 두 경우(부동산 2개 이상, 당사자 여럿)도 함께 묻는다."},"33회-1차-003":{"한줄":"소유권이 인정되지 않는 바다와 육지 사이의 해변 토지는 빈지이고, 포락지는 지적공부에 등록된 토지가 물에 침식되어 수면 밑으로 잠긴 토지다.","근거":[{"법령":"도시개발법","조문":"제34조제1항","원문":"시행자는 도시개발사업에 필요한 경비에 충당하거나 규약ㆍ정관ㆍ시행규정 또는 실시계획으로 정하는 목적을 위하여 일정한 토지를 환지로 정하지 아니하고 보류지로 정할 수 있으며, 그 중 일부를 체비지로 정하여 도시개발사업에 필요한 경비에 충당할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"환지는 사업 후 토지소유자에게 재분배하는 토지다. 환지 계획은 도시개발법 제28조에 따라 작성한다."},{"번호":2,"판정":"옳음","설명":"법지는 소유는 인정되나 이용 가치가 낮은 경사진 부분이다."},{"번호":3,"판정":"옳음","설명":"선하지는 고압송전선로 아래 토지로 이용에 제한이 따른다."},{"번호":4,"판정":"틀림","설명":"소유권이 인정되지 않는 바다와 육지 사이 해변 토지는 빈지다. 포락지는 물에 침식되어 수면 밑으로 잠긴 지적공부 등록 토지다."},{"번호":5,"판정":"옳음","설명":"체비지는 보류지 중 사업 경비에 충당하려고 정한 토지다(도시개발법 제34조제1항)."}],"개념":[{"종류":"표","제목":"이용 상태·관계에 따른 토지 용어","머리":["용어","뜻"],"행":[["나지","건물 등 정착물이 없고 지상권 등 사법상 권리가 설정되지 않은 토지"],["건부지","건물 등의 부지로 이용 중인 토지"],["공지","건폐율·용적률 제한으로 건축하지 않고 남겨둔 부분의 토지"],["법지","소유는 인정되나 이용 가치가 낮은 경사진 부분의 토지"],["빈지","소유권이 인정되지 않는 바다와 육지 사이의 해변 토지"],["포락지","지적공부에 등록된 토지가 물에 침식되어 수면 밑으로 잠긴 토지"],["선하지","고압송전선로 아래의 토지"]]},{"종류":"표","제목":"단위·전환·사업과 관련된 용어","머리":["용어","뜻"],"행":[["필지","법률적(지적공부상) 토지 등록 단위"],["획지","경제적 단위로 가격수준이 비슷한 일단의 토지"],["후보지","용도적 지역(택지·농지·임지) 간 전환 과정에 있는 토지"],["이행지","한 용도적 지역 안에서 세분된 지역 간 전환 과정에 있는 토지"],["환지","도시개발사업 후 토지소유자에게 재분배하는 토지"],["보류지","환지로 정하지 않고 남겨두는 토지(체비지·공공시설 용지)"],["체비지","보류지 중 사업 경비에 충당하기 위한 토지"]]}],"함정":"빈지와 포락지를 바꿔 외우면 4번을 놓친다. 소유권 부정은 빈지, 침식으로 잠김은 포락지다."},"33회-1차-024":{"한줄":"수익률법과 승수법은 투자현금흐름의 시간가치를 반영하지 않는 어림셈법이다. 시간가치를 반영하는 방법은 순현가법·내부수익률법·수익성지수법이다.","근거":[{"이론":"투자분석기법의 분류","내용":"어림셈법(비할인법)은 회수기간법·승수법·수익률법·비율분석법이고 현금흐름의 시간가치를 반영하지 않는다. 할인현금흐름분석법은 순현가·내부수익률·수익성지수이며 시간가치를 반영한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"수익률법과 승수법은 시간가치를 반영하지 않는다. 시간가치를 반영하는 것은 순현가법·내부수익률법·수익성지수법이다."},{"번호":2,"판정":"옳음","설명":"부(−)와 정(+)의 현금흐름이 여러 번 바뀌면 순현가를 0으로 만드는 할인율이 둘 이상 나올 수 있다."},{"번호":3,"판정":"옳음","설명":"세후지분투자수익률은 세후현금수지÷지분투자액이다."},{"번호":4,"판정":"옳음","설명":"총소득승수는 총투자액÷총소득이므로 총투자액 기준이다. 세전·세후현금수지승수는 지분투자액 기준이다."},{"번호":5,"판정":"옳음","설명":"총부채상환비율(DTI)은 연간 원리금 상환액÷연소득이다. 높을수록 소득에서 원리금이 차지하는 몫이 커서 채무불이행 위험이 높다."}],"개념":[{"종류":"표","제목":"투자분석기법 분류","머리":["구분","기법","시간가치","기준 자본"],"행":[["어림셈법","회수기간법","반영하지 않음","투자액"],["어림셈법","승수법(총소득승수·순소득승수·세전/세후현금수지승수)","반영하지 않음","총투자액 또는 지분투자액"],["어림셈법","수익률법(종합자본환원율·세전/세후지분투자수익률)","반영하지 않음","총투자액 또는 지분투자액"],["어림셈법","비율분석법(대부비율·부채감당률·채무불이행률 등)","반영하지 않음","-"],["할인현금흐름분석법","순현가법·내부수익률법·수익성지수법","반영함","투자 지출의 현재가치"]]},{"종류":"표","제목":"승수와 수익률의 대응(서로 역수)","머리":["승수","식","대응 수익률","식"],"행":[["총소득승수","총투자액÷총소득","총소득률","총소득÷총투자액"],["순소득승수","총투자액÷순영업소득","종합자본환원율","순영업소득÷총투자액"],["세전현금수지승수","지분투자액÷세전현금수지","세전지분투자수익률","세전현금수지÷지분투자액"],["세후현금수지승수","지분투자액÷세후현금수지","세후지분투자수익률","세후현금수지÷지분투자액"]]}],"함정":"수익률법·승수법을 할인현금흐름분석법과 섞어 읽는 것이 오답 경로이다. 이름에 '수익률'이 들어가도 시간가치를 반영하는 방법이 아니다."},"33회-1차-036":{"한줄":"시장가치 외의 가치를 기준으로 감정평가할 때에는 그 가치의 성격과 특징을 검토해야 한다(법령에 다른 규정이 있는 경우는 제외).","근거":[{"법령":"감정평가에 관한 규칙","조문":"제5조제1항","원문":"① 대상물건에 대한 감정평가액은 시장가치를 기준으로 결정한다."},{"법령":"감정평가에 관한 규칙","조문":"제5조제2항","원문":"② 감정평가법인등은 제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 대상물건의 감정평가액을 시장가치 외의 가치를 기준으로 결정할 수 있다.\n1. 법령에 다른 규정이 있는 경우\n2. 감정평가 의뢰인(이하 \"의뢰인\"이라 한다)이 요청하는 경우\n3. 감정평가의 목적이나 대상물건의 특성에 비추어 사회통념상 필요하다고 인정되는 경우"},{"법령":"감정평가에 관한 규칙","조문":"제5조제3항","원문":"③ 감정평가법인등은 제2항에 따라 시장가치 외의 가치를 기준으로 감정평가할 때에는 다음 각 호의 사항을 검토해야 한다. 다만, 제2항제1호의 경우에는 그렇지 않다."},{"법령":"감정평가에 관한 규칙","조문":"제5조제4항","원문":"④ 감정평가법인등은 시장가치 외의 가치를 기준으로 하는 감정평가의 합리성 및 적법성이 결여(缺如)되었다고 판단할 때에는 의뢰를 거부하거나 수임(受任)을 철회할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"감정평가액은 시장가치를 기준으로 결정하는 것이 원칙이다(제5조제1항)."},{"번호":2,"판정":"옳음","설명":"법령에 다른 규정이 있으면 시장가치 외의 가치를 기준으로 결정할 수 있다(제5조제2항제1호)."},{"번호":3,"판정":"옳음","설명":"감정평가의 목적이나 대상물건의 특성에 비추어 사회통념상 필요하다고 인정되면 시장가치 외의 가치를 기준으로 할 수 있다(제5조제2항제3호)."},{"번호":4,"판정":"틀림","설명":"시장가치 외의 가치를 기준으로 할 때에는 그 가치의 성격과 특징, 감정평가의 합리성과 적법성을 검토해야 한다(제5조제3항). 법령에 다른 규정이 있는 경우만 검토를 면한다."},{"번호":5,"판정":"옳음","설명":"합리성과 적법성이 결여되었다고 판단하면 의뢰를 거부하거나 수임을 철회할 수 있다(제5조제4항)."}],"개념":[{"종류":"표","제목":"시장가치 외의 가치를 기준으로 할 수 있는 경우","머리":["사유","검토 사항","합리성·적법성 결여 시"],"행":[["법령에 다른 규정이 있는 경우","검토하지 않는다","-"],["의뢰인이 요청하는 경우","그 가치의 성격과 특징, 합리성과 적법성","의뢰 거부·수임 철회 가능"],["목적이나 대상물건의 특성상 사회통념상 필요한 경우","그 가치의 성격과 특징, 합리성과 적법성","의뢰 거부·수임 철회 가능"]]},{"종류":"표","제목":"기본적 사항의 확정과 용어","머리":["용어·원칙","내용","근거"],"행":[["시장가치","통상적인 시장에서 충분한 기간 공개된 뒤 정통한 당사자 사이에 신중하고 자발적인 거래가 있을 경우 성립될 가능성이 가장 높다고 인정되는 가액","제2조제1호"],["기준시점","감정평가액을 결정하는 기준이 되는 날짜(가격조사를 완료한 날짜가 원칙)","제2조제2호, 제9조제2항"],["기준가치","감정평가의 기준이 되는 가치","제2조제3호"],["현황기준","기준시점의 이용상황(불법적·일시적 이용 제외)과 공법상 제한을 받는 상태 기준","제6조제1항"],["감정평가조건","기준시점의 가치형성요인 등을 실제와 다르게 가정하거나 특수한 경우로 한정하는 조건","제6조제2항"]]}],"함정":"시장가치 외의 가치를 쓸 수 있는 세 사유 중 법령 규정 하나만 검토 의무가 없다. 의뢰인이 요청한 경우에도 성격·특징을 검토해야 한다."},"33회-1차-041":{"한줄":"유증은 유언자 한 사람의 의사표시만으로 성립하고 의사표시를 받을 상대방이 없는 단독행위이다.","근거":[{"법령":"민법","조문":"제1073조제1항","원문":"①유언은 유언자가 사망한 때로부터 그 효력이 생긴다."},{"법령":"민법","조문":"제1074조제1항","원문":"①유증을 받을 자는 유언자의 사망후에 언제든지 유증을 승인 또는 포기할 수 있다."},{"법령":"민법","조문":"제142조","원문":"취소할 수 있는 법률행위의 상대방이 확정한 경우에는 그 취소는 그 상대방에 대한 의사표시로 하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"취소는 상대방이 확정되어 있으면 그 상대방에 대한 의사표시로 한다(제142조). 상대방 있는 단독행위이다."},{"번호":2,"판정":"틀림","설명":"추인은 상대방에 대하여 하지 않으면 그 상대방에게 대항하지 못한다(제132조). 상대방 있는 단독행위이다."},{"번호":3,"판정":"틀림","설명":"동의는 동의를 받을 미성년자에게 하는 의사표시이다(제5조제1항). 상대방 있는 단독행위이다."},{"번호":4,"판정":"옳음","설명":"유증은 유언자의 단독 의사표시로 성립하고 유언자 사망 때 효력이 생긴다(제1073조제1항). 수증자의 승낙은 성립요건이 아니다."},{"번호":5,"판정":"틀림","설명":"해제는 상대방에 대한 의사표시로 한다(제543조제1항). 상대방 있는 단독행위이다."}],"개념":[{"종류":"표","제목":"법률행위의 구분: 의사표시의 수와 상대방","머리":["구분","특징","대표 예"],"행":[["상대방 없는 단독행위","의사표시 1개, 받을 사람 없음","유언·유증, 재단법인 설립(출연), 소유권 포기"],["상대방 있는 단독행위","의사표시 1개, 상대방에게 도달해야 함","취소·추인·동의·철회, 해제·해지, 채무면제, 상계"],["계약","서로 대립하는 의사표시 2개의 합치","매매·증여·임대차·사인증여"],["합동행위","방향이 같은 의사표시 여럿의 합치","사단법인 설립행위"]]},{"종류":"표","제목":"채권행위·물권행위·준물권행위","머리":["구분","효과","예"],"행":[["채권행위","채권·채무 발생","매매·임대차·증여"],["물권행위","물권 변동이 바로 생김","소유권이전의 합의와 등기, 저당권 설정"],["준물권행위","물권 이외의 권리가 바로 변동","채권양도, 채무면제"]]}],"함정":"유증을 받는 사람이 있으니 상대방이 있다고 보기 쉽다. 유증은 수증자의 승낙 없이 성립하고 승인·포기는 사망 뒤 따로 한다. 취소·추인·동의·해제는 모두 상대방에게 가는 의사표시다. 사인증여는 계약이어서 유증과 구별한다."},"33회-2차-004":{"한줄":"공인중개사자격증은 합격자 결정 공고일부터 1개월 이내에 교부한다. 2개월이 아니다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제3조제1항","원문":"특별시장ㆍ광역시장ㆍ도지사ㆍ특별자치도지사(이하 \"시ㆍ도지사\"라 한다)는 「공인중개사법」(이하 \"법\"이라 한다) 제5조제1항에 따른 시험합격자의 결정 공고일부터 1개월 이내에 시험합격자에 관한 사항을 별지 제2호서식의 공인중개사자격증교부대장에 기재한 후, 시험 합격자에게 별지 제3호서식의 공인중개사자격증을 교부하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"제3조제2항","원문":"법 제5조제3항의 규정에 따라 공인중개사자격증의 재교부를 신청하는 자는 별지 제4호서식의 재교부신청서를 자격증을 교부한 시ㆍ도지사에게 제출하여야 한다."},{"법령":"공인중개사법","조문":"제47조제1항제2호","원문":"제5조제3항에 따라 공인중개사자격증의 재교부를 신청하는 자"},{"법령":"공인중개사법","조문":"제7조제1항","원문":"공인중개사는 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 자기의 공인중개사자격증을 양도 또는 대여하여서는 아니된다."},{"법령":"공인중개사법","조문":"제49조제1항제2호","원문":"제8조의 규정을 위반하여 공인중개사가 아닌 자로서 공인중개사 또는 이와 유사한 명칭을 사용한 자"}],"선지":[{"번호":1,"판정":"틀림","설명":"교부기한은 공고일부터 1개월 이내다(시행규칙 제3조제1항)."},{"번호":2,"판정":"옳음","설명":"재교부는 재교부신청서(별지 제4호서식)를 자격증을 교부한 시ㆍ도지사에게 제출해 신청한다(시행규칙 제3조제2항, 법 제5조제3항)."},{"번호":3,"판정":"옳음","설명":"재교부 신청자는 해당 지방자치단체의 조례로 정한 수수료를 낸다(법 제47조제1항제2호)."},{"번호":4,"판정":"옳음","설명":"유상ㆍ무상을 가리지 않고 자격증을 양도ㆍ대여할 수 없다(법 제7조제1항)."},{"번호":5,"판정":"옳음","설명":"공인중개사가 아니면서 공인중개사 명칭을 쓰면 1년 이하의 징역 또는 1천만원 이하의 벌금이다(법 제8조, 제49조제1항제2호)."}],"개념":[{"종류":"표","제목":"공인중개사자격증과 자격 관련 규정 모음","머리":["구분","내용","근거"],"행":[["교부","합격자 결정 공고일부터 1개월 이내, 시ㆍ도지사가 교부","시행규칙 제3조제1항"],["재교부","잃어버리거나 못쓰게 된 경우, 교부한 시ㆍ도지사에게 신청","법 제5조제3항, 시행규칙 제3조제2항"],["수수료","지방자치단체 조례로 정함(국토교통부장관이 시행하는 시험의 응시수수료는 장관이 결정ㆍ공고)","법 제47조제1항"],["양도ㆍ대여 금지","양도ㆍ대여, 양수ㆍ대여받아 사용, 이를 알선하는 행위 금지","법 제7조"],["유사명칭 금지","공인중개사 아닌 자의 사용 금지, 1년 이하 징역 또는 1천만원 이하 벌금","법 제8조, 제49조제1항제2호"],["반납","자격취소처분을 받은 날부터 7일 이내 교부한 시ㆍ도지사에게 반납","법 제35조제3항, 시행규칙 제21조"]]},{"종류":"비교","제목":"자격취소와 자격정지","왼쪽":{"이름":"자격취소(법 제35조)","항목":["처분권자: 시ㆍ도지사, 청문 필수","사유: 부정한 방법으로 자격 취득, 자격증 양도ㆍ대여, 자격정지기간 중 중개업무, 형법 일정 조문 위반으로 금고 이상 형 선고(집행유예 포함)","효과: 자격증 반납, 취소 후 3년간 공인중개사가 될 수 없음(법 제6조)","필요적 취소(하여야 한다)"]},"오른쪽":{"이름":"자격정지(법 제36조)","항목":["처분권자: 시ㆍ도지사","대상: 소속공인중개사로서 업무를 수행하는 기간 중의 공인중개사","사유: 이중소속, 인장 미등록ㆍ미사용, 확인ㆍ설명 소홀, 서명날인 누락, 거래계약서 거짓 기재, 금지행위","기간: 6개월의 범위에서 정함, 임의적 처분(할 수 있다)"]}}],"함정":"숫자 하나를 바꾼 선지다. 교부기한 1개월을 2개월로 늘렸을 뿐 나머지 네 선지는 모두 사실이라, 합격 후 절차의 기한을 알면 바로 가려진다."},"33회-2차-037":{"한줄":"임차는 권리취득용(Ⅱ)에 적으며, 항목은 희망물건의 종류, 취득 희망가격, 희망 지역, 그 밖의 희망조건이다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제13조","원문":"영 제19조의 규정에 따른 일반중개계약서는 별지 제14호서식에 따른다."},{"법령":"공인중개사법 시행규칙","조문":"별지 제14호서식(뒤쪽) Ⅱ","원문":"Ⅱ. 권리취득용(매수ㆍ임차 등): 희망물건의 종류 / 취득 희망가격 / 희망 지역 / 그 밖의 희망조건 / 첨부서류(중개보수 요율표)"},{"법령":"공인중개사법","조문":"제22조","원문":"중개의뢰인은 중개의뢰내용을 명확하게 하기 위하여 필요한 경우에는 개업공인중개사에게 다음 각 호의 사항을 기재한 일반중개계약서의 작성을 요청할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"소유자 및 등기명의인은 권리이전용(매도ㆍ임대 등) 항목이다."},{"번호":2,"판정":"틀림","설명":"은행융자ㆍ권리금ㆍ제세공과금 등(또는 월임대료ㆍ보증금ㆍ관리비 등)은 권리이전용의 '권리관계'란이다."},{"번호":3,"판정":"틀림","설명":"중개의뢰 금액은 권리이전용 항목이다."},{"번호":4,"판정":"옳음","설명":"희망 지역은 권리취득용(매수ㆍ임차 등) 항목이다."},{"번호":5,"판정":"틀림","설명":"거래규제 및 공법상 제한사항은 권리이전용 항목이다."}],"개념":[{"종류":"비교","제목":"일반중개계약서 뒤쪽: 권리이전용과 권리취득용","왼쪽":{"이름":"Ⅰ. 권리이전용(매도ㆍ임대 등)","항목":["구분: 매도ㆍ임대ㆍ그 밖의 사항","소유자 및 등기명의인(성명, 생년월일, 주소)","중개대상물의 표시(건축물ㆍ토지)","권리관계: 은행융자ㆍ권리금ㆍ제세공과금 등(또는 월임대료ㆍ보증금ㆍ관리비 등)","거래규제 및 공법상 제한사항","중개의뢰 금액, 그 밖의 사항"]},"오른쪽":{"이름":"Ⅱ. 권리취득용(매수ㆍ임차 등)","항목":["구분: 매수ㆍ임차ㆍ그 밖의 사항","희망물건의 종류","취득 희망가격","희망 지역","그 밖의 희망조건","첨부서류: 중개보수 요율표"]}},{"종류":"표","제목":"일반중개계약서 앞쪽의 주요 내용","머리":["항목","내용"],"행":[["을(개업공인중개사)의 의무","거래가 조속히 이루어지도록 성실히 노력"],["갑(중개의뢰인)의 권리ㆍ의무","다른 개업공인중개사에게도 중개를 의뢰할 수 있고, 확인ㆍ설명의무 이행에 협조"],["유효기간","3개월을 원칙으로 하되 합의로 별도 정할 수 있음"],["중개보수","거래가액의 일정 비율(또는 금액), 뒤쪽 별표의 요율을 넘지 않아야 하며 실비는 별도 지급"],["손해배상 책임","보수ㆍ실비 과다수령은 차액 환급, 확인ㆍ설명 소홀로 재산상 피해를 낸 경우 손해액 배상"],["작성","계약서 2통을 작성해 쌍방이 1통씩 보관"]]}],"함정":"서식 뒤쪽이 거래 방향에 따라 둘로 나뉜다는 점을 놓치면 권리이전용 항목(소유자, 권리관계, 공법상 제한, 중개의뢰 금액)을 임차인 계약서에 적게 된다."},"33회-2차-015":{"한줄":"법정 중개보수 초과 수수는 제33조제1항제3호 금지행위로, 1년 이하의 징역 또는 1천만원 이하의 벌금이다(법 제49조제1항제10호).","근거":[{"법령":"공인중개사법","조문":"제48조","원문":"제48조(벌칙) 다음 각 호의 어느 하나에 해당하는 자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.\n1. 제9조에 따른 중개사무소의 개설등록을 하지 아니하고 중개업을 한 자\n2. 거짓이나 그 밖의 부정한 방법으로 중개사무소의 개설등록을 한 자\n3. 제33조제1항제5호부터 제9호까지의 규정을 위반한 자\n4. 제33조제2항 각 호의 규정을 위반한 자"},{"법령":"공인중개사법","조문":"제49조 제1항","원문":"①다음 각 호의 어느 하나에 해당하는 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.\n1. 제7조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도ㆍ대여한 자 또는 다른 사람의 공인중개사자격증을 양수ㆍ대여받은 자\n1의2. 제7조제3항을 위반하여 같은 조 제1항 및 제2항에서 금지한 행위를 알선한 자\n2. 제8조의 규정을 위반하여 공인중개사가 아닌 자로서 공인중개사 또는 이와 유사한 명칭을 사용한 자\n3. 제12조의 규정을 위반하여 이중으로 중개사무소의 개설등록을 하거나 둘 이상의 중개사무소에 소속된 자\n4. 제13조제1항의 규정을 위반하여 둘 이상의 중개사무소를 둔 자\n5. 제13조제2항의 규정을 위반하여 임시 중개시설물을 설치한 자\n5의2. 제15조제3항을 위반하여 중개보조원을 고용한 자\n6. 제18조제2항의 규정을 위반하여 개업공인중개사가 아닌 자로서 \"공인중개사사무소\", \"부동산중개\" 또는 이와 유사한 명칭을 사용한 자\n6의2. 제18조의2제3항을 위반하여 개업공인중개사가 아닌 자로서 중개업을  하기 위하여 중개대상물에 대한 표시ㆍ광고를 한 자\n7. 제19조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명 또는 상호를 사용하여 중개업무를 하게 하거나 중개사무소등록증을 다른 사람에게 양도ㆍ대여한 자 또는 다른 사람의 성명ㆍ상호를 사용하여 중개업무를 하거나 중개사무소등록증을 양수ㆍ대여받은 자\n7의2. 제19조제3항을 위반하여 같은 조 제1항 및 제2항에서 금지한 행위를 알선한 자\n8. 제24조제4항의 규정을 위반하여 정보를 공개한 자\n9. 제29조제2항의 규정을 위반하여 업무상 비밀을 누설한 자\n10. 제33조제1항제1호부터 제4호까지의 규정을 위반한 자"},{"법령":"공인중개사법","조문":"제33조 제1항","원문":"① 개업공인중개사등은 다음 각 호의 행위를 하여서는 아니된다.\n1. 제3조에 따른 중개대상물의 매매를 업으로 하는 행위\n2. 제9조에 따른 중개사무소의 개설등록을 하지 아니하고 중개업을 영위하는 자인 사실을 알면서 그를 통하여 중개를 의뢰받거나 그에게 자기의 명의를 이용하게 하는 행위\n3. 사례ㆍ증여 그 밖의 어떠한 명목으로도 제32조에 따른 보수 또는 실비를 초과하여 금품을 받는 행위\n4. 해당 중개대상물의 거래상의 중요사항에 관하여 거짓된 언행 그 밖의 방법으로 중개의뢰인의 판단을 그르치게 하는 행위\n5. 관계 법령에서 양도ㆍ알선 등이 금지된 부동산의 분양ㆍ임대 등과 관련 있는 증서 등의 매매ㆍ교환 등을 중개하거나 그 매매를 업으로 하는 행위\n6. 중개의뢰인과 직접 거래를 하거나 거래당사자 쌍방을 대리하는 행위\n7. 탈세 등 관계 법령을 위반할 목적으로 소유권보존등기 또는 이전등기를 하지 아니한 부동산이나 관계 법령의 규정에 의하여 전매 등 권리의 변동이 제한된 부동산의 매매를 중개하는 등 부동산투기를 조장하는 행위\n8. 부당한 이익을 얻거나 제3자에게 부당한 이익을 얻게 할 목적으로 거짓으로 거래가 완료된 것처럼 꾸미는 등 중개대상물의 시세에 부당한 영향을 주거나 줄 우려가 있는 행위\n9. 단체를 구성하여 특정 중개대상물에 대하여 중개를 제한하거나 단체 구성원 이외의 자와 공동중개를 제한하는 행위"}],"선지":[{"번호":1,"판정":"옳음","설명":"양도·알선이 금지된 분양·임대 관련 증서의 매매·교환 중개는 제33조제1항제5호이고, 3년 이하의 징역 또는 3천만원 이하의 벌금이다(법 제48조제3호)."},{"번호":2,"판정":"틀림","설명":"제33조제1항제3호 위반이므로 1년 이하의 징역 또는 1천만원 이하의 벌금이다(법 제49조제1항제10호)."},{"번호":3,"판정":"옳음","설명":"직접 거래는 제33조제1항제6호이고 3년 이하의 징역 또는 3천만원 이하의 벌금이다(법 제48조제3호)."},{"번호":4,"판정":"옳음","설명":"거래당사자 쌍방 대리도 제33조제1항제6호다. 같은 벌칙을 받는다."},{"번호":5,"판정":"옳음","설명":"단체를 구성하여 특정 중개대상물의 중개를 제한하는 행위는 제33조제1항제9호이고 3년 이하의 징역 또는 3천만원 이하의 벌금이다."}],"개념":[{"종류":"비교","제목":"금지행위의 형량 경계 (법 제33조제1항)","왼쪽":{"이름":"1년 이하 징역·1천만원 이하 벌금 (제49조제1항제10호)","항목":["제1호: 중개대상물 매매업","제2호: 무등록 중개업자와 거래하거나 명의를 이용하게 하는 행위","제3호: 보수·실비를 초과하는 금품 수수","제4호: 거래상 중요사항에 관한 거짓된 언행"]},"오른쪽":{"이름":"3년 이하 징역·3천만원 이하 벌금 (제48조제3호)","항목":["제5호: 양도·알선이 금지된 증서 등의 매매·중개, 그 매매업","제6호: 직접 거래, 쌍방 대리","제7호: 미등기 전매 등 투기 조장","제8호: 거짓 거래완료 등 시세 부당 영향","제9호: 단체 구성으로 중개·공동중개 제한"]}},{"종류":"표","제목":"징역·벌금 대상 비교","머리":["벌칙","대상 행위"],"행":[["3년 이하 · 3천만원 이하 (제48조)","무등록 중개업, 거짓·부정 개설등록, 제33조제1항제5호~제9호, 제33조제2항(업무방해)"],["1년 이하 · 1천만원 이하 (제49조제1항)","자격증·등록증 양도·대여와 알선, 유사명칭, 이중등록·이중소속, 둘 이상의 중개사무소, 임시 중개시설물, 중개보조원 수 초과, 개업공인중개사 아닌 자의 명칭·표시·광고, 정보 부당 공개, 비밀 누설, 제33조제1항제1호~제4호"],["양벌규정 (제50조)","소속공인중개사·중개보조원·법인 사원·임원이 중개업무에 관해 위반하면 행위자를 벌하는 외에 개업공인중개사에게도 벌금형. 상당한 주의·감독을 다했으면 제외"]]}],"함정":"금지행위 9가지 중 앞의 4가지(제1호~제4호)는 1년·1천만원, 뒤의 5가지(제5호~제9호)는 3년·3천만원으로 갈린다. 초과 수수는 앞쪽에 속한다."},"33회-2차-054":{"한줄":"준공검사를 받은 시행자는 60일 이내에 환지처분을 하여야 한다.","근거":[{"법령":"도시개발법 시행령","조문":"제65조","원문":"법 제40조제4항에서 \"대통령령으로 정하는 기간\"이란 60일 이내를 말한다."},{"법령":"도시개발법","조문":"제40조제4항","원문":"④ 시행자는 지정권자에 의한 준공검사를 받은 경우(지정권자가 시행자인 경우에는 제51조에 따른 공사 완료 공고가 있는 때)에는 대통령령으로 정하는 기간에 환지처분을 하여야 한다."},{"법령":"도시개발법","조문":"제40조제2항","원문":"② 도시개발구역의 토지 소유자나 이해관계인은 제1항의 공람 기간에 시행자에게 의견서를 제출할 수 있으며, 의견서를 받은 시행자는 공사 결과와 실시계획 내용에 맞는지를 확인하여 필요한 조치를 하여야 한다."},{"법령":"도시개발법","조문":"제41조제1항","원문":"① 환지를 정하거나 그 대상에서 제외한 경우 그 과부족분(過不足分)은 종전의 토지 … 및 환지의 위치ㆍ지목ㆍ면적ㆍ토질ㆍ수리ㆍ이용 상황ㆍ환경, 그 밖의 사항을 종합적으로 고려하여 금전으로 청산하여야 한다."},{"법령":"도시개발법","조문":"제40조제5항","원문":"⑤ 시행자는 환지처분을 하려는 경우에는 환지 계획에서 정한 사항을 토지 소유자에게 알리고 대통령령으로 정하는 바에 따라 이를 공고하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"공사 관계 서류의 공람 기간에 토지 소유자와 이해관계인이 의견서를 낼 수 있다(법 제40조제2항)."},{"번호":2,"판정":"옳음","설명":"환지의 과부족분은 금전으로 청산한다(법 제41조제1항)."},{"번호":3,"판정":"틀림","설명":"환지처분 기한은 준공검사를 받은 날부터 60일 이내다(법 제40조제4항, 영 제65조)."},{"번호":4,"판정":"옳음","설명":"환지 계획에서 정한 사항을 토지 소유자에게 알리고 관보 또는 공보에 공고한다(법 제40조제5항, 영 제66조제1항)."},{"번호":5,"판정":"옳음","설명":"환지는 공고된 날의 다음 날부터 종전의 토지로 본다(법 제42조제1항)."}],"개념":[{"종류":"표","제목":"환지 관련 기간","머리":["단계","기간","근거"],"행":[["환지 계획 공람","14일 이상(토요일·공휴일 제외)","영 제61조제2항"],["의견 반영 여부 통보","공람 기일이 종료된 날부터 60일 이내","법 제29조제6항"],["공사완료 공고 후 서류 공람","14일 이상","영 제64조제3항"],["환지처분","준공검사를 받은 날부터 60일 이내(지정권자가 시행자이면 공사 완료 공고가 있는 때부터)","법 제40조제4항, 영 제65조"],["등기 촉탁·신청","환지처분 공고 후 14일 이내","법 제43조제1항"],["사용·수익 정지 예고","30일 이상의 기간을 두고 미리 알림","법 제37조제2항"],["입체환지 신청 기간","통지한 날부터 30일 이상 60일 이하(20일 범위에서 연장 가능)","법 제32조제4항"],["청산금 시효","5년","법 제47조"]]},{"종류":"비교","제목":"환지 예정지 지정과 환지처분","왼쪽":{"이름":"환지 예정지 지정(법 제35조·제36조)","항목":["시행자가 필요하면 지정하고, 소유자·임차권자등에게 위치·면적·효력발생 시기를 알린다","효력발생일부터 환지처분 공고일까지 종전 토지는 사용·수익할 수 없고, 환지 예정지에서 종전과 같은 권리를 행사한다","체비지 용도로 지정된 환지 예정지는 시행자가 사용·수익하게 하거나 처분할 수 있다"]},"오른쪽":{"이름":"환지처분(법 제40조~제43조)","항목":["공사 완료 후 준공검사를 받은 날부터 60일 이내에 하고 공고한다","공고된 날의 다음 날부터 환지가 종전 토지로 간주된다","청산금은 공고된 날의 다음 날 확정되고, 공고 후 14일 이내에 등기를 촉탁·신청한다"]}}],"함정":"환지처분 기한은 준공검사를 받은 날부터 60일이다. 90일이라는 기간은 이 절차에 나오지 않는다. 의견 검토 결과 통지(60일), 환지처분(60일), 등기(14일)의 기간이 서로 섞이기 쉽다."},"33회-2차-063":{"한줄":"토지등소유자 전체회의는 신탁업자가 사업시행자인 경우에만 시행규정에 넣는다. 한국토지주택공사 단독시행의 시행규정에는 들어가지 않는다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"제53조","원문":"제53조(시행규정의 작성) 시장ㆍ군수등, 토지주택공사등 또는 신탁업자가 단독으로 정비사업을 시행하는 경우 다음 각 호의 사항을 포함하는 시행규정을 작성하여야 한다.\n1. 정비사업의 종류 및 명칭\n2. 정비사업의 시행연도 및 시행방법\n3. 비용부담 및 회계\n4. 토지등소유자의 권리ㆍ의무\n5. 정비기반시설 및 공동이용시설의 부담\n6. 공고ㆍ공람 및 통지의 방법\n7. 토지 및 건축물에 관한 권리의 평가방법\n8. 관리처분계획 및 청산(분할징수 또는 납입에 관한 사항을 포함한다). 다만, 수용의 방법으로 시행하는 경우는 제외한다.\n9. 시행규정의 변경\n10. 사업시행계획서의 변경\n11. 토지등소유자 전체회의(신탁업자가 사업시행자인 경우로 한정한다)\n12. 그 밖에 시ㆍ도조례로 정하는 사항"}],"선지":[{"번호":1,"판정":"틀림","설명":"제11호 전체회의는 '신탁업자가 사업시행자인 경우로 한정'한다. 토지주택공사등 단독시행에는 해당하지 않는다."},{"번호":2,"판정":"옳음","설명":"제4호. 시행규정 포함사항이다."},{"번호":3,"판정":"옳음","설명":"제7호. 시행규정 포함사항이다."},{"번호":4,"판정":"옳음","설명":"제2호. 시행규정 포함사항이다."},{"번호":5,"판정":"옳음","설명":"제6호. 시행규정 포함사항이다."}],"개념":[{"종류":"표","제목":"시행규정 포함사항(법 제53조)","머리":["호","사항","비고"],"행":[["1","정비사업의 종류 및 명칭",""],["2","정비사업의 시행연도 및 시행방법",""],["3","비용부담 및 회계",""],["4","토지등소유자의 권리ㆍ의무",""],["5","정비기반시설 및 공동이용시설의 부담",""],["6","공고ㆍ공람 및 통지의 방법",""],["7","토지 및 건축물에 관한 권리의 평가방법",""],["8","관리처분계획 및 청산","수용 방법으로 시행하면 제외"],["9","시행규정의 변경",""],["10","사업시행계획서의 변경",""],["11","토지등소유자 전체회의","신탁업자가 사업시행자인 경우만"],["12","그 밖에 시ㆍ도조례로 정하는 사항",""]]},{"종류":"표","제목":"주민대표회의·세입자가 시행규정에 의견을 낼 수 있는 사항(법 제47조제5항)","머리":["호","사항"],"행":[["1","건축물의 철거"],["2","주민의 이주(세입자의 퇴거 포함)"],["3","토지 및 건축물의 보상(세입자 주거이전비 등 포함)"],["4","정비사업비의 부담"],["5","세입자에 대한 임대주택의 공급 및 입주자격"]]}],"함정":"시행규정을 쓰는 주체는 시장·군수등, 토지주택공사등, 신탁업자다. 12개 호 가운데 전체회의 하나만 신탁업자 전용이다. 나머지 사항이 눈에 익어 어디가 예외인지 놓치기 쉽다."},"33회-2차-093":{"한줄":"토지의 표시는 소재와 지번, 지목, 면적을 신청정보로 제공한다.","근거":[{"법령":"부동산등기규칙","조문":"제43조제1항","원문":"제43조(신청정보의 내용)\n① 등기를 신청하는 경우에는 다음 각 호의 사항을 신청정보의 내용으로 등기소에 제공하여야 한다.\n  1. 다음 각 목의 구분에 따른 부동산의 표시에 관한 사항\n    가. 토지 : 법 제34조제3호부터 제5호까지의 규정에서 정하고 있는 사항\n  3. 신청인이 법인인 경우에는 그 대표자의 성명과 주소\n  4. 대리인에 의하여 등기를 신청하는 경우에는 그 성명과 주소\n  7. 등기필정보. 다만, 공동신청 또는 승소한 등기의무자의 단독신청에 의하여 권리에 관한 등기를 신청하는 경우로 한정한다."},{"법령":"부동산등기법","조문":"제34조","원문":"제34조(등기사항) 등기관은 토지 등기기록의 표제부에 다음 각 호의 사항을 기록하여야 한다.\n  1. 표시번호\n  3. 소재와 지번(地番)\n  4. 지목(地目)\n  5. 면적"}],"선지":[{"번호":1,"판정":"틀림","설명":"제공하는 등기필정보는 등기의무자의 것이다. 공동신청 또는 승소한 등기의무자의 단독신청일 때만 제공한다(규칙 제43조제1항제7호)."},{"번호":2,"판정":"옳음","설명":"토지의 표시는 법 제34조제3호부터 제5호까지의 소재와 지번, 지목, 면적이다(규칙 제43조제1항제1호 가목)."},{"번호":3,"판정":"틀림","설명":"표시번호는 법 제34조제1호 사항으로, 규칙 제43조제1항제1호 가목이 정한 제3호~제5호에 들어가지 않는다."},{"번호":4,"판정":"틀림","설명":"신청인이 법인이면 대표자의 성명과 주소를 제공한다(규칙 제43조제1항제3호). 주민등록번호는 포함되지 않는다."},{"번호":5,"판정":"틀림","설명":"대리인에 의한 신청이면 대리인의 성명과 주소를 제공한다(규칙 제43조제1항제4호). 주민등록번호는 포함되지 않는다."}],"개념":[{"종류":"표","제목":"신청정보의 내용(규칙 제43조제1항)","머리":["호","제공 사항"],"행":[["1호","부동산의 표시(토지: 소재와 지번·지목·면적)"],["2호","신청인의 성명(명칭), 주소(사무소 소재지), 주민등록번호(등록번호)"],["3호","신청인이 법인이면 대표자의 성명과 주소"],["4호","대리인에 의한 신청이면 대리인의 성명과 주소"],["5호","등기원인과 그 연월일"],["6호","등기의 목적"],["7호","등기필정보(공동신청·승소한 등기의무자의 단독신청)"],["8호","등기소의 표시"],["9호","신청연월일"]]}],"함정":"법인의 대표자와 대리인은 성명과 주소만 제공하고, 주민등록번호는 신청인 본인에게만 요구한다(법인 아닌 사단의 대표자는 예외로 주민등록번호까지). 등기필정보는 등기권리자가 아니라 등기의무자의 것이다."},"33회-2차-102":{"한줄":"특정 층 전부는 층 표시만으로 범위가 정해지므로 도면을 첨부하지 않는다. 도면은 층의 일부처럼 범위를 그림으로 특정해야 할 때 낸다.","근거":[{"법령":"부동산등기규칙","조문":"제128조제2항","원문":"전세권설정 또는 전전세의 범위가 부동산의 일부인 경우에는 그 부분을 표시한 지적도나 건물도면을 첨부정보로서 등기소에 제공하여야 한다."},{"법령":"부동산등기법","조문":"제72조제1항제1호·제6호","원문":"1. 전세금 또는 전전세금\n6. 전세권설정이나 전전세의 범위가 부동산의 일부인 경우에는 그 부분을 표시한 도면의 번호"},{"법령":"부동산등기법","조문":"제57조제1항","원문":"등기의 말소를 신청하는 경우에 그 말소에 대하여 등기상 이해관계 있는 제3자가 있을 때에는 제3자의 승낙이 있어야 한다."},{"판례":"대법원 판례","요지":"전세권설정계약의 당사자가 전세권자의 사용·수익 권능을 배제하고 채권담보만을 위해 전세권을 설정했다면 그 전세권설정등기는 무효다. 민법 제303조 제1항이 전세권을 사용·수익하는 물권으로 정하기 때문이다."}],"선지":[{"번호":1,"판정":"옳음","설명":"전세금은 전세권설정등기에서 반드시 적는 사항이다(법 제72조제1항제1호). 존속기간·위약금·민법 제306조 단서 약정은 원인에 약정이 있을 때만 적는다."},{"번호":2,"판정":"옳음","설명":"사용·수익을 배제한 채 채권담보만 목적으로 한 전세권설정등기는 무효다(민법 제303조제1항, 대법원 판례)."},{"번호":3,"판정":"옳음","설명":"전유부분과 대지사용권은 분리해 처분할 수 없다(집합건물법 제20조제2항). 대지권 등기를 한 뒤에는 전유부분이나 대지권만을 따로 목적으로 하는 권리등기를 할 수 없다(법 제61조제3항·제4항)."},{"번호":4,"판정":"틀림","설명":"도면은 범위가 부동산의 일부일 때 낸다(규칙 제128조제2항). 특정 층 전부는 층으로 범위가 특정되어 도면 첨부 대상이 아니다."},{"번호":5,"판정":"옳음","설명":"전세권 위에 가압류를 한 丙은 전세권 말소로 불이익을 받는 이해관계인이다. 말소판결이 있어도 丙의 승낙서나 대항 재판의 등본을 첨부한다(법 제57조제1항)."}],"개념":[{"종류":"표","제목":"용익권 설정등기의 기록사항","머리":["권리","반드시 적는 것","약정이 있을 때만","일부 설정 시"],"행":[["지상권(법 제69조)","목적, 범위","존속기간, 지료·지급시기, 민법 제289조의2제1항 후단의 약정","도면 번호"],["지역권(법 제70조)","목적, 범위, 요역지","민법 제292조제1항 단서·제297조제1항 단서·제298조의 약정","승역지 일부면 도면 번호"],["전세권(법 제72조)","전세금, 범위","존속기간, 위약금·배상금, 민법 제306조 단서의 약정","도면 번호"],["임차권(법 제74조)","차임, 범위","차임지급시기, 존속기간, 임차보증금, 양도·전대 동의","도면 번호"]]},{"종류":"표","제목":"전세권 등기 쟁점 모음","머리":["쟁점","결론","근거"],"행":[["일부 설정","도면이나 지적도 첨부, 등기기록에 도면 번호 기록","규칙 제128조제2항, 법 제72조제1항제6호"],["층 전부 설정","층으로 범위가 특정되어 도면 불요","선지 4의 판단"],["전세금반환채권 일부양도","존속기간 만료 전에는 일부이전 신청 불가, 소멸 증명 시 가능","법 제73조제2항"],["일부이전 기록사항","양도액 기록","법 제73조제1항"],["전세권 말소 시 그 위의 가압류권자","승낙서 또는 대항 재판 필요","법 제57조제1항"],["사용·수익 배제 전세권","무효","민법 제303조제1항"]]}],"함정":"선지 5를 틀렸다고 보기 쉽다. 말소판결이 있으면 승낙이 필요 없다고 생각하는 경우다. 판결로 단독신청을 해도 이해관계인의 승낙 요건은 그대로여서 가압류권자 丙의 승낙서나 대항 재판의 등본이 필요하다. 선지 3은 대지권 등기를 한 구분건물이라는 전제를 놓치면 틀려 보인다."},"33회-2차-108":{"한줄":"1년 이상 공용으로 쓰는 재산이라도 소유권 유상이전을 약정하고 취득 전에 미리 사용하는 경우에는 재산세를 부과한다.","근거":[{"법령":"지방세법","조문":"제107조제2항제3호","원문":"② 제1항에도 불구하고 재산세 과세기준일 현재 다음 각 호의 어느 하나에 해당하는 자는 재산세를 납부할 의무가 있다. 3. 공부상에 개인 등의 명의로 등재되어 있는 사실상의 종중재산으로서 종중소유임을 신고하지 아니하였을 때에는 공부상 소유자"},{"법령":"지방세법","조문":"제107조제3항","원문":"③ 재산세 과세기준일 현재 소유권의 귀속이 분명하지 아니하여 사실상의 소유자를 확인할 수 없는 경우에는 그 사용자가 재산세를 납부할 의무가 있다."},{"법령":"지방세법","조문":"제109조제2항","원문":"② 국가, 지방자치단체 또는 지방자치단체조합이 1년 이상 공용 또는 공공용으로 사용(1년 이상 사용할 것이 계약서 등에 의하여 입증되는 경우를 포함한다)하는 재산에 대하여는 재산세를 부과하지 아니한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 재산세를 부과한다. 1. 유료로 사용하는 경우 2. 소유권의 유상이전을 약정한 경우로서 그 재산을 취득하기 전에 미리 사용하는 경우"},{"법령":"지방세법","조문":"제115조제1항","원문":"① 재산세의 납기는 다음 각 호와 같다. 1. 토지: 매년 9월 16일부터 9월 30일까지 2. 건축물: 매년 7월 16일부터 7월 31일까지"},{"법령":"지방세법","조문":"제115조제2항","원문":"② 제1항에도 불구하고 지방자치단체의 장은 과세대상 누락, 위법 또는 착오 등으로 인하여 이미 부과한 세액을 변경하거나 수시부과하여야 할 사유가 발생하면 수시로 부과ㆍ징수할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"종중소유임을 신고하지 않은 사실상 종중재산은 공부상 소유자가 납세의무자다(지방세법 제107조제2항제3호)."},{"번호":2,"판정":"틀림","설명":"국가·지방자치단체가 1년 이상 공용 또는 공공용으로 사용하는 재산은 재산세를 부과하지 않는다. 유료 사용과 소유권 유상이전 약정 후 취득 전 사용은 예외로 과세한다(지방세법 제109조제2항제2호)."},{"번호":3,"판정":"옳음","설명":"소유권 귀속이 분명하지 않아 사실상 소유자를 확인할 수 없으면 사용자가 납세의무자다(지방세법 제107조제3항)."},{"번호":4,"판정":"옳음","설명":"토지는 9월 16일~9월 30일, 건축물은 7월 16일~7월 31일이다(지방세법 제115조제1항제1호·제2호)."},{"번호":5,"판정":"옳음","설명":"과세대상 누락, 위법 또는 착오 등으로 부과세액을 변경하거나 수시부과할 사유가 생기면 납기와 관계없이 수시로 부과·징수할 수 있다(지방세법 제115조제2항)."}],"개념":[{"종류":"표","제목":"재산세 납세의무자 특례(과세기준일 6월 1일 현재, 지방세법 제107조)","머리":["상황","납세의무자"],"행":[["원칙","재산을 사실상 소유하고 있는 자"],["공유재산","지분권자(지분 표시가 없으면 균등한 것으로 봄)"],["주택의 건물과 부속토지 소유자가 다른 경우","산출세액을 시가표준액 비율로 안분해 각 소유자"],["소유권 변동 미신고로 사실상 소유자를 알 수 없음","공부상 소유자"],["상속등기 미이행 + 사실상 소유자 미신고","행정안전부령으로 정하는 주된 상속자"],["공부상 개인 명의의 종중재산 + 종중소유 미신고","공부상 소유자"],["국가·지방자치단체와 연부 매매계약 + 무상 사용권","매수계약자"],["수탁자 명의로 등기·등록된 신탁재산","위탁자(위탁자가 소유한 것으로 봄)"],["환지방식 도시개발·재개발사업의 체비지·보류지","사업시행자"],["소유권 귀속 불분명으로 소유자 확인 불가","사용자"]]},{"종류":"표","제목":"재산세 납기(지방세법 제115조)","머리":["과세대상","납기"],"행":[["토지","9월 16일부터 9월 30일까지"],["건축물","7월 16일부터 7월 31일까지"],["주택","세액의 2분의 1은 7월 16일~7월 31일, 나머지는 9월 16일~9월 30일(부과세액 20만원 이하는 조례로 7월에 한꺼번에 부과 가능)"],["선박","7월 16일부터 7월 31일까지"],["항공기","7월 16일부터 7월 31일까지"],["과세대상 누락·착오 등","수시로 부과·징수"]]}],"함정":"2번은 1년 이상 공용 사용이면 무조건 비과세라는 암기를 노린 선지다. 비과세의 예외가 유료 사용과 유상이전 약정 후 취득 전 사용 두 가지다. 3번의 사용자 납세의무는 소유자를 확인할 수 없을 때만 적용되고, 공부상 소유자를 알 수 없는 경우(제107조제2항제1호)와 구별해야 한다. 4번은 토지와 건축물의 납기월을 서로 바꾸는 숫자 함정이 자주 나온다."},"33회-2차-114":{"한줄":"증여자가 직접 양도한 것으로 보면 당초 증여받은 자산에는 증여세를 부과하지 않으므로, 乙의 증여세를 필요경비에 산입하는 일은 없다.","근거":[{"법령":"소득세법","조문":"제101조제2항","원문":"② 거주자가 제1항에서 규정하는 특수관계인(제97조의2제1항을 적용받는 배우자 및 직계존비속의 경우는 제외한다)에게 자산을 증여한 후 그 자산을 증여받은 자가 그 증여일부터 10년 이내에 다시 타인에게 양도한 경우로서 제1호에 따른 세액이 제2호에 따른 세액보다 적은 경우에는 증여자가 그 자산을 직접 양도한 것으로 본다. 다만, 양도소득이 해당 수증자에게 실질적으로 귀속된 경우에는 그러하지 아니하다. 1. 증여받은 자의 증여세(「상속세 및 증여세법」에 따른 산출세액에서 공제ㆍ감면세액을 뺀 세액을 말한다)와 양도소득세(이 법에 따른 산출세액에서 공제ㆍ감면세액을 뺀 결정세액을 말한다. 이하 제2호에서 같다)를 합한 세액 2. 증여자가 직접 양도하는 경우로 보아 계산한 양도소득세"},{"법령":"소득세법","조문":"제101조제3항","원문":"③ 제2항에 따라 증여자에게 양도소득세가 과세되는 경우에는 당초 증여받은 자산에 대해서는 「상속세 및 증여세법」의 규정에도 불구하고 증여세를 부과하지 아니한다."},{"법령":"소득세법","조문":"제2조의2제3항","원문":"③ 제101조제2항에 따라 증여자가 자산을 직접 양도한 것으로 보는 경우 그 양도소득에 대해서는 증여자와 증여받은 자가 연대하여 납세의무를 진다."},{"법령":"소득세법","조문":"제95조제4항","원문":"④ 제2항에서 규정하는 자산의 보유기간은 그 자산의 취득일부터 양도일까지로 한다. 다만, 제97조의2제1항의 경우에는 증여한 배우자 또는 직계존비속이 해당 자산을 취득한 날부터 기산(起算)하고, 같은 조 제4항제1호에 따른 가업상속공제가 적용된 비율에 해당하는 자산의 경우에는 피상속인이 해당 자산을 취득한 날부터 기산한다."},{"법령":"소득세법","조문":"제97조의2제1항제3호","원문":"① 거주자가 양도일부터 소급하여 10년(제94조제1항제3호에 따른 자산의 경우에는 1년) 이내에 그 배우자(양도 당시 혼인관계가 소멸된 경우를 포함하되, 사망으로 혼인관계가 소멸된 경우는 제외한다. 이하 이 항에서 같다) 또는 직계존비속(양도 당시 사망한 경우는 제외한다. 이하 이 항에서 같다)으로부터 증여받은 제94조제1항제1호 및 제3호에 따른 자산이나 그 밖에 대통령령으로 정하는 자산의 양도차익을 계산할 때 양도가액에서 공제할 필요경비는 제97조제2항에 따르되, 다음 각 호의 기준을 적용한다. 3. 거주자가 해당 자산에 대하여 납부하였거나 납부할 증여세 상당액이 있는 경우 필요경비에 산입한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"증여자에게 양도소득세를 과세하면 당초 증여받은 자산에 증여세를 부과하지 않는다(소득세법 제101조제3항). 증여세 상당액을 필요경비에 넣는 것은 배우자·직계존비속으로부터 증여받은 자산의 이월과세 규정이다(제97조의2제1항제3호)."},{"번호":2,"판정":"옳음","설명":"甲이 그 자산을 직접 양도한 것으로 보므로 취득가액은 甲의 취득 당시 금액 1억원이다(소득세법 제101조제2항)."},{"번호":3,"판정":"옳음","설명":"제101조제2항에 따라 증여자가 직접 양도한 것으로 보는 경우 그 양도소득에 대해 증여자와 수증자가 연대하여 납세의무를 진다(소득세법 제2조의2제3항)."},{"번호":4,"판정":"옳음","설명":"甲이 직접 양도한 것으로 보므로 甲이 양도소득세 납세의무자다(소득세법 제101조제2항)."},{"번호":5,"판정":"옳음","설명":"甲이 직접 양도한 것으로 보므로 보유기간은 甲의 취득일(2016.10.20.)부터 乙의 양도일(2022.6.30.)까지다(소득세법 제95조제4항, 제101조제2항)."}],"개념":[{"종류":"비교","제목":"이월과세와 양도소득의 부당행위계산 부인","왼쪽":{"이름":"이월과세(소득세법 제97조의2)","항목":["증여자: 배우자 또는 직계존비속(양도 당시 사망한 직계존비속은 제외)","기간: 양도일부터 소급해 10년 이내 증여받은 토지·건물 등(주식등 제94조제1항제3호는 1년)","납세의무자: 증여받아 양도한 거주자","취득가액: 증여자가 취득할 당시 금액","증여세 상당액: 필요경비에 산입","보유기간: 증여자가 취득한 날부터 기산"]},"오른쪽":{"이름":"부당행위계산 부인(제101조제2항)","항목":["증여자: 특수관계인(제97조의2제1항 적용 대상 배우자·직계존비속은 제외)","기간: 증여일부터 10년 이내 수증자가 타인에게 양도","요건: 증여세+양도소득세 합계가 증여자 직접 양도 시 양도소득세보다 적고, 양도소득이 수증자에게 실질 귀속되지 않음","효과: 증여자가 직접 양도한 것으로 보아 증여자·수증자가 연대납세","증여세: 부과하지 않음(제101조제3항)"]}},{"종류":"계산","제목":"乙의 양도로 보지 않고 甲이 직접 양도한 것으로 본 양도차익(다른 필요경비 없음, 가정)","단계":[{"설명":"乙 기준 양도차익이라면(취득가액 증여 시가 3억원)","식":"10억원 − 3억원","값":"7억원"},{"설명":"甲이 직접 양도한 것으로 보면 취득가액은 甲의 취득 당시 1억원","식":"10억원 − 1억원","값":"9억원"},{"설명":"보유기간은 甲 취득일 2016.10.20.부터 양도일 2022.6.30.까지 5년 8개월이므로 5년 이상 6년 미만 구간의 장기보유특별공제율 100분의 10(표 1)","식":"9억원 × 10%","값":"9천만원"},{"설명":"양도소득금액","식":"9억원 − 9천만원","값":"8억1천만원"}]}],"함정":"1번은 이월과세에서 증여세 상당액을 필요경비에 넣는 규정과 섞은 선지다. 부당행위 부인은 증여세를 부과하지 않는 구조라서 필요경비 산입 대상 자체가 없다. 3번의 연대납세는 제2조의2제3항에서 나오고, 4번 납세의무자는 증여자 甲이다. 乙이 형제여서 이월과세(배우자·직계존비속)가 아닌 제101조제2항이 적용된다는 점이 출발점이다.","개정":"현행 제101조제2항은 증여일부터 10년 이내 재양도를 기준으로 하며 2022.12.31. 개정 표시가 붙어 있다. 이 문항은 증여(2019.10.1.)와 양도(2022.6.30.)의 간격이 3년이 안 되어 기간 기준이 5년이든 10년이든 결론이 같다."},"33회-2차-118":{"한줄":"결정·경정으로 총결정세액이 기납부세액을 넘으면 그 초과액(추가납부세액)을 거주자에게 알린 날부터 30일 이내에 징수한다.","근거":[{"법령":"소득세법","조문":"제116조제2항","원문":"② 납세지 관할 세무서장은 제114조에 따라 양도소득과세표준과 세액을 결정 또는 경정한 경우 제92조제3항제3호에 따른 양도소득 총결정세액이 다음 각 호의 금액의 합계액을 초과할 때에는 그 초과하는 세액(이하 \"추가납부세액\"이라 한다)을 해당 거주자에게 알린 날부터 30일 이내에 징수한다. 1. 제106조에 따른 예정신고납부세액과 제111조에 따른 확정신고납부세액 2. 제1항에 따라 징수하는 세액 3. 제82조 및 제118조에 따른 수시부과세액 4. 제156조제1항제5호에 따라 원천징수한 세액"},{"법령":"소득세법","조문":"제117조","원문":"제117조(양도소득세의 환급) 납세지 관할 세무서장은 과세기간별로 제116조제2항 각 호의 금액의 합계액이 제92조제3항제3호에 따른 양도소득 총결정세액을 초과할 때에는 그 초과하는 세액을 환급하거나 다른 국세 및 강제징수비에 충당하여야 한다."},{"법령":"소득세법","조문":"제105조제1항제3호","원문":"① 제94조제1항 각 호(같은 항 제3호다목 및 같은 항 제5호는 제외한다)에서 규정하는 자산을 양도한 거주자는 제92조제2항에 따라 계산한 양도소득과세표준을 다음 각 호의 구분에 따른 기간에 대통령령으로 정하는 바에 따라 납세지 관할 세무서장에게 신고하여야 한다. 3. 제1호 및 제2호에도 불구하고 제88조제1호 각 목 외의 부분 후단에 따른 부담부증여의 채무액에 해당하는 부분으로서 양도로 보는 경우에는 그 양도일이 속하는 달의 말일부터 3개월"},{"법령":"국세기본법","조문":"제22조제2항","원문":"② 다음 각 호의 국세는 납세의무자가 과세표준과 세액을 정부에 신고했을 때에 확정된다. 다만, 납세의무자가 과세표준과 세액의 신고를 하지 아니하거나 신고한 과세표준과 세액이 세법에서 정하는 바와 맞지 아니한 경우에는 정부가 과세표준과 세액을 결정하거나 경정하는 때에 그 결정 또는 경정에 따라 확정된다. 1. 소득세"}],"선지":[{"번호":1,"판정":"틀림","설명":"기납부 확정신고세액이 총결정세액을 초과하면 그 초과액을 환급하거나 다른 국세 및 강제징수비에 충당하여야 한다(소득세법 제117조)."},{"번호":2,"판정":"옳음","설명":"총결정세액이 예정·확정신고납부세액 등의 합계를 초과하면 초과분을 해당 거주자에게 알린 날부터 30일 이내에 징수한다(소득세법 제116조제2항)."},{"번호":3,"판정":"틀림","설명":"부담부증여의 채무액 해당 부분은 양도일이 속하는 달의 말일부터 3개월 이내에 예정신고를 해야 한다(소득세법 제105조제1항제3호)."},{"번호":4,"판정":"틀림","설명":"소득세는 납세의무자가 과세표준과 세액을 신고한 때 확정된다. 신고를 하지 않았거나 신고 내용이 세법과 맞지 않을 때 정부의 결정·경정으로 확정된다(국세기본법 제22조제2항)."},{"번호":5,"판정":"틀림","설명":"소득세법 제117조는 초과세액의 환급 또는 충당만 정하고 결정일부터 90일 이내라는 기한은 두지 않는다(소득세법 제117조)."}],"개념":[{"종류":"흐름","제목":"양도소득세 신고·결정·징수·환급 절차","단계":[{"이름":"예정신고·납부","설명":"양도일이 속하는 달의 말일부터 2개월 이내(부담부증여의 채무액 해당 부분은 3개월). 양도차익이 없거나 양도차손이어도 신고한다."},{"이름":"확정신고·납부","설명":"다음 연도 5월 1일부터 5월 31일까지. 예정신고를 한 자는 확정신고를 생략할 수 있다. 다만 누진세율 자산에 대한 예정신고를 2회 이상 한 경우 등은 확정신고를 해야 한다."},{"이름":"결정·경정","설명":"신고를 하지 않으면 결정, 신고 내용에 탈루·오류가 있으면 경정한다. 결과는 거주자에게 서면으로 알린다."},{"이름":"추가 징수","설명":"총결정세액이 기납부세액(예정·확정신고납부, 수시부과, 징수된 세액 등)의 합계를 초과하면 초과분을 알린 날부터 30일 이내에 징수한다."},{"이름":"환급·충당","설명":"기납부세액 합계가 총결정세액을 초과하면 그 초과분을 환급하거나 다른 국세 및 강제징수비에 충당한다."}]},{"종류":"표","제목":"국세 납세의무의 확정 방식(국세기본법 제22조)","머리":["확정 방식","해당 국세","확정 시기"],"행":[["신고로 확정","소득세(양도소득세 포함), 법인세, 부가가치세, 개별소비세, 주세, 증권거래세, 교육세, 교통ㆍ에너지ㆍ환경세","납세의무자가 신고한 때. 미신고·신고 오류는 정부의 결정·경정 때"],["신고로 확정(선택)","종합부동산세","제16조제3항에 따라 신고한 때에 한함"],["정부 결정으로 확정","상속세, 증여세 등 위 목록 외의 국세","정부가 과세표준과 세액을 결정하는 때"],["성립과 동시에 확정","인지세, 원천징수 소득세·법인세, 납세조합 징수 소득세 등","납세의무 성립 때"]]}],"함정":"4번의 확정 방식은 신고납세와 부과과세의 구별 문제다. 소득세는 신고로 확정되고 상속세·증여세는 정부 결정으로 확정된다. 3번은 부담부증여도 예정신고 대상이라는 점을 놓친 선지로, 기한이 일반 양도보다 1개월 긴 3개월이라는 차이만 따로 붙는다. 1번은 환급과 충당이 둘 다 가능하다는 점, 5번은 90일 같은 숫자가 법에 없다는 점이 포인트다."},"33회-1차-022":{"한줄":"위험감소효과가 최대인 것은 상관계수가 −1일 때이고, 0일 때가 아니다.","근거":[{"이론":"포트폴리오이론","내용":"상관계수가 +1이면 분산효과가 없고, −1이면 위험감소효과가 최대다. 포트폴리오의 기대수익률은 자산별 기대수익률의 가중평균이다."}],"선지":[{"번호":1,"판정":"틀림","설명":"상관계수가 −1일 때 위험이 가장 크게 줄어든다. 0이면 일부만 줄어든다."},{"번호":2,"판정":"옳음","설명":"포트폴리오 기대수익률 = Σ(투자비중 × 개별자산 기대수익률)."},{"번호":3,"판정":"옳음","설명":"같은 자산이라도 투자비중이 달라지면 기대수익률과 분산이 달라진다."},{"번호":4,"판정":"옳음","설명":"무차별곡선은 효용이 같은 수익-위험 조합을 이은 선이다."},{"번호":5,"판정":"옳음","설명":"위험회피도가 투자자마다 달라 최적 포트폴리오도 달라진다."}],"개념":[{"종류":"표","제목":"상관계수와 분산투자 효과","머리":["상관계수","의미","위험감소효과"],"행":[["+1","같은 방향으로 완전히 움직임","없음"],["0","서로 무관하게 움직임","일부 있음"],["−1","반대 방향으로 완전히 움직임","최대(위험 제거 가능)"],["−1 < r < +1","일반 경우","상관계수가 낮을수록 효과 큼"]]},{"종류":"계산","제목":"포트폴리오 기대수익률","단계":[{"설명":"공식","식":"E(R_p) = Σ(w_i × E(R_i))","값":"가중평균"},{"설명":"대입: A 40%·기대수익률 12%, B 60%·기대수익률 7%","식":"0.4 × 12 + 0.6 × 7 = 4.8 + 4.2","값":"9.0%"}]}],"함정":"상관계수 0과 −1을 혼동한다. 최대 효과는 −1이고, 같은 방향(+1)이면 효과가 없다."},"33회-1차-028":{"한줄":"주택담보노후연금보증은 한국주택금융공사가 하는 업무로 한국주택금융공사법에 규정되어 있다.","근거":[{"법령":"한국주택금융공사법","조문":"제1조","원문":"이 법은 한국주택금융공사를 설립하여 주택저당채권 등의 유동화(流動化)와 주택금융 신용보증 및 주택담보노후연금보증 업무를 수행하게 함으로써 주택금융 등의 장기적ㆍ안정적 공급을 촉진하여 국민의 복지증진과 국민경제의 발전에 이바지함을 목적으로 한다."},{"법령":"한국주택금융공사법","조문":"제22조제1항제9호","원문":"공사는 다음 각 호의 업무를 수행한다. … 9. 주택담보노후연금보증"},{"법령":"한국주택금융공사법","조문":"제2조제8호의2","원문":"\"주택담보노후연금보증\"이란 주택소유자가 주택에 저당권 설정 또는 주택소유자와 공사가 체결하는 신탁계약(주택소유자 또는 주택소유자의 배우자를 수익자로 하되, 공사를 공동수익자로 하는 계약을 말한다)에 따른 신탁을 등기하고 금융기관으로부터 대통령령으로 정하는 연금 방식으로 노후생활자금을 대출받음으로써 부담하는 금전채무를 공사가 계정의 부담으로 보증하는 행위를 말한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"한국부동산원은 표준주택가격과 공동주택가격의 조사·산정을 의뢰받는 기관이다(부동산 가격공시에 관한 법률 제16조제4항, 제18조제6항). 주택연금 보증기관이 아니다."},{"번호":2,"판정":"틀림","설명":"주택담보노후연금보증을 수행하는 주체는 한국주택금융공사로 법에 정해져 있다(한국주택금융공사법 제22조제1항제9호). 신용보증기금은 보증기관이 아니다."},{"번호":3,"판정":"틀림","설명":"주택도시보증공사는 주택분양보증 등을 하는 기관이다. 주택연금의 보증기관은 아니다."},{"번호":4,"판정":"틀림","설명":"한국토지주택공사는 택지 개발과 공공주택 공급을 하는 기관이다. 주택연금 보증 업무는 법에 없다."},{"번호":5,"판정":"옳음","설명":"주택소유자가 금융기관에서 연금 방식으로 대출받는 채무를 공사가 보증한다(한국주택금융공사법 제2조제8호의2). 보증기관은 한국주택금융공사다."}],"개념":[{"종류":"흐름","제목":"주택담보노후연금보증 성립부터 이행까지","단계":[{"이름":"설명","설명":"공사는 보증을 받으려는 사람에게 연금 지급액·변제시기, 저당권 설정 또는 신탁 등기, 채권 행사 범위, 설정 제한, 보증료를 설명한다(제43조의2제1항)"},{"이름":"담보 등기","설명":"담보로 제공하는 주택에 공사를 저당권자로 하는 등기 또는 공사를 공동수익자로 하는 신탁 등기를 한다(제43조의2제2항)"},{"이름":"보증 결정 통지","설명":"공사가 보증하기로 결정하면 보증받는 사람과 채권자가 될 자에게 각각 통지한다(제43조의2제3항)"},{"이름":"채권채무관계 성립","설명":"통지일부터 60일 이내에 주된 채권채무관계가 성립하지 않으면 보증관계는 성립하지 않는다(제43조의2제4항·제5항)"},{"이름":"보증채무 이행","설명":"보증받은 사람의 사망 등 사유가 생기면 금융기관이 공사에 보증채무 이행을 청구하고, 공사는 지체 없이 이행한다(제43조의3)"},{"이름":"채권 행사 범위","설명":"연금채권과 구상권은 담보주택에 대해서만 행사한다. 조세채권·임금채권 등 예외 항목만 채무자의 다른 재산에도 행사한다(제43조의4)"}]},{"종류":"표","제목":"주택담보노후연금보증 관련 법 규정","머리":["항목","내용","조문"],"행":[["보증 주체","한국주택금융공사","제2조제8호의2, 제22조제1항제9호"],["연금 수급권 보호","연금을 받을 권리는 양도·압류하거나 담보로 제공할 수 없다","제43조의6제1항"],["담보주택 제한","저당권·가등기담보권 설정, 전세권 설정, 임대를 하여서는 안 된다(대통령령으로 정하는 경우 제외)","제43조의7제1항"],["초기보증료","담보주택 가격에 2% 이하의 범위에서 대통령령으로 정하는 요율을 곱한 금액","제43조의8제1항"],["보증료","보증금액에 연 2% 이하의 범위에서 대통령령으로 정하는 요율을 곱한 금액","제43조의8제2항"]]}],"함정":"한국부동산원(가격공시), 주택도시보증공사(분양·전세 보증), 한국토지주택공사(택지·공공주택)는 각각 하는 일이 달라 보증기관 후보로 자주 나온다. 주택연금은 공사가 보증하고 금융기관이 연금을 지급한다. 지급 주체와 보증 주체를 구별한다."},"33회-1차-042":{"한줄":"보험금을 부정하게 취득할 목적으로 체결한 보험계약은 사회질서에 반하는 내용을 목적으로 하여 제103조에 따라 무효이다.","근거":[{"법령":"민법","조문":"제103조","원문":"선량한 풍속 기타 사회질서에 위반한 사항을 내용으로 하는 법률행위는 무효로 한다."},{"법령":"민법","조문":"제104조","원문":"당사자의 궁박, 경솔 또는 무경험으로 인하여 현저하게 공정을 잃은 법률행위는 무효로 한다."},{"법령":"공인중개사법","조문":"제33조제1항제6호","원문":"중개의뢰인과 직접 거래를 하거나 거래당사자 쌍방을 대리하는 행위"},{"판례":"대법원 판례","요지":"보험금을 취득할 목적으로 보험사고를 가장하거나 고의로 일으키려는 보험계약은 사회질서에 반하여 무효이다. 변호사의 성공보수약정은 형사사건에서는 무효이나 민사사건에서 적정한 수준이면 유효하다. 불공정한 법률행위는 궁박·경솔·무경험과 현저한 불균형에 더해 상대방이 이를 알고 이용하려는 의사가 있어야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"개업공인중개사가 임대인으로서 직접 거래하는 행위는 금지행위(공인중개사법 제33조제1항제6호)이지만 단속규정이라 임대차계약의 사법상 효력은 유효하다."},{"번호":2,"판정":"틀림","설명":"우연히 1회 한 중개행위는 중개업에 해당하지 않아 공인중개사법의 규제를 받지 않고, 적정한 수준의 보수약정은 유효하다."},{"번호":3,"판정":"틀림","설명":"민사사건의 성공보수약정은 적정한 수준이면 유효하다. 무효가 되는 것은 형사사건의 성공보수약정이다."},{"번호":4,"판정":"틀림","설명":"매도인의 실수는 상대방의 궁박·무경험을 알고 이용한 것이 아니므로 불공정한 법률행위(제104조)가 되지 않는다. 매매계약은 유효하다."},{"번호":5,"판정":"옳음","설명":"보험금 취득을 목적으로 보험사고를 가장한 보험계약은 반사회질서의 법률행위로 무효이다(제103조). 보험자가 선의여도 같다."}],"개념":[{"종류":"표","제목":"강행규정 위반의 효과: 효력규정과 단속규정","머리":["구분","의미","대표 예"],"행":[["효력규정","위반하면 사법상 효력도 무효","중개보수 한도 초과 약정(초과 부분), 부동산 명의신탁약정"],["단속규정","위반하면 처벌·제재만 받고 사법상 효력은 유효","개업공인중개사의 직접거래, 무허가 음식점의 판매행위, 중간생략등기 합의"],["판단 기준","규정의 목적, 위반 시 거래 안전에 미치는 영향","입법 취지가 행위의 법률상 효과를 막는 데 있으면 효력규정"],["일부무효","효력규정 위반 시 위반 부분만 무효로 하는 경우가 많음","한도를 넘은 초과 보수만 무효(제137조)"]]},{"종류":"표","제목":"제103조와 제104조 비교","머리":["구분","제103조 반사회질서","제104조 불공정"],"행":[["요건","법률행위의 내용이 사회질서에 반함(동기가 표시되거나 알려진 경우 포함)","궁박·경솔·무경험 + 현저한 불균형 + 상대방의 악용 의사"],["판단 시점","법률행위 성립 시","법률행위 성립 시"],["효과","절대적 무효, 추인해도 유효가 되지 않음","절대적 무효, 추인해도 유효가 되지 않음"],["불법원인급여(제746조)","적용됨","적용되지 않음(판례)"],["무효 예","보험금 부정취득 목적 보험, 허위진술 대가 약정, 형사사건 성공보수","상대방의 무경험을 알고 이용해 시세와 현저히 다른 대금을 받은 매매"]]}],"함정":"선지 4는 대금이 2배라도 매도인의 단순 실수이므로 제104조의 요건(상대방의 악용 의사)이 빠진다. 선지 1의 직접거래는 처벌 대상이어도 계약은 유효하다. 선지 3은 민사 성공보수가 유효하고 형사만 무효이다."},"33회-1차-046":{"한줄":"불법조건이 붙은 법률행위는 정지조건이든 해제조건이든 법률행위 전체가 무효이다(제151조제1항). 조건 없는 법률행위로 되는 것은 아니다.","근거":[{"법령":"민법","조문":"제147조","원문":"①정지조건있는 법률행위는 조건이 성취한 때로부터 그 효력이 생긴다.\n②해제조건있는 법률행위는 조건이 성취한 때로부터 그 효력을 잃는다.\n③당사자가 조건성취의 효력을 그 성취전에 소급하게 할 의사를 표시한 때에는 그 의사에 의한다."},{"법령":"민법","조문":"제150조제1항","원문":"조건의 성취로 인하여 불이익을 받을 당사자가 신의성실에 반하여 조건의 성취를 방해한 때에는 상대방은 그 조건이 성취한 것으로 주장할 수 있다."},{"법령":"민법","조문":"제151조제1항","원문":"조건이 선량한 풍속 기타 사회질서에 위반한 것인 때에는 그 법률행위는 무효로 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"조건성취의 효력은 성취한 때부터 생기고 소급하지 않는 것이 원칙이다(제147조제1항·제2항, 제3항은 소급 약정을 허용)."},{"번호":2,"판정":"틀림","설명":"불법조건이 붙은 법률행위는 그 법률행위 전체가 무효이다(제151조제1항)."},{"번호":3,"판정":"옳음","설명":"표시된 사실이 발생하지 않는 것으로 확정된 때에도 채무를 이행해야 하면 불확정기한이고, 이행할 필요가 없으면 정지조건이다(판례)."},{"번호":4,"판정":"옳음","설명":"최고와 함께 그 기간 내에 이행이 없을 것을 정지조건으로 한 해제의 의사표시는 유효하다(판례)."},{"번호":5,"판정":"옳음","설명":"조건 성취를 신의칙에 반하여 방해한 경우 성취된 것으로 주장할 수 있고(제150조제1항), 의제 시점은 방해가 없었더라면 성취되었을 시점이다(판례)."}],"개념":[{"종류":"표","제목":"조건과 기한 비교","머리":["구분","조건","기한"],"행":[["의미","발생 여부가 불확실한 사실","발생이 확실한 사실"],["종류","정지조건, 해제조건","시기(始期), 종기(終期), 확정기한, 불확정기한"],["효력 발생","정지조건은 성취한 때 효력 발생, 해제조건은 성취한 때 효력 상실(제147조)","기한 도래 시 효력 발생·소멸"],["소급효","원칙 없음, 당사자가 소급 약정 가능(제147조제3항)","소급효 없음"],["이익","-","기한의 이익은 채무자를 위한 것으로 추정(제153조제1항)"]]},{"종류":"표","제목":"조건을 붙일 수 없는 법률행위","머리":["유형","예","이유"],"행":[["친족법·상속법상 행위","혼인, 입양, 상속 승인·포기","신분관계의 안정"],["상대방에게 불이익을 주는 단독행위","취소, 추인, 해제, 상계","상대방의 지위를 불안정하게 함(상계는 제493조제1항이 명시)"],["불법조건","범죄를 하지 않으면 금전을 주겠다는 약정 등","조건 때문에 법률행위 전체 무효(제151조제1항)"]]}],"함정":"불법조건은 정지조건이든 해제조건이든 법률행위 전체가 무효이다. 기성조건·불능조건은 정지·해제에 따라 결과가 반대로 갈린다(제151조제2항·제3항)."},"33회-1차-070":{"한줄":"예약완결권은 재산권이므로 특별한 사정이 없으면 양도할 수 있다.","근거":[{"법령":"민법","조문":"제564조제1항","원문":"매매의 일방예약은 상대방이 매매를 완결할 의사를 표시하는 때에 매매의 효력이 생긴다."},{"판례":"대법원 판례(예약완결권)","요지":"예약완결권은 형성권으로서 행사기간은 제척기간이다. 당사자가 기간을 약정하면 그에 따르고, 약정이 없으면 예약이 성립한 때부터 10년이다. 제척기간은 직권조사사항이다. 예약완결권은 재산권으로서 양도할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"매매의 효력은 완결의 의사표시가 있는 때에 생긴다(제564조제1항). 예약체결시로 소급하지 않는다."},{"번호":2,"판정":"틀림","설명":"당사자가 행사기간을 약정하면 그 기간(20년)에 따른다. 약정이 없을 때 10년이다(판례)."},{"번호":3,"판정":"옳음","설명":"예약완결권은 재산권이어서 특별한 사정이 없는 한 양도할 수 있다(판례)."},{"번호":4,"판정":"틀림","설명":"제척기간은 직권조사사항이어서 당사자의 주장이 없어도 법원이 고려한다(판례)."},{"번호":5,"판정":"틀림","설명":"일방예약은 상대방이 완결의 의사표시를 하면 예약자의 승낙 없이 매매의 효력이 생긴다(제564조제1항)."}],"개념":[{"종류":"표","제목":"매매의 일방예약과 예약완결권","머리":["쟁점","내용","근거"],"행":[["성립","상대방이 완결의 의사표시를 하는 때 매매의 효력 발생(예약자의 승낙 불요)","제564조제1항"],["성질","형성권, 재산권(양도 가능)","판례"],["행사기간","약정이 있으면 그 기간, 없으면 예약성립시부터 10년. 제척기간","판례"],["기간 약정 없을 때 최고","예약자는 상당한 기간을 정해 확답을 최고, 답이 없으면 예약 효력 상실","제564조제2항·제3항"],["제척기간 도과","당사자 주장 없어도 법원이 직권으로 조사","판례"],["효력 발생 시점","완결 의사표시 시점(소급 없음)","제564조제1항"]]},{"종류":"흐름","제목":"예약완결권 행사 절차","단계":[{"이름":"일방예약 체결","설명":"예약자와 상대방이 장래 매매를 성립시킬 권리(예약완결권)를 상대방에게 부여"},{"이름":"행사기간 확인","설명":"약정 기간이 있으면 그에 따르고, 없으면 예약 성립 후 10년"},{"이름":"완결 의사표시","설명":"상대방이 매매를 완결하겠다고 예약자에게 표시"},{"이름":"매매 성립","설명":"의사표시가 도달한 때 매매의 효력 발생, 예약자의 승낙 불요"}]}],"함정":"형성권은 모두 10년으로 본다고 기억하면 약정 기간(20년)이 있는 이 사례에서 틀린다. 약정이 없을 때의 보충 기간이 10년이다. 제척기간 도과를 상대방이 주장해야 한다는 선지도 함정이다."},"33회-2차-008":{"한줄":"일반·전속 두 표준서식 모두 중개보수 또는 실비를 과다수령하면 차액을 환급하도록 정하므로 5번이 옳다.","근거":[{"법령":"공인중개사법","조문":"제23조제1항","원문":"중개의뢰인은 중개대상물의 중개를 의뢰하는 경우 특정한 개업공인중개사를 정하여 그 개업공인중개사에 한정하여 해당 중개대상물을 중개하도록 하는 계약(이하 \"전속중개계약\"이라 한다)을 체결할 수 있다."},{"법령":"공인중개사법","조문":"제23조제3항","원문":"개업공인중개사는 전속중개계약을 체결한 때에는 제24조에 따른 부동산거래정보망 또는 일간신문에 해당 중개대상물에 관한 정보를 공개하여야 한다. 다만, 중개의뢰인이 비공개를 요청한 경우에는 이를 공개하여서는 아니된다."},{"법령":"공인중개사법","조문":"제39조제1항제3호","원문":"제23조제2항의 규정을 위반하여 국토교통부령으로 정하는 전속중개계약서에 의하지 아니하고 전속중개계약을 체결하거나 계약서를 보존하지 아니한 경우"},{"법령":"공인중개사법 시행규칙","조문":"별지 제15호서식(전속중개계약서) 5.","원문":"을의 손해배상 책임 … 1) 중개보수 또는 실비의 과다수령: 차액 환급 2) 중개대상물의 확인ㆍ설명을 소홀히 하여 재산상의 피해를 발생하게 한 경우: 손해액 배상"},{"법령":"공인중개사법 시행규칙","조문":"별지 제14호서식(일반중개계약서) 손해배상 책임","원문":"1) 중개보수 또는 실비의 과다수령: 차액 환급"}],"선지":[{"번호":1,"판정":"틀림","설명":"특정 개업공인중개사에 한정하는 계약은 전속중개계약이다(법 제23조제1항). 일반중개계약은 한정하지 않는다."},{"번호":2,"판정":"틀림","설명":"정보 공개 의무는 전속중개계약을 체결한 때 생긴다(법 제23조제3항). 일반중개계약에는 공개 의무가 없다."},{"번호":3,"판정":"틀림","설명":"2주일에 1회 이상 문서 통지는 전속중개계약서의 개업공인중개사 의무다(칙 전속중개계약서 1.①)."},{"번호":4,"판정":"틀림","설명":"전속중개계약서 서식 위반은 업무정지 사유다(법 제39조제1항제3호, 칙 별표 4: 3개월)."},{"번호":5,"판정":"옳음","설명":"두 서식 모두 과다수령 시 차액 환급을 규정한다."}],"개념":[{"종류":"비교","제목":"일반중개계약과 전속중개계약","왼쪽":{"이름":"일반중개계약","항목":["중개의뢰인이 필요하면 작성을 요청할 수 있음(법 제22조)","여러 개업공인중개사에게 중복 의뢰 가능","표준서식 사용을 권장(영 제19조)","정보 공개 의무·처리상황 통지 의무 없음","서식 위반은 업무정지 사유 아님"]},"오른쪽":{"이름":"전속중개계약","항목":["특정 개업공인중개사에 한정해 중개하도록 하는 계약(법 제23조제1항)","국토교통부령 서식(별지 제15호)에 의해야 함","체결 후 7일 이내 정보망·일간신문에 공개(비공개 요청 시 공개 금지)","계약 체결 후 2주일에 1회 이상 처리상황을 문서로 통지","서식 위반·계약서 미보존은 업무정지 사유(법 제39조제1항제3호)"]}},{"종류":"표","제목":"일반중개계약서 기재사항(법 제22조)","머리":["호","기재사항"],"행":[["1","중개대상물의 위치 및 규모"],["2","거래예정가격"],["3","거래예정가격에 대하여 제32조에 따라 정한 중개보수"],["4","그 밖에 개업공인중개사와 중개의뢰인이 준수하여야 할 사항"]]}],"함정":"일반중개계약에 전속계약의 의무(공개, 2주 통지, 서식 강제)를 붙인 선지가 번갈아 나온다. 두 계약에 공통인 것은 과다수령 시 차액 환급 같은 서식 내용뿐이다."},"33회-2차-045":{"한줄":"중앙행정기관의 장, 시ㆍ도지사, 시장 또는 군수는 국토교통부장관이나 도지사에게 광역계획권의 지정 또는 변경을 요청할 수 있다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제10조제1항·제2항","원문":"① 국토교통부장관 또는 도지사는 둘 이상의 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 공간구조 및 기능을 상호 연계시키고 환경을 보전하며 광역시설을 체계적으로 정비하기 위하여 필요한 경우에는 다음 각 호의 구분에 따라 인접한 둘 이상의 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 관할 구역 전부 또는 일부를 대통령령으로 정하는 바에 따라 광역계획권으로 지정할 수 있다.\n1. 광역계획권이 둘 이상의 특별시ㆍ광역시ㆍ특별자치시ㆍ도 또는 특별자치도(이하 \"시ㆍ도\"라 한다)의 관할 구역에 걸쳐 있는 경우: 국토교통부장관이 지정\n2. 광역계획권이 도의 관할 구역에 속하여 있는 경우: 도지사가 지정\n② 중앙행정기관의 장, 시ㆍ도지사, 시장 또는 군수는 국토교통부장관이나 도지사에게 광역계획권의 지정 또는 변경을 요청할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제10조제3항·제4항","원문":"③ 국토교통부장관은 광역계획권을 지정하거나 변경하려면 관계 시ㆍ도지사, 시장 또는 군수의 의견을 들은 후 중앙도시계획위원회의 심의를 거쳐야 한다.\n④ 도지사가 광역계획권을 지정하거나 변경하려면 관계 중앙행정기관의 장, 관계 시ㆍ도지사, 시장 또는 군수의 의견을 들은 후 지방도시계획위원회의 심의를 거쳐야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"둘 이상의 시·도에 걸친 광역계획권은 국토교통부장관이 지정한다. 도지사들의 공동 지정이 아니다(법 제10조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"하나의 도 안에 속한 광역계획권은 도지사가 지정한다. 국토교통부장관과 공동으로 지정하는 구조가 아니다(법 제10조제1항제2호)."},{"번호":3,"판정":"틀림","설명":"도지사는 관계 중앙행정기관의 장, 관계 시·도지사, 시장 또는 군수의 의견을 들은 뒤 지방도시계획위원회의 심의를 거친다. 중앙도시계획위원회는 국토교통부장관 몫이다(법 제10조제4항)."},{"번호":4,"판정":"틀림","설명":"국토교통부장관은 관계 시·도지사, 시장 또는 군수의 의견을 들은 뒤 중앙도시계획위원회의 심의를 거친다. 지방도시계획위원회가 아니다(법 제10조제3항)."},{"번호":5,"판정":"옳음","설명":"중앙행정기관의 장, 시·도지사, 시장 또는 군수는 국토교통부장관이나 도지사에게 광역계획권의 지정 또는 변경을 요청할 수 있다(법 제10조제2항)."}],"개념":[{"종류":"표","제목":"광역계획권 지정과 광역도시계획 수립·승인","머리":["구분","같은 도 안","둘 이상 시·도에 걸침"],"행":[["광역계획권 지정","도지사(법 제10조①2호)","국토교통부장관(법 제10조①1호)"],["지정 전 의견·심의","관계 중앙행정기관의 장, 시·도지사, 시장·군수 의견 → 지방도시계획위원회 심의(제10조④)","관계 시·도지사, 시장·군수 의견 → 중앙도시계획위원회 심의(제10조③)"],["광역도시계획 수립","관할 시장·군수 공동. 지정일부터 3년 내 승인신청이 없으면 도지사(제11조①1·3호)","관할 시·도지사 공동. 지정일부터 3년 내 승인신청이 없으면 국토교통부장관(제11조①2·4호)"],["승인","시장·군수가 수립하면 도지사 승인(제16조⑤)","시·도지사가 수립하면 국토교통부장관 승인(제16조①)"],["협의가 안 될 때 조정","도지사에게 신청(제17조⑤)","국토교통부장관에게 신청(제17조①)"]]},{"종류":"흐름","제목":"광역도시계획 수립 절차","단계":[{"이름":"광역계획권 지정","설명":"국토교통부장관 또는 도지사가 지정(제10조)"},{"이름":"기초조사","설명":"인구·경제·토지이용 등 조사. 정보체계를 구축하면 5년마다 확인(제13조)"},{"이름":"공청회","설명":"수립·변경 전에 공청회를 열어 의견을 듣는다(제14조)"},{"이름":"의견 청취","설명":"관계 의회와 시장·군수 의견. 30일 이내 제시(제15조)"},{"이름":"승인","설명":"국토교통부장관 또는 도지사 승인. 관계 중앙행정기관 협의 의견은 30일 이내(제16조)"}]}],"함정":"선지 1·2는 지정권자를 바꿔 쓴 선지이다. 도지사가 지정하는 범위는 하나의 도 안이고, 두 개 이상의 시·도에 걸치면 국토교통부장관이 맡는다. 선지 3·4는 위원회 이름이 서로 바뀌어 있다."},"33회-2차-062":{"한줄":"등기우편으로 통지하는 사항은 조합설립 동의철회 방법과 조합설립 동의서 포함사항뿐이고, 정비사업비의 분담기준은 동의서 포함사항이다.","근거":[{"법령":"도시 및 주거환경정비법 시행령","조문":"제29조제1항","원문":"① 추진위원회는 법 제34조제5항에 따라 다음 각 호의 사항을 토지등소유자가 쉽게 접할 수 있는 일정한 장소에 게시하거나 인터넷 등을 통하여 공개하고, 필요한 경우에는 토지등소유자에게 서면통지를 하는 등 토지등소유자가 그 내용을 충분히 알 수 있도록 하여야 한다. 다만, 제8호 및 제9호의 사항은 법 제35조에 따른 조합설립인가(이하 \"조합설립인가\"라 한다) 신청일 60일 전까지 추진위원회 구성에 동의한 토지등소유자에게 등기우편으로 통지하여야 한다.\n1. 법 제12조에 따른 재건축진단의 결과\n2. 정비사업전문관리업자의 선정에 관한 사항\n3. 토지등소유자의 부담액 범위를 포함한 개략적인 사업시행계획서\n4. 추진위원회 위원의 선정에 관한 사항\n5. 토지등소유자의 비용부담을 수반하거나 권리ㆍ의무에 변동을 일으킬 수 있는 사항\n6. 법 제32조제1항에 따른 추진위원회의 업무에 관한 사항\n7. 창립총회 개최의 방법 및 절차\n8. 조합설립에 대한 동의철회(법 제31조제3항 단서에 따른 반대의 의사표시를 포함한다) 및 방법\n9. 제30조제2항에 따른 조합설립 동의서에 포함되는 사항"},{"법령":"도시 및 주거환경정비법 시행령","조문":"제30조제2항","원문":"② 제1항에 따른 동의서에는 다음 각 호의 사항이 포함되어야 한다.\n1. 건설되는 건축물의 설계의 개요\n2. 공사비 등 정비사업비용에 드는 비용(이하 \"정비사업비\"라 한다)\n3. 정비사업비의 분담기준\n4. 사업 완료 후 소유권의 귀속에 관한 사항\n5. 조합 정관"},{"법령":"도시 및 주거환경정비법","조문":"제31조제1항","원문":"① 조합을 설립하려는 경우에는 다음 각 호의 사항에 대하여 토지등소유자 과반수의 동의를 받아 조합설립을 위한 추진위원회를 구성하여 국토교통부령으로 정하는 방법과 절차에 따라 시장ㆍ군수등의 승인을 받아야 한다. 이 경우 시장ㆍ군수등은 승인 이후 구역경계, 토지등소유자의 수 등 국토교통부령으로 정하는 사항을 해당 지방자치단체 공보에 고시하여야 한다.\n1. 추진위원회 위원장(이하 \"추진위원장\"이라 한다)을 포함한 5명 이상의 추진위원회 위원(이하 \"추진위원\"이라 한다)"},{"법령":"도시 및 주거환경정비법","조문":"제35조제10항","원문":"⑩ 추진위원회는 조합설립에 필요한 동의를 받기 전에 추정분담금 등 대통령령으로 정하는 정보를 토지등소유자에게 제공하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"재건축진단의 결과는 영 제29조제1항제1호 사항이라 게시·공개 대상이다. 등기우편은 제8호·제9호만 해당한다."},{"번호":2,"판정":"옳음","설명":"동의서에는 건설되는 건축물의 설계 개요, 정비사업비, 정비사업비의 분담기준, 사업 완료 후 소유권 귀속, 조합 정관이 들어간다(영 제30조제2항). 이 동의서 포함사항이 영 제29조제1항제9호로서 등기우편 통지 대상이다."},{"번호":3,"판정":"틀림","설명":"토지등소유자의 부담액 범위를 포함한 개략적인 사업시행계획서는 제3호 사항이다. 게시·공개하고 필요하면 서면통지한다."},{"번호":4,"판정":"틀림","설명":"정비사업전문관리업자의 선정에 관한 사항은 제2호 사항이다. 등기우편 통지 대상이 아니다."},{"번호":5,"판정":"틀림","설명":"추진위원회 위원의 선정에 관한 사항은 제4호 사항이다. 등기우편 통지 대상이 아니다."}],"개념":[{"종류":"표","제목":"추진위원회의 공개·통지 사항(영 제29조제1항)","머리":["호","사항","공개·통지 방법"],"행":[["1","재건축진단의 결과","게시·공개, 필요하면 서면통지"],["2","정비사업전문관리업자의 선정에 관한 사항","게시·공개, 필요하면 서면통지"],["3","토지등소유자의 부담액 범위를 포함한 개략적인 사업시행계획서","게시·공개, 필요하면 서면통지"],["4","추진위원회 위원의 선정에 관한 사항","게시·공개, 필요하면 서면통지"],["5~7","비용부담·권리의무 변동 사항, 추진위원회 업무, 창립총회 개최 방법·절차","게시·공개, 필요하면 서면통지"],["8","조합설립 동의철회(반대의 의사표시 포함) 및 방법","조합설립인가 신청일 60일 전까지 동의한 토지등소유자에게 등기우편"],["9","조합설립 동의서에 포함되는 사항","조합설립인가 신청일 60일 전까지 동의한 토지등소유자에게 등기우편"]]},{"종류":"흐름","제목":"추진위원회 구성에서 조합설립인가까지","단계":[{"이름":"추진위원회 구성승인","설명":"토지등소유자 과반수 동의를 받아 위원장 포함 5명 이상의 추진위원과 운영규정으로 시장·군수등의 승인을 받는다(법 제31조제1항)."},{"이름":"정보 제공","설명":"조합설립 동의를 받기 전에 추정분담금 등 정보를 토지등소유자에게 제공한다(법 제35조제10항)."},{"이름":"등기우편 통지","설명":"동의철회 방법과 동의서 포함사항을 인가 신청일 60일 전까지 동의자에게 등기우편으로 통지한다(영 제29조제1항 단서)."},{"이름":"조합설립 동의","설명":"재개발은 토지등소유자 4분의 3 이상 및 토지면적 2분의 1 이상 토지소유자의 동의를 받는다(법 제35조제2항)."},{"이름":"조합설립인가","설명":"정비구역 지정·고시 후 정관 등을 첨부해 시장·군수등의 인가를 받는다(법 제35조제2항)."},{"이름":"업무 인계","설명":"추진위원회는 회계장부와 관계 서류를 인가일부터 30일 이내에 조합에 인계하고, 업무상 권리·의무는 조합이 포괄승계한다(법 제34조제3항·제4항)."}]}],"함정":"1번의 재건축진단 결과, 3번의 개략적인 사업시행계획서처럼 비용·권리에 크게 관련된 사항이 등기우편 대상일 것 같지만 게시·공개 사항이다. 등기우편은 동의철회 방법(제8호)과 동의서 포함사항(제9호) 둘이다.","개정":"법 제12조제1항이 2024.12.3 개정되어 안전진단이 재건축진단으로 바뀌었다. 영 제29조제1항제1호도 「재건축진단의 결과」로 표기하며, 재건축진단은 정비계획 수립시기가 도래한 때부터 사업시행계획인가 전까지 실시한다."},"33회-2차-068":{"한줄":"제93조제1항에 따른 출입·검사를 방해한 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.","근거":[{"법령":"주택법","조문":"제104조제13호","원문":"13. 제93조제1항에 따른 검사 등을 거부ㆍ방해 또는 기피한 자"},{"법령":"주택법","조문":"제93조제1항","원문":"① 국토교통부장관 또는 지방자치단체의 장은 필요하다고 인정할 때에는 다음 각 호의 어느 하나에 해당하는 자에게 필요한 보고를 하게 하거나, 관계 공무원으로 하여금 사업장에 출입하여 필요한 검사를 하게 할 수 있다."},{"법령":"주택법","조문":"제106조제1항제2호","원문":"① 다음 각 호의 어느 하나에 해당하는 자에게는 2천만원 이하의 과태료를 부과한다.\n2. 제48조의3제3항을 위반하여 점검에 따르지 아니하거나 기피 또는 방해한 자"},{"법령":"주택법","조문":"제106조제2항제4호","원문":"② 다음 각 호의 어느 하나에 해당하는 자에게는 1천만원 이하의 과태료를 부과한다.\n4. 제13조제4항을 위반하여 겸직한 자"},{"법령":"주택법","조문":"제106조제3항제4호의5","원문":"③ 다음 각 호의 어느 하나에 해당하는 자에게는 500만원 이하의 과태료를 부과한다.\n4의5. 제48조의3제7항을 위반하여 조치명령을 이행하지 아니한 자"},{"법령":"주택법","조문":"제106조제4항제2호","원문":"④ 다음 각 호의 어느 하나에 해당하는 자에게는 300만원 이하의 과태료를 부과한다.\n2. 제57조의3제1항에 따른 서류 등의 제출을 거부하거나 해당 주택의 출입ㆍ조사 또는 질문을 방해하거나 기피한 자"}],"선지":[{"번호":1,"판정":"옳음","설명":"검사 거부·방해·기피는 법 제104조제13호로 1년 이하의 징역 또는 1천만원 이하의 벌금이다."},{"번호":2,"판정":"틀림","설명":"품질점검단의 점검에 따르지 않거나 기피·방해하면 2천만원 이하의 과태료다(법 제48조의3제3항, 제106조제1항제2호)."},{"번호":3,"판정":"틀림","설명":"주택조합 임원이 다른 주택조합의 임원, 직원 또는 발기인을 겸하면 1천만원 이하의 과태료다(법 제13조제4항, 제106조제2항제4호)."},{"번호":4,"판정":"틀림","설명":"거주실태 조사의 출입·조사·질문을 방해하거나 기피하면 300만원 이하의 과태료다(법 제57조의3제1항, 제106조제4항제2호)."},{"번호":5,"판정":"틀림","설명":"품질점검단 점검결과에 따른 조치명령을 이행하지 않으면 500만원 이하의 과태료다(법 제48조의3제7항, 제106조제3항제4호의5)."}],"개념":[{"종류":"표","제목":"주택법 벌칙과 과태료 구분","머리":["조문","수준","주요 위반행위"],"행":[["제98조","10년 이하 징역","설계·시공·감리 위반으로 담보책임기간에 공동주택 내력구조부에 중대한 하자를 발생시켜 일반인을 위험에 처하게 함"],["제101조","3년 이하 징역 또는 3천만원 이하 벌금","조합업무를 대행하게 한 주택조합·발기인, 주택 전매·전매 알선(제64조제1항), 제65조제1항 위반"],["제102조","2년 이하 징역 또는 2천만원 이하 벌금","등록 없이 사업, 사업계획승인 없이 사업 시행, 사용검사 전 주택·대지 사용, 주택 공급 방법 위반"],["제104조","1년 이하 징역 또는 1천만원 이하 벌금","영업정지기간 영업, 제93조제1항 검사 거부·방해·기피, 공사 중지 명령 위반"],["제106조제1항","2천만원 이하 과태료","사전방문 미실시, 품질점검단 점검 불응·기피·방해, 표준임대차계약서 미사용"],["제106조제2항","1천만원 이하 과태료","주택조합 임원 겸직, 가입 설명의무 위반, 건축구조기술사 협력 미이행, 현장점검 요청 불응"],["제106조제3항","500만원 이하 과태료","제16조제2항 착공신고 미이행, 품질점검단 점검결과 조치명령 불이행, 제93조제1항 보고·검사 명령 위반"],["제106조제4항","300만원 이하 과태료","거주의무자의 한국토지주택공사 매입 신청 불이행, 거주실태 조사 방해·기피"]]},{"종류":"표","제목":"출입·검사·조사 방해 관련 제재 비교","머리":["위반행위","근거","제재"],"행":[["제93조제1항에 따른 출입·검사 거부·방해·기피","제104조제13호","1년 이하 징역 또는 1천만원 이하 벌금"],["제93조제1항에 따른 보고 또는 검사 명령 위반","제106조제3항제7호","500만원 이하 과태료"],["품질점검단 점검 불응·기피·방해(제48조의3제3항)","제106조제1항제2호","2천만원 이하 과태료"],["거주실태 조사 서류 제출 거부·출입 방해(제57조의3제1항)","제106조제4항제2호","300만원 이하 과태료"]]}],"함정":"같은 「방해」라도 사업장에 대한 출입·검사(제93조제1항)는 형벌이고, 품질점검단 점검과 거주실태 조사 방해는 과태료다. 품질점검단 관련 위반(2번, 5번)과 분양가상한제 주택 거주실태 조사(4번)는 모두 과태료이며 금액만 다르다."},"33회-2차-067":{"한줄":"토지임대료를 보증금으로 전환할 때 적용하는 이자율은 은행의 3년 만기 정기예금 평균이자율 이상이어야 한다.","근거":[{"법령":"주택법 시행령","조문":"제82조","원문":"제82조(토지임대료의 선납 및 보증금 전환) 법 제78조제6항에 따라 토지임대료를 선납하거나 보증금으로 전환하려는 경우 그 선납 토지임대료 또는 보증금을 산정할 때 적용되는 이자율은 「은행법」에 따른 은행의 3년 만기 정기예금 평균이자율 이상이어야 한다."},{"법령":"주택법","조문":"제78조제1항","원문":"① 토지임대부 분양주택의 토지에 대한 임대차기간은 40년 이내로 한다. 이 경우 토지임대부 분양주택 소유자의 75퍼센트 이상이 계약갱신을 청구하는 경우 40년의 범위에서 이를 갱신할 수 있다."},{"법령":"주택법","조문":"제78조제6항","원문":"⑥ 제5항의 토지임대료는 월별 임대료를 원칙으로 하되, 토지소유자와 주택을 공급받은 자가 합의한 경우 대통령령으로 정하는 바에 따라 임대료를 선납하거나 보증금으로 전환하여 납부할 수 있다."},{"법령":"주택법","조문":"제78조의2제1항","원문":"① 토지임대부 분양주택을 공급받은 자는 제64조제1항에도 불구하고 전매제한기간이 지나기 전에 대통령령으로 정하는 바에 따라 한국토지주택공사에 해당 주택의 매입을 신청할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"임대차기간은 40년 이내다(법 제78조제1항)."},{"번호":2,"판정":"틀림","설명":"소유자의 75퍼센트 이상이 계약갱신을 청구하면 40년의 범위에서 갱신할 수 있다(법 제78조제1항)."},{"번호":3,"판정":"옳음","설명":"영 제82조에 있는 내용이다. 선납 토지임대료를 산정할 때도 같은 기준이다."},{"번호":4,"판정":"틀림","설명":"전매제한기간이 지나기 전에 매입을 신청하는 상대방은 한국토지주택공사이며, 신청은 의무가 아니라 할 수 있는 것이다(법 제78조의2제1항)."},{"번호":5,"판정":"틀림","설명":"토지임대료는 월별 임대료가 원칙이며, 합의가 있으면 선납하거나 보증금으로 전환할 수 있다(법 제78조제6항)."}],"개념":[{"종류":"표","제목":"토지임대부 분양주택의 토지 임대차(법 제78조)","머리":["구분","내용"],"행":[["임대차기간","40년 이내"],["갱신","소유자의 75퍼센트 이상이 계약갱신을 청구하면 40년의 범위에서 갱신"],["지상권","임대차계약을 체결하면 임대차기간 동안 구분소유권을 목적으로 지상권이 설정된 것으로 봄"],["표준임대차계약서","국토교통부령으로 정하는 표준임대차계약서 사용"],["승계","양수인 또는 상속인이 임대차계약을 승계"],["토지임대료","월별 임대료가 원칙. 합의하면 선납 또는 보증금 전환 가능"],["법 적용 순서","주택법에서 정하지 않은 사항은 집합건물법, 민법 순으로 적용"]]},{"종류":"표","제목":"토지임대료 산정과 증액(영 제81조·제82조)","머리":["구분","내용"],"행":[["공공택지","조성원가에 입주자모집공고일이 속하는 달의 전전달 은행 3년 만기 정기예금 평균이자율을 적용한 금액을 12개월로 분할한 금액 이하"],["공공택지 외","감정평가한 가액에 같은 평균이자율을 적용한 금액을 12개월로 분할한 금액 이하"],["선납·보증금 전환 이자율","은행 3년 만기 정기예금 평균이자율 이상(영 제82조)"],["증액 청구 제한","토지임대료약정 체결 후 2년이 지나기 전에는 증액 청구 불가"],["증액 한도","시·군·구 평균지가상승률을 고려하되 주택임대차보호법 시행령 제8조제1항의 차임 증액 한도 비율 초과 불가"],["공공매입(법 제78조의2)","전매제한기간이 지나기 전에 한국토지주택공사에 매입 신청 가능"]]}],"함정":"임대차기간 40년, 갱신 청구 75퍼센트, 월별 임대료 원칙, 3년 만기 정기예금 이자율 이상이라는 네 가지 수치·용어가 한 묶음으로 출제된다. 매입 신청 상대방은 시·도지사가 아니라 한국토지주택공사다.","개정":"영 제82조는 2024.6.18 개정되어, 토지임대료를 선납하거나 보증금으로 전환할 때 적용하는 이자율을 은행의 3년 만기 정기예금 평균이자율 이상으로 정한다. 법 제78조제6항은 2023.12.26 개정 조문이다."},"33회-2차-070":{"한줄":"공동주택의 리모델링은 동을 단위로 할 수 있고, 동 리모델링은 그 동 구분소유자와 의결권의 각 3분의 2 이상 결의로 조합을 설립한다.","근거":[{"법령":"주택법","조문":"제11조제3항","원문":"③ 제1항에 따라 주택을 리모델링하기 위하여 주택조합을 설립하려는 경우에는 다음 각 호의 구분에 따른 구분소유자(「집합건물의 소유 및 관리에 관한 법률」 제2조제2호에 따른 구분소유자를 말한다. 이하 같다)와 의결권(「집합건물의 소유 및 관리에 관한 법률」 제37조에 따른 의결권을 말한다. 이하 같다)의 결의를 증명하는 서류를 첨부하여 관할 시장ㆍ군수ㆍ구청장의 인가를 받아야 한다.\n1. 주택단지 전체를 리모델링하고자 하는 경우에는 주택단지 전체의 구분소유자와 의결권의 각 3분의 2 이상의 결의 및 각 동의 구분소유자와 의결권의 각 과반수의 결의\n2. 동을 리모델링하고자 하는 경우에는 그 동의 구분소유자 및 의결권의 각 3분의 2 이상의 결의"},{"법령":"주택법","조문":"제2조제25호","원문":"25. \"리모델링\"이란 제66조제1항 및 제2항에 따라 건축물의 노후화 억제 또는 기능 향상 등을 위한 다음 각 목의 어느 하나에 해당하는 행위를 말한다.\n가. 대수선(大修繕)"},{"법령":"주택법","조문":"제66조제1항","원문":"① 공동주택(부대시설과 복리시설을 포함한다)의 입주자ㆍ사용자 또는 관리주체가 공동주택을 리모델링하려고 하는 경우에는 허가와 관련된 면적, 세대수 또는 입주자 등의 동의 비율에 관하여 대통령령으로 정하는 기준 및 절차 등에 따라 시장ㆍ군수ㆍ구청장의 허가를 받아야 한다."},{"법령":"주택법 시행령","조문":"제20조제8항","원문":"⑧ 리모델링주택조합 설립에 동의한 자로부터 건축물을 취득한 자는 리모델링주택조합 설립에 동의한 것으로 본다."}],"선지":[{"번호":1,"판정":"틀림","설명":"대수선은 리모델링에 포함된다(법 제2조제25호가목)."},{"번호":2,"판정":"옳음","설명":"동을 리모델링하려는 경우의 설립 결의 요건이 따로 있다(법 제11조제3항제2호)."},{"번호":3,"판정":"틀림","설명":"주택단지 전체를 리모델링하려면 전체 구분소유자와 의결권의 각 3분의 2 이상 결의 및 각 동의 구분소유자와 의결권의 각 과반수 결의가 필요하다(법 제11조제3항제1호)."},{"번호":4,"판정":"틀림","설명":"리모델링 허가권자는 시장·군수·구청장이다(법 제66조제1항)."},{"번호":5,"판정":"틀림","설명":"설립에 동의한 자로부터 건축물을 취득한 자는 동의한 것으로 본다(영 제20조제8항)."}],"개념":[{"종류":"표","제목":"리모델링주택조합 설립 결의와 동의(법 제11조제3항, 영 제20조제8항, 영 제75조제3항)","머리":["구분","내용"],"행":[["주택단지 전체 리모델링","주택단지 전체의 구분소유자와 의결권 각 3분의 2 이상 + 각 동의 구분소유자와 의결권 각 과반수"],["동 리모델링","그 동의 구분소유자 및 의결권 각 3분의 2 이상"],["인가","결의를 증명하는 서류를 첨부해 시장·군수·구청장의 인가"],["동의자의 승계","동의한 자로부터 건축물을 취득한 자는 동의한 것으로 봄"],["동의 철회","리모델링주택조합 또는 입주자대표회의가 허가신청서를 제출하기 전까지 서면으로 철회 가능"]]},{"종류":"표","제목":"리모델링의 종류와 허가(법 제2조제25호, 제66조)","머리":["구분","내용"],"행":[["대수선","리모델링에 포함"],["증축","사용검사일 또는 사용승인일부터 15년(15년 이상 20년 미만의 연수 중 시·도조례로 정한 연수)이 지난 공동주택을 각 세대 주거전용면적의 30퍼센트 이내(85제곱미터 미만은 40퍼센트 이내)에서 증축"],["세대수 증가형","각 세대의 증축 가능 면적을 합산한 범위에서 기존 세대수의 15퍼센트 이내로 세대수를 증가. 수직증축은 최대 3개층 이하 등 요건 충족 필요"],["허가권자","시장·군수·구청장"],["세대수 증가형 허가","대통령령으로 정하는 세대수 이상 증가하면 시·군·구도시계획위원회 심의"],["시공자 선정","리모델링주택조합 총회 또는 소유자 전원이 동의한 입주자대표회의가 경쟁입찰로 선정"],["사용검사","허가받은 리모델링 공사를 완료하면 시장·군수·구청장의 사용검사"]]}],"함정":"주택단지 전체 리모델링의 결의는 3분의 2 이상과 각 동 과반수가 합쳐진 이중 요건이다. 3번은 이 중 과반수만 적었고 3분의 2 요건이 빠져 있다. 허가권자는 시·도지사가 아니라 시장·군수·구청장이다."},"33회-2차-098":{"한줄":"소유권보존등기에는 등기원인과 그 연월일을 기록하지 않는다.","근거":[{"법령":"부동산등기법","조문":"제64조","원문":"등기관이 소유권보존등기를 할 때에는 제48조제1항제4호에도 불구하고 등기원인과 그 연월일을 기록하지 아니한다."},{"법령":"부동산등기법","조문":"제65조","원문":"미등기의 토지 또는 건물에 관한 소유권보존등기는 다음 각 호의 어느 하나에 해당하는 자가 신청할 수 있다. 1. 토지대장, 임야대장 또는 건축물대장에 최초의 소유자로 등록되어 있는 자 또는 그 상속인, 그 밖의 포괄승계인 2. 확정판결에 의하여 자기의 소유권을 증명하는 자 3. 수용(收用)으로 인하여 소유권을 취득하였음을 증명하는 자 4. 특별자치도지사, 시장, 군수 또는 구청장(자치구의 구청장을 말한다)의 확인에 의하여 자기의 소유권을 증명하는 자(건물의 경우로 한정한다)"},{"법령":"부동산등기법","조문":"제66조제1항","원문":"등기관이 미등기부동산에 대하여 법원의 촉탁에 따라 소유권의 처분제한의 등기를 할 때에는 직권으로 소유권보존등기를 하고, 처분제한의 등기를 명하는 법원의 재판에 따라 소유권의 등기를 한다는 뜻을 기록하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"보존등기는 최초의 등기라 등기원인이 없다. 등기원인과 연월일을 기록하지 않는다(법 제64조, 규칙 제121조제1항)."},{"번호":2,"판정":"옳음","설명":"대장상 최초 소유자의 상속인, 그 밖의 포괄승계인이 신청할 수 있다(법 제65조제1호)."},{"번호":3,"판정":"옳음","설명":"수용으로 소유권을 취득했음을 증명하는 자는 신청할 수 있다(법 제65조제3호)."},{"번호":4,"판정":"옳음","설명":"시장ㆍ군수ㆍ구청장의 확인으로 소유권을 증명하는 자는 신청할 수 있고, 건물에 한정된다(법 제65조제4호)."},{"번호":5,"판정":"옳음","설명":"법원의 촉탁으로 처분제한등기를 하면 등기관이 직권으로 보존등기를 한다(법 제66조제1항)."}],"개념":[{"종류":"표","제목":"소유권보존등기 신청인 (법 제65조)","머리":["유형","신청할 수 있는 자","대상"],"행":[["대장등록형","토지대장ㆍ임야대장ㆍ건축물대장에 최초 소유자로 등록된 자, 그 상속인ㆍ포괄승계인","토지ㆍ건물"],["판결형","확정판결로 자기 소유권을 증명하는 자","토지ㆍ건물"],["수용형","수용으로 소유권을 취득했음을 증명하는 자","토지ㆍ건물"],["확인형","특별자치도지사ㆍ시장ㆍ군수ㆍ구청장 확인으로 소유권을 증명하는 자","건물에 한정"]]},{"종류":"흐름","제목":"미등기부동산의 처분제한등기와 직권 보존","단계":[{"이름":"법원의 촉탁","설명":"미등기부동산에 소유권의 처분제한(가압류 등) 등기를 촉탁 (법 제66조제1항)."},{"이름":"직권 소유권보존","설명":"등기관이 직권으로 소유권보존등기를 하고, 재판에 따라 소유권의 등기를 한다는 뜻 기록."},{"이름":"건물의 특례","설명":"신청인 자격 제한(법 제65조)을 적용하지 않는다. 사용승인 대상인데 사용승인 전이면 그 사실을 표제부에 기록 (법 제66조제2항)."},{"이름":"사용승인 후 말소","설명":"사용승인이 나면 소유권 등기명의인이 1개월 이내 그 기록의 말소등기 신청 (법 제66조제3항)."}]}],"함정":"보존등기의 신청인 4유형 가운데 4호만 건물에 한정된다. 군수 확인으로 토지를 보존등기하는 길은 없다. 5번은 신청이 아니라 직권으로 하는 보존등기라는 점이 다르다."},"33회-2차-101":{"한줄":"가등기권자가 여럿이면 각자 자기 지분에 관한 본등기만 신청할 수 있고, 공유물 보존행위에 준해 전부의 본등기를 신청할 수는 없다.","근거":[{"법령":"부동산등기법","조문":"제89조","원문":"가등기권리자는 제23조제1항에도 불구하고 가등기의무자의 승낙이 있거나 가등기를 명하는 법원의 가처분명령(假處分命令)이 있을 때에는 단독으로 가등기를 신청할 수 있다."},{"법령":"부동산등기법","조문":"제93조","원문":"① 가등기명의인은 제23조제1항에도 불구하고 단독으로 가등기의 말소를 신청할 수 있다.\n② 가등기의무자 또는 가등기에 관하여 등기상 이해관계 있는 자는 제23조제1항에도 불구하고 가등기명의인의 승낙을 받아 단독으로 가등기의 말소를 신청할 수 있다."},{"법령":"부동산등기법","조문":"제92조제1항","원문":"등기관은 가등기에 의한 본등기를 하였을 때에는 대법원규칙으로 정하는 바에 따라 가등기 이후에 된 등기로서 가등기에 의하여 보전되는 권리를 침해하는 등기를 직권으로 말소하여야 한다."},{"이론":"공동 가등기권자의 본등기","내용":"가등기 권리자가 여럿이면 각자 자기 지분에 관해서만 본등기를 신청한다. 공유물 보존행위에 준해 1인이 전부의 본등기를 신청하는 것은 허용되지 않는다(등기선례·예규 취지)."}],"선지":[{"번호":1,"판정":"틀림","설명":"가등기명의인은 단독으로 말소를 신청할 수 있다(법 제93조제1항)."},{"번호":2,"판정":"틀림","설명":"가등기의무자는 가등기명의인의 승낙을 받아 단독으로 말소를 신청할 수 있다(법 제93조제2항, 규칙 제150조)."},{"번호":3,"판정":"틀림","설명":"가등기의무자의 승낙이 있거나 가등기를 명하는 법원의 가처분명령이 있으면 가등기권리자가 단독으로 신청할 수 있다(법 제89조, 제90조)."},{"번호":4,"판정":"옳음","설명":"가등기권자가 여럿이면 각자 자기 지분의 본등기만 신청한다. 일부 권리자가 보존행위를 이유로 전부를 신청할 수 없다."},{"번호":5,"판정":"틀림","설명":"가등기 후 소유권이 제3자에게 넘어갔더라도 본등기의 등기의무자는 제3자가 아니라 가등기 당시의 소유자(가등기의무자)다. 본등기를 하면 제3자 명의의 소유권이전등기는 가등기로 보전되는 권리를 침해하는 등기로서 등기관이 직권으로 말소한다(법 제92조제1항)."}],"개념":[{"종류":"표","제목":"가등기 신청·말소 주체","머리":["구분","단독 신청","요건","조문"],"행":[["가등기 신청","가등기권리자","가등기의무자의 승낙 또는 법원의 가처분명령","법 제89조"],["가등기 말소","가등기명의인","없음","법 제93조제1항"],["가등기 말소","가등기의무자·이해관계인","가등기명의인의 승낙 또는 대항 재판","법 제93조제2항, 규칙 제150조"],["가처분명령 관할","부동산 소재지 지방법원","원인사실 소명","법 제90조제1항"]]},{"종류":"흐름","제목":"가등기에 의한 본등기","단계":[{"이름":"가등기","설명":"소유권이전청구권 등 청구권 보전을 위해 가등기(법 제88조)"},{"이름":"본등기 신청","설명":"가등기권리자와 의무자가 공동으로 신청, 가등기 지분별로 신청"},{"이름":"본등기 실행","설명":"가등기의 순위번호를 사용해 본등기(규칙 제146조), 순위는 가등기 순위에 따름(법 제91조)"},{"이름":"직권말소","설명":"가등기 후에 된 등기 중 가등기 권리를 침해하는 등기 직권말소, 명의인에게 통지(법 제92조)"}]}],"함정":"선지 1·2·3은 단독신청 규정(법 제89조, 제93조)의 요건을 뒤집은 문장이다. 선지 5는 제3자 명의 등기를 보호해야 한다고 오해하기 쉽지만 가등기 이후의 침해 등기는 직권말소 대상이다."},"33회-1차-002":{"한줄":"부동성 때문에 시장이 지역별로 나뉘어 국지화되고, 지역마다 수요·공급과 가격이 따로 형성된다.","근거":[{"이론":"토지의 자연적 특성","내용":"부동성(위치 고정)은 시장의 국지화·지역성, 외부효과, 지역분석의 근거다. 영속성은 소모되지 않아 감가상각을 배제하고, 부증성은 물리적 공급 증가를 막는다. 개별성은 일물일가 법칙의 배제, 비교 곤란과 관련된다."}],"선지":[{"번호":1,"판정":"옳음","설명":"부동성으로 부동산시장은 지역별로 수요·공급이 따로 형성되는 국지적 시장이 된다."},{"번호":2,"판정":"틀림","설명":"토지는 생산요소와 자본의 성격에 더해 소비재(주거 등 소비 목적)의 성격도 가진다."},{"번호":3,"판정":"틀림","설명":"물리적 공급은 늘릴 수 없어도 용도적 관점(용도 전환·용도변경)에서는 공급을 늘릴 수 있다. 용도적 공급 변화는 개별성이 아니라 용도의 다양성과 관련된다."},{"번호":4,"판정":"틀림","설명":"부증성은 물리적 공급이 고정된다는 뜻이다. 특정 용도의 토지는 용도 전환으로 공급이 변하므로 장·단기 모두 완전비탄력적이라고 할 수 없다."},{"번호":5,"판정":"틀림","설명":"영속성(비소모성)이 있어 토지는 물리적·경제적으로 감가상각을 하지 않는다. 감가상각 대상은 건물이다."}],"개념":[{"종류":"표","제목":"토지의 자연적 특성과 파생 현상","머리":["특성","내용","파생 현상"],"행":[["부동성","위치가 고정","지역성·국지적 시장, 외부효과, 지역분석, 임장활동, 부동산활동의 장소적 한계"],["영속성(비소모성)","사용·시간으로 소모되지 않음","감가상각 배제, 가치보존·소유 선호, 장기 투자"],["부증성(비생산성)","물리적 양을 늘릴 수 없음","물리적 공급의 완전비탄력, 지대·지가 발생, 최유효이용, 집약적 이용"],["개별성(비동질성)","같은 토지가 없음","일물일가 법칙 배제, 상품 비교 곤란, 개별분석, 거래 정보의 비공개성"]]},{"종류":"비교","제목":"토지 공급: 물리적 공급과 경제적 공급","왼쪽":{"이름":"물리적(자연적) 공급","항목":["토지 면적 자체","부증성 때문에 장·단기 완전비탄력","간척 등이 있어도 일반적으로 고정으로 봄"]},"오른쪽":{"이름":"경제적(용도적) 공급","항목":["특정 용도의 토지 공급","용도 전환·용도변경으로 증감","가격이 오르면 늘어나므로 비탄력적이어도 완전비탄력은 아님"]}}],"함정":"부증성을 곧바로 모든 공급의 완전비탄력으로 확장한 선지에 속는다. 완전비탄력은 물리적 공급에만 해당한다. 영속성과 감가상각을 이어 붙인 문장도 자주 나온다. 토지는 감가상각하지 않고 건물은 한다."},"33회-1차-006":{"한줄":"수요와 공급이 함께 줄면 균형거래량은 확실히 감소하고, 가격은 수요 감소폭이 더 클 때 하락한다.","근거":[{"이론":"수요·공급 변화와 균형","내용":"수요 증가는 가격과 거래량을 올리고, 공급 증가는 가격을 내리고 거래량을 올린다. 둘이 같은 방향으로 함께 움직이면 거래량 방향이 확정되고 가격은 변화폭으로 정해진다. 반대 방향으로 움직이면 가격 방향이 확정되고 거래량은 변화폭으로 정해진다."}],"선지":[{"번호":1,"판정":"틀림","설명":"수요 불변·공급 감소이면 공급곡선이 왼쪽으로 이동해 균형가격은 상승하고 균형거래량은 감소한다."},{"번호":2,"판정":"틀림","설명":"공급 불변·수요 증가이면 균형가격은 상승하고 균형거래량도 증가한다."},{"번호":3,"판정":"틀림","설명":"수요·공급이 동시에 증가할 때 공급 증가폭이 더 크면 균형가격은 하락하고 균형거래량은 증가한다."},{"번호":4,"판정":"옳음","설명":"동시 감소이므로 거래량은 감소한다. 수요 감소폭이 더 크면 가격은 하락한다."},{"번호":5,"판정":"틀림","설명":"수요 증가·공급 감소이면 가격은 상승한다. 수요 증가폭이 더 크면 거래량은 증가하고, 공급 감소폭이 더 크면 거래량은 감소한다."}],"개념":[{"종류":"표","제목":"수요·공급 변화에 따른 균형 변화","머리":["수요","공급","균형가격","균형거래량"],"행":[["증가","불변","상승","증가"],["감소","불변","하락","감소"],["불변","증가","하락","증가"],["불변","감소","상승","감소"],["증가","증가","증가폭 비교(수요폭이 크면 상승, 공급폭이 크면 하락)","증가"],["감소","감소","감소폭 비교(수요폭이 크면 하락, 공급폭이 크면 상승)","감소"],["증가","감소","상승","증가폭 비교(수요폭이 크면 증가, 공급폭이 크면 감소)"],["감소","증가","하락","변화폭 비교(수요폭이 크면 감소, 공급폭이 크면 증가)"]]}],"함정":"수요·공급이 같은 방향으로 움직이면 거래량이, 반대 방향이면 가격이 확정된다. 확정되지 않는 변수만 변화폭으로 가른다. 3번은 동시 증가에서 가격이 상승한다고 확정해 놓았고, 5번은 반대 방향 이동에서 거래량을 감소로 확정해 놓았다."},"33회-1차-018":{"한줄":"개발부담금은 개발이익 환수에 관한 법률에 따라 먼저 도입됐고, 재건축부담금은 재건축초과이익 환수에 관한 법률에 따라 나중에 도입됐다.","근거":[{"법령":"개발이익 환수에 관한 법률","조문":"제2조제4호","원문":"4. \"개발부담금\"이란 개발이익 중 이 법에 따라 특별자치시장ㆍ특별자치도지사ㆍ시장ㆍ군수 또는 구청장(구청장은 자치구의 구청장을 말하며, 이하 \"시장ㆍ군수ㆍ구청장\"이라 한다)이 부과ㆍ징수하는 금액을 말한다."},{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제1조","원문":"이 법은 부동산에 관한 소유권과 그 밖의 물권을 실체적 권리관계와 일치하도록 실권리자 명의(名義)로 등기하게 함으로써 부동산등기제도를 악용한 투기ㆍ탈세ㆍ탈법행위 등 반사회적 행위를 방지하고 부동산 거래의 정상화와 부동산 가격의 안정을 도모하여 국민경제의 건전한 발전에 이바지함을 목적으로 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"분양가상한제는 주택법 제57조에 따라 시행 중이나 택지소유상한제는 폐지되어 시행되지 않는다."},{"번호":2,"판정":"틀림","설명":"토지비축제도는 정부가 직접 토지를 매입·비축하는 직접개입 수단이다. 부동산가격공시제도는 정보 제공으로 시장 판단을 돕는 간접개입이다."},{"번호":3,"판정":"옳음","설명":"개발이익 환수에 관한 법률의 개발부담금이 먼저 시행됐고, 재건축부담금은 재건축초과이익 환수에 관한 법률로 뒤에 도입됐다."},{"번호":4,"판정":"틀림","설명":"PIR은 주택가격÷가구소득으로, 값이 클수록 소득에 비해 주택가격이 높아 구매가 어렵다."},{"번호":5,"판정":"틀림","설명":"부동산실명제의 근거 법률은 부동산 실권리자명의 등기에 관한 법률이다(제1조)."}],"개념":[{"종류":"표","제목":"정부의 시장개입 방식","머리":["구분","수단","내용"],"행":[["직접개입","토지은행(토지비축), 공영개발, 공공임대주택 공급","정부가 직접 매입·공급하는 방식"],["직접규제","토지거래허가제, 분양가상한제, 용도지역·지구제","행위나 가격을 법으로 제한"],["간접개입","금융지원, 세제 혜택·중과, 보조금, 부동산가격공시","유인이나 정보를 통해 민간 결정에 영향"],["환수·부담금","개발부담금, 재건축부담금","개발이익을 환수해 공익에 사용"]]},{"종류":"표","제목":"주택지불능력 지표","머리":["지표","산식","값이 클수록"],"행":[["PIR(소득 대비 주택가격 비율)","주택가격÷가구소득","구매 부담 증가, 주택구매 어려움"],["RIR(소득 대비 임대료 비율)","임대료÷가구소득","임차 부담 증가"],["의의","가구의 지불능력 측정","정책 대상 판단"]]}],"함정":"토지비축을 간접개입으로 분류한 문장에 속기 쉽다. 정부가 직접 사고 파는 방식이 직접개입이다. PIR은 값이 클수록 구매가 어려워진다는 점도 반대로 쓰기 쉽다. 폐지된 제도(택지소유상한제)는 현재 시행되지 않는다."},"33회-1차-021":{"한줄":"순현재가치는 내부수익률이 아니라 투자자의 요구수익률로 할인한 현금유입의 현가에서 현금유출의 현가를 뺀 값이다.","근거":[{"이론":"순현재가치(NPV)와 내부수익률(IRR)","내용":"NPV = 현금유입의 현가(요구수익률로 할인) − 현금유출의 현가. IRR은 NPV를 0으로 만드는 할인율, 곧 유입의 현가와 유출의 현가를 같게 하는 수익률이다."},{"이론":"요구수익률","내용":"요구수익률 = 무위험률 + 위험할증률 + 예상 인플레이션율. 시장금리가 오르거나 투자자가 위험을 더 싫어하면 오른다."}],"선지":[{"번호":1,"판정":"옳음","설명":"자산가치 극대화와 운영수익 극대화는 자산관리의 목적이다. 투자 후 관리 단계에서 운영전략을 세운다."},{"번호":2,"판정":"옳음","설명":"금리가 오르면 무위험률이 올라 요구수익률의 기본 수준이 높아진다."},{"번호":3,"판정":"옳음","설명":"위험기피도가 클수록 위험할증률이 커져 같은 자산에도 더 높은 수익률을 요구한다."},{"번호":4,"판정":"옳음","설명":"민감도분석은 수익, 비용, 공실률 같은 투입변수가 변할 때 순현재가치·내부수익률 등 결과가 얼마나 달라지는지 본다."},{"번호":5,"판정":"틀림","설명":"NPV를 구하는 할인율은 요구수익률이다. 내부수익률은 NPV를 0으로 만드는 값으로 NPV 계산의 입력값이 아니다."}],"개념":[{"종류":"표","제목":"수익률 세 가지","머리":["구분","뜻","시점·쓰임"],"행":[["기대수익률","투자로 얻을 것으로 예상하는 수익률","투자 전, 요구수익률과 비교해 투자 여부를 정한다"],["요구수익률","투자자가 최소한 얻어야 한다고 보는 수익률 (무위험률 + 위험할증률 + 예상 인플레이션율)","투자 전, NPV의 할인율·투자 기준선"],["실현수익률","투자를 끝내고 실제로 얻은 수익률","투자 후, 사후 성과"],["투자 결정","기대수익률 > 요구수익률이면 채택, 기대수익률 < 요구수익률이면 기각","위험이 클수록 요구수익률이 높아진다"]]},{"종류":"표","제목":"요구수익률을 움직이는 요인","머리":["요인","변화","요구수익률"],"행":[["시장금리(무위험률)","상승","상승"],["투자자의 위험기피도","커짐","상승"],["투자자산의 위험","커짐","상승"],["예상 인플레이션율","상승","상승"],["위험 선호(위험 감수 성향)","커짐","하락"]]}],"함정":"⑤는 ‘내부수익률’이라는 낱말이 투자분석 문맥에서 자연스러워 맞는 문장처럼 읽힌다. 할인율은 요구수익률이고 내부수익률은 계산으로 구하는 결과값이다."},"33회-1차-023":{"한줄":"자본환원율 = 순영업소득 ÷ 자산가격이므로, 순영업소득이 일정한데 자산가격이 오르면 자본환원율은 낮아진다.","근거":[{"이론":"자본환원율","내용":"자본환원율(R) = 순영업소득(NOI) ÷ 부동산가격(V). 부동산가격 = NOI ÷ R. 자본의 기회비용과 투자위험을 반영한다."},{"이론":"자본환원율 산정방법","내용":"시장추출법(유사 거래사례에서 추출), 조성법(무위험률 + 위험할증률 ± 비유동성·관리 난이도·금융 상 이점), 투자결합법(물리적 결합·금융적 결합), 부채감당법, 엘우드법."}],"선지":[{"번호":1,"판정":"옳음","설명":"자본환원율을 구하는 대표 방법이다. 시장추출법은 시장자료에서 직접 뽑는다."},{"번호":2,"판정":"옳음","설명":"금리가 오르면 자본의 기회비용이 커져 자본환원율이 높아진다."},{"번호":3,"판정":"틀림","설명":"NOI가 일정할 때 가격이 오르면 R = NOI ÷ V가 작아진다. 투자수요 증가·가격 상승은 자본환원율을 낮추는 요인이다."},{"번호":4,"판정":"옳음","설명":"위험할증률이 줄어 자본환원율이 낮아진다."},{"번호":5,"판정":"옳음","설명":"시장이 균형이어도 유형·위치별 위험과 성장 전망이 달라 자본환원율은 부동산마다 다를 수 있다."}],"개념":[{"종류":"표","제목":"자본환원율을 움직이는 요인 (NOI 일정 가정)","머리":["요인","변화","자본환원율","부동산가격"],"행":[["시장금리·기회비용","상승","상승","하락"],["투자위험(위험할증률)","감소","하락","상승"],["투자수요","증가 (가격 상승)","하락","상승"],["순영업소득 성장 기대","커짐","하락","상승"],["부동산 유동성","높음","하락","상승"]]},{"종류":"표","제목":"자본환원율 산정방법","머리":["방법","내용"],"행":[["시장추출법","시장에서 거래된 유사 부동산의 NOI와 가격으로 R을 추출"],["조성법","무위험률 + 위험할증률(+ 비유동성·관리 난이도·금융 상 이점 가감)"],["투자결합법(물리적)","토지환원율과 건물환원율을 가격 구성비로 가중평균"],["투자결합법(금융적)","저당환원율과 지분환원율을 대출·자기자본 구성비로 가중평균"],["부채감당법","R = 부채감당률 × 대부비율 × 저당상수"]]}],"함정":"‘수요가 늘면 좋은 것이니 환원율도 오른다’는 식의 직관이 ③을 맞는 문장으로 읽게 만든다. 환원율은 수익률이므로 가격이 오르면 내려간다."},"33회-1차-027":{"한줄":"주택가격이 급등할 때는 대출을 죄고 금리를 올리는 방향으로 대응한다. 소비금융 확대, 금리인하, 대출규제 완화는 수요를 더 키운다.","근거":[{"법령":"주택도시기금법","조문":"제9조제1항제1호","원문":"기금의 주택계정은 다음 각 호의 용도에 사용한다. 1. 다음 각 목에 대한 출자 또는 융자 가. 국민주택의 건설 나. 국민주택규모 이하의 주택의 구입ㆍ임차 또는 개량"},{"이론":"주택금융의 경기조절 기능","내용":"과열기에는 금리 인상, LTV·DTI 하향, 대출규제 강화로 수요를 억제하고, 침체기에는 반대로 금리 인하, LTV·DTI 상향, 상환기간 연장으로 수요를 늘린다."}],"선지":[{"번호":1,"판정":"틀림","설명":"가격 급등기에는 소비금융 축소, 금리 인상, 대출규제 강화로 수요를 억제한다. 지문의 세 수단은 침체기 처방이다."},{"번호":2,"판정":"옳음","설명":"주택구입 자금을 빌려 줄수록 구입능력이 커져 자가소유가 늘 수 있다."},{"번호":3,"판정":"옳음","설명":"대출이 늘면 매수 여력이 커져 거래가 활발해진다."},{"번호":4,"판정":"옳음","설명":"주택금융은 거주용 부동산의 구입·임차에 필요한 자금조달 금융상품을 포괄하는 개념이다."},{"번호":5,"판정":"옳음","설명":"주택도시기금 주택계정은 국민주택의 건설, 국민주택규모 이하 주택의 구입·임차·개량에 출자 또는 융자한다(주택도시기금법 제9조제1항제1호가목·나목)."}],"개념":[{"종류":"표","제목":"경기 국면별 주택금융 정책수단","머리":["수단","과열기(가격 급등)","침체기"],"행":[["금리","인상","인하"],["LTV·DTI","하향","상향"],["대출규제","강화","완화"],["상환기간","단축","연장"],["주택거래·가격에 미치는 효과","수요 억제","수요 확대"]]},{"종류":"표","제목":"주택도시기금 주택계정의 출자·융자 대상 (주택도시기금법 제9조제1항제1호)","머리":["목","대상"],"행":[["가","국민주택의 건설"],["나","국민주택규모 이하 주택의 구입·임차·개량"],["다","준주택의 건설"],["라","준주택의 구입·임차·개량"],["마","국민주택규모 이하 주택의 리모델링"],["바","국민주택 건설을 위한 대지조성사업"]]}],"함정":"‘주택금융 확대 = 좋은 것’이라는 인상으로 ①을 고르지 못한다. 가격 급등과 대출 확대는 같이 움직이므로 대응 방향은 반대다."},"33회-1차-040":{"한줄":"공시지가기준법은 거래사례비교법, 임대사례비교법과 함께 비교방식에 속한다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제11조제2호","원문":"비교방식: 거래사례비교법, 임대사례비교법 등 시장성의 원리에 기초한 감정평가방식 및 공시지가기준법"},{"법령":"감정평가에 관한 규칙","조문":"제2조제2호","원문":"\"기준시점\"이란 대상물건의 감정평가액을 결정하는 기준이 되는 날짜를 말한다."},{"법령":"감정평가에 관한 규칙","조문":"제7조제3항","원문":"하나의 대상물건이라도 가치를 달리하는 부분은 이를 구분하여 감정평가할 수 있다."},{"법령":"감정평가에 관한 규칙","조문":"제12조제1항","원문":"감정평가법인등은 제14조부터 제26조까지의 규정에서 대상물건별로 정한 감정평가방법(이하 \"주된 방법\"이라 한다)을 적용하여 감정평가해야 한다. 다만, 주된 방법을 적용하는 것이 곤란하거나 부적절한 경우에는 다른 감정평가방법을 적용할 수 있다."},{"법령":"감정평가에 관한 규칙","조문":"제13조제1항","원문":"감정평가법인등은 법 제6조에 따른 감정평가서(「전자문서 및 전자거래기본법」에 따른 전자문서로 된 감정평가서를 포함한다. 이하 같다)를 의뢰인과 이해관계자가 이해할 수 있도록 명확하고 일관성 있게 작성해야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"기준시점의 정의다(제2조제2호)."},{"번호":2,"판정":"옳음","설명":"구분 평가의 근거는 제7조제3항이다."},{"번호":3,"판정":"틀림","설명":"공시지가기준법도 비교방식이다(제11조제2호). 토지는 공시지가기준법이 주된 방법이다(제14조제1항)."},{"번호":4,"판정":"옳음","설명":"주된 방법이 곤란하거나 부적절하면 다른 방법을 적용할 수 있다(제12조제1항 단서)."},{"번호":5,"판정":"옳음","설명":"감정평가서 작성 원칙이다(제13조제1항)."}],"개념":[{"종류":"표","제목":"3방식 6방법 (규칙 제11조)","머리":["방식 (원리)","가액을 구하면","임대료를 구하면"],"행":[["원가방식 (비용성)","원가법 → 적산가액","적산법 → 적산임료"],["비교방식 (시장성)","거래사례비교법 → 비준가액, 공시지가기준법(토지)","임대사례비교법 → 비준임료"],["수익방식 (수익성)","수익환원법 → 수익가액","수익분석법 → 수익임료"]]},{"종류":"표","제목":"감정평가 기본원칙","머리":["원칙","내용","조문"],"행":[["시장가치기준 원칙","감정평가액은 시장가치를 기준으로 결정. 법령 규정·의뢰인 요청·사회통념상 필요 시 시장가치 외 가치도 가능","제5조"],["현황기준 원칙","기준시점의 이용상황(불법적·일시적 이용 제외)과 공법상 제한을 받는 상태 기준. 감정평가조건을 붙일 수 있는 경우 있음","제6조"],["개별물건기준 원칙","대상물건마다 개별로 평가. 일체 거래·용도상 불가분이면 일괄 가능, 가치를 달리하는 부분은 구분 가능, 일부분 평가도 가능","제7조"]]}],"함정":"‘공시지가비교법’이라는 이름이 비교방식이 아니라는 느낌을 준다. 공시지가기준법은 비교방식에 들어간다."},"33회-1차-043":{"한줄":"제108조제2항에 따라 보호받는 선의의 제3자에게는 누구도 허위표시의 무효로 대항하지 못한다.","근거":[{"법령":"민법","조문":"제108조","원문":"①상대방과 통정한 허위의 의사표시는 무효로 한다. ②전항의 의사표시의 무효는 선의의 제삼자에게 대항하지 못한다."},{"법령":"민법","조문":"제107조제1항","원문":"①의사표시는 표의자가 진의아님을 알고 한 것이라도 그 효력이 있다. 그러나 상대방이 표의자의 진의아님을 알았거나 이를 알 수 있었을 경우에는 무효로 한다."},{"판례":"대법원 판례(제3자의 범위)","요지":"허위표시의 당사자와 포괄승계인 이외의 자로서 허위표시에 기초하여 새로운 이해관계를 맺은 자가 제3자이다. 가장소비대차의 대여금채권을 양수한 자, 가장 매수인으로부터 저당권을 취득한 자가 이에 해당한다. 대리인이 허위표시를 한 경우 본인은 제3자가 아니다."}],"선지":[{"번호":1,"판정":"틀림","설명":"통정은 상대방과 합의하여 허위의 표시를 하는 것이다. 상대방이 진의 아님을 알기만 한 경우는 비진의표시(제107조제1항 단서)의 문제이다."},{"번호":2,"판정":"틀림","설명":"가장행위가 무효여도 은닉행위는 그 자체의 요건을 갖추어야 유효하다. 은닉행위가 당연히 무효가 되는 것은 아니다."},{"번호":3,"판정":"틀림","설명":"대리행위의 효과는 본인에게 귀속되므로 본인은 허위표시의 당사자와 같은 지위이다. 제3자에 해당하지 않는다."},{"번호":4,"판정":"옳음","설명":"제108조제2항의 선의 제3자에게는 표의자, 상대방, 그 승계인 누구도 무효로 대항하지 못한다."},{"번호":5,"판정":"틀림","설명":"가장소비대차의 대여금채권을 양수한 선의의 양수인은 허위표시에 기초하여 새로 이해관계를 맺은 제3자로서 보호받는다."}],"개념":[{"종류":"표","제목":"제108조제2항의 제3자 해당 여부","머리":["구분","사례","제3자 해당"],"행":[["해당","가장소비대차 대여금채권의 양수인","해당"],["해당","허위표시로 이전등기를 받은 자로부터 저당권을 취득한 자","해당"],["해당","가장채권을 압류한 채권자","해당"],["해당하지 않음","대리인이 한 허위표시에서의 본인","해당하지 않음"],["해당하지 않음","당사자의 상속인 등 포괄승계인","해당하지 않음"],["해당하지 않음","채권 가장양도에서의 채무자","해당하지 않음"],["해당하지 않음","허위표시 목적물에 대한 일반 채권자","해당하지 않음"]]},{"종류":"표","제목":"진의 아닌 표시와 통정허위표시 비교","머리":["구분","비진의표시(제107조)","통정허위표시(제108조)"],"행":[["상대방과의 통정","없음","있음"],["무효 요건","상대방이 진의 아님을 알았거나 알 수 있었을 때","상대방과 통정한 허위의 표시이면 무효"],["선의 제3자 보호","있음(제107조제2항)","있음(제108조제2항)"],["제3자의 선의 증명","무효를 주장하는 자가 제3자의 악의를 증명","무효를 주장하는 자가 제3자의 악의를 증명"]]}],"함정":"상대방이 진의 아님을 알기만 한 경우는 비진의표시이고 통정허위표시가 아니다. 대리인이 한 허위표시에서 본인은 제3자가 아니다. 가장채권의 양수인은 보호되는 제3자이다."},"33회-1차-048":{"한줄":"법정대리인은 자기 책임으로 복대리인을 선임할 수 있다(제122조).","근거":[{"법령":"민법","조문":"제122조","원문":"법정대리인은 그 책임으로 복대리인을 선임할 수 있다. 그러나 부득이한 사유로 인한 때에는 전조제1항에 정한 책임만이 있다."},{"법령":"민법","조문":"제119조","원문":"대리인이 수인인 때에는 각자가 본인을 대리한다. 그러나 법률 또는 수권행위에 다른 정한 바가 있는 때에는 그러하지 아니하다."},{"법령":"민법","조문":"제123조","원문":"①복대리인은 그 권한내에서 본인을 대리한다."},{"판례":"대법원 판례(증명책임)","요지":"등기가 마쳐져 있으면 그 원인과 절차가 적법한 것으로 추정되므로, 대리권이 없었다고 다투는 쪽이 증명책임을 진다."}],"선지":[{"번호":1,"판정":"틀림","설명":"대리인이 수인이면 각자가 본인을 대리한다(제119조). 공동대리는 법률이나 수권행위에 정한 경우에 한한다."},{"번호":2,"판정":"틀림","설명":"대리행위의 하자로 인한 취소권은 법률행위의 당사자인 본인에게 귀속한다. 대리인이 취소하려면 별도의 수권이 있어야 한다."},{"번호":3,"판정":"틀림","설명":"등기가 마쳐진 경우 적법하게 이루어진 것으로 추정되어, 대리권 없음을 주장하는 쪽에 증명책임이 있다."},{"번호":4,"판정":"틀림","설명":"복대리인은 대리인이 본인의 이름으로 선임한, 본인의 대리인이다(제123조제1항)."},{"번호":5,"판정":"옳음","설명":"법정대리인은 자유롭게 복대리인을 선임할 수 있고 그 대신 선임·감독의 전 책임을 진다(제122조). 부득이한 사유로 선임한 때에는 선임·감독 책임만 진다."}],"개념":[{"종류":"표","제목":"복임권과 복대리인 선임의 책임","머리":["구분","임의대리인","법정대리인"],"행":[["복임권","본인의 승낙이 있거나 부득이한 사유가 있을 때만(제120조)","자유롭게 가능(제122조)"],["선임·감독 책임","본인에 대해 선임·감독 책임(제121조제1항)","원칙적으로 전 책임, 부득이한 사유로 선임했으면 선임·감독 책임만(제122조)"],["본인이 지명한 복대리인","부적임·불성실을 알고 통지나 해임을 게을리한 때만 책임(제121조제2항)","해당 없음"],["복대리인의 지위","본인의 대리인, 본인·제3자에 대해 대리인과 동일한 권리의무(제123조)","같음"]]},{"종류":"표","제목":"대리인 관련 기준","머리":["쟁점","기준","근거"],"행":[["의사표시의 하자·악의·과실 판단","대리인을 기준으로 결정","제116조제1항"],["본인이 특정 행위를 지시한 경우","본인이 안 사정은 대리인의 부지를 주장하지 못함","제116조제2항"],["대리인의 행위능력","필요 없음","제117조"],["수인의 대리인","각자 대리가 원칙","제119조"]]}],"함정":"등기가 있으면 대리권 없음을 주장하는 쪽이 증명한다. 복대리인은 본인의 대리인이다. 수인의 대리인은 각자 대리하는 것이 원칙이다."},"33회-1차-052":{"한줄":"등기부상 명의인에게서 양수하여 인도받고 명의를 의심할 사정이 없으면 과실 없는 점유자이다.","근거":[{"법령":"민법","조문":"제207조","원문":"①전3조의 청구권은 제194조의 규정에 의한 간접점유자도 이를 행사할 수 있다."},{"법령":"민법","조문":"제197조","원문":"①점유자는 소유의 의사로 선의, 평온 및 공연하게 점유한 것으로 추정한다. ②선의의 점유자라도 본권에 관한 소에 패소한 때에는 그 소가 제기된 때로부터 악의의 점유자로 본다."},{"판례":"대법원 판례(과실 없는 점유)","요지":"양도인이 등기부상 명의인과 동일인이고 그 명의를 의심할 만한 특별한 사정이 없으면, 양수하여 인도받은 자는 과실 없이 점유를 개시한 것으로 본다."}],"선지":[{"번호":1,"판정":"틀림","설명":"간접점유자도 점유보호청구권을 행사할 수 있다(제207조제1항)."},{"번호":2,"판정":"틀림","설명":"취득시효의 점유에는 간접점유도 포함된다."},{"번호":3,"판정":"틀림","설명":"점유자는 소유의 의사로 점유한 것으로 추정되므로(제197조제1항) 타주점유라고 주장하는 쪽이 증명한다."},{"번호":4,"판정":"틀림","설명":"선의 점유자는 본권에 관한 소가 제기된 때부터 악의 점유자로 본다(제197조제2항). 패소 확정 시가 아니다."},{"번호":5,"판정":"옳음","설명":"등기부를 믿고 양수하여 인도받은 자는 과실 없는 점유자이다."}],"개념":[{"종류":"표","제목":"점유의 추정(제197조~제200조)","머리":["규정","추정 내용","의미"],"행":[["제197조제1항","소유의 의사, 선의, 평온, 공연한 점유","자주점유 아님을 주장하는 쪽이 증명"],["제197조제2항","본권 소에서 패소하면 소 제기 때부터 악의","확정 시가 아님"],["제198조","전후 양 시점에 점유하면 계속한 것으로 추정","중간 점유의 중단은 반증"],["제199조","점유의 승계 시 자기 점유만 또는 전점유와 합산 주장 가능","합산 시 하자도 승계"],["제200조","점유물에 행사하는 권리는 적법하게 보유한 것으로 추정","권리의 적법 추정"]]},{"종류":"표","제목":"점유보호청구권","머리":["청구권","행사 기간","내용"],"행":[["점유물반환(제204조)","침탈을 당한 날부터 1년","물건의 반환과 손해배상, 악의의 특별승계인에게만 행사"],["점유물방해제거(제205조)","방해가 종료한 날부터 1년","방해의 제거와 손해배상"],["점유물방해예방(제206조)","방해 염려가 있는 동안","방해의 예방 또는 손해배상의 담보"],["간접점유자(제207조)","위와 같음","제204조~제206조를 행사 가능"]]}],"함정":"본권 소송의 패소는 확정 시가 아니라 소가 제기된 때부터 악의로 본다. 자주점유는 추정되므로 타주점유를 주장하는 쪽이 증명한다. 간접점유는 점유보호청구권과 취득시효 모두에서 인정된다."},"33회-1차-063":{"한줄":"요역지 공유자 1인은 자기 지분에 관하여 그 토지를 위한 지역권을 소멸하게 하지 못한다(제293조제1항).","근거":[{"법령":"민법","조문":"제293조","원문":"①토지공유자의 1인은 지분에 관하여 그 토지를 위한 지역권 또는 그 토지가 부담한 지역권을 소멸하게 하지 못한다."},{"법령":"민법","조문":"제292조","원문":"①지역권은 요역지소유권에 부종하여 이전하며 또는 요역지에 대한 소유권이외의 권리의 목적이 된다. 그러나 다른 약정이 있는 때에는 그 약정에 의한다."},{"법령":"민법","조문":"제301조","원문":"제214조의 규정은 지역권에 준용한다."},{"판례":"대법원 판례(지역권의 존속기간)","요지":"지역권의 존속기간은 영구무한으로 약정할 수 있다."},{"판례":"대법원 판례(승역지 반환청구)","요지":"지역권자에게는 승역지 반환청구권이 인정되지 않는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"요역지는 1필의 토지 전부여야 한다. 일부를 요역지로 할 수 없다."},{"번호":2,"판정":"틀림","설명":"지역권은 요역지 소유권에 부종하여 함께 이전한다(제292조제1항)."},{"번호":3,"판정":"틀림","설명":"지역권의 존속기간은 영구무한으로도 약정할 수 있다."},{"번호":4,"판정":"틀림","설명":"지역권은 점유를 수반하지 않으므로 승역지 반환청구권이 없다. 방해제거·예방청구만 한다(제301조)."},{"번호":5,"판정":"옳음","설명":"공유자 1인은 자기 지분만으로 그 토지를 위한 지역권을 소멸하게 하지 못한다(제293조제1항)."}],"개념":[{"종류":"표","제목":"지역권 불가분성 정리","머리":["상황","효과","근거"],"행":[["공유자 1인의 지역권 취득","다른 공유자도 취득","제295조제1항"],["점유 취득시효 중단","지역권을 행사하는 모든 공유자에 대한 사유가 아니면 효력 없음","제295조제2항"],["요역지 공유자 1인의 시효 중단·정지","다른 공유자를 위해서도 효력 있음","제296조"],["공유자 1인의 지역권 소멸","자기 지분에 관해 소멸하게 하지 못함","제293조제1항"],["토지 분할·일부 양도","지역권은 요역지·승역지 각 부분에 존속","제293조제2항"]]},{"종류":"표","제목":"지역권의 기본 구조","머리":["구분","내용"],"행":[["요역지","편익을 받는 토지, 1필 전부"],["승역지","편익을 제공하는 토지, 일부도 가능"],["존속기간","영구무한 약정 가능"],["지역권자의 청구","방해제거·방해예방, 반환청구는 불가"]]}],"함정":"요역지는 1필 전부여야 하고, 지역권은 요역지 소유권과 함께 이전한다. 존속기간은 영구도 가능하다. 지역권자에게는 승역지 반환청구권이 없고 방해제거·예방청구만 인정된다."},"33회-1차-080":{"한줄":"구분소유자가 10인 이상이면 관리단을 대표하고 사무를 집행할 관리인을 반드시 선임하여야 한다.","근거":[{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제24조제1·2항","원문":"제24조(관리인의 선임 등) ① 구분소유자가 10인 이상일 때에는 관리단을 대표하고 관리단의 사무를 집행할 관리인을 선임하여야 한다. ② 관리인은 구분소유자일 필요가 없으며, 그 임기는 2년의 범위에서 규약으로 정한다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제26조의3제3항","원문":"제26조의3(관리위원회의 설치 및 기능) ③ 제1항에 따라 관리위원회를 둔 경우 관리인은 제25조제1항 각 호의 행위를 하려면 관리위원회의 결의를 거쳐야 한다. 다만, 규약으로 달리 정한 사항은 그러하지 아니하다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제26조의4제2항","원문":"제26조의4(관리위원회의 구성 및 운영) ② 관리인은 규약에 달리 정한 바가 없으면 관리위원회의 위원이 될 수 없다."},{"법령":"집합건물의 소유 및 관리에 관한 법률 시행령","조문":"제10조제2항","원문":"제10조(관리위원회의 의결방법) ② 관리위원회 위원은 질병, 해외체류 등 부득이한 사유가 있는 경우 외에는 서면이나 대리인을 통하여 의결권을 행사할 수 없다."}],"선지":[{"번호":1,"판정":"틀림","설명":"관리인은 구분소유자일 필요가 없다(제24조 제2항)."},{"번호":2,"판정":"옳음","설명":"제24조 제1항이다."},{"번호":3,"판정":"틀림","설명":"관리위원회를 둔 경우 관리인은 제25조 제1항 각 호의 행위(공용부분의 보존행위 포함)를 하려면 관리위원회의 결의를 거쳐야 한다. 규약으로 달리 정한 사항만 예외이다(제26조의3 제3항)."},{"번호":4,"판정":"틀림","설명":"관리인은 규약에 달리 정한 바가 없으면 관리위원회의 위원이 될 수 없다(제26조의4 제2항)."},{"번호":5,"판정":"틀림","설명":"관리위원회 위원은 질병, 해외체류 등 부득이한 사유가 있는 경우 외에는 서면이나 대리인을 통하여 의결권을 행사할 수 없다(시행령 제10조 제2항)."}],"개념":[{"종류":"표","제목":"관리인·관리위원회","머리":["구분","내용","근거"],"행":[["관리인 선임","구분소유자 10인 이상이면 선임 의무","법 제24조 제1항"],["관리인 자격·임기","구분소유자일 필요 없음, 임기 2년 범위에서 규약","법 제24조 제2항"],["선임·해임","관리단집회 결의(규약으로 관리위원회 결의 가능)","법 제24조 제3항"],["관리인 권한","공용부분 보존행위, 결의 집행, 비용 청구·수령 등","법 제25조 제1항"],["관리위원회 설치","규약으로 설치 가능, 관리인 감독","법 제26조의3 제1·2항"],["관리인과 위원","규약이 없으면 관리인은 위원 불가","법 제26조의4 제2항"],["위원 의결권","부득이한 사유 외 서면·대리 행사 불가","시행령 제10조 제2항"]]},{"종류":"표","제목":"관리단집회 의결정족수","머리":["사항","정족수","근거"],"행":[["통상 결의","구분소유자 과반수 및 의결권 과반수","법 제38조 제1항"],["공용부분 변경","구분소유자 2/3 이상 및 의결권 2/3 이상(개량 목적이 지나치게 많은 비용이 들지 않으면 통상 결의)","법 제15조 제1항"],["재건축 결의","구분소유자 4/5 이상 및 의결권 4/5 이상","법 제47조 제2항"],["서면·전자적 방법 합의","구분소유자 3/4 이상 및 의결권 3/4 이상(재건축 등은 4/5 이상)","법 제41조 제1항·제2항"],["임시 집회 소집","구분소유자 5분의 1 이상이 청구(규약으로 감경 가능)","법 제33조 제2항"]]}],"함정":"관리인은 구분소유자여야 한다고 보기 쉽다. 구분소유자일 필요가 없다. 관리위원회를 둔 경우 보존행위도 관리위원회 결의를 거쳐야 하고(규약 예외), 관리인은 위원이 될 수 없다는 점이 함께 나온다."},"33회-2차-034":{"한줄":"스스로 발견한 상대방과 거래한 경우 의뢰인은 중개보수 전액이 아니라 중개보수의 50% 범위에서 중개사가 쓴 비용을 낸다.","근거":[{"법령":"공인중개사법 시행령","조문":"제20조제1항","원문":"법 제23조제1항의 규정에 따른 전속중개계약의 유효기간은 3월로 한다. 다만, 당사자간에 다른 약정이 있는 경우에는 그 약정에 따른다."},{"법령":"공인중개사법 시행규칙","조문":"제14조제2항","원문":"법 제23조제2항에서 \"국토교통부령이 정하는 기간\"이라 함은 3년을 말한다."},{"법령":"공인중개사법 시행규칙","조문":"별지 제15호서식(전속중개계약서)","원문":"② 갑은 을이 법 제25조에 따른 중개대상물 확인ㆍ설명의무를 이행하는데 협조하여야 한다. / 제3호의 경우에는 중개보수의 50퍼센트에 해당하는 금액의 범위에서 을이 중개행위를 할 때 소요된 비용…을 지급한다. / 이 계약에 정하지 않은 사항에 대하여는 갑과 을이 합의하여 별도로 정할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"약정이 있으면 3개월보다 길어도 된다(영 제20조제1항)."},{"번호":2,"판정":"옳음","설명":"전속중개계약서는 3년 보존한다(규칙 제14조제2항)."},{"번호":3,"판정":"옳음","설명":"의뢰인의 협조의무가 전속중개계약서(별지 제15호서식)에 있다."},{"번호":4,"판정":"옳음","설명":"계약서의 그 밖의 사항 조항에 합의로 별도 정할 수 있다고 되어 있다(별지 제15호서식)."},{"번호":5,"판정":"틀림","설명":"스스로 발견한 상대방과의 거래는 중개보수의 50% 범위의 비용만 낸다(별지 제15호서식)."}],"개념":[{"종류":"흐름","제목":"전속중개계약 이후 개업공인중개사의 의무","단계":[{"이름":"계약 체결","설명":"별지 제15호서식 사용, 계약서 3년 보존"},{"이름":"정보공개","설명":"체결 후 7일 이내 부동산거래정보망 또는 일간신문에 공개. 의뢰인이 비공개를 요청하면 공개하지 않음(법 제23조제3항)"},{"이름":"공개 통지","설명":"공개했으면 지체 없이 의뢰인에게 내용을 문서로 통지"},{"이름":"처리상황 통지","설명":"계약 체결 후 2주일에 1회 이상 문서로 통지"},{"이름":"거래 완성","설명":"정보망에 공개한 물건은 거래가 완성되면 지체 없이 거래정보사업자에게 통보(법 제24조제7항)"}]},{"종류":"표","제목":"공개할 정보(영 제20조제2항)","머리":["공개 항목","비고"],"행":[["종류·소재지·지목·면적·용도·구조·건축연도","물건 특정 사항"],["벽면·도배 상태","-"],["수도·전기·가스·소방·열공급·승강기 설비, 오수·폐수·쓰레기 처리시설 상태","-"],["도로·대중교통 연계성, 시장·학교 근접성, 지형, 일조·소음·진동","입지·환경조건"],["소유권·전세권·저당권·지상권·임차권 등 권리관계","권리자의 주소·성명 등 인적 사항은 공개 금지"],["공법상 이용제한·거래규제","-"],["거래예정금액·공시지가","임대차는 공시지가 공개하지 않을 수 있음"]]}],"함정":"선지 1과 2는 길이와 숫자만 보고 틀렸다고 오해하기 쉽다. 4개월 약정은 유효하고 보존은 3년이다. 5번만 위약금 범위가 다르다."},"33회-2차-051":{"한줄":"시장·군수가 도지사에게 기본계획 승인을 신청할 때 기초조사 결과를 첨부한다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제17조제1항","원문":"①시장 또는 군수는 법 제22조의2제1항에 따라 도시ㆍ군기본계획의 승인을 받으려면 도시ㆍ군기본계획안에 다음 각 호의 서류를 첨부하여 도지사에게 제출하여야 한다. 1. 기초조사 결과 2. 공청회개최 결과 3. 법 제21조에 따른 해당 시ㆍ군의 의회의 의견청취 결과 4. 해당 시ㆍ군에 설치된 지방도시계획위원회의 자문을 거친 경우에는 그 결과 5. 법 제22조의2제2항에 따른 관계 행정기관의 장과의 협의 및 도의 지방도시계획위원회의 심의에 필요한 서류"}],"선지":[{"번호":1,"판정":"옳음","설명":"첨부서류의 첫째가 기초조사 결과이다(영 제17조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"첨부하는 것은 공청회개최 결과이다. 청문조서는 해당하지 않는다(영 제17조제1항제2호). 청문은 개발행위허가 취소 등 처분에서 하는 절차이다(법 제136조)."},{"번호":3,"판정":"틀림","설명":"의회 관련 서류는 해당 시·군 의회의 의견청취 결과이다. 도의 의회는 관계가 없고 심의·의결 결과도 아니다(영 제17조제1항제3호)."},{"번호":4,"판정":"틀림","설명":"시·군 지방도시계획위원회는 자문을 거친 경우의 그 결과만 첨부한다. 도의 지방도시계획위원회는 심의 결과가 아니라 그 심의에 필요한 서류를 낸다(영 제17조제1항제4호·제5호)."},{"번호":5,"판정":"틀림","설명":"협의 상대는 관계 행정기관의 장이고, 심의 기관은 도의 지방도시계획위원회이다. 중앙도시계획위원회가 아니다(영 제17조제1항제5호, 법 제22조의2제2항)."}],"개념":[{"종류":"표","제목":"시장·군수 도시·군기본계획 승인 신청 첨부서류","머리":["호","서류","근거"],"행":[["1","기초조사 결과","영 제17조제1항제1호"],["2","공청회개최 결과","같은 항 제2호"],["3","해당 시·군 의회의 의견청취 결과","같은 항 제3호, 법 제21조"],["4","해당 시·군 지방도시계획위원회의 자문 결과(자문을 거친 경우)","같은 항 제4호"],["5","관계 행정기관 협의 및 도의 지방도시계획위원회 심의에 필요한 서류","같은 항 제5호, 법 제22조의2제2항"]]},{"종류":"흐름","제목":"시·군 기본계획 승인 후속 절차","단계":[{"이름":"승인 신청","설명":"시장·군수가 첨부서류를 붙여 도지사에게 제출(영 제17조제1항)"},{"이름":"보완 요청","설명":"수립기준 등에 맞지 않으면 도지사가 보완 요청(영 제17조제2항)"},{"이름":"협의·심의","설명":"도지사가 관계 행정기관 협의 후 지방도시계획위원회 심의(법 제22조의2제2항)"},{"이름":"승인·송부","설명":"승인하면 관계 행정기관의 장과 시장·군수에게 관계 서류 송부(법 제22조의2제4항)"},{"이름":"공고·열람","설명":"시·군 공보와 인터넷 홈페이지에 게재, 열람기간 30일 이상(영 제17조제3항)"}]}],"함정":"첨부서류는 영 제17조제1항 다섯 호에 적힌 것뿐이다. 의회 관련 서류는 시·군 의회의 의견청취 결과이고, 위원회 관련 서류는 시·군은 자문 결과, 도는 심의에 필요한 서류이다."},"33회-2차-041":{"한줄":"택지개발지구로 지정·고시된 지역은 도시지역으로 결정·고시된 것으로 본다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제42조제1항제4호","원문":"4. 「택지개발촉진법」 제3조에 따른 택지개발지구"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제37조제5항","원문":"⑤ 시ㆍ도지사 또는 대도시 시장은 대통령령으로 정하는 주거지역ㆍ공업지역ㆍ관리지역에 복합용도지구를 지정할 수 있으며, 그 지정기준 및 방법 등에 필요한 사항은 대통령령으로 정한다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제31조제6항","원문":"⑥ 법 제37조제5항에서 \"대통령령으로 정하는 주거지역ㆍ공업지역ㆍ관리지역\"이란 다음 각 호의 어느 하나에 해당하는 용도지역을 말한다. 1. 일반주거지역 2. 일반공업지역 3. 계획관리지역"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제37조제4항","원문":"④ 시ㆍ도지사 또는 대도시 시장은 연안침식이 진행 중이거나 우려되는 지역 등 대통령령으로 정하는 지역에 대해서는 제1항제5호의 방재지구의 지정 또는 변경을 도시ㆍ군관리계획으로 결정하여야 한다. 이 경우 도시ㆍ군관리계획의 내용에는 해당 방재지구의 재해저감대책을 포함하여야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제83조제1항","원문":"①용도지역ㆍ용도지구안에서의 도시ㆍ군계획시설에 대하여는 제71조 내지 제82조의 규정을 적용하지 아니한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제41조제2항","원문":"② 공유수면의 매립 목적이 그 매립구역과 이웃하고 있는 용도지역의 내용과 다른 경우 및 그 매립구역이 둘 이상의 용도지역에 걸쳐 있거나 이웃하고 있는 경우 그 매립구역이 속할 용도지역은 도시ㆍ군관리계획결정으로 지정하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"복합용도지구는 일반주거지역·일반공업지역·계획관리지역에 지정한다. 유통상업지역은 대상이 아니다(법 제37조제5항, 영 제31조제6항)."},{"번호":2,"판정":"틀림","설명":"연안침식이 진행 중이거나 동일 재해가 최근 10년 내 2회 이상 발생해 인명 피해를 입은 지역 등은 방재지구를 지정해야 한다. 특정용도제한지구는 오염물질 배출시설·청소년 유해시설 등의 입지를 제한하는 지구이다(법 제37조제1항제8호·제4항, 영 제31조제5항)."},{"번호":3,"판정":"틀림","설명":"용도지역·용도지구 안의 도시·군계획시설에는 영 제71조부터 제82조까지의 건축제한을 적용하지 않는다(영 제83조제1항)."},{"번호":4,"판정":"틀림","설명":"매립 목적이 이웃 용도지역과 다르면 도시·군관리계획결정으로 지정한다. 이웃 용도지역으로 보는 경우는 목적이 같을 때뿐이다(법 제41조제1항·제2항)."},{"번호":5,"판정":"옳음","설명":"택지개발지구는 도시지역으로 결정·고시된 것으로 본다(법 제42조제1항제4호)."}],"개념":[{"종류":"표","제목":"복합용도지구와 방재지구","머리":["구분","요건","근거"],"행":[["복합용도지구 지정 대상","일반주거지역, 일반공업지역, 계획관리지역","법 제37조제5항, 영 제31조제6항"],["복합용도지구 지정 면적","해당 용도지역 전체 면적의 3분의 1 이하","영 제31조제7항제3호"],["방재지구 의무 지정","연안침식관리구역으로 지정된 지역(연안육역)","영 제31조제5항제1호"],["방재지구 의무 지정","풍수해·산사태 등 동일 재해가 최근 10년 이내 2회 이상 발생해 인명 피해를 입은 지역","영 제31조제5항제2호"],["방재지구 지정 시 포함","재해저감대책","법 제37조제4항 후단"]]},{"종류":"표","제목":"용도지역·용도지구 건축제한의 적용 범위","머리":["대상","건축제한 적용"],"행":[["용도지역 안의 일반 건축물","영 제71조 및 해당 별표에 따름"],["도시·군계획시설","적용하지 않음(영 제83조제1항)"],["개발제한구역·도시자연공원구역·시가화조정구역·수산자원보호구역","각 해당 법령(영 제83조제3항)"],["취락지구·개발진흥지구·복합용도지구","지정목적 범위에서 대통령령으로 따로 정함(법 제76조제5항)"]]}],"함정":"복합용도지구는 일반주거지역·일반공업지역·계획관리지역에만 지정한다. 재해 반복 지역에는 방재지구를 지정하고, 도시·군계획시설에는 용도지역 건축제한이 적용되지 않으며, 매립 목적이 이웃 용도지역과 다르면 관리계획결정으로 용도지역을 정한다."},"33회-2차-056":{"한줄":"주된 사무소의 소재지를 변경하는 것은 경미한 사항의 변경이어서 변경인가가 아니라 신고 대상이다.","근거":[{"법령":"도시개발법","조문":"제13조제2항","원문":"② 조합이 제1항에 따라 인가를 받은 사항을 변경하려면 지정권자로부터 변경인가를 받아야 한다. 다만, 대통령령으로 정하는 경미한 사항을 변경하려는 경우에는 신고하여야 한다."},{"법령":"도시개발법 시행령","조문":"제30조제1호","원문":"제30조(조합설립인가사항의 경미한 변경) 법 제13조제2항 단서에서 \"대통령령으로 정하는 경미한 사항을 변경하려는 경우\"란 다음 각 호의 경우를 말한다. 1. 주된 사무소의 소재지를 변경하려는 경우"},{"법령":"도시개발법","조문":"제13조제3항","원문":"③ 제1항에 따라 조합 설립의 인가를 신청하려면 해당 도시개발구역의 토지면적의 3분의 2 이상에 해당하는 토지 소유자와 그 구역의 토지 소유자 총수의 2분의 1 이상의 동의를 받아야 한다."},{"법령":"도시개발법","조문":"제14조제1항","원문":"① 조합의 조합원은 도시개발구역의 토지 소유자로 한다."},{"법령":"도시개발법","조문":"제15조제2항","원문":"② 조합은 그 주된 사무소의 소재지에서 등기를 하면 성립한다."},{"법령":"도시개발법 시행령","조문":"제32조제1항","원문":"① 법 제13조에 따라 조합의 설립인가를 받은 조합의 대표자는 설립인가를 받은 날부터 30일 이내에 주된 사무소의 소재지에서 설립등기를 하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"조합은 법인이고 주된 사무소의 소재지에서 등기하면 성립한다(법 제15조제1항·제2항)."},{"번호":2,"판정":"틀림","설명":"주된 사무소의 소재지 변경은 경미한 사항이다. 신고하면 된다(법 제13조제2항 단서, 영 제30조제1호)."},{"번호":3,"판정":"옳음","설명":"설립인가 신청에는 토지면적 3분의 2 이상의 토지 소유자와 토지 소유자 총수 2분의 1 이상의 동의가 필요하다(법 제13조제3항)."},{"번호":4,"판정":"옳음","설명":"조합원은 도시개발구역의 토지 소유자이다(법 제14조제1항)."},{"번호":5,"판정":"옳음","설명":"설립인가를 받은 날부터 30일 이내에 설립등기를 한다(영 제32조제1항)."}],"개념":[{"종류":"흐름","제목":"도시개발조합 설립 절차","단계":[{"이름":"정관 작성","설명":"토지 소유자 7명 이상이 정관을 작성(법 제13조제1항)"},{"이름":"동의 확보","설명":"구역 토지면적의 3분의 2 이상에 해당하는 토지 소유자와 토지 소유자 총수의 2분의 1 이상, 인가 신청 전에는 철회 가능(법 제13조제3항, 영 제31조제2항)"},{"이름":"설립인가","설명":"지정권자의 인가(법 제13조제1항)"},{"이름":"설립등기","설명":"인가를 받은 날부터 30일 이내 주된 사무소의 소재지에서 대표자가 등기(영 제32조제1항)"},{"이름":"조합 성립","설명":"등기하면 법인으로 성립(법 제15조제1항·제2항)"}]},{"종류":"표","제목":"조합 인가사항의 변경","머리":["구분","절차","근거"],"행":[["일반 변경","지정권자로부터 변경인가","법 제13조제2항 본문"],["주된 사무소의 소재지 변경","신고","영 제30조제1호"],["공고방법 변경","신고","영 제30조제2호"],["임원 결격","피성년후견인·피한정후견인·미성년자, 복권되지 않은 파산자, 금고 이상 형 집행 종료 후 2년이 지나지 않은 자 또는 집행유예 기간 중인 자","법 제14조제3항"]]}],"함정":"조합 인가사항 변경은 원칙적으로 변경인가이고, 주된 사무소 소재지와 공고방법 변경은 신고이다. 설립 동의율은 면적 3분의 2와 인원 2분의 1이고, 설립등기는 인가일부터 30일 이내이다."},"33회-2차-053":{"한줄":"토지상환채권의 발행규모는 분양토지·분양건축물 면적의 2분의 1을 초과할 수 없다.","근거":[{"법령":"도시개발법 시행령","조문":"제45조","원문":"제45조(토지상환채권의 발행규모) 법 제23조제1항에 따른 토지상환채권(이하 \"토지상환채권\"이라 한다)의 발행규모는 그 토지상환채권으로 상환할 토지ㆍ건축물이 해당 도시개발사업으로 조성되는 분양토지 또는 분양건축물 면적의 2분의 1을 초과하지 아니하도록 하여야 한다."},{"법령":"도시개발법","조문":"제23조제1항","원문":"① 시행자는 토지 소유자가 원하면 토지등의 매수 대금의 일부를 지급하기 위하여 대통령령으로 정하는 바에 따라 사업 시행으로 조성된 토지ㆍ건축물로 상환하는 채권(이하 \"토지상환채권\"이라 한다)을 발행할 수 있다. 다만, 제11조제1항제5호부터 제11호까지의 규정에 해당하는 자는 대통령령으로 정하는 금융기관 등으로부터 지급보증을 받은 경우에만 이를 발행할 수 있다."},{"법령":"도시개발법 시행령","조문":"제47조제6호","원문":"제47조(토지상환채권의 발행계획) 법 제23조제2항에 따른 토지상환채권의 발행계획에는 다음 각 호의 사항이 포함되어야 한다. 6. 토지가격의 추산방법"},{"법령":"도시개발법 시행령","조문":"제53조제1항","원문":"① 토지상환채권을 이전하는 경우 취득자는 그 성명과 주소를 토지상환채권원부에 기재하여 줄 것을 요청하여야 하며, 취득자의 성명과 주소가 토지상환채권에 기재되지 아니하면 취득자는 발행자 및 그 밖의 제3자에게 대항하지 못한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"지급보증은 제11조제1항제5호부터 제11호까지의 시행자에게 요구된다. 지방공사는 제4호 시행자이므로 지급보증 없이 발행할 수 있다(법 제23조제1항 단서)."},{"번호":2,"판정":"옳음","설명":"발행규모는 분양토지·분양건축물 면적의 2분의 1을 넘지 않아야 한다(영 제45조)."},{"번호":3,"판정":"틀림","설명":"토지상환채권은 이전할 수 있다. 취득자의 성명과 주소를 원부에 기재해야 발행자와 제3자에게 대항할 수 있다(영 제53조제1항)."},{"번호":4,"판정":"틀림","설명":"발행계획에 토지가격의 추산방법이 포함된다(영 제47조제6호)."},{"번호":5,"판정":"틀림","설명":"토지등의 매수 대금의 일부를 지급하기 위해 발행할 수 있다(법 제23조제1항)."}],"개념":[{"종류":"표","제목":"토지상환채권 요건","머리":["항목","내용","근거"],"행":[["발행 목적","토지 소유자가 원하면 토지등의 매수 대금의 일부를 조성된 토지·건축물로 상환","법 제23조제1항"],["발행규모","상환할 토지·건축물이 분양토지·분양건축물 면적의 2분의 1 이하","영 제45조"],["지급보증","제11조제1항제5호~제11호 시행자는 은행, 보험회사, 공제조합 등의 지급보증","법 제23조제1항 단서, 영 제46조"],["발행계획 승인","시행자(지정권자 제외)는 발행계획을 작성해 미리 지정권자의 승인","법 제23조제2항"],["증권 형식","기명식 증권","영 제49조제2항"],["이전","취득자 성명·주소를 원부에 기재해야 제3자 대항, 질권자도 원부 기재","영 제53조"]]},{"종류":"흐름","제목":"토지상환채권 발행 절차","단계":[{"이름":"발행계획 작성","설명":"시행자 명칭, 발행총액, 이율, 발행가액·시기, 상환대상지역 또는 토지 용도, 토지가격의 추산방법, 보증기관·내용(영 제47조)"},{"이름":"지정권자 승인","설명":"지정권자가 시행자인 경우를 제외하고 미리 승인(법 제23조제2항)"},{"이름":"발행공고","설명":"채권 명칭과 발행계획 사항 공고(영 제48조)"},{"이름":"청약","설명":"청약자가 청약서 2통을 작성해 시행자에게 제출(영 제50조)"},{"이름":"발행·이전","설명":"기명식 증권으로 발행하고 이전은 원부 기재(영 제49조, 제53조)"}]}],"함정":"지방공사는 법 제11조제1항제4호 시행자여서 지급보증 대상이 아니다. 발행규모는 2분의 1 이하이고, 발행계획에는 토지가격의 추산방법이 들어가며, 채권은 이전할 수 있다."},"33회-2차-077":{"한줄":"지하주차장의 경사로는 건축면적에 산입하지 않는다.","근거":[{"법령":"건축법 시행령","조문":"영 제119조제1항제2호다목4)","원문":"다. 다음의 경우에는 건축면적에 산입하지 않는다.\n4) 지하주차장의 경사로"},{"법령":"건축법 시행령","조문":"영 제119조제1항제3호마목","원문":"마. 공동주택으로서 지상층에 설치한 기계실, 전기실, 어린이놀이터, 조경시설 및 생활폐기물 보관시설의 면적은 바닥면적에 산입하지 않는다."},{"법령":"건축법 시행령","조문":"영 제119조제1항제4호가목","원문":"4. 연면적: 하나의 건축물 각 층의 바닥면적의 합계로 하되, 용적률을 산정할 때에는 다음 각 목에 해당하는 면적은 제외한다.\n가. 지하층의 면적"},{"법령":"건축법 시행규칙","조문":"규칙 제43조제1항","원문":"①영 제119조제1항제2호나목1) 및 3)에 따라 태양열을 주된 에너지원으로 이용하는 주택의 건축면적과 단열재를 구조체의 외기측에 설치하는 단열공법으로 건축된 건축물의 건축면적은 건축물의 외벽중 내측 내력벽의 중심선을 기준으로 한다. 이 경우 태양열을 주된 에너지원으로 이용하는 주택의 범위는 국토교통부장관이 정하여 고시하는 바에 따른다."}],"선지":[{"번호":1,"판정":"옳음","설명":"공동주택으로서 지상층에 설치한 기계실·전기실·어린이놀이터·조경시설·생활폐기물 보관시설은 바닥면적에 산입하지 않는다(영 제119조제1항제3호마목)."},{"번호":2,"판정":"틀림","설명":"지하주차장의 경사로는 건축면적에 산입하지 않는 경우에 해당한다(영 제119조제1항제2호다목4))."},{"번호":3,"판정":"옳음","설명":"태양열을 주된 에너지원으로 이용하는 주택의 건축면적은 외벽 중 내측 내력벽의 중심선을 기준으로 한다(영 제119조제1항제2호나목1), 규칙 제43조제1항)."},{"번호":4,"판정":"옳음","설명":"용적률을 산정할 때 연면적에서 지하층의 면적은 제외한다(영 제119조제1항제4호가목)."},{"번호":5,"판정":"옳음","설명":"층의 구분이 명확하지 않은 건축물은 높이 4미터마다 하나의 층으로 보아 층수를 산정한다(영 제119조제1항제9호)."}],"개념":[{"종류":"표","제목":"면적·높이·층수 산정방법(영 제119조제1항)","머리":["대상","산정 기준"],"행":[["건축면적","외벽 중심선으로 둘러싸인 부분의 수평투영면적. 처마·차양 등이 중심선에서 1미터 이상 돌출되면 돌출 끝에서 일정 거리 후퇴한 선 기준(그 밖의 건축물은 1미터)"],["바닥면적","각 층 또는 그 일부로서 벽·기둥 등 구획의 중심선으로 둘러싸인 부분의 수평투영면적"],["연면적","각 층 바닥면적의 합계. 용적률 산정 시 지하층, 지상층의 부속용도 주차용 면적, 피난안전구역 면적 등 제외"],["건축물의 높이","지표면에서 건축물 상단까지. 옥상 승강기탑·계단탑 등은 수평투영면적 합계가 건축면적의 8분의 1 이하이면 12미터를 넘는 부분만 산입"],["층수","층의 구분이 명확하지 않으면 높이 4미터마다 한 층. 지하층과 건축면적 8분의 1 이하의 옥상 부분은 불산입. 부분별로 층수가 다르면 가장 많은 층수"]]},{"종류":"비교","제목":"건축면적과 바닥면적에서 빼는 것","왼쪽":{"이름":"건축면적에 산입하지 않는 것","항목":["지표면으로부터 1미터 이하에 있는 부분(창고 입출고 차량 접안 부분은 1.5미터 이하)","건축물 지상층의 보행통로나 차량통로","지하주차장의 경사로","건축물 지하층의 출입구 상부(출입구 너비에 상당하는 규모)","생활폐기물 보관시설","장애인용 승강기·에스컬레이터·휠체어리프트·경사로"]},"오른쪽":{"이름":"바닥면적에 산입하지 않는 것","항목":["공동주택 지상층의 기계실·전기실·어린이놀이터·조경시설·생활폐기물 보관시설","공중통행·차량통행·주차에 전용되는 필로티, 공동주택의 필로티","승강기탑, 계단탑, 장식탑, 층고 1.5미터(경사지붕 1.8미터) 이하 다락","지하주차장의 경사로(지상층에서 지하 1층으로 내려가는 부분)","장애인용 승강기·에스컬레이터·휠체어리프트·경사로"]}}],"함정":"지하주차장 경사로는 건축면적과 바닥면적 모두에서 빠진다. 공동주택 지상층의 조경시설은 바닥면적 불산입이다. 태양열 주택의 건축면적 기준(내측 내력벽의 중심선)은 시행규칙 제43조에 있다."},"33회-2차-084":{"한줄":"취수ㆍ저수ㆍ도수ㆍ정수ㆍ송수ㆍ배수 시설의 부지와 이에 접속된 부속시설물의 부지가 수도용지다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제21호","원문":"21. 수도용지\n물을 정수하여 공급하기 위한 취수ㆍ저수ㆍ도수(導水)ㆍ정수ㆍ송수 및 배수 시설의 부지 및 이에 접속된 부속시설물의 부지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제6호","원문":"6. 광천지\n지하에서 온수ㆍ약수ㆍ석유류 등이 용출되는 용출구(湧出口)와 그 유지(維持)에 사용되는 부지. 다만, 온수ㆍ약수ㆍ석유류 등을 일정한 장소로 운송하는 송수관ㆍ송유관 및 저장시설의 부지는 제외한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제3호","원문":"3. 과수원\n사과ㆍ배ㆍ밤ㆍ호두ㆍ귤나무 등 과수류를 집단적으로 재배하는 토지와 이에 접속된 저장고 등 부속시설물의 부지. 다만, 주거용 건축물의 부지는 \"대\"로 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제26호","원문":"26. 사적지\n국가유산으로 지정된 역사적인 유적ㆍ고적ㆍ기념물 등을 보존하기 위하여 구획된 토지. 다만, 학교용지ㆍ공원ㆍ종교용지 등 다른 지목으로 된 토지에 있는 유적ㆍ고적ㆍ기념물 등을 보호하기 위하여 구획된 토지는 제외한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제15호","원문":"15. 철도용지\n교통 운수를 위하여 일정한 궤도 등의 설비와 형태를 갖추어 이용되는 토지와 이에 접속된 역사(驛舍)ㆍ차고ㆍ발전시설 및 공작창(工作廠) 등 부속시설물의 부지"}],"선지":[{"번호":1,"판정":"틀림","설명":"송수관ㆍ송유관 및 저장시설의 부지는 광천지에서 빠진다. 광천지는 용출구와 그 유지에 사용되는 부지만 해당한다(영 제58조제6호 단서)."},{"번호":2,"판정":"틀림","설명":"과수원에 접속된 주거용 건축물의 부지는 “대”다. 과수원에 포함되는 부속시설물은 저장고 등이다(영 제58조제3호 단서)."},{"번호":3,"판정":"틀림","설명":"종교용지 등 다른 지목으로 된 토지에 있는 유적ㆍ고적ㆍ기념물 보호 구획 토지는 사적지에서 제외된다. 그 토지는 종교용지로 남는다(영 제58조제26호 단서)."},{"번호":4,"판정":"옳음","설명":"수도용지의 정의 그대로다(영 제58조제21호)."},{"번호":5,"판정":"틀림","설명":"궤도 등의 설비를 갖춘 토지와 접속된 차고ㆍ발전시설 등의 부지는 “철도용지”다. 도로는 보행이나 차량운행에 필요한 설비ㆍ형태를 갖춘 토지다(영 제58조제14호, 제15호)."}],"개념":[{"종류":"표","제목":"지목 정의의 단서ㆍ제외 규정","머리":["지목","원칙","단서ㆍ제외"],"행":[["과수원","과수류 집단 재배 토지와 접속된 저장고 등 부속시설물의 부지","주거용 건축물의 부지는 대"],["목장용지","초지 조성 토지, 가축 사육 축사 등의 부지, 접속된 부속시설물의 부지","주거용 건축물의 부지는 대"],["광천지","온수ㆍ약수ㆍ석유류 등의 용출구와 그 유지에 사용되는 부지","송수관ㆍ송유관 및 저장시설의 부지 제외"],["사적지","국가유산으로 지정된 유적ㆍ고적ㆍ기념물 등을 보존하기 위하여 구획된 토지","학교용지ㆍ공원ㆍ종교용지 등 다른 지목 토지에 있는 것 제외"],["묘지","시체ㆍ유골이 매장된 토지, 묘지공원, 봉안시설과 접속된 부속시설물의 부지","묘지 관리를 위한 건축물의 부지는 대"],["주차장","독립적 시설을 갖춘 주차 부지, 주차전용 건축물과 접속된 부속시설물의 부지","노상주차장, 부설주차장, 자동차 판매 목적의 물류장ㆍ야외전시장 제외"]]},{"종류":"표","제목":"교통ㆍ수로 관련 지목 구분","머리":["지목","해당 토지","제외 또는 부속시설"],"행":[["도로","일반 공중의 교통 운수를 위해 보행이나 차량운행에 필요한 설비ㆍ형태를 갖춘 토지, 2필지 이상에 진입하는 통로, 고속도로 휴게소 부지","아파트ㆍ공장 등 단일 용도 단지 안의 통로 제외"],["철도용지","궤도 등의 설비와 형태를 갖추어 이용되는 토지","접속된 역사ㆍ차고ㆍ발전시설ㆍ공작창 부지 포함"],["수도용지","취수ㆍ저수ㆍ도수ㆍ정수ㆍ송수ㆍ배수 시설의 부지","접속된 부속시설물의 부지 포함"],["제방","방조제ㆍ방수제ㆍ방사제ㆍ방파제 등의 부지","-"],["하천","자연의 유수가 있거나 있을 것으로 예상되는 토지","-"],["구거","인공 수로ㆍ둑ㆍ부속시설물의 부지, 소규모 수로부지","-"]]}],"함정":"①②③은 지목 정의의 단서(제외) 규정을 반대로 읽게 만든 선지다. 주거용 건축물의 부지는 과수원ㆍ목장용지에서 모두 대로 나간다. ⑤는 철도용지의 정의에 지목명만 도로로 바꿔 넣었다."},"33회-2차-081":{"한줄":"대지권등록부에는 지번은 있으나 지목은 없다. 지목은 토지대장ㆍ임야대장의 등록사항이다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제71조제3항","원문":"③ 토지대장이나 임야대장에 등록하는 토지가 「부동산등기법」에 따라 대지권 등기가 되어 있는 경우에는 대지권등록부에 다음 각 호의 사항을 등록하여야 한다.\n  1. 토지의 소재\n  2. 지번\n  3. 대지권 비율\n  4. 소유자의 성명 또는 명칭, 주소 및 주민등록번호\n  5. 그 밖에 국토교통부령으로 정하는 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제68조제4항","원문":"④ 법 제71조제3항제5호에서 \"그 밖에 국토교통부령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다.\n  1. 토지의 고유번호\n  2. 전유부분(專有部分)의 건물표시\n  3. 건물의 명칭\n  4. 집합건물별 대지권등록부의 장번호\n  5. 토지소유자가 변경된 날과 그 원인\n  6. 소유권 지분"}],"선지":[{"번호":1,"판정":"-","설명":"지번은 등록사항이나 지목은 아니다. 토지대장과 임야대장에 등록한다(법 제71조제1항제3호)."},{"번호":2,"판정":"-","설명":"둘 다 등록사항이다(법 제71조제3항제1호, 규칙 제68조제4항제1호)."},{"번호":3,"판정":"-","설명":"둘 다 등록사항이다(법 제71조제3항제3호, 규칙 제68조제4항제2호)."},{"번호":4,"판정":"-","설명":"둘 다 등록사항이다(규칙 제68조제4항제5호ㆍ제6호)."},{"번호":5,"판정":"-","설명":"둘 다 등록사항이다(규칙 제68조제4항제3호ㆍ제4호)."}],"개념":[{"종류":"표","제목":"지적공부별 등록사항 비교","머리":["등록사항","토지ㆍ임야대장","공유지연명부","대지권등록부"],"행":[["토지의 소재ㆍ지번","○","○","○"],["지목ㆍ면적","○","-","-"],["소유자의 성명ㆍ주소ㆍ주민등록번호","○","○","○"],["소유권 지분","-","○","○"],["대지권 비율","-","-","○"],["전유부분의 건물표시ㆍ건물의 명칭","-","-","○"],["토지의 고유번호","○","○","○"],["토지소유자가 변경된 날과 그 원인","○","○","○"]]},{"종류":"표","제목":"토지대장ㆍ임야대장의 그 밖의 등록사항 (규칙 제68조제2항)","머리":["번호","등록사항"],"행":[["1","토지의 고유번호"],["2","지적도 또는 임야도의 번호와 필지별 토지대장 또는 임야대장의 장번호 및 축척"],["3","토지의 이동사유"],["4","토지소유자가 변경된 날과 그 원인"],["5","토지등급 또는 기준수확량등급과 그 설정ㆍ수정 연월일"],["6","개별공시지가와 그 기준일"],["7","그 밖에 국토교통부장관이 정하는 사항"]]}],"함정":"지번과 지목은 토지대장에서 붙어 다니는 항목이라 한 묶음으로 읽고 넘기기 쉽다. 대지권등록부는 지목과 면적을 두지 않는다. 나머지 선지는 규칙 제68조제4항의 항목 그대로다."},"33회-2차-104":{"한줄":"법원이 신탁관리인 선임의 재판을 하면 신탁관리인이 아니라 법원이 지체 없이 신탁원부 기록의 변경등기를 등기소에 촉탁한다.","근거":[{"법령":"부동산등기법","조문":"제85조제1항","원문":"① 법원은 다음 각 호의 어느 하나에 해당하는 재판을 한 경우 지체 없이 신탁원부 기록의 변경등기를 등기소에 촉탁하여야 한다.\n  1. 수탁자 해임의 재판\n  2. 신탁관리인의 선임 또는 해임의 재판\n  3. 신탁 변경의 재판"},{"법령":"부동산등기법","조문":"제82조제2항","원문":"② 수익자나 위탁자는 수탁자를 대위하여 신탁등기를 신청할 수 있다. 이 경우 제1항은 적용하지 아니한다."},{"법령":"부동산등기법","조문":"제87조제3항","원문":"③ 신탁등기의 말소등기는 수탁자가 단독으로 신청할 수 있다."},{"법령":"부동산등기법","조문":"제85조의2","원문":"제85조의2(직권에 의한 신탁변경등기) 등기관이 신탁재산에 속하는 부동산에 관한 권리에 대하여 다음 각 호의 어느 하나에 해당하는 등기를 할 경우 직권으로 그 부동산에 관한 신탁원부 기록의 변경등기를 하여야 한다.\n  1. 수탁자의 변경으로 인한 이전등기\n  2. 여러 명의 수탁자 중 1인의 임무 종료로 인한 변경등기\n  3. 수탁자인 등기명의인의 성명 및 주소(법인인 경우에는 그 명칭 및 사무소 소재지를 말한다)에 관한 변경등기 또는 경정등기"},{"법령":"부동산등기규칙","조문":"제139조제3항","원문":"③ 신탁등기를 신청하는 경우에는 법 제81조제1항 각 호의 사항을 첨부정보로서 등기소에 제공하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"수익자나 위탁자는 수탁자를 대위하여 신탁등기를 신청할 수 있다(법 제82조제2항)."},{"번호":2,"판정":"옳음","설명":"신탁등기의 말소등기는 수탁자가 단독으로 신청할 수 있다(법 제87조제3항)."},{"번호":3,"판정":"옳음","설명":"가등기 신청 방식에 따르되 신탁원부 작성을 위해 법 제81조제1항 각 호의 사항을 첨부정보로 제공한다(규칙 제139조제3항)."},{"번호":4,"판정":"옳음","설명":"수탁자 1인의 임무 종료로 인한 변경등기를 하면 등기관이 직권으로 신탁원부를 변경한다(법 제85조의2제2호)."},{"번호":5,"판정":"틀림","설명":"신탁관리인 선임 재판에 따른 신탁원부 변경등기는 법원이 촉탁한다(법 제85조제1항제2호). 신탁관리인에게 신청 의무가 있지 않다."}],"개념":[{"종류":"표","제목":"신탁등기 관련 신청ㆍ촉탁ㆍ직권","머리":["구분","내용","근거"],"행":[["신탁등기 신청","수탁자가 단독으로, 권리의 설정ㆍ보존ㆍ이전ㆍ변경 신청과 동시에(1건의 신청정보로 일괄)","법 제23조제7항, 제82조제1항, 규칙 제139조제1항"],["대위신청","수익자 또는 위탁자가 수탁자를 대위하여 신청, 이 경우 동시 신청 불요","법 제82조제2항"],["수탁자 임무 종료","신수탁자가 단독으로 권리이전등기 신청","법 제83조"],["수탁자 여럿 중 1인의 임무 종료","다른 수탁자가 단독으로 권리변경등기 신청, 다른 수탁자가 여럿이면 전원 공동","법 제84조제2항"],["법원의 촉탁","수탁자 해임, 신탁관리인 선임 또는 해임, 신탁 변경의 재판","법 제85조제1항"],["법무부장관의 촉탁","수탁자 직권 해임, 신탁관리인 직권 선임ㆍ해임, 신탁내용 변경 명령","법 제85조제2항"],["등기관의 직권 변경","수탁자 변경 이전등기, 수탁자 1인의 임무 종료 변경등기, 수탁자의 성명ㆍ주소 변경ㆍ경정","법 제85조의2"],["수탁자의 변경등기 신청","위 경우를 제외하고 신탁원부 사항이 변경되면 지체 없이 신청","법 제86조"],["신탁등기 말소","수탁자가 단독으로, 권리 이전ㆍ변경ㆍ소멸 신청과 동시에","법 제87조"]]},{"종류":"표","제목":"신탁원부의 기록사항 (법 제81조제1항)","머리":["구분","내용"],"행":[["당사자","위탁자, 수탁자, 수익자의 성명ㆍ주소"],["수익자 관련","수익자를 지정ㆍ변경할 권한자, 지정ㆍ변경 방법, 수익권 발생ㆍ소멸 조건"],["신탁관리인","선임된 경우 성명ㆍ주소"],["특수 신탁","수익자 없는 특정 목적 신탁, 재신탁, 유언대용신탁, 수익자연속신탁, 수익증권발행신탁, 공익신탁, 유한책임신탁인 경우 그 뜻"],["신탁 내용","신탁의 목적, 신탁재산의 관리ㆍ처분ㆍ운용ㆍ개발 방법, 신탁종료 사유, 그 밖의 신탁 조항"]]}],"함정":"‘신청해야 한다’의 주체를 바꾼 선지다. 신탁관리인 선임이나 수탁자 해임 같은 재판이 있으면 법원이 촉탁하고, 수탁자 1인의 임무 종료나 수탁자의 성명ㆍ주소 변경은 등기관이 직권으로 신탁원부를 고친다."},"33회-2차-103":{"한줄":"소유권이전청구권 가등기로 본등기를 하면 가등기 후 본등기 전의 등기는 거의 모두 직권말소하지만, 해당 가등기상 권리를 목적으로 하는 가압류·가처분등기는 남긴다.","근거":[{"법령":"부동산등기규칙","조문":"제147조제1항","원문":"등기관이 소유권이전등기청구권보전 가등기에 의하여 소유권이전의 본등기를 한 경우에는 법 제92조제1항에 따라 가등기 후 본등기 전에 마쳐진 등기 중 다음 각 호의 등기를 제외하고는 모두 직권으로 말소한다.\n1. 해당 가등기상 권리를 목적으로 하는 가압류등기나 가처분등기\n2. 가등기 전에 마쳐진 가압류에 의한 강제경매개시결정등기\n3. 가등기 전에 마쳐진 담보가등기, 전세권 및 저당권에 의한 임의경매개시결정등기\n4. 가등기권자에게 대항할 수 있는 주택임차권등기, 주택임차권설정등기, 상가건물임차권등기, 상가건물임차권설정등기(이하 \"주택임차권등기등\"이라 한다)"},{"법령":"부동산등기법","조문":"제92조제1항","원문":"등기관은 가등기에 의한 본등기를 하였을 때에는 대법원규칙으로 정하는 바에 따라 가등기 이후에 된 등기로서 가등기에 의하여 보전되는 권리를 침해하는 등기를 직권으로 말소하여야 한다."}],"선지":[{"번호":1,"판정":"-","설명":"규칙 제147조제1항 각 호에 없어 직권말소 대상이다."},{"번호":2,"판정":"-","설명":"각 호에 없어 직권말소 대상이다."},{"번호":3,"판정":"-","설명":"각 호에 없어 직권말소 대상이다. 남는 것은 가등기 전에 마쳐진 저당권에 의한 임의경매개시결정등기이고(제3호), 가등기 후의 저당권설정등기는 말소된다."},{"번호":4,"판정":"-","설명":"제4호는 가등기권자에게 대항할 수 있는 임차권등기만 남긴다. 가등기 후에 설정된 임차권설정등기는 대항할 수 없어 직권말소 대상이다."},{"번호":5,"판정":"-","설명":"제1호에 해당하므로 직권말소 대상이 아니다."}],"개념":[{"종류":"표","제목":"소유권이전청구권 가등기의 본등기 후 처리","머리":["구분","내용"],"행":[["직권말소","가등기 후 본등기 전에 마쳐진 등기 중 아래 남기는 등기를 뺀 모두"],["남기는 등기 1","해당 가등기상 권리를 목적으로 하는 가압류·가처분등기"],["남기는 등기 2","가등기 전에 마쳐진 가압류에 의한 강제경매개시결정등기"],["남기는 등기 3","가등기 전에 마쳐진 담보가등기·전세권·저당권에 의한 임의경매개시결정등기"],["남기는 등기 4","가등기권자에게 대항할 수 있는 주택·상가건물 임차권등기 및 임차권설정등기"],["체납처분 압류","직권말소대상통지 후 이의신청이 있으면 예규에 따라 말소 여부 결정(규칙 제147조제2항)"]]},{"종류":"표","제목":"가등기 종류별 본등기 후 직권말소","머리":["가등기 종류","말소하는 것","말소하지 않는 것"],"행":[["소유권이전청구권","위 남기는 등기를 뺀 모든 등기","위 남기는 등기"],["지상권·전세권·임차권 설정청구권","같은 부분의 지상권·지역권·전세권·임차권설정등기, 대항력 없는 주택임차권등기등","소유권이전·가등기, 가압류·가처분, 체납처분 압류, 저당권설정등기"],["저당권설정청구권","없음","가등기 후 본등기 전의 등기 전부"]]}],"함정":"지상권·지역권·임차권처럼 용익권이면 남는다고 보거나, 가압류는 처분제한이니 모두 남는다고 보기 쉽다. 남는 가압류는 가등기상 권리를 목적으로 한 것뿐이다. 가등기 후에 설정된 저당권·임차권설정등기는 말소된다."},"33회-2차-115":{"한줄":"신고·납부기한 안에 등기·등록하려면 등기·등록 신청서를 접수하는 날까지 취득세를 신고·납부해야 한다.","근거":[{"법령":"지방세법","조문":"제20조제4항","원문":"제1항부터 제3항까지의 신고ㆍ납부기한 이내에 재산권과 그 밖의 권리의 취득ㆍ이전에 관한 사항을 공부(公簿)에 등기하거나 등록[등재(登載)를 포함한다. 이하 같다]하려는 경우에는 등기 또는 등록 신청서를 등기ㆍ등록관서에 접수하는 날까지 취득세를 신고ㆍ납부하여야 한다."},{"법령":"지방세법","조문":"제18조","원문":"취득세의 징수는 신고납부의 방법으로 한다."},{"법령":"지방세법","조문":"제20조제1항","원문":"상속으로 인한 경우는 상속개시일이 속하는 달의 말일부터, 실종으로 인한 경우는 실종선고일이 속하는 달의 말일부터 각각 6개월(외국에 주소를 둔 상속인이 있는 경우에는 각각 9개월)"},{"법령":"지방세법","조문":"제20조제2항","원문":"이미 납부한 세액(가산세는 제외한다)을 공제한 금액을 세액으로 하여 대통령령으로 정하는 바에 따라 신고하고 납부하여야 한다."},{"법령":"지방세법","조문":"제22조의2제2항","원문":"지방자치단체의 장은 취득세 납세의무가 있는 법인이 제1항에 따른 의무를 이행하지 아니하는 경우에는 산출된 세액 또는 부족세액의 100분의 10에 상당하는 금액을 징수하여야 할 세액에 가산한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"취득세는 신고납부 방식으로 징수한다(지방세법 제18조). 보통징수는 제20조에 따른 신고·납부의무를 다하지 않았을 때 부족세액과 가산세를 걷는 방법이다(제21조 제1항)."},{"번호":2,"판정":"틀림","설명":"상속은 상속개시일이 속하는 달의 말일부터 6개월 이내다. 외국에 주소를 둔 상속인이 있으면 9개월이다. 60일은 유상 취득 등 일반 기한이다(지방세법 제20조 제1항)."},{"번호":3,"판정":"옳음","설명":"신고·납부기한 이내에 등기·등록하려면 신청서를 접수하는 날까지 신고·납부해야 한다(지방세법 제20조 제4항)."},{"번호":4,"판정":"틀림","설명":"중과세율 적용대상이 된 때에는 이미 납부한 세액에서 가산세를 제외하고 공제한다(지방세법 제20조 제2항)."},{"번호":5,"판정":"틀림","설명":"장부를 갖추지 않은 법인에는 산출세액 또는 부족세액의 100분의 10을 가산한다(지방세법 제22조의2 제2항)."}],"개념":[{"종류":"흐름","제목":"취득세 신고·납부 절차","단계":[{"이름":"취득","설명":"과세물건을 취득한 날이 기산점이다. 토지거래허가구역 토지는 허가 전에 대금을 완납했다면 허가일이 기산점이다."},{"이름":"신고·납부","설명":"일반 취득은 60일 이내, 무상취득(상속 제외)과 부담부증여는 취득일이 속하는 달의 말일부터 3개월, 상속·실종은 6개월(외국 주소 상속인이 있으면 9개월) 이내에 신고하고 낸다."},{"이름":"등기·등록이 먼저인 경우","설명":"기한 안에 등기·등록하려면 등기·등록 신청서를 접수하는 날까지 신고·납부한다(제20조제4항)."},{"이름":"사후 변동","설명":"중과세율 적용대상이 되거나 비과세·감면 뒤 추징사유가 생기면 사유 발생일부터 60일 이내에 차액을 신고·납부한다. 공제하는 기납부세액에서 가산세는 뺀다(제20조제2항·제3항)."},{"이름":"불이행 시 징수","설명":"신고·납부의무를 다하지 않으면 산출세액 또는 부족세액에 가산세를 더해 보통징수한다(제21조제1항). 신고 없이 매각하면 산출세액에 100분의 80을 가산한다(제21조제2항)."}]},{"종류":"표","제목":"취득세 신고·납부 기한과 가산 규정","머리":["구분","기한·가산","근거"],"행":[["유상취득 등 일반","취득한 날부터 60일 이내","제20조제1항"],["무상취득(상속 제외)·부담부증여","취득일이 속하는 달의 말일부터 3개월 이내","제20조제1항"],["상속","상속개시일이 속하는 달의 말일부터 6개월(외국 주소 상속인 있으면 9개월)","제20조제1항"],["실종","실종선고일이 속하는 달의 말일부터 6개월(외국 주소 상속인 있으면 9개월)","제20조제1항"],["중과세율 적용대상이 된 경우","대통령령이 정하는 날부터 60일 이내, 기납부세액(가산세 제외) 공제","제20조제2항"],["법인이 취득당시가액 장부를 갖추지 않은 경우","산출세액 또는 부족세액의 100분의 10 가산","제22조의2제2항"],["신고 없이 사실상 취득 후 매각","산출세액에 100분의 80 가산","제21조제2항"]]}],"함정":"②는 60일이라는 일반 기한을 상속에 그대로 적용한 문장이다. 상속은 6개월, 외국 주소 상속인이 있으면 9개월이다. ⑤의 20%는 일반 무신고가산세율이고 장부 미비 가산율은 10%다. ①은 징수방법을 보통징수로 바꿔 놓았다."},"33회-2차-116":{"한줄":"3주택 이상을 소유해도 주택 보증금등의 합계액이 3억원을 초과하는 경우에 한해 간주임대료를 총수입금액에 산입한다.","근거":[{"법령":"소득세법","조문":"제25조제1항제1호","원문":"3주택 이상을 소유하고 해당 주택의 보증금등의 합계액이 3억원을 초과하는 경우"},{"법령":"소득세법","조문":"제25조제1항 단서","원문":"주택[주거의 용도로만 쓰이는 면적이 1호(戶) 또는 1세대당 40제곱미터 이하인 주택으로서 해당 과세기간의 기준시가가 2억원 이하인 주택은 2026년 12월 31일까지는 주택 수에 포함하지 아니한다]을 대여하고 보증금등을 받은 경우에는 다음 각 호의 어느 하나에 해당하는 경우를 말하며,"},{"법령":"소득세법","조문":"제45조제2항","원문":"제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 사업(이하 \"부동산임대업\"이라 한다)에서 발생한 결손금은 종합소득 과세표준을 계산할 때 공제하지 아니한다. 다만, 주거용 건물 임대업의 경우에는 그러하지 아니하다."},{"법령":"소득세법","조문":"제160조제4항","원문":"제1항이나 제2항의 경우에 사업소득에 부동산임대업에서 발생한 소득이 포함되어 있는 사업자는 그 소득별로 구분하여 회계처리하여야 한다."},{"법령":"소득세법","조문":"제70조제1항·제2항","원문":"해당 과세기간의 종합소득금액이 있는 거주자(종합소득과세표준이 없거나 결손금이 있는 거주자를 포함한다)는 그 종합소득 과세표준을 그 과세기간의 다음 연도 5월 1일부터 5월 31일까지 대통령령으로 정하는 바에 따라 납세지 관할 세무서장에게 신고하여야 한다.\n② 해당 과세기간에 분리과세 주택임대소득 및 제127조제1항제6호나목의 소득이 있는 경우에도 제1항을 적용한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"주거용 건물 임대업을 제외한 부동산임대업의 결손금은 종합소득 과세표준 계산 때 공제하지 않는다(소득세법 제45조 제2항)."},{"번호":2,"판정":"옳음","설명":"사업소득에 부동산임대업 소득이 포함되면 소득별로 구분해 회계처리한다(소득세법 제160조 제4항)."},{"번호":3,"판정":"틀림","설명":"3주택 이상 소유만으로는 부족하고 보증금등의 합계액이 3억원을 초과해야 한다(소득세법 제25조 제1항 제1호)."},{"번호":4,"판정":"옳음","설명":"주거전용 40㎡ 이하이면서 기준시가 2억원 이하인 주택은 주택 수에서 뺀다. 이 특례는 2026년 12월 31일까지다(소득세법 제25조 제1항 단서)."},{"번호":5,"판정":"옳음","설명":"분리과세 주택임대소득만 있거나 과세표준이 없어도 다음 연도 5월 1일~31일에 확정신고한다(소득세법 제70조 제1항·제2항)."}],"개념":[{"종류":"표","제목":"주택 수별 주택임대소득 과세","머리":["소유 주택 수","월세(사업소득)","보증금등 간주임대료"],"행":[["1주택(국내, 기준시가 12억원 이하)","비과세","대상 아님"],["1주택(기준시가 12억원 초과 또는 국외 주택)","과세","대상 아님(제25조 제1항은 3주택 이상 또는 2주택일 때만 규정)"],["2주택","과세","기준시가 12억원 이하 주택은 주택 수에서 빼고 센 2주택이어야 하고, 보증금등 합계액이 시행령 제53조 제1항의 12억원을 초과해야 함"],["3주택 이상","과세","보증금등 합계액이 3억원을 초과해야 함, 주택부수토지만 임대하면 제외"],["주택 수에서 제외하는 주택","40㎡ 이하이면서 기준시가 2억원 이하(2026년 12월 31일까지)","보증금등 판정 때 주택 수에서 제외"]]},{"종류":"계산","제목":"상가 보증금 간주임대료 계산 예(이자율 연 3%, 수치는 가정)","단계":[{"설명":"주택 외 임대의 총수입금액 산입액 = (보증금등의 적수 − 건설비 상당액의 적수) × 1/365 × 정기예금이자율 − 수입이자·할인료·배당금. 연간 기준으로 보증금 5억원, 건물 건설비 상당액 2억원으로 가정","식":"(5억원 − 2억원) × 3%","값":"900만원"},{"설명":"해당 임대사업부분에서 발생한 수입이자와 할인료 및 배당금 100만원을 뺀다. 유가증권처분이익은 빼지 않는다","식":"900만원 − 100만원","값":"800만원"},{"설명":"총수입금액 = 월세 연 합계 + 간주임대료. 월세 연 합계 1,200만원으로 가정","식":"1,200만원 + 800만원","값":"2,000만원"}]}],"함정":"간주임대료는 3주택 이상이면서 보증금등 합계액이 3억원을 초과해야 한다(③). 40㎡·2억원 소형주택의 주택 수 제외는 2026년 12월 31일까지만 적용된다(④). 분리과세 주택임대소득만 있어도 5월에 확정신고한다(⑤).","개정":"2주택 소유자도 기준시가 12억원 이하 주택을 빼고 센 2주택이고 보증금등이 12억원을 초과하면 간주임대료 대상이다(소득세법 제25조 제1항 제2호, 시행령 제53조 제1항 <신설 2025.2.28> 표시). 기출 선지는 3주택 이상만 다뤘다."},"33회-2차-083":{"한줄":"토지이동현황 조사계획은 시·군·구별로 수립하되 부득이한 사유가 있으면 읍·면·동별로 수립할 수 있으므로 ①이 옳다(규칙 제59조제1항).","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제59조제1항","원문":"지적소관청은 법 제64조제2항 단서에 따라 토지의 이동현황을 직권으로 조사ㆍ측량하여 토지의 지번ㆍ지목ㆍ면적ㆍ경계 또는 좌표를 결정하려는 때에는 토지이동현황 조사계획을 수립하여야 한다. 이 경우 토지이동현황 조사계획은 시ㆍ군ㆍ구별로 수립하되, 부득이한 사유가 있는 때에는 읍ㆍ면ㆍ동별로 수립할 수 있다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제64조제2항","원문":"지적공부에 등록하는 지번ㆍ지목ㆍ면적ㆍ경계 또는 좌표는 토지의 이동이 있을 때 토지소유자(법인이 아닌 사단이나 재단의 경우에는 그 대표자나 관리인을 말한다. 이하 같다)의 신청을 받아 지적소관청이 결정한다. 다만, 신청이 없으면 지적소관청이 직권으로 조사ㆍ측량하여 결정할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"ㄱ은 시·군·구, ㄴ은 읍·면·동이다(규칙 제59조제1항)."},{"번호":2,"판정":"틀림","설명":"ㄴ은 시·도가 아니라 읍·면·동이다(규칙 제59조제1항)."},{"번호":3,"판정":"틀림","설명":"ㄱ이 읍·면·동, ㄴ이 시·군·구로 바뀌어 있다. 원칙은 시·군·구별이다(규칙 제59조제1항)."},{"번호":4,"판정":"틀림","설명":"ㄱ은 읍·면·동이 아니라 시·군·구, ㄴ은 시·도가 아니라 읍·면·동이다(규칙 제59조제1항)."},{"번호":5,"판정":"틀림","설명":"ㄱ은 시·도가 아니라 시·군·구, ㄴ은 시·군·구가 아니라 읍·면·동이다(규칙 제59조제1항)."}],"개념":[{"종류":"흐름","제목":"토지의 직권 조사·등록(법 제64조제2항 단서, 규칙 제59조)","단계":[{"이름":"계획 수립","설명":"토지소유자의 신청이 없으면 지적소관청이 토지이동현황 조사계획을 수립. 시·군·구별 수립이 원칙, 부득이하면 읍·면·동별(규칙 제59조제1항)"},{"이름":"조사","설명":"조사한 이동현황을 토지이동 조사부에 기재(규칙 제59조제2항)"},{"이름":"결정","설명":"조사 결과에 따라 지번·지목·면적·경계 또는 좌표를 결정하고 지적공부 정리(규칙 제59조제3항)"},{"이름":"결의서 작성","설명":"토지이동 조사부를 근거로 토지이동 조서를 작성해 토지이동정리 결의서에 첨부, 하단에 직권정리 문구 기재(규칙 제59조제4항)"}]}],"함정":"원칙과 예외의 순서가 핵심이다. 시·군·구가 원칙이고 읍·면·동이 예외이며, 이 규정에는 시·도 단위가 없다."},"33회-2차-085":{"한줄":"부동산종합공부의 제5호 등록사항은 부동산등기법 제48조에 따른 부동산의 권리에 관한 사항이며 토지적성평가서의 내용은 등록사항이 아니므로(법 제76조의3, 영 제62조의2) 등록사항에 해당하지 않는 것은 ⑤다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제76조의3제1호","원문":"토지의 표시와 소유자에 관한 사항: 이 법에 따른 지적공부의 내용"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제76조의3제2호","원문":"건축물의 표시와 소유자에 관한 사항(토지에 건축물이 있는 경우만 해당한다): 「건축법」 제38조에 따른 건축물대장의 내용"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제76조의3제3호","원문":"토지의 이용 및 규제에 관한 사항: 「토지이용규제 기본법」 제10조에 따른 토지이용계획확인서의 내용"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제76조의3제4호","원문":"부동산의 가격에 관한 사항: 「부동산 가격공시에 관한 법률」 제10조에 따른 개별공시지가, 같은 법 제16조, 제17조 및 제18조에 따른 개별주택가격 및 공동주택가격 공시내용"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제76조의3제5호","원문":"그 밖에 부동산의 효율적 이용과 부동산과 관련된 정보의 종합적 관리ㆍ운영을 위하여 필요한 사항으로서 대통령령으로 정하는 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제62조의2","원문":"법 제76조의3제5호에서 \"대통령령으로 정하는 사항\"이란 「부동산등기법」 제48조에 따른 부동산의 권리에 관한 사항을 말한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"토지이용계획확인서의 내용은 토지의 이용 및 규제에 관한 사항으로 등록한다(법 제76조의3제3호)."},{"번호":2,"판정":"옳음","설명":"건축물대장의 내용은 건축물의 표시와 소유자에 관한 사항(토지에 건축물이 있는 경우만)으로 등록한다(법 제76조의3제2호)."},{"번호":3,"판정":"옳음","설명":"지적공부의 내용은 토지의 표시와 소유자에 관한 사항으로 등록한다(법 제76조의3제1호)."},{"번호":4,"판정":"옳음","설명":"개별공시지가와 개별주택가격·공동주택가격 공시내용은 부동산의 가격에 관한 사항으로 등록한다(법 제76조의3제4호)."},{"번호":5,"판정":"틀림","설명":"제5호 사항은 대통령령으로 정하는 사항이고, 영 제62조의2는 부동산등기법 제48조에 따른 부동산의 권리에 관한 사항이다. 토지적성평가서의 내용은 등록사항이 아니다."}],"개념":[{"종류":"표","제목":"부동산종합공부의 등록사항(법 제76조의3, 영 제62조의2)","머리":["호","등록사항","내용 출처"],"행":[["1","토지의 표시와 소유자에 관한 사항","공간정보법에 따른 지적공부의 내용"],["2","건축물의 표시와 소유자에 관한 사항(토지에 건축물이 있는 경우만)","건축법 제38조에 따른 건축물대장의 내용"],["3","토지의 이용 및 규제에 관한 사항","토지이용규제 기본법 제10조에 따른 토지이용계획확인서의 내용"],["4","부동산의 가격에 관한 사항","부동산 가격공시에 관한 법률 제10조에 따른 개별공시지가, 같은 법 제16조·제17조·제18조에 따른 개별주택가격 및 공동주택가격 공시내용"],["5","부동산의 효율적 이용과 정보의 종합적 관리·운영을 위하여 필요한 사항","부동산등기법 제48조에 따른 부동산의 권리에 관한 사항(영 제62조의2)"]]}],"함정":"⑤는 제5호 사항의 설명에 토지적성평가서라는 출처를 붙였다. 제5호의 내용은 부동산의 권리에 관한 사항이다."},"33회-2차-086":{"한줄":"지적전산자료 이용·활용 신청에 대해 관계 중앙행정기관의 장이 심사하는 사항은 신청 내용의 타당성·적합성·공익성, 개인의 사생활 침해 여부, 목적 외 사용 방지 및 안전관리대책이며(영 제62조제2항) 지적전산코드 지정의 적정 여부는 심사사항이 아니므로 ②가 심사사항에 해당하지 않는다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제62조제1항","원문":"법 제76조제1항에 따라 지적공부에 관한 전산자료(이하 \"지적전산자료\"라 한다)를 이용하거나 활용하려는 자는 같은 조 제2항에 따라 다음 각 호의 사항을 적은 신청서를 관계 중앙행정기관의 장에게 제출하여 심사를 신청하여야 한다. 1. 자료의 이용 또는 활용 목적 및 근거 2. 자료의 범위 및 내용 3. 자료의 제공 방식, 보관 기관 및 안전관리대책 등"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제62조제2항","원문":"제1항에 따른 심사 신청을 받은 관계 중앙행정기관의 장은 다음 각 호의 사항을 심사한 후 그 결과를 신청인에게 통지하여야 한다. 1. 신청 내용의 타당성, 적합성 및 공익성 2. 개인의 사생활 침해 여부 3. 자료의 목적 외 사용 방지 및 안전관리대책"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제62조제4항","원문":"제3항에 따른 신청을 받은 국토교통부장관, 시ㆍ도지사 또는 지적소관청은 지적전산자료의 이용ㆍ활용 신청서 및 제2항에 따른 심사 결과(제3항 단서에 따라 지적전산자료의 이용ㆍ활용 신청서만 제출한 경우는 제외한다)를 확인한 후 지적전산자료를 제공해야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 지적전산자료를 제공하지 않을 수 있다. 1. 신청한 사항의 처리가 전산정보처리조직으로 불가능한 경우 2. 신청한 사항의 처리가 지적업무수행에 지장을 주는 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"개인의 사생활 침해 여부는 심사사항이다(영 제62조제2항제2호)."},{"번호":2,"판정":"틀림","설명":"지적전산코드 지정의 적정 여부는 심사사항에 없다(영 제62조제2항)."},{"번호":3,"판정":"옳음","설명":"자료의 목적 외 사용 방지 및 안전관리대책은 심사사항이다(영 제62조제2항제3호)."},{"번호":4,"판정":"옳음","설명":"신청 내용의 타당성 및 적합성은 심사사항이다(영 제62조제2항제1호)."},{"번호":5,"판정":"옳음","설명":"신청 내용의 공익성은 심사사항이다(영 제62조제2항제1호)."}],"개념":[{"종류":"흐름","제목":"지적전산자료의 이용·활용 절차(영 제62조)","단계":[{"이름":"심사 신청","설명":"이용·활용하려는 자가 이용 목적 및 근거, 자료의 범위 및 내용, 제공 방식·보관 기관·안전관리대책을 적은 신청서를 관계 중앙행정기관의 장에게 제출(제1항)"},{"이름":"심사","설명":"관계 중앙행정기관의 장이 타당성·적합성·공익성, 사생활 침해 여부, 목적 외 사용 방지 및 안전관리대책을 심사하고 결과를 신청인에게 통지(제2항)"},{"이름":"이용·활용 신청","설명":"심사 결과를 첨부하여 국토교통부장관, 시·도지사 또는 지적소관청에 신청. 중앙행정기관 등의 신청은 심사 결과 첨부를 생략할 수 있음(제3항)"},{"이름":"확인 후 제공","설명":"신청서와 심사 결과를 확인한 후 제공. 전산처리 불가 또는 지적업무 지장 시 제공하지 않을 수 있음(제4항)"},{"이름":"기록·사용료","설명":"이용·활용 대장에 기록·관리, 제공받는 자는 사용료 납부(국가·지방자치단체는 면제)(제5항·제6항)"}]}],"함정":"심사사항에는 지적전산코드 지정 여부가 없다. 전산처리 가능 여부와 업무 지장 여부는 심사사항이 아니라 제공을 거부할 수 있는 사유다.","개정":"영 제62조가 2024.9.19 개정되면서 국토교통부장관·시·도지사·지적소관청이 승인 신청을 받아 심사하던 방식이 없어지고 관계 중앙행정기관의 장이 심사하는 구조가 되었다. 현행 영 제62조제2항의 심사사항은 신청 내용의 타당성·적합성·공익성, 개인의 사생활 침해 여부, 목적 외 사용 방지 및 안전관리대책이다. 전산처리 불가능 여부와 지적업무수행에 지장을 주는지 여부는 제공하지 않을 수 있는 사유(제4항 단서)로 옮겨졌다. 이 문항의 발문과 ④, ⑤는 이에 맞춰 고친 문장이고, 당시 시험은 문제 오류로 전항 정답 처리되었으나 고친 문장 기준으로 ②만 심사사항이 아니다."},"33회-2차-092":{"한줄":"지적측량 의뢰서는 규칙 제72조의 복구자료에 없으므로(규칙 제72조) ①이 복구자료가 아니다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제72조","원문":"영 제61조제1항에 따른 지적공부의 복구에 관한 관계 자료(이하 \"복구자료\"라 한다)는 다음 각 호와 같다. 1. 지적공부의 등본 2. 측량 결과도 3. 토지이동정리 결의서 4. 토지(건물)등기사항증명서 등 등기사실을 증명하는 서류 5. 지적소관청이 작성하거나 발행한 지적공부의 등록내용을 증명하는 서류 6. 법 제69조제3항에 따라 복제된 지적공부 7. 법원의 확정판결서 정본 또는 사본"}],"선지":[{"번호":1,"판정":"틀림","설명":"지적측량 의뢰서는 복구자료가 아니다. 복구자료에는 측량 결과도가 있다(규칙 제72조제2호)."},{"번호":2,"판정":"옳음","설명":"지적공부의 등본은 복구자료다(규칙 제72조제1호)."},{"번호":3,"판정":"옳음","설명":"토지이동정리 결의서는 복구자료다(규칙 제72조제3호)."},{"번호":4,"판정":"옳음","설명":"법원의 확정판결서 정본 또는 사본은 복구자료다(규칙 제72조제7호)."},{"번호":5,"판정":"옳음","설명":"지적소관청이 작성하거나 발행한 지적공부의 등록내용을 증명하는 서류는 복구자료다(규칙 제72조제5호)."}],"개념":[{"종류":"표","제목":"지적공부의 복구자료(규칙 제72조)","머리":["호","복구자료"],"행":[["1","지적공부의 등본"],["2","측량 결과도"],["3","토지이동정리 결의서"],["4","토지(건물)등기사항증명서 등 등기사실을 증명하는 서류"],["5","지적소관청이 작성하거나 발행한 지적공부의 등록내용을 증명하는 서류"],["6","법 제69조제3항에 따라 복제된 지적공부"],["7","법원의 확정판결서 정본 또는 사본"]]},{"종류":"흐름","제목":"지적공부의 복구 절차(영 제61조, 규칙 제73조)","단계":[{"이름":"자료 조사","설명":"멸실·훼손 당시의 지적공부와 가장 부합된다고 인정되는 관계 자료(복구자료)를 조사(영 제61조제1항, 규칙 제73조제1항)"},{"이름":"조사서·복구자료도 작성","설명":"토지대장·임야대장·공유지연명부는 지적복구자료 조사서, 지적도면은 복구자료도로 작성(규칙 제73조제2항)"},{"이름":"면적 판단","설명":"복구자료도 측정면적과 조사서 면적의 증감이 영 제19조의 허용범위를 초과하거나 복구자료도를 만들 자료가 없으면 복구측량, 허용범위 이내이면 조사된 면적이 복구면적(규칙 제73조제3항·제4항)"},{"이름":"게시","설명":"복구하려는 토지의 표시 등을 시·군·구 게시판 및 인터넷 홈페이지에 15일 이상 게시(규칙 제73조제6항)"},{"이름":"이의신청","설명":"게시기간 내에 이의가 있는 자는 지적소관청에 이의신청, 이유 있으면 시정 조치(규칙 제73조제7항)"},{"이름":"복구","설명":"조사서, 복구자료도, 복구측량 결과도 등에 따라 토지대장·임야대장·공유지연명부 또는 지적도면을 복구(규칙 제73조제8항)"}]}],"함정":"측량 결과도는 복구자료이지만 측량 의뢰서·측량신청서 같은 신청 서류는 복구자료가 아니다."},"33회-2차-082":{"한줄":"청산금에 이의가 있는 자는 납부고지 또는 수령통지를 받은 날부터 1개월 이내에 이의신청을 할 수 있고, 지적소관청은 1개월 이내에 축척변경위원회의 심의·의결을 거쳐 인용 여부를 결정한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제77조제1항","원문":"제76조제1항에 따라 납부고지되거나 수령통지된 청산금에 관하여 이의가 있는 자는 납부고지 또는 수령통지를 받은 날부터 1개월 이내에 지적소관청에 이의신청을 할 수 있다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제77조제2항","원문":"제1항에 따른 이의신청을 받은 지적소관청은 1개월 이내에 축척변경위원회의 심의ㆍ의결을 거쳐 그 인용(認容) 여부를 결정한 후 지체 없이 그 내용을 이의신청인에게 통지하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"이의신청 기간은 15일이 아니라 1개월이고 결정 기간은 2개월이 아니라 1개월이다."},{"번호":2,"판정":"틀림","설명":"이의신청 기간 1개월은 맞으나 결정 기간이 2개월이 아니라 1개월이다."},{"번호":3,"판정":"옳음","설명":"ㄱ 1개월 이내, ㄴ 1개월 이내다(영 제77조)."},{"번호":4,"판정":"틀림","설명":"이의신청 기간이 2개월이 아니라 1개월이다."},{"번호":5,"판정":"틀림","설명":"이의신청 기간이 2개월이 아니라 1개월이고 결정 기간이 15일이 아니라 1개월이다."}],"개념":[{"종류":"표","제목":"청산금 절차의 기간","머리":["단계","기간","근거"],"행":[["청산금 결정 공고","15일 이상","영 제75조제4항"],["납부고지·수령통지","청산금 결정 공고일부터 20일 이내","영 제76조제1항"],["청산금 납부","납부고지를 받은 날부터 6개월 이내","영 제76조제2항"],["청산금 지급","수령통지를 한 날부터 6개월 이내","영 제76조제3항"],["이의신청","납부고지 또는 수령통지를 받은 날부터 1개월 이내","영 제77조제1항"],["이의신청 결정","이의신청을 받은 날부터 1개월 이내 위원회 심의·의결 후 인용 여부 결정, 지체 없이 통지","영 제77조제2항"]]},{"종류":"표","제목":"청산금의 산정(영 제75조)","머리":["항목","내용"],"행":[["청산 대상","측량 결과 측량 전에 비하여 면적의 증감이 있는 경우의 증감면적"],["청산하지 않는 경우","필지별 증감면적이 허용범위 이내인 경우(위원회 의결이 있으면 제외), 토지소유자 전원이 청산하지 않기로 합의하여 서면으로 제출한 경우"],["산정 방법","지번별 조서의 필지별 증감면적 × 위원회 의결로 정한 지번별 제곱미터당 금액"],["차액 처리","증가분과 감소분 청산금의 차액이 생기면 초과액은 지방자치단체의 수입, 부족액은 지방자치단체가 부담"]]}],"함정":"이의신청 기간과 결정 기간이 모두 1개월이다. 납부고지 기한(20일)이나 납부 기한(6개월)과 섞으면 ①·④·⑤로 흐른다."},"33회-2차-087":{"한줄":"축척변경에 관한 측량을 완료하면 시행공고일 현재의 지적공부상 면적과 측량 후의 면적을 비교하여 축척변경 지번별 조서를 작성해야 한다(영 제73조). 신청일 기준의 토지이동현황 조사서가 아니다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제83조제1항","원문":"축척변경에 관한 사항을 심의ㆍ의결하기 위하여 지적소관청에 축척변경위원회를 둔다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제79조제2항","원문":"위원장은 위원 중에서 지적소관청이 지명한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제73조","원문":"지적소관청은 제72조제2항에 따라 축척변경에 관한 측량을 완료하였을 때에는 시행공고일 현재의 지적공부상의 면적과 측량 후의 면적을 비교하여 그 변동사항을 표시한 축척변경 지번별 조서를 작성하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제76조제1항","원문":"지적소관청은 제75조제4항에 따라 청산금의 결정을 공고한 날부터 20일 이내에 토지소유자에게 청산금의 납부고지 또는 수령통지를 하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제78조제1항","원문":"청산금의 납부 및 지급이 완료되었을 때에는 지적소관청은 지체 없이 축척변경의 확정공고를 하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"축척변경에 관한 사항을 심의·의결하기 위해 지적소관청에 축척변경위원회를 둔다(법 제83조제1항)."},{"번호":2,"판정":"옳음","설명":"위원장은 위원 중에서 지적소관청이 지명한다(영 제79조제2항)."},{"번호":3,"판정":"틀림","설명":"기준일은 시행공고일이고 작성하는 문서는 축척변경 지번별 조서다(영 제73조). 신청일 현재의 면적과 토지이동현황 조사서가 아니다."},{"번호":4,"판정":"옳음","설명":"청산금 결정을 공고한 날부터 20일 이내에 납부고지 또는 수령통지를 해야 한다(영 제76조제1항)."},{"번호":5,"판정":"옳음","설명":"청산금의 납부 및 지급이 완료되면 지체 없이 확정공고를 한다(영 제78조제1항)."}],"개념":[{"종류":"표","제목":"축척변경 단계별 문서와 기준일","머리":["단계","문서·행위","기준"],"행":[["측량 완료","축척변경 지번별 조서","시행공고일 현재의 지적공부상 면적과 측량 후 면적 비교(영 제73조)"],["청산금 산정","청산금 조서(지번별 조서에 필지별 청산금 명세를 적은 것)","시행공고일 현재 지번별 제곱미터당 금액 조사(영 제75조)"],["청산금 결정 공고","청산금이 결정되었다는 뜻을 15일 이상 공고","영 제75조제4항"],["납부고지·수령통지","공고일부터 20일 이내","영 제76조제1항"],["확정공고","청산금 납부·지급 완료 시","영 제78조제1항"]]},{"종류":"흐름","제목":"축척변경 절차 전체 흐름","단계":[{"이름":"신청 또는 직권","설명":"지적도가 일정한 사유에 해당하면 토지소유자의 신청 또는 지적소관청의 직권으로 일정 지역의 축척을 변경한다(법 제83조제2항)."},{"이름":"동의·의결·승인","설명":"축척변경 시행지역 토지소유자 3분의 2 이상의 동의, 축척변경위원회의 의결, 시·도지사 또는 대도시 시장의 승인(법 제83조제3항)."},{"이름":"시행공고","설명":"승인을 받으면 지체 없이 20일 이상 공고(영 제71조제1항). 토지소유자·점유자는 공고일부터 30일 이내에 경계점표지를 설치(영 제71조제3항)."},{"이름":"측량과 조서","설명":"새 축척으로 측량하고 시행공고일 현재의 면적과 측량 후 면적을 비교한 축척변경 지번별 조서를 작성(영 제72조, 제73조)."},{"이름":"청산금 산정·공고","설명":"지번별 제곱미터당 금액은 위원회 의결로 정하고, 청산금 결정을 15일 이상 공고(영 제75조)."},{"이름":"납부고지·이의신청","설명":"공고일부터 20일 이내에 납부고지·수령통지(영 제76조제1항). 이의신청은 통지를 받은 날부터 1개월 이내, 지적소관청은 1개월 이내에 위원회 의결을 거쳐 결정(영 제77조)."},{"이름":"확정공고","설명":"청산금의 납부 및 지급이 완료되면 지체 없이 확정공고하고 확정된 사항을 지적공부에 등록한다. 확정공고일에 토지의 이동이 있는 것으로 본다(영 제78조)."}]}],"함정":"③은 기준일(시행공고일)과 문서 이름(축척변경 지번별 조서)을 모두 바꿔 놓았다. 청산금 조서는 이 지번별 조서에 필지별 청산금 명세를 적은 문서다."},"33회-2차-090":{"한줄":"지적공부에 등록된 토지소유자의 변경사항은 등기 증명자료에 따라 정리한다. 신규등록하는 토지의 소유자는 지적소관청이 직접 조사하여 등록한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제88조제1항","원문":"지적공부에 등록된 토지소유자의 변경사항은 등기관서에서 등기한 것을 증명하는 등기필증, 등기완료통지서, 등기사항증명서 또는 등기관서에서 제공한 등기전산정보자료에 따라 정리한다. 다만, 신규등록하는 토지의 소유자는 지적소관청이 직접 조사하여 등록한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"축척변경은 기존 토지의 소유자가 등기부에 있으므로 등기자료로 정리한다. 직접 조사하는 경우는 신규등록이다."},{"번호":2,"판정":"틀림","설명":"축척변경은 해당하지 않고 시·도지사가 조사하는 규정도 없다."},{"번호":3,"판정":"틀림","설명":"신규등록은 맞으나 조사 주체가 등기관이 아니라 지적소관청이다."},{"번호":4,"판정":"옳음","설명":"신규등록하는 토지의 소유자는 지적소관청이 직접 조사하여 등록한다(법 제88조제1항 단서)."},{"번호":5,"판정":"틀림","설명":"등록전환은 임야대장 등록 토지를 옮기는 것이라 소유자가 이미 등록되어 있다. 시·도지사가 조사하지도 않는다."}],"개념":[{"종류":"표","제목":"토지소유자의 정리(법 제88조)","머리":["구분","내용"],"행":[["원칙","등기필증, 등기완료통지서, 등기사항증명서, 등기전산정보자료에 따라 정리(제1항)"],["예외","신규등록하는 토지의 소유자는 지적소관청이 직접 조사하여 등록(제1항 단서)"],["총괄청 등의 등록 신청","소유자 없는 부동산은 지적공부에 소유자가 등록되지 않은 경우에만 등록(제2항)"],["표시 불일치","등기부의 토지 표시가 지적공부와 다르면 소유자를 정리할 수 없고 관할 등기관서에 통지(제3항)"],["일치 여부 조사","지적소관청이 필요하면 등기부를 열람하여 조사·확인하고 직권정리 또는 신청 요구(제4항)"]]},{"종류":"표","제목":"신규등록 신청","머리":["구분","내용","근거"],"행":[["신청 기한","신규등록할 사유가 발생한 날부터 60일 이내","법 제77조"],["소유자 등록","지적소관청이 직접 조사","법 제88조제1항 단서"],["지적공부 정리","토지이동정리 결의서와 소유자정리 결의서 작성","영 제84조제2항"]]}],"함정":"신규등록한 토지만 등기자료가 없어서 지적소관청이 직접 조사한다. 조사 주체를 등기관이나 시·도지사로 바꾼 선지가 3개다."},"33회-2차-091":{"한줄":"축척변경을 신청하는 토지소유자는 시행지역 토지소유자 3분의 2 이상의 동의서를 첨부해야 한다(규칙 제85조).","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제85조","원문":"영 제69조에서 \"국토교통부령으로 정하는 서류\"란 토지소유자 3분의 2 이상의 동의서를 말한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제83조제3항","원문":"지적소관청은 제2항에 따라 축척변경을 하려면 축척변경 시행지역의 토지소유자 3분의 2 이상의 동의를 받아 제1항에 따른 축척변경위원회의 의결을 거친 후 시ㆍ도지사 또는 대도시 시장의 승인을 받아야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"2분의 1 이상이 아니라 3분의 2 이상이다."},{"번호":2,"판정":"옳음","설명":"토지소유자 3분의 2 이상의 동의서를 첨부한다(규칙 제85조, 법 제83조제3항)."},{"번호":3,"판정":"틀림","설명":"4분의 1 이상은 동의 요건이 아니다."},{"번호":4,"판정":"틀림","설명":"5분의 2 이상은 동의 요건이 아니다."},{"번호":5,"판정":"틀림","설명":"5분의 3 이상은 동의 요건이 아니다."}],"개념":[{"종류":"표","제목":"축척변경의 요건과 절차(법 제83조)","머리":["구분","내용"],"행":[["축척변경 사유","① 잦은 토지의 이동으로 1필지 규모가 작아 소축척으로는 측량성과 결정이나 정리가 곤란한 경우 ② 하나의 지번부여지역에 서로 다른 축척의 지적도가 있는 경우 ③ 그 밖에 지적공부를 관리하기 위해 필요하다고 인정하는 경우"],["신청권자","토지소유자의 신청 또는 지적소관청의 직권"],["동의","시행지역 토지소유자 3분의 2 이상"],["의결·승인","축척변경위원회의 의결을 거친 후 시·도지사 또는 대도시 시장의 승인"],["의결·승인 면제","합병하려는 토지가 축척이 다른 지적도에 각각 등록되어 있는 경우, 도시개발사업 등 시행지역에서 사업 시행에서 제외된 토지의 축척변경은 위원회 의결과 시·도지사 승인 없이 할 수 있음(제3항 단서)"]]},{"종류":"흐름","제목":"축척변경 절차에서 동의서의 위치","단계":[{"이름":"신청 또는 직권","설명":"지적도가 일정한 사유에 해당하면 토지소유자의 신청 또는 지적소관청의 직권으로 일정 지역의 축척을 변경한다(법 제83조제2항)."},{"이름":"동의·의결·승인","설명":"축척변경 시행지역 토지소유자 3분의 2 이상의 동의, 축척변경위원회의 의결, 시·도지사 또는 대도시 시장의 승인(법 제83조제3항)."},{"이름":"시행공고","설명":"승인을 받으면 지체 없이 20일 이상 공고(영 제71조제1항). 토지소유자·점유자는 공고일부터 30일 이내에 경계점표지를 설치(영 제71조제3항)."},{"이름":"측량과 조서","설명":"새 축척으로 측량하고 시행공고일 현재의 면적과 측량 후 면적을 비교한 축척변경 지번별 조서를 작성(영 제72조, 제73조)."},{"이름":"청산금 산정·공고","설명":"지번별 제곱미터당 금액은 위원회 의결로 정하고, 청산금 결정을 15일 이상 공고(영 제75조)."},{"이름":"납부고지·이의신청","설명":"공고일부터 20일 이내에 납부고지·수령통지(영 제76조제1항). 이의신청은 통지를 받은 날부터 1개월 이내, 지적소관청은 1개월 이내에 위원회 의결을 거쳐 결정(영 제77조)."},{"이름":"확정공고","설명":"청산금의 납부 및 지급이 완료되면 지체 없이 확정공고하고 확정된 사항을 지적공부에 등록한다. 확정공고일에 토지의 이동이 있는 것으로 본다(영 제78조)."}]}],"함정":"3분의 2라는 숫자는 법 제83조제3항(소유자 동의)과 규칙 제85조(신청 서류)에서 같다. 위원회 위원 중 토지소유자 비율 2분의 1 이상과 혼동하지 않는다."},"33회-2차-088":{"한줄":"시·도지사나 지적소관청은 지적기준점성과와 그 측량기록을 보관하고 일반인이 열람할 수 있게 해야 하므로 ③이 옳다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제27조제1항","원문":"시ㆍ도지사나 지적소관청은 지적기준점성과(지적기준점에 의한 측량성과를 말한다. 이하 같다)와 그 측량기록을 보관하고 일반인이 열람할 수 있도록 하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"시행규칙 제25조제1항","원문":"법 제24조제1항에 따라 지적측량을 의뢰하려는 자는 별지 제15호서식의 지적측량 의뢰서(전자문서로 된 의뢰서를 포함한다)에 의뢰 사유를 증명하는 서류(전자문서를 포함한다)를 첨부하여 지적측량수행자에게 제출하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"시행규칙 제25조제2항","원문":"지적측량수행자는 제1항에 따른 지적측량 의뢰를 받은 때에는 측량기간, 측량일자 및 측량 수수료 등을 적은 별지 제16호서식의 지적측량 수행계획서를 그 다음 날까지 지적소관청에 제출하여야 한다. 제출한 지적측량 수행계획서를 변경한 경우에도 같다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"시행규칙 제25조제4항","원문":"제3항에도 불구하고 지적측량 의뢰인과 지적측량수행자가 서로 합의하여 따로 기간을 정하는 경우에는 그 기간에 따르되, 전체 기간의 4분의 3은 측량기간으로, 전체 기간의 4분의 1은 측량검사기간으로 본다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"시행규칙 제26조제1항","원문":"법 제27조에 따라 지적측량기준점성과 또는 그 측량부를 열람하거나 등본을 발급받으려는 자는 지적삼각점성과에 대해서는 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ도지사ㆍ특별자치도지사(이하 \"시ㆍ도지사\"라 한다) 또는 지적소관청에 신청하고, 지적삼각보조점성과 및 지적도근점성과에 대해서는 지적소관청에 신청하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"지적삼각보조점성과와 지적도근점성과는 지적소관청에 신청한다(시행규칙 제26조제1항). 지적측량수행자가 아니다."},{"번호":2,"판정":"틀림","설명":"지적측량 의뢰서는 지적측량수행자에게 제출한다(시행규칙 제25조제1항)."},{"번호":3,"판정":"옳음","설명":"시·도지사나 지적소관청이 지적기준점성과와 그 측량기록을 보관하고 일반인이 열람할 수 있게 한다(법 제27조제1항)."},{"번호":4,"판정":"틀림","설명":"지적측량 수행계획서를 제출하는 주체는 지적측량수행자이고 제출처는 지적소관청이다(시행규칙 제25조제2항). 주체와 제출처를 바꿨다."},{"번호":5,"판정":"틀림","설명":"합의한 기간에서 4분의 3은 측량기간, 4분의 1은 측량검사기간으로 본다(시행규칙 제25조제4항). 반대로 적혀 있다."}],"개념":[{"종류":"표","제목":"지적측량 의뢰와 성과(법 제24조~제27조, 시행규칙 제25조·제26조)","머리":["구분","내용"],"행":[["의뢰","지적측량 의뢰서에 의뢰 사유를 증명하는 서류를 첨부해 지적측량수행자에게 제출"],["수행계획서","지적측량수행자가 의뢰를 받은 때 측량기간, 측량일자, 수수료 등을 적어 그 다음 날까지 지적소관청에 제출"],["합의 기간","전체 기간의 4분의 3은 측량기간, 4분의 1은 측량검사기간"],["성과 보관·열람","시·도지사나 지적소관청"],["열람·등본 신청","지적삼각점성과는 시·도지사 또는 지적소관청, 삼각보조점·도근점성과는 지적소관청"]]}],"함정":"의뢰서 제출처(수행자), 수행계획서 제출처(소관청), 합의 기간의 배분(측량 3/4, 검사 1/4)이 각각 선지에서 바뀌어 있다. 제출 방향을 구별한다."},"33회-2차-002":{"한줄":"동·호수가 특정되어 분양계약이 체결된 아파트분양권과 주벽을 갖춘 신축 중 미등기 건물만 중개대상물이어서 ㄱ, ㄴ이 정답이다.","근거":[{"법령":"공인중개사법","조문":"제3조","원문":"1. 토지 2. 건축물 그 밖의 토지의 정착물 3. 그 밖에 대통령령으로 정하는 재산권 및 물건"},{"판례":"대법원 판례(아파트 분양권·신축 건물)","요지":"동·호수가 특정되어 분양계약이 체결된 아파트 분양권은 중개대상물이다. 기둥, 지붕, 주벽이 갖추어진 신축 중 건물은 미등기여도 건물로서 중개대상물이다."},{"판례":"대법원 판례(입주권·대토권)","요지":"추첨으로 분양예정자로 선정될 수 있는 지위인 입주권과 이주자택지를 공급받을 지위인 대토권은 중개대상물이 아니다."}],"선지":[{"번호":1,"판정":"옳음","설명":"ㄱ, ㄴ만 중개대상물에 해당한다."},{"번호":2,"판정":"틀림","설명":"ㄷ(입주권)은 중개대상물이 아니고 ㄱ이 빠져 있다."},{"번호":3,"판정":"틀림","설명":"ㄷ, ㄹ은 모두 중개대상물이 아니다."},{"번호":4,"판정":"틀림","설명":"ㄹ(대토권)은 중개대상물이 아니다."},{"번호":5,"판정":"틀림","설명":"ㄷ, ㄹ은 중개대상물이 아니라서 전부는 될 수 없다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"동·호수가 특정되어 분양계약이 체결된 아파트분양권은 중개대상물이다."},{"기호":"ㄴ","판정":"옳음","설명":"기둥, 지붕, 주벽이 갖추어지면 미등기 신축 중 건물도 중개대상물이다(제3조제2호)."},{"기호":"ㄷ","판정":"틀림","설명":"추첨기일에 신청해 당첨되어야 분양예정자가 되는 지위일 뿐이라 중개대상물이 아니다."},{"기호":"ㄹ","판정":"틀림","설명":"택지를 공급받을 지위인 대토권은 중개대상물이 아니다."}],"개념":[{"종류":"표","제목":"중개대상물 해당 여부 모음","머리":["대상","해당 여부","근거"],"행":[["토지(토지거래허가구역 토지, 가압류된 토지 포함)","해당","제3조제1호"],["건축물·정착물(미등기 건축물, 주벽을 갖춘 신축 중 건물)","해당","제3조제2호"],["입목법상 입목, 공장재단·광업재단","해당","시행령 제2조"],["동·호수가 특정되어 분양계약이 체결된 아파트 분양권","해당","판례"],["입주권(추첨 신청으로 분양예정자가 될 지위), 대토권","비해당","판례"],["영업시설·비품, 거래처·신용·점포 위치의 이점 등 무형의 가치","비해당","판례"],["금전채권(피담보채권 포함)","비해당","판례"]]}],"함정":"ㄷ은 분양권과 같은 성격으로 오해하기 쉽다. 동·호수가 특정되고 계약이 체결되었는지가 갈림길이다. 대토권은 권리의 이름이 붙어 있어도 중개대상물이 아니다."},"33회-2차-010":{"한줄":"한도를 초과하는 중개보수 약정은 초과 범위 내에서 무효이고, 거래계약이 완료되지 않아도 중개행위에 상응하는 보수 약정에는 보수 제한 규정이 적용되므로 ㄴ, ㄷ이 옳다.","근거":[{"법령":"공인중개사법","조문":"제32조제4항","원문":"주택(부속토지를 포함한다. 이하 이 항에서 같다)의 중개에 대한 보수와 제2항에 따른 실비의 한도 등에 관하여 필요한 사항은 국토교통부령으로 정하는 범위 안에서 특별시ㆍ광역시ㆍ도 또는 특별자치도(이하 \"시ㆍ도\"라 한다)의 조례로 정하고, 주택 외의 중개대상물의 중개에 대한 보수는 국토교통부령으로 정한다."},{"법령":"공인중개사법","조문":"제33조제1항제3호","원문":"사례ㆍ증여 그 밖의 어떠한 명목으로도 제32조에 따른 보수 또는 실비를 초과하여 금품을 받는 행위"},{"판례":"대법원 판례(공매 대상 부동산 취득 알선)","요지":"공매 대상 부동산 취득의 알선에도 공인중개사법령상 중개보수 제한 규정이 적용된다."},{"판례":"대법원 판례(한도 초과 약정)","요지":"공인중개사법령이 정한 한도를 초과하는 부동산 중개보수 약정은 한도를 초과하는 범위 내에서 무효다."},{"판례":"대법원 판례(거래 불성립 시 보수 약정)","요지":"개업공인중개사는 거래계약이 완료되지 않은 경우에도 중개의뢰인과 중개행위에 상응하는 보수를 지급하기로 약정할 수 있고, 이 경우에도 중개보수 제한 규정이 적용된다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄱ은 틀린 보기이고 ㄴ, ㄷ이 빠져 있다."},{"번호":2,"판정":"틀림","설명":"ㄴ도 옳아서 ㄷ만으로는 부족하다."},{"번호":3,"판정":"틀림","설명":"ㄱ은 틀린 보기이고 ㄷ이 빠져 있다."},{"번호":4,"판정":"옳음","설명":"ㄴ, ㄷ이 옳다."},{"번호":5,"판정":"틀림","설명":"ㄱ이 틀린 보기라 세 보기 전부는 될 수 없다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"공매 대상 부동산 취득의 알선에도 중개보수 제한 규정이 적용된다."},{"기호":"ㄴ","판정":"옳음","설명":"한도 초과 약정은 초과하는 범위 내에서 무효다."},{"기호":"ㄷ","판정":"옳음","설명":"거래가 완료되지 않아도 중개행위에 상응하는 보수 약정은 가능하며 그 경우도 제한 규정이 적용된다."}],"개념":[{"종류":"표","제목":"중개보수 제한 규정의 적용 범위","머리":["상황","제한 규정 적용 여부","근거"],"행":[["일반 매매·임대차 중개","적용","법 제32조제4항"],["공매 대상 부동산 취득의 알선","적용","판례"],["거래계약이 완료되지 않았으나 중개행위에 상응하는 보수 약정","약정 가능, 제한 규정 적용","판례"],["한도를 초과하는 약정","초과하는 범위 내 무효","판례"],["사례·증여 등 어떠한 명목으로든 보수 초과 수령","금지행위","법 제33조제1항제3호"]]}],"함정":"공매 대상 부동산 취득의 알선은 일반 매매 중개와 달라 보수 제한이 없다고 생각하기 쉽다. 제한 규정은 공매 대상 부동산 취득의 알선에도 적용된다."},"33회-2차-017":{"한줄":"보수의 지급시기는 약정에 따르되 약정이 없으면 중개대상물의 거래대금 지급이 완료된 날이므로 ④가 옳다.","근거":[{"법령":"공인중개사법","조문":"제32조제1항","원문":"개업공인중개사는 중개업무에 관하여 중개의뢰인으로부터 소정의 보수를 받는다. 다만, 개업공인중개사의 고의 또는 과실로 인하여 중개의뢰인간의 거래행위가 무효ㆍ취소 또는 해제된 경우에는 그러하지 아니하다."},{"법령":"공인중개사법","조문":"제32조제2항","원문":"개업공인중개사는 중개의뢰인으로부터 제25조제1항에 따른 중개대상물의 권리관계 등의 확인 또는 제31조에 따른 계약금등의 반환채무이행 보장에 소요되는 실비를 받을 수 있다."},{"법령":"공인중개사법 시행규칙","조문":"제20조제2항","원문":"법 제32조제4항에 따른 실비의 한도는 중개대상물의 권리관계 등의 확인 또는 계약금 등의 반환채무이행 보장에 드는 비용으로 하되, 개업공인중개사가 영수증 등을 첨부하여 매도ㆍ임대 그 밖의 권리를 이전하고자 하는 중개의뢰인(계약금 등의 반환채무이행 보장에 소요되는 실비의 경우에는 매수ㆍ임차 그 밖의 권리를 취득하고자 하는 중개의뢰인을 말한다)에게 청구할 수 있다."},{"법령":"공인중개사법 시행령","조문":"제27조의2","원문":"법 제32조제3항에 따른 중개보수의 지급시기는 개업공인중개사와 중개의뢰인간의 약정에 따르되, 약정이 없을 때에는 중개대상물의 거래대금 지급이 완료된 날로 한다."},{"법령":"공인중개사법","조문":"제32조제4항","원문":"주택(부속토지를 포함한다. 이하 이 항에서 같다)의 중개에 대한 보수와 제2항에 따른 실비의 한도 등에 관하여 필요한 사항은 국토교통부령으로 정하는 범위 안에서 특별시ㆍ광역시ㆍ도 또는 특별자치도(이하 \"시ㆍ도\"라 한다)의 조례로 정하고, 주택 외의 중개대상물의 중개에 대한 보수는 국토교통부령으로 정한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"개업공인중개사의 고의 또는 과실로 거래행위가 취소되면 보수를 받지 못한다(제32조제1항 단서)."},{"번호":2,"판정":"틀림","설명":"권리를 이전하려는 중개의뢰인에게 권리관계 등의 확인에 소요되는 실비를 청구할 수 있다(규칙 제20조제2항)."},{"번호":3,"판정":"틀림","설명":"권리를 취득하려는 중개의뢰인에게 계약금등의 반환채무이행 보장에 소요되는 실비를 청구할 수 있다(규칙 제20조제2항)."},{"번호":4,"판정":"옳음","설명":"약정에 따르고 약정이 없으면 거래대금 지급이 완료된 날이다(시행령 제27조의2)."},{"번호":5,"판정":"틀림","설명":"주택 외 중개대상물의 보수는 국토교통부령으로 정한다. 시·도 조례는 주택의 보수와 실비 한도에 관한 것이다(제32조제4항)."}],"개념":[{"종류":"표","제목":"실비의 종류와 청구 상대","머리":["실비","청구 상대","조문"],"행":[["중개대상물의 권리관계 등 확인에 소요되는 실비","권리를 이전하려는 중개의뢰인(매도·임대 등)","규칙 제20조제2항"],["계약금등의 반환채무이행 보장에 소요되는 실비","권리를 취득하려는 중개의뢰인(매수·임차 등)","규칙 제20조제2항"],["청구 방법","영수증 등을 첨부하여 청구","규칙 제20조제2항"],["주택의 보수·실비 한도","국토교통부령 범위 안에서 시·도 조례","법 제32조제4항"],["주택 외 보수","국토교통부령","법 제32조제4항"]]}],"함정":"②와 ③은 실비를 받을 수 있는 상대가 서로 바뀌어 있다. 확인 실비는 권리를 이전하려는 쪽에, 반환채무이행 보장 실비는 취득하려는 쪽에 청구한다."},"33회-2차-038":{"한줄":"요건을 갖춘 오피스텔은 주택이 아니라 시행규칙 제20조제4항제1호·별표 2가 적용되어 ㄱ, ㄴ, ㄷ만 옳고 ㄹ이 틀리므로 ④가 정답이다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제20조제4항제1호","원문":"「건축법 시행령」 별표 1 제14호나목2)에 따른 오피스텔(다음 각 목의 요건을 모두 갖춘 경우에 한정한다): 중개의뢰인 쌍방으로부터 각각 받되, 별표 2의 상한요율 이내에서 중개의뢰인과 개업공인중개사가 서로 협의하여 결정한다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제20조제4항제1호가목","원문":"전용면적이 85제곱미터 이하일 것"},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 별표 2","원문":"오피스텔 중개보수 요율: 매매·교환 상한요율 1천분의 5, 임대차 등 상한요율 1천분의 4"},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제20조제3항","원문":"제1항 및 제2항의 경우에 중개대상물의 소재지와 중개사무소의 소재지가 다른 경우에는 개업공인중개사는 중개사무소의 소재지를 관할하는 시ㆍ도의 조례에서 정한 기준에 따라 중개보수 및 실비를 받아야 한다."},{"법령":"공인중개사법","조문":"법 제32조제4항","원문":"주택(부속토지를 포함한다. 이하 이 항에서 같다)의 중개에 대한 보수와 제2항에 따른 실비의 한도 등에 관하여 필요한 사항은 국토교통부령으로 정하는 범위 안에서 특별시ㆍ광역시ㆍ도 또는 특별자치도(이하 \"시ㆍ도\"라 한다)의 조례로 정하고, 주택 외의 중개대상물의 중개에 대한 보수는 국토교통부령으로 정한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄹ만 고른 조합이다. ㄱ, ㄴ, ㄷ이 옳은 보기이므로 맞지 않는다."},{"번호":2,"판정":"틀림","설명":"ㄴ도 옳다. 오피스텔 매매의 상한요율은 1천분의 5다(시행규칙 제20조제4항제1호, 별표 2)."},{"번호":3,"판정":"틀림","설명":"ㄱ, ㄷ이 빠졌고 ㄹ은 틀린 보기다. 요건을 갖춘 오피스텔은 주택 규정(제1항, 별표 1)이 아니라 제4항제1호가 적용된다."},{"번호":4,"판정":"옳음","설명":"ㄱ, ㄴ, ㄷ이 옳은 보기이고 ㄹ만 틀려 이 조합이 맞다."},{"번호":5,"판정":"틀림","설명":"ㄹ이 틀린 보기라 네 보기를 모두 고르면 맞지 않는다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"실비의 한도는 시·도 조례로 정하고(법 제32조제4항), 중개대상물과 사무소의 소재지가 다르면 사무소 소재지 시·도의 조례 기준에 따른다(시행규칙 제20조제3항). 甲의 사무소는 A시에 있다."},{"기호":"ㄴ","판정":"옳음","설명":"요건을 갖춘 오피스텔의 매매·교환 상한요율은 1천분의 5다(시행규칙 제20조제4항제1호, 별표 2). 전용면적 80제곱미터는 85제곱미터 이하이고 부엌·화장실·목욕시설 요건도 갖췄다."},{"기호":"ㄷ","판정":"옳음","설명":"주택 외 중개대상물의 보수는 중개의뢰인 쌍방으로부터 각각 받는다(시행규칙 제20조제4항제1호)."},{"기호":"ㄹ","판정":"틀림","설명":"요건을 갖춘 오피스텔은 시행규칙 제20조제4항제1호와 별표 2가 적용되고 주택의 보수 규정(제1항)은 적용되지 않는다."}],"개념":[{"종류":"표","제목":"중개보수 적용 규정","머리":["구분","적용 규정","한도"],"행":[["주택(부속토지 포함)","시행규칙 제20조제1항, 별표 1, 시·도 조례","거래금액 구간별 상한요율·한도액 이내에서 협의"],["오피스텔(전용 85제곱미터 이하, 입식 부엌·수세식 화장실·목욕시설 구비)","시행규칙 제20조제4항제1호, 별표 2","매매·교환 1천분의 5, 임대차 등 1천분의 4 이내"],["그 밖의 주택 외 중개대상물","시행규칙 제20조제4항제2호","거래금액의 1천분의 9 이내"],["건축물 중 주택 면적이 2분의 1 이상","시행규칙 제20조제6항","주택 규정(제1항) 적용"],["건축물 중 주택 면적이 2분의 1 미만","시행규칙 제20조제6항","주택 외 규정(제4항) 적용"],["중개대상물과 중개사무소의 소재지가 다른 경우","시행규칙 제20조제3항","중개사무소 소재지 시·도 조례 기준"]]},{"종류":"비교","제목":"주택 중개보수와 오피스텔 중개보수","왼쪽":{"이름":"주택(제20조제1항)","항목":["한도는 별표 1의 거래금액 구간별 상한요율·한도액","시·도 조례가 요율한도를 정하고 그 범위에서 협의","쌍방으로부터 각각 받음","실비는 사무소 소재지 시·도 조례 기준"]},"오른쪽":{"이름":"오피스텔(제20조제4항제1호)","항목":["전용 85제곱미터 이하, 입식 부엌·수세식 화장실·목욕시설 구비가 요건","별표 2: 매매·교환 1천분의 5, 임대차 등 1천분의 4","쌍방으로부터 각각 받음","요건 불충족 시 거래금액의 1천분의 9 이내(제4항제2호)"]}}],"함정":"ㄹ을 옳게 보면 ⑤를 고른다. 오피스텔을 주거용으로 쓰더라도 요건을 모두 갖춘 경우의 보수는 주택 규정이 아니라 별표 2에서 정한다. 발문에 건축법령상 업무시설이라고 적혀 있다. ㄴ은 매매 1천분의 5와 임대차 1천분의 4를 바꿔 기억하면 틀린 보기로 보인다. ㄱ은 중개대상물 소재지(B시)가 아니라 중개사무소 소재지(A시)가 기준이다.","개정":"보기 ㄴ은 원문에 1천분의 50으로 적혀 있었으나 별표 2의 오피스텔 매매·교환 상한요율 1천분의 5로 바로잡아 실었다. 법령 개정이 아니라 입력 오기 정정이다."},"33회-2차-020":{"한줄":"포상금 신고·고발 대상은 법 제46조제1항에 열거되는데 자격증을 대여받은 자(제3호)만 들어 있고 매매업과 거짓 언행은 빠져 ㄴ만 해당한다.","근거":[{"법령":"공인중개사법","조문":"법 제46조제1항제3호","원문":"중개사무소등록증 또는 공인중개사자격증을 다른 사람에게 양도ㆍ대여하거나 다른 사람으로부터 양수ㆍ대여받은 자"},{"법령":"공인중개사법","조문":"법 제46조제1항제5호","원문":"제33조제1항제8호 또는 제9호에 따른 행위를 한 자"},{"법령":"공인중개사법","조문":"법 제33조제1항제1호","원문":"제3조에 따른 중개대상물의 매매를 업으로 하는 행위"},{"법령":"공인중개사법","조문":"법 제33조제1항제4호","원문":"해당 중개대상물의 거래상의 중요사항에 관하여 거짓된 언행 그 밖의 방법으로 중개의뢰인의 판단을 그르치게 하는 행위"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄱ은 포상금 대상이 아니고 ㄴ이 빠졌다."},{"번호":2,"판정":"옳음","설명":"ㄴ만 포상금 대상이어서 이 조합이 맞다."},{"번호":3,"판정":"틀림","설명":"ㄱ, ㄷ 모두 포상금 대상이 아니다."},{"번호":4,"판정":"틀림","설명":"ㄷ은 포상금 대상이 아니다."},{"번호":5,"판정":"틀림","설명":"ㄱ, ㄷ은 포상금 대상이 아니다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"중개대상물의 매매업은 제33조제1항제1호 금지행위로 포상금 대상이 아니다. 제33조제1항 중에는 제8호·제9호만 대상이다(법 제46조제1항제5호)."},{"기호":"ㄴ","판정":"옳음","설명":"자격증을 다른 사람으로부터 양수·대여받은 자는 포상금 대상이다(법 제46조제1항제3호)."},{"기호":"ㄷ","판정":"틀림","설명":"거래상 중요사항에 관한 거짓된 언행은 제33조제1항제4호 금지행위로 포상금 대상이 아니다."}],"개념":[{"종류":"표","제목":"포상금 지급 대상 신고·고발(법 제46조제1항)","머리":["호","대상 행위","비고"],"행":[["1","중개사무소 개설등록 없이 중개업을 한 자","제9조 위반"],["2","거짓이나 그 밖의 부정한 방법으로 개설등록을 한 자",""],["3","중개사무소등록증 또는 공인중개사자격증을 양도·대여하거나 양수·대여받은 자","양수·대여받은 자도 포함"],["4","개업공인중개사가 아닌 자로서 중개대상물을 표시·광고한 자","제18조의2제3항 위반"],["5","제33조제1항제8호 또는 제9호의 행위를 한 자","시세 부당 영향, 단체 구성 중개 제한"],["6","시세에 부당한 영향을 줄 목적으로 개업공인중개사등의 업무를 방해한 자","제33조제2항 위반"]]},{"종류":"비교","제목":"제33조제1항 금지행위 중 포상금 대상 여부","왼쪽":{"이름":"포상금 대상","항목":["제8호 거래 완료를 꾸미는 등 시세에 부당한 영향을 주는 행위","제9호 단체를 구성하여 중개를 제한하는 행위","제33조제2항 업무방해(별도 항)"]},"오른쪽":{"이름":"포상금 대상 아님","항목":["제1호 중개대상물의 매매업","제2호 무등록업자 통한 중개의뢰·명의 이용","제3호 보수·실비 초과 금품 수수","제4호 거짓된 언행","제5호 증서 등의 중개","제6호 직접 거래·쌍방 대리","제7호 투기 조장"]}}],"함정":"금지행위(제33조제1항) 전부가 포상금 대상이라고 보면 ㄱ, ㄷ을 고르게 된다. 포상금 대상은 제8호·제9호뿐이다. ㄴ에서는 자격증을 빌려준 사람만이 아니라 대여받은 사람도 대상이라는 점을 놓치기 쉽다."},"33회-2차-013":{"한줄":"이동이 용이한 임시 중개시설물의 설치는 법 제38조제2항제3호의 임의적 취소 사유라 취소해야 하는 사유(제1항)로 명시되지 않았으므로 ④가 정답이다.","근거":[{"법령":"공인중개사법","조문":"법 제38조제2항제3호","원문":"제13조제2항의 규정을 위반하여 임시 중개시설물을 설치한 경우"},{"법령":"공인중개사법","조문":"법 제38조제1항제7호","원문":"업무정지기간 중에 중개업무를 하거나 자격정지처분을 받은 소속공인중개사로 하여금 자격정지기간 중에 중개업무를 하게 한 경우"},{"법령":"공인중개사법","조문":"법 제38조제1항제1호","원문":"개인인 개업공인중개사가 사망하거나 개업공인중개사인 법인이 해산한 경우"},{"법령":"공인중개사법","조문":"법 제38조제1항제4호","원문":"제12조제1항의 규정을 위반하여 이중으로 중개사무소의 개설등록을 한 경우"},{"법령":"공인중개사법","조문":"법 제38조제1항제8호","원문":"최근 1년 이내에 이 법에 의하여 2회 이상 업무정지처분을 받고 다시 업무정지처분에 해당하는 행위를 한 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"업무정지기간 중에 중개업무를 한 경우는 취소해야 하는 사유로 명시되어 있다(법 제38조제1항제7호)."},{"번호":2,"판정":"옳음","설명":"개인인 개업공인중개사가 사망한 경우는 취소해야 하는 사유로 명시되어 있다(법 제38조제1항제1호)."},{"번호":3,"판정":"옳음","설명":"이중등록은 취소해야 하는 사유로 명시되어 있다(법 제38조제1항제4호)."},{"번호":4,"판정":"틀림","설명":"임시 중개시설물 설치는 취소할 수 있는 사유(제38조제2항제3호)로만 명시되어 있다."},{"번호":5,"판정":"옳음","설명":"최근 1년 이내 업무정지 2회 이상 후 다시 업무정지 해당 행위를 한 경우는 취소해야 하는 사유로 명시되어 있다(법 제38조제1항제8호)."}],"개념":[{"종류":"표","제목":"중개사무소 개설등록 취소 사유","머리":["구분","사유","조문"],"행":[["필요적 취소","개인인 개업공인중개사의 사망, 법인의 해산","법 제38조제1항제1호"],["필요적 취소","거짓이나 그 밖의 부정한 방법으로 개설등록","제1항제2호"],["필요적 취소","결격사유 해당(제10조제1항제2호~제6호, 제11호, 제12호)","제1항제3호"],["필요적 취소","이중등록","제1항제4호"],["필요적 취소","다른 개업공인중개사의 소속공인중개사·중개보조원 또는 법인의 사원·임원이 된 경우","제1항제5호"],["필요적 취소","중개보조원 고용 상한(개업공인중개사와 소속공인중개사 합산 수의 5배) 초과","제1항제5호의2"],["필요적 취소","자기의 성명·상호를 사용하여 중개업무를 하게 하거나 등록증을 양도·대여","제1항제6호"],["필요적 취소","업무정지기간 중 중개업무, 자격정지 중인 소속공인중개사에게 중개업무를 하게 함","제1항제7호"],["필요적 취소","최근 1년 이내 2회 이상 업무정지처분을 받고 다시 업무정지 해당 행위","제1항제8호"],["임의적 취소","등록기준 미달, 둘 이상의 중개사무소, 임시 중개시설물, 겸업 위반","법 제38조제2항제1호~제4호"],["임의적 취소","6개월 초과 휴업, 정보 비공개 위반, 거래계약서 거짓 기재, 손해배상 보장조치 미이행, 금지행위","제2항제5호~제9호"],["임의적 취소","최근 1년 이내 3회 이상 업무정지 또는 과태료 처분을 받고 다시 업무정지 또는 과태료 처분 해당 행위(제1항제8호 해당 제외)","제2항제10호"],["임의적 취소","사업자단체 또는 구성원이 공정거래법 위반으로 최근 2년 이내 2회 이상 처분","제2항제11호"]]}],"함정":"\"취소하여야 하는 사유로 명시되지 않은 것\"은 제1항 여덟 호에 없는 것을 찾는 문제다. 임시 중개시설물은 제2항(취소할 수 있음)에 있어 정답이 된다. 같은 제13조의 사무소 설치 위반(둘 이상의 중개사무소, 임시 시설물)은 모두 제2항이다."},"33회-2차-018":{"한줄":"처분 효과 승계는 처분일부터 1년이고(ㄱ 틀림), 업무정지 사유 위반행위는 폐업기간이 1년을 넘으면 처분할 수 없고(ㄴ), 과태료 처분 효과는 10개월 만의 재등록이면 승계되며(ㄷ), 3년을 초과하면 등록취소도 할 수 없어(ㄹ) ㄴ, ㄷ, ㄹ이 옳다.","근거":[{"법령":"공인중개사법","조문":"법 제40조제2항","원문":"제1항의 경우 폐업신고 전의 개업공인중개사에 대하여 제39조제1항 각 호, 제51조제1항 각 호, 같은 조 제2항 각 호 및 같은 조 제3항 각 호의 위반행위를 사유로 행한 행정처분의 효과는 그 처분일부터 1년간 다시 중개사무소의 개설등록을 한 자(이하 이 조에서 \"재등록 개업공인중개사\"라 한다)에게 승계된다."},{"법령":"공인중개사법","조문":"법 제40조제3항제1호","원문":"폐업신고를 한 날부터 다시 중개사무소의 개설등록을 한 날까지의 기간(이하 제2호에서 \"폐업기간\"이라 한다)이 3년을 초과한 경우"},{"법령":"공인중개사법","조문":"법 제40조제3항제2호","원문":"폐업신고 전의 위반행위에 대한 행정처분이 업무정지에 해당하는 경우로서 폐업기간이 1년을 초과한 경우"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄱ만 고른 조합이다. ㄱ은 승계 기간을 2년으로 적어 틀린 보기이고 ㄴ, ㄷ, ㄹ이 옳다."},{"번호":2,"판정":"틀림","설명":"ㄱ이 틀린 보기라 ㄱ, ㄹ 조합은 맞지 않다."},{"번호":3,"판정":"틀림","설명":"ㄹ도 옳은 보기라 ㄴ, ㄷ만 고른 조합은 부족하다."},{"번호":4,"판정":"옳음","설명":"ㄴ, ㄷ, ㄹ이 옳고 ㄱ만 틀려 이 조합이 맞다."},{"번호":5,"판정":"틀림","설명":"ㄱ이 틀린 보기라 네 보기를 모두 고르면 맞지 않는다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"업무정지처분의 효과는 그 처분일부터 1년간 승계된다(법 제40조제2항). 2년이 아니다."},{"기호":"ㄴ","판정":"옳음","설명":"업무정지에 해당하는 위반행위는 폐업기간이 1년을 초과하면 처분할 수 없다(법 제40조제3항제2호). 2년을 초과한 경우도 마찬가지다."},{"기호":"ㄷ","판정":"옳음","설명":"과태료부과처분의 효과는 처분일부터 1년간 승계되므로 10개월 만에 재등록하면 승계된다(법 제40조제2항)."},{"기호":"ㄹ","판정":"옳음","설명":"폐업기간이 3년을 초과하면 등록취소 사유라도 처분할 수 없다(법 제40조제3항제1호). 3년 6개월은 3년을 초과한다."}],"개념":[{"종류":"표","제목":"행정제재처분효과의 승계(법 제40조)","머리":["구분","내용"],"행":[["지위 승계","폐업신고 후 다시 개설등록을 하면 폐업신고 전 개업공인중개사의 지위를 승계(동일인 재등록의 경우)"],["처분 효과의 승계","폐업신고 전 업무정지·과태료 처분의 효과는 그 처분일부터 1년간 재등록 개업공인중개사에게 승계"],["위반행위에 대한 처분","재등록 개업공인중개사에게 폐업신고 전의 등록취소·업무정지 사유 위반행위로 처분 가능"],["처분 불가 1","폐업기간(폐업신고일~재등록일)이 3년을 초과한 경우"],["처분 불가 2","폐업신고 전 위반행위에 대한 처분이 업무정지에 해당하는 경우로서 폐업기간이 1년을 초과한 경우"],["처분 시 고려","폐업기간과 폐업의 사유 등을 고려"],["법인","법인의 대표자에 관하여 준용(개업공인중개사는 법인의 대표자로 봄)"]]},{"종류":"표","제목":"폐업기간에 따른 처분 가능 여부(법 제40조제3항)","머리":["폐업기간","위반행위의 처분이 업무정지에 해당","그 밖의 처분(등록취소 등)에 해당"],"행":[["1년 이하","처분 가능","처분 가능"],["1년 초과 3년 이하","처분 불가","처분 가능"],["3년 초과","처분 불가","처분 불가"]]}],"함정":"ㄱ의 2년은 승계 기간(처분일부터 1년)을 늘려 놓은 것이다. ㄴ의 \"2년을 초과한\"은 1년을 초과한 경우를 포함하는 더 좁은 범위라 옳은 서술이다. 업무정지는 폐업기간 1년 초과부터, 등록취소는 3년 초과부터 처분이 막힌다."},"33회-2차-003":{"한줄":"정책심의위원회의 심의사항은 시험 등 자격취득(제1호), 중개업의 육성(제2호), 중개보수 변경(제3호), 손해배상책임의 보장(제4호) 네 가지여서 ㄱ~ㄹ이 모두 해당한다.","근거":[{"법령":"공인중개사법","조문":"법 제2조의2제1항제1호","원문":"공인중개사의 시험 등 공인중개사의 자격취득에 관한 사항"},{"법령":"공인중개사법","조문":"법 제2조의2제1항제2호","원문":"부동산 중개업의 육성에 관한 사항"},{"법령":"공인중개사법","조문":"법 제2조의2제1항제3호","원문":"중개보수 변경에 관한 사항"},{"법령":"공인중개사법","조문":"법 제2조의2제1항제4호","원문":"손해배상책임의 보장 등에 관한 사항"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄴ, ㄷ, ㄹ도 심의사항이라 ㄱ만 고른 조합은 부족하다."},{"번호":2,"판정":"틀림","설명":"ㄱ, ㄹ도 심의사항이라 ㄴ, ㄷ만 고른 조합은 부족하다."},{"번호":3,"판정":"틀림","설명":"ㄱ, ㄷ도 심의사항이라 ㄴ, ㄹ만 고른 조합은 부족하다."},{"번호":4,"판정":"틀림","설명":"ㄴ도 심의사항이라 ㄱ, ㄷ, ㄹ만 고른 조합은 부족하다."},{"번호":5,"판정":"옳음","설명":"네 보기가 모두 심의사항이라 이 조합이 맞다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"공인중개사의 시험 등 자격취득에 관한 사항은 심의사항이다(법 제2조의2제1항제1호)."},{"기호":"ㄴ","판정":"옳음","설명":"부동산 중개업의 육성에 관한 사항은 심의사항이다(법 제2조의2제1항제2호)."},{"기호":"ㄷ","판정":"옳음","설명":"중개보수 변경에 관한 사항은 심의사항이다(법 제2조의2제1항제3호)."},{"기호":"ㄹ","판정":"옳음","설명":"손해배상책임의 보장 등에 관한 사항은 심의사항이다(법 제2조의2제1항제4호)."}],"개념":[{"종류":"표","제목":"공인중개사 정책심의위원회","머리":["항목","내용","조문"],"행":[["설치","국토교통부에 둘 수 있음","법 제2조의2제1항"],["심의사항","① 공인중개사의 시험 등 자격취득, ② 부동산 중개업의 육성, ③ 중개보수 변경, ④ 손해배상책임의 보장 등","법 제2조의2제1항제1호~제4호"],["시·도지사 구속력","심의사항 중 제1호(시험 등 자격취득)에 한해 시·도지사가 따라야 함","법 제2조의2제3항"],["구성","위원장 1명 포함 7명 이상 11명 이내","영 제1조의2제1항"],["위원장","국토교통부 제1차관","영 제1조의2제2항"],["위원 임기","위원장 제외 위원 2년(보궐위원은 전임자 잔여기간)","영 제1조의2제3항"],["제척","위원이 안건에 증언·진술·자문·조사·연구·용역·감정을 한 경우 등","영 제1조의3제1항"],["기피","당사자가 신청하고 심의위원회가 의결로 결정(대상 위원은 참여 불가)","영 제1조의3제2항"],["위원장 직무대행","위원장이 미리 지명한 위원","영 제1조의4제2항"],["회의","재적위원 과반수 출석으로 개의, 출석위원 과반수 찬성으로 의결","영 제1조의5제2항"]]}],"함정":"심의사항은 자격취득, 육성, 보수 변경, 손해배상책임 보장의 네 가지이고 그중 시·도지사가 따라야 하는 것은 제1호뿐이다."},"33회-2차-005":{"한줄":"금고 이상 실형의 집행이 면제된 날부터 3년이 지나지 않은 자(ㄱ)와 사원 중 집행유예 기간 중인 자가 있는 법인(ㄷ)이 결격이다.","근거":[{"법령":"공인중개사법","조문":"법 제10조제1항제4호","원문":"다음 각 호의 어느 하나에 해당하는 자는 중개사무소의 개설등록을 할 수 없다. 금고 이상의 실형의 선고를 받고 그 집행이 종료(집행이 종료된 것으로 보는 경우를 포함한다)되거나 집행이 면제된 날부터 3년이 지나지 아니한 자"},{"법령":"공인중개사법","조문":"법 제10조제1항제11호","원문":"다음 각 호의 어느 하나에 해당하는 자는 중개사무소의 개설등록을 할 수 없다. 이 법을 위반하여 300만원 이상의 벌금형의 선고를 받고 3년이 지나지 아니한 자"},{"법령":"공인중개사법","조문":"법 제10조제1항제12호","원문":"다음 각 호의 어느 하나에 해당하는 자는 중개사무소의 개설등록을 할 수 없다. 사원 또는 임원 중 제1호부터 제11호까지의 어느 하나에 해당하는 자가 있는 법인"},{"법령":"공인중개사법","조문":"법 제10조제1항제5호","원문":"다음 각 호의 어느 하나에 해당하는 자는 중개사무소의 개설등록을 할 수 없다. 금고 이상의 형의 집행유예를 받고 그 유예기간이 만료된 날부터 2년이 지나지 아니한 자"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄷ도 결격이라서 ㄱ만으로는 모자란다."},{"번호":2,"판정":"틀림","설명":"ㄴ은 결격이 아니다."},{"번호":3,"판정":"옳음","설명":"ㄱ, ㄷ이 결격이다."},{"번호":4,"판정":"틀림","설명":"ㄴ은 결격이 아니고 ㄱ이 빠졌다."},{"번호":5,"판정":"틀림","설명":"ㄴ은 결격이 아니다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"금고 이상의 실형은 집행이 면제된 날부터 3년이 지나야 한다. 2년이 된 자는 결격이다(법 제10조제1항제4호)."},{"기호":"ㄴ","판정":"틀림","설명":"이 법 위반 벌금형은 300만원 이상이어야 결격이다. 200만원은 해당하지 않는다(법 제10조제1항제11호)."},{"기호":"ㄷ","판정":"옳음","설명":"사원 중 집행유예 기간 중인 자가 있으면(제5호) 그 법인은 결격이다(법 제10조제1항제12호)."}],"개념":[{"종류":"표","제목":"결격 기간 비교(법 제10조제1항)","머리":["사유","기산 시점","기간"],"행":[["금고 이상의 실형(제4호)","집행 종료·집행 면제일","3년"],["금고 이상의 집행유예(제5호)","유예기간 만료일","2년(유예기간 중 포함)"],["이 법 위반 300만원 이상 벌금형(제11호)","선고일","3년"],["공인중개사 자격취소(제6호)","취소일","3년"],["개설등록 취소(제8호)","취소일","3년(법 제40조제3항 취소는 폐업기간 공제)"],["자격정지(제7호)","-","자격정지기간 중"],["업무정지 후 폐업(제9호)","-","업무정지기간이 지나기 전"]]},{"종류":"비교","제목":"법정형 구분: 제48조와 제49조","왼쪽":{"이름":"제48조: 3년 이하의 징역 또는 3천만원 이하의 벌금","항목":["무등록 중개업","거짓이나 부정한 방법으로 개설등록","법 제33조제1항제5호~제9호 금지행위","법 제33조제2항 각 호의 업무방해"]},"오른쪽":{"이름":"제49조제1항: 1년 이하의 징역 또는 1천만원 이하의 벌금","항목":["자격증·등록증 대여, 이중등록·이중소속, 둘 이상의 사무소","유사명칭 사용, 임시 중개시설물, 중개보조원 5배 초과 고용","법 제33조제1항제1호~제4호 금지행위","업무상 비밀 누설 등"]}}],"함정":"이 법 위반 벌금형은 300만원 이상일 때만 결격이다(ㄴ의 200만원은 미달). 실형은 집행 면제일부터 3년이므로 2년이 지난 자(ㄱ)는 아직 결격이다."},"33회-2차-019":{"한줄":"대표자가 공인중개사이고(ㄱ) 건축물대장에 기재된 건물에 전세로 사무소를 확보했으면(ㄴ) 기준에 맞고, 사회적협동조합(ㄷ)은 제외된다.","근거":[{"법령":"공인중개사법 시행령","조문":"영 제13조제1항제2호다목","원문":"다. 대표자는 공인중개사이어야 하며, 대표자를 제외한 임원 또는 사원(합명회사 또는 합자회사의 무한책임사원을 말한다. 이하 이 조에서 같다)의 3분의 1 이상은 공인중개사일 것"},{"법령":"공인중개사법 시행령","조문":"영 제13조제1항제2호마목","원문":"마. 건축물대장에 기재된 건물에 중개사무소를 확보(소유ㆍ전세ㆍ임대차 또는 사용대차 등의 방법에 의하여 사용권을 확보하여야 한다)할 것"},{"법령":"공인중개사법 시행령","조문":"영 제13조제1항제2호가목","원문":"가. 「상법」상 회사 또는 「협동조합 기본법」 제2조제1호에 따른 협동조합(같은 조 제3호에 따른 사회적협동조합은 제외한다)으로서 자본금이 5천만원 이상일 것"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄴ도 기준에 맞아 ㄱ만으로는 모자란다."},{"번호":2,"판정":"틀림","설명":"ㄷ은 기준에 맞지 않는다."},{"번호":3,"판정":"옳음","설명":"ㄱ, ㄴ이 기준에 맞는다."},{"번호":4,"판정":"틀림","설명":"ㄷ은 기준에 맞지 않고 ㄱ이 빠졌다."},{"번호":5,"판정":"틀림","설명":"ㄷ은 기준에 맞지 않는다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"법인의 대표자는 공인중개사여야 한다(영 제13조제1항제2호다목)."},{"기호":"ㄴ","판정":"옳음","설명":"건축물대장에 기재된 건물에 소유·전세·임대차·사용대차 등으로 사용권을 확보하면 된다(영 제13조제1항제2호마목)."},{"기호":"ㄷ","판정":"틀림","설명":"사회적협동조합은 법인의 개설등록 기준에서 제외된다(영 제13조제1항제2호가목)."}],"개념":[{"종류":"표","제목":"중개사무소 개설등록 기준(영 제13조제1항)","머리":["구분","공인중개사","법인"],"행":[["자본금","요건 없음","상법상 회사 또는 협동조합(사회적협동조합 제외)으로서 5천만원 이상"],["업무 범위","-","법 제14조에 규정된 업무만 영위할 목적으로 설립"],["공인중개사 요건","본인이 공인중개사","대표자는 공인중개사, 대표자를 제외한 임원·사원의 3분의 1 이상이 공인중개사"],["실무교육","본인","대표자·임원·사원 전원, 분사무소를 설치하려면 분사무소 책임자도 포함"],["사무소","건축물대장에 기재된 건물에 소유·전세·임대차·사용대차 등으로 사용권 확보","같음"],["예외","-","다른 법률에 따라 중개업을 할 수 있는 경우 위 기준을 적용하지 않음"]]},{"종류":"표","제목":"사무소 확보의 요건","머리":["항목","내용","근거"],"행":[["확보 방법","소유·전세·임대차·사용대차 등으로 사용권 확보","영 제13조제1항제2호마목"],["대상 건물","건축물대장에 기재된 건물(준공검사·사용승인 등을 받았으나 대장 기재 전인 건물 포함)","영 제13조제1항제1호나목"],["제외","가설건축물대장에 기재된 건물","영 제13조제1항제1호나목"],["증명","사용권 확보 증명서류. 대장에 기재되지 않은 건물이면 기재 지연 사유서도 제출","시행규칙 제4조제1항제5호"],["공동 사용","다른 개업공인중개사와 공동 사용하려면 승낙서 첨부","영 제16조제1항"]]}],"함정":"사용권은 전세로도 확보할 수 있다(ㄴ). 사회적협동조합은 법인 기준에서 제외된다(ㄷ). 건축물대장에서 가설건축물대장은 제외되므로 일반 건축물대장 기재 건물이어야 한다."},"33회-2차-011":{"한줄":"ㄱ은 15일, ㄴ은 7일, ㄷ은 10일이므로 큰 것부터 ㄱ-ㄷ-ㄴ 순이다.","근거":[{"법령":"공인중개사법 시행령","조문":"영 제26조제2항","원문":"개업공인중개사는 보증보험금ㆍ공제금 또는 공탁금으로 손해배상을 한 때에는 15일 이내에 보증보험 또는 공제에 다시 가입하거나 공탁금 중 부족하게 된 금액을 보전하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제9조제2항","원문":"제1항의 규정에 따라 등록한 인장을 변경한 경우에는 개업공인중개사 및 소속공인중개사는 변경일부터 7일 이내에 그 변경된 인장을 등록관청에 등록(전자문서에 의한 등록을 포함한다)하여야 한다."},{"법령":"공인중개사법","조문":"법 제20조제1항","원문":"개업공인중개사는 중개사무소를 이전한 때에는 이전한 날부터 10일 이내에 국토교통부령으로 정하는 바에 따라 등록관청에 이전사실을 신고하여야 한다. 다만, 중개사무소를 등록관청의 관할 지역 외의 지역으로 이전한 경우에는 이전 후의 중개사무소를 관할하는 시장ㆍ군수 또는 구청장(이하 이 조에서 \"이전후 등록관청\"이라 한다)에게 신고하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"ㄱ 15일(영 제26조제2항) > ㄷ 10일(법 제20조제1항) > ㄴ 7일(시행규칙 제9조제2항) 순이다."},{"번호":2,"판정":"틀림","설명":"ㄴ(7일)이 가장 작은 수라 맨 앞에 올 수 없다."},{"번호":3,"판정":"틀림","설명":"ㄴ(7일)이 가장 작은 수라 맨 앞에 올 수 없다."},{"번호":4,"판정":"틀림","설명":"ㄷ(10일)이 ㄱ(15일)보다 작아 맨 앞에 올 수 없다."},{"번호":5,"판정":"틀림","설명":"ㄷ(10일)이 ㄱ(15일)보다 작아 맨 앞에 올 수 없다."}],"개념":[{"종류":"표","제목":"신고·등록·반납 기한 모음","머리":["구분","기한","근거"],"행":[["등록한 인장 변경","변경일부터 7일 이내 등록","시행규칙 제9조제2항"],["중개사무소 이전신고","이전한 날부터 10일 이내","법 제20조제1항"],["고용관계 종료 신고","종료된 날부터 10일 이내","시행규칙 제8조제4항"],["손해배상 후 보증 재설정","보증보험금·공제금·공탁금으로 배상한 때부터 15일 이내","영 제26조제2항"],["자격증 반납","자격취소처분을 받은 날부터 7일 이내","시행규칙 제21조"],["등록증 반납","등록취소처분을 받은 날부터 7일 이내","시행규칙 제24조제1항"],["자격취소 통보","5일 이내 국토교통부장관과 다른 시·도지사에게","영 제29조제3항"],["등록 통지","신청을 받은 날부터 7일 이내 서면 통지","시행규칙 제4조제2항"],["협회 통보","매월 다음달 10일까지","시행규칙 제6조"]]},{"종류":"표","제목":"손해배상책임의 보장(법 제30조, 영 제24조~제26조)","머리":["항목","내용","근거"],"행":[["설정 시점","업무를 개시하기 전에 보증보험·공제 가입 또는 공탁","법 제30조제3항"],["보장금액","법인 4억원 이상(분사무소마다 2억원 추가), 법인이 아닌 개업공인중개사 2억원 이상","영 제24조제1항"],["다른 법률의 중개업자","보장금액 2천만원 이상","영 제24조제3항"],["신고","증명서류를 갖추어 등록관청에 신고(보증기관이 직접 통보하면 생략)","영 제24조제2항"],["보증 변경","기존 보증의 효력이 있는 기간 중에 다른 보증을 설정하고 신고","영 제25조제1항"],["재설정","배상한 때부터 15일 이내 다시 가입하거나 공탁금 부족액 보전","영 제26조제2항"],["공탁금 회수","폐업 또는 사망한 날부터 3년 이내 회수 불가","법 제30조제4항"]]}],"함정":"세 기한은 공제 재가입 15일, 이전신고 10일, 인장 변경 등록 7일이다. 공제 재가입의 15일이 가장 길다."},"33회-2차-014":{"한줄":"ㄱ부터 ㄹ까지 모두 법 제24조제5항이 정한 거래정보사업자 지정취소 사유다.","근거":[{"법령":"공인중개사법","조문":"법 제24조제5항제1호","원문":"1. 거짓이나 그 밖의 부정한 방법으로 지정을 받은 경우"},{"법령":"공인중개사법","조문":"법 제24조제5항제4호","원문":"4. 정당한 사유 없이 지정받은 날부터 1년 이내에 부동산거래정보망을 설치ㆍ운영하지 아니한 경우"},{"법령":"공인중개사법","조문":"법 제24조제5항제3호","원문":"3. 제4항의 규정을 위반하여 정보를 공개한 경우"},{"법령":"공인중개사법","조문":"법 제24조제5항제2호","원문":"2. 제3항의 규정을 위반하여 운영규정의 승인 또는 변경승인을 받지 아니하거나 운영규정을 위반하여 부동산거래정보망을 운영한 경우"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄷ, ㄹ도 취소 사유라 ㄱ, ㄴ만 고른 조합은 부족하다."},{"번호":2,"판정":"틀림","설명":"ㄱ, ㄹ도 취소 사유라 ㄴ, ㄷ만 고른 조합은 부족하다."},{"번호":3,"판정":"틀림","설명":"ㄱ, ㄴ도 취소 사유라 ㄷ, ㄹ만 고른 조합은 부족하다."},{"번호":4,"판정":"틀림","설명":"ㄴ도 취소 사유라 ㄱ, ㄷ, ㄹ만 고른 조합은 부족하다."},{"번호":5,"판정":"옳음","설명":"네 보기가 모두 취소 사유라 이 조합이 맞다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"거짓이나 그 밖의 부정한 방법으로 지정을 받은 경우다(법 제24조제5항제1호)."},{"기호":"ㄴ","판정":"옳음","설명":"지정받은 날부터 1년 이내에 설치·운영하지 않은 경우다(법 제24조제5항제4호)."},{"기호":"ㄷ","판정":"옳음","설명":"의뢰받은 내용과 다르게 정보를 공개하는 것은 제4항 위반이다(법 제24조제5항제3호)."},{"기호":"ㄹ","판정":"옳음","설명":"운영규정을 위반하여 운영한 경우다(법 제24조제5항제2호)."}],"개념":[{"종류":"표","제목":"거래정보사업자 지정취소 사유(법 제24조제5항·제6항)","머리":["호","사유","청문"],"행":[["1","거짓이나 그 밖의 부정한 방법으로 지정을 받은 경우","실시"],["2","운영규정의 승인 또는 변경승인을 받지 않거나 운영규정을 위반하여 부동산거래정보망을 운영한 경우","실시"],["3","공개를 의뢰받은 정보에 한정하지 않고 공개하거나 의뢰받은 내용과 다르게, 또는 개업공인중개사에 따라 차별적으로 공개한 경우","실시"],["4","정당한 사유 없이 지정받은 날부터 1년 이내에 부동산거래정보망을 설치·운영하지 않은 경우","실시"],["5","개인인 거래정보사업자의 사망 또는 법인인 거래정보사업자의 해산 그 밖의 사유로 계속적인 운영이 불가능한 경우","청문 없음"]]}],"함정":"ㄴ의 기한은 1년이다. 31회 기출은 이 기한을 6개월로 바꿔 틀린 보기로 냈다. 취소 사유 다섯 가지 중 네 가지는 청문을 거친다."},"33회-2차-012":{"한줄":"확인·설명서 교부일자는 거래계약서 기재사항이므로 ②가 옳다.","근거":[{"법령":"공인중개사법 시행령","조문":"영 제22조제1항제8호","원문":"8. 중개대상물확인ㆍ설명서 교부일자"},{"법령":"공인중개사법 시행령","조문":"영 제22조제3항","원문":"국토교통부장관은 개업공인중개사가 작성하는 거래계약서의 표준이 되는 서식을 정하여 그 사용을 권장할 수 있다."},{"법령":"공인중개사법","조문":"법 제35조제1항제1호","원문":"1. 부정한 방법으로 공인중개사의 자격을 취득한 경우"},{"법령":"공인중개사법","조문":"법 제38조제2항제7호","원문":"7. 제26조제3항의 규정을 위반하여 거래계약서에 거래금액 등 거래내용을 거짓으로 기재하거나 서로 다른 둘 이상의 거래계약서를 작성한 경우"},{"법령":"공인중개사법","조문":"법 제25조제4항","원문":"해당 중개행위를 한 소속공인중개사가 있는 경우에는 소속공인중개사가 함께 서명 및 날인하여야 한다."},{"법령":"공인중개사법","조문":"법 제26조제1항","원문":"다만, 거래계약서가 공인전자문서센터에 보관된 경우에는 그러하지 아니하다."}],"선지":[{"번호":1,"판정":"틀림","설명":"표준서식은 사용을 권장하는 것이고(영 제22조제3항), 자격취소는 법 제35조제1항의 사유에 한해 시·도지사가 한다."},{"번호":2,"판정":"옳음","설명":"확인·설명서 교부일자는 거래계약서 기재사항이다(영 제22조제1항제8호)."},{"번호":3,"판정":"틀림","설명":"서로 다른 둘 이상의 거래계약서 작성은 등록관청이 개설등록을 취소할 수 있는 사유이다(법 제38조제2항제7호). 시·도지사의 업무정지 사유가 아니다."},{"번호":4,"판정":"틀림","설명":"소속공인중개사가 함께 서명 및 날인하는 것이지 개업공인중개사의 서명 및 날인의무가 없어지는 것이 아니다(법 제25조제4항)."},{"번호":5,"판정":"틀림","설명":"공인전자문서센터에 보관된 경우에는 보존의무가 없다(법 제26조제1항 단서)."}],"개념":[{"종류":"표","제목":"거래계약서 기재사항(영 제22조제1항)","머리":["호","기재사항"],"행":[["1","거래당사자의 인적 사항"],["2","물건의 표시"],["3","계약일"],["4","거래금액·계약금액 및 그 지급일자 등 지급에 관한 사항"],["5","물건의 인도일시"],["6","권리이전의 내용"],["7","계약의 조건이나 기한이 있는 경우에는 그 조건 또는 기한"],["8","중개대상물확인·설명서 교부일자"],["9","그 밖의 약정내용"]]},{"종류":"표","제목":"거래계약서 관련 위반과 제재","머리":["위반 행위","개업공인중개사","소속공인중개사"],"행":[["거래금액 등을 거짓으로 기재하거나 서로 다른 둘 이상의 거래계약서 작성","개설등록 취소 가능(법 제38조제2항제7호)","자격정지(법 제36조제1항제6호)"],["거래계약서를 작성·교부하지 않거나 보존하지 않음","업무정지(법 제39조제1항제8호)","해당 규정 없음"],["거래계약서에 서명 및 날인을 하지 않음","업무정지(법 제39조제1항제9호)","자격정지(법 제36조제1항제5호)"]]}],"함정":"③은 제재 종류와 처분권자를 모두 바꿨다. 업무정지는 등록관청이 하고 사유도 다르다. 이중 계약서는 등록관청의 임의적 취소 사유이고 소속공인중개사에게는 시·도지사가 자격정지를 할 수 있다."},"33회-2차-033":{"한줄":"임대차 중개에서 취득 시 조세(ㄱ)는 제외하고 개별공시지가·건물(주택)공시가격(ㄴ)은 생략할 수 있으나, 최우선변제금(ㄷ)과 건축물의 방향(ㄹ)은 생략할 수 없다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"별지 제20호서식 작성방법 9","원문":"거래예정금액 등의 \"거래예정금액\"은 중개가 완성되기 전 거래예정금액을, \"개별공시지가(㎡당)\" 및 \"건물(주택)공시가격\"은 중개가 완성되기 전 공시된 공시지가 또는 공시가격을 적습니다[임대차의 경우에는 \"개별공시지가(㎡당)\" 및 \"건물(주택)공시가격\"을 생략할 수 있습니다]."},{"법령":"공인중개사법 시행규칙","조문":"별지 제20호서식 작성방법 10","원문":"취득 시 부담할 조세의 종류 및 세율은 중개가 완성되기 전 「지방세법」의 내용을 확인하여 적습니다(임대차의 경우에는 제외합니다)."},{"법령":"공인중개사법 시행규칙","조문":"별지 제20호서식 작성방법 6","원문":"다. 최우선변제금은 「주택임대차보호법 시행령」 제10조(보증금 중 일정액의 범위 등) 및 제11조(우선변제를 받을 임차인의 범위)를 확인하여 각각 적되"},{"법령":"공인중개사법 시행규칙","조문":"별지 제20호서식 작성방법 3","원문":"건축물의 방향은 주택의 경우 거실이나 안방 등 주실(主室)의 방향을"}],"선지":[{"번호":1,"판정":"옳음","설명":"ㄱ(제외)과 ㄴ(생략 가능)이 임대차에서 빼도 되는 항목이므로 이 조합이 맞다."},{"번호":2,"판정":"틀림","설명":"ㄷ 최우선변제금은 임대차 확인사항으로 적어야 한다."},{"번호":3,"판정":"틀림","설명":"ㄷ, ㄹ 모두 생략할 수 없다."},{"번호":4,"판정":"틀림","설명":"ㄹ 건축물의 방향은 대상물건의 표시 항목이라 생략할 수 없다."},{"번호":5,"판정":"틀림","설명":"ㄷ, ㄹ은 생략할 수 없다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"임대차의 경우 취득 시 부담할 조세의 종류 및 세율은 제외한다(작성방법 10)."},{"기호":"ㄴ","판정":"옳음","설명":"임대차의 경우 개별공시지가(㎡당)와 건물(주택)공시가격은 생략할 수 있다(작성방법 9)."},{"기호":"ㄷ","판정":"틀림","설명":"최우선변제금은 ④ 임대차 확인사항으로 적는 항목이라 생략할 수 없다(작성방법 6다)."},{"기호":"ㄹ","판정":"틀림","설명":"건축물의 방향은 ① 대상물건의 표시에 적는 항목이라 생략할 수 없다(작성방법 3)."}],"개념":[{"종류":"표","제목":"주거용 확인·설명서[Ⅰ] 임대차 중개 시 작성방법","머리":["항목","임대차의 경우","근거"],"행":[["토지이용계획·공법상 이용제한 및 거래규제 중 그 밖의 이용제한 및 거래규제사항","생략 가능","작성방법 5"],["개별공시지가(㎡당), 건물(주택)공시가격","생략 가능","작성방법 9"],["취득 시 부담할 조세의 종류 및 세율","제외","작성방법 10"],["④ 임대차 확인사항(확정일자 부여현황, 체납정보, 전입세대 확인서, 최우선변제금, 민간임대 등록여부)","적어야 하는 항목","작성방법 6"],["① 대상물건의 표시(건축물의 방향 포함)","생략 불가","작성방법 3"]]},{"종류":"표","제목":"확인·설명서 서식별 항목([Ⅰ]~[Ⅳ])","머리":["항목","[Ⅰ] 주거용","[Ⅱ] 비주거용","[Ⅲ] 토지","[Ⅳ] 입목·광업재단·공장재단"],"행":[["권리관계(등기부 기재사항)","있음","있음","있음","있음"],["거래예정금액 등","있음","있음","있음","있음"],["취득 시 부담할 조세의 종류 및 세율","있음","있음","있음","있음"],["실제 권리관계 또는 공시되지 않은 물건의 권리 사항(세부)","있음","있음","있음","있음"],["비선호시설(1km이내)","있음","없음","있음","없음"],["환경조건(일조량·소음·진동)","있음","없음","없음","없음"],["입지조건","있음","있음","있음","없음"]]}],"함정":"임대차를 중개해도 대상물건의 표시, 권리관계, 임대차 확인사항은 그대로 적는다. 빼도 되는 것은 취득 시 조세, 개별공시지가·건물(주택)공시가격, 그 밖의 이용제한 및 거래규제사항이다.","개정":"선지의 보기 ㄷ을 「다가구주택 확인서류 제출여부」에서 「최우선변제금」으로 바꿨다. 현행 별지 제20호서식(개정 2026.8.11)에 앞의 항목이 없고 최우선변제금은 ④ 임대차 확인사항에 있다. 최우선변제금은 임대차에서 생략할 수 없는 항목이라 ㄷ의 판정은 그대로 틀림이고 정답은 같다."},"33회-2차-023":{"한줄":"정보체계 관리 정보에는 부동산거래 관련 정보, 검인 관련 정보, 토지거래계약 허가 관련 정보가 들어 있고 중개사무소 개설등록 정보는 없다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제25조","원문":"제25조(부동산정보체계의 구축ㆍ운영) 국토교통부장관은 효율적인 정보의 관리 및 국민편의 증진을 위하여 대통령령으로 정하는 바에 따라 부동산거래 및 주택 임대차의 계약ㆍ신고ㆍ허가ㆍ관리 등의 업무와 관련된 정보체계를 구축ㆍ운영할 수 있다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제19조제1항","원문":"① 국토교통부장관은 법 제25조에 따라 효율적인 정보의 관리 및 국민편의 증진을 위하여 다음 각 호의 정보를 관리할 수 있는 정보체계를 구축ㆍ운영할 수 있다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제19조제1항제4호","원문":"4. 토지거래계약의 허가 관련 정보"},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제19조제1항제5호","원문":"5. 「부동산등기 특별조치법」 제3조에 따른 검인 관련 정보"},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제19조제1항제6호","원문":"6. 부동산 거래계약 등 부동산거래 관련 정보"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄷ(중개사무소 개설등록 정보)은 영 제19조제1항의 관리 대상 정보가 아니고, ㄴ·ㄹ이 빠져 있다."},{"번호":2,"판정":"틀림","설명":"ㄱ이 빠졌다(영 제19조제1항제6호)."},{"번호":3,"판정":"옳음","설명":"ㄱ(제6호), ㄴ(제5호), ㄹ(제4호)이 명시되어 있다."},{"번호":4,"판정":"틀림","설명":"ㄷ이 들어 있다. 개설등록 정보는 영 제19조제1항에 없다."},{"번호":5,"판정":"틀림","설명":"ㄷ이 들어 있다. 개설등록 정보는 영 제19조제1항에 없다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"부동산 거래계약 등 부동산거래 관련 정보다(영 제19조제1항제6호)."},{"기호":"ㄴ","판정":"옳음","설명":"부동산등기 특별조치법 제3조에 따른 검인 관련 정보다(영 제19조제1항제5호)."},{"기호":"ㄷ","판정":"틀림","설명":"중개사무소의 개설등록에 관한 정보는 영 제19조제1항에 열거되어 있지 않다."},{"기호":"ㄹ","판정":"옳음","설명":"토지거래계약의 허가 관련 정보다(영 제19조제1항제4호)."}],"개념":[{"종류":"표","제목":"부동산정보체계 관리 정보(영 제19조제1항)","머리":["호","정보"],"행":[["1","법 제3조에 따른 부동산거래 신고 정보"],["2","검증체계 관련 정보"],["2의2","법 제6조의2에 따른 주택 임대차 계약 신고 정보"],["2의3","법 제6조의3에 따른 주택 임대차 계약의 변경 및 해제 신고 정보"],["3","법 제8조에 따른 외국인등의 부동산 취득·보유 신고 자료 및 관련 정보"],["4","토지거래계약의 허가 관련 정보"],["5","부동산등기 특별조치법 제3조에 따른 검인 관련 정보"],["6","부동산 거래계약 등 부동산거래 관련 정보"]]}],"함정":"중개사무소 개설등록은 공인중개사법에 따른 업무정보라 부동산정보체계 목록에 없다. 검인 관련 정보(제5호)는 목록에 있다."},"33회-2차-039":{"한줄":"공급계약(분양)은 물건별 거래가격과 총 실제거래가격에 부가가치세를 포함한 금액을 적는다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"별지 제1호서식 유의사항 5","원문":"5. 거래대상의 종류가 공급계약(분양) 또는 전매계약(분양권, 입주권)인 경우 ⑧ 물건별 거래가격 및 ⑨ 총 실제거래가격에 부가가치세를 포함한 금액을 적고, 그 외의 거래대상의 경우 부가가치세를 제외한 금액을 적습니다."},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"별지 제1호서식 작성방법 1","원문":"1. ①ㆍ② 거래당사자가 다수인 경우 매도인 또는 매수인의 주소란에 ⑥의 거래대상별 거래지분을 기준으로 각자의 거래 지분 비율(매도인과 매수인의 거래지분 비율은 일치해야 합니다)을 표시하고, 거래당사자가 외국인인 경우 거래당사자의 국적을 반드시 적어야 하며"},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"별지 제1호서식 작성방법 6","원문":"6. ⑦ “계약대상 면적”란에는 실제 거래면적을 계산하여 적되, 건축물 면적은 집합건축물의 경우 전용면적을 적고, 그 밖의 건축물의 경우 연면적을 적습니다."},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"별지 제1호서식 작성방법 9","원문":"9. ⑩ “종전 부동산”란은 입주권 매매의 경우에만 작성하고, 거래금액란에는 추가 지급액 등(프리미엄 등 분양가격을 초과 또는 미달하는 금액) 및 권리가격, 합계 금액, 계약금, 중도금, 잔금을 적습니다."},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"별지 제1호서식 작성방법 10","원문":"10. ⑪ “계약의 조건 및 참고사항”란은 부동산 거래계약 내용에 계약조건이나 기한을 붙인 경우, 거래와 관련한 참고내용이 있을 경우에 적습니다."}],"선지":[{"번호":1,"판정":"옳음","설명":"외국인의 국적은 반드시 적는다(서식 작성방법 1)."},{"번호":2,"판정":"옳음","설명":"건축물 면적은 집합건축물이면 전용면적이다(서식 작성방법 6)."},{"번호":3,"판정":"옳음","설명":"종전 부동산란은 입주권 매매에만 작성한다(서식 작성방법 9)."},{"번호":4,"판정":"옳음","설명":"조건·기한을 붙인 경우와 참고내용이 있는 경우에 적는다(서식 작성방법 10)."},{"번호":5,"판정":"틀림","설명":"공급계약(분양)은 부가가치세를 포함한 금액을 적는다. 제외하는 쪽은 분양·전매가 아닌 거래다(서식 유의사항 5)."}],"개념":[{"종류":"비교","제목":"부가가치세 기재 기준(서식 유의사항 5)","왼쪽":{"이름":"부가가치세 포함","항목":["공급계약(분양)","전매계약(분양권, 입주권)","물건별 거래가격·총 실제거래가격에 각 비용(분양가격, 선택비용, 추가 지급액)의 부가가치세를 포함해 적는다"]},"오른쪽":{"이름":"부가가치세 제외","항목":["위 두 경우가 아닌 거래대상(일반 매매 등)","물건별 거래가격·총 실제거래가격에 부가가치세를 제외한 금액을 적는다"]}},{"종류":"표","제목":"부동산거래계약 신고서 작성방법 요점(규칙 별지 제1호서식)","머리":["항목","작성 내용"],"행":[["거래당사자","다수인이면 거래지분 비율 표시(매도인·매수인 일치). 외국인은 국적 필수, 매수인이 외국인이면 체류자격과 국내 주소·183일 이상 거소 여부"],["법인신고서등","법인 주택 거래계약 신고서, 주택취득자금 조달 및 입주계획서, 토지취득자금 조달 및 토지이용계획서를 함께 또는 별도로 제출하는지 표시. 해당 없으면 해당 없음"],["거래대상 종류","매매는 토지·건축물·토지 및 건축물. 공급계약은 시행사 또는 건축주 등이 최초로 분양하는 계약. 전매는 분양권·입주권"],["임대주택 분양전환","임대주택사업자(법인으로 한정)가 임대기한 완료로 분양전환하는 주택"],["계약대상 면적","실제 거래면적. 건축물은 집합건축물이면 전용면적, 그 밖의 건축물은 연면적"],["물건별 거래가격","부동산별 거래가격. 분양·전매는 분양가격, 발코니 확장 등 선택비용, 추가 지급액을 각각 적고 부가가치세 포함"],["총 실제 거래가격","전체 거래가격(합계)과 계약금·중도금·잔금 및 지급일"],["종전 부동산","입주권 매매에만 작성"],["계약의 조건 및 참고사항","조건·기한을 붙인 경우, 거래와 관련한 참고내용이 있는 경우"],["기재사항이 복잡한 경우","다른 용지에 작성하여 간인 처리 후 첨부"]]}],"함정":"분양·전매는 포함, 그 밖의 거래는 제외라는 구분이 선지에서 반대로 서술된다. 같은 기준이 27회 40번 ㄱ, 28회 39번 ④에도 나왔다."},"33회-2차-027":{"한줄":"국제연합의 전문기구, 외국 국적 개인, 외국 법령에 따른 법인, 비정부간 국제기구, 외국 정부는 모두 외국인등이다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제2조제4호가목","원문":"가. 대한민국의 국적을 보유하고 있지 아니한 개인"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제2조제4호나목","원문":"나. 외국의 법령에 따라 설립된 법인 또는 단체"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제2조제4호바목·사목","원문":"바. 외국 정부 … 사. 대통령령으로 정하는 국제기구"},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제2조","원문":"1. 국제연합과 그 산하기구ㆍ전문기구 … 4. 비정부간 국제기구"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄷ(외국 법령에 따른 법인), ㄹ, ㅁ도 외국인등인데 빠져 있다."},{"번호":2,"판정":"틀림","설명":"ㄱ(국제연합의 전문기구), ㄹ도 외국인등인데 빠져 있다."},{"번호":3,"판정":"틀림","설명":"ㄹ(비정부간 국제기구)도 외국인등인데 빠져 있다."},{"번호":4,"판정":"틀림","설명":"ㄴ(외국 국적 개인)도 외국인등인데 빠져 있다."},{"번호":5,"판정":"옳음","설명":"다섯 보기 모두 외국인등이다(법 제2조제4호, 영 제2조)."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"국제연합의 전문기구는 영 제2조제1호의 국제기구다."},{"기호":"ㄴ","판정":"옳음","설명":"대한민국 국적을 보유하고 있지 아니한 개인이다(법 제2조제4호가목)."},{"기호":"ㄷ","판정":"옳음","설명":"외국의 법령에 따라 설립된 법인이다(법 제2조제4호나목)."},{"기호":"ㄹ","판정":"옳음","설명":"비정부간 국제기구는 영 제2조제4호에 있다."},{"기호":"ㅁ","판정":"옳음","설명":"외국 정부다(법 제2조제4호바목)."}],"개념":[{"종류":"표","제목":"외국인등의 범위(법 제2조제4호, 영 제2조)","머리":["구분","해당 개인·법인·단체"],"행":[["가목","대한민국 국적을 보유하고 있지 아니한 개인"],["나목","외국의 법령에 따라 설립된 법인 또는 단체"],["다목","사원 또는 구성원의 2분의 1 이상이 가목에 해당하는 법인 또는 단체"],["라목","업무를 집행하는 사원이나 이사 등 임원의 2분의 1 이상이 가목에 해당하는 법인 또는 단체"],["마목","가목의 사람이나 나목의 법인·단체가 자본금의 2분의 1 이상 또는 의결권의 2분의 1 이상을 가진 법인 또는 단체"],["바목","외국 정부"],["사목","대통령령으로 정하는 국제기구: 국제연합과 그 산하기구·전문기구, 정부간 기구, 준정부간 기구, 비정부간 국제기구"]]}],"함정":"비정부간 국제기구까지 외국인등에 포함된다는 점을 빠뜨리기 쉽다. 국제기구는 영 제2조의 네 유형(국제연합과 산하기구·전문기구, 정부간 기구, 준정부간 기구, 비정부간 국제기구)이다."},"33회-2차-022":{"한줄":"도시지역 허가 면제 면적은 주거지역 60, 상업지역 150, 공업지역 150, 녹지지역 200제곱미터다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제9조제1항제1호","원문":"1. 「국토의 계획 및 이용에 관한 법률」 제36조제1항제1호에 따른 도시지역(이하 \"도시지역\"이라 한다): 다음 각 목의 세부 용도지역별 구분에 따른 면적"},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제9조제1항제1호가목","원문":"가. 주거지역: 60제곱미터"},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제9조제1항제1호나목","원문":"나. 상업지역: 150제곱미터"},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제9조제1항제1호다목","원문":"다. 공업지역: 150제곱미터"},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제9조제1항제1호라목","원문":"라. 녹지지역: 200제곱미터"}],"선지":[{"번호":1,"판정":"-","설명":"상업지역 150, 공업지역 150이다. 100이 아니다(영 제9조제1항제1호나목·다목)."},{"번호":2,"판정":"-","설명":"주거 60, 상업 150, 공업 150, 녹지 200이다(영 제9조제1항제1호)."},{"번호":3,"판정":"-","설명":"주거지역은 60이다. 180이 아니다(영 제9조제1항제1호가목)."},{"번호":4,"판정":"-","설명":"주거지역은 60이다. 180이 아니다(영 제9조제1항제1호가목)."},{"번호":5,"판정":"-","설명":"도시지역에서는 영 제9조제1항제1호가 정한 값(60, 150, 150, 200)만 쓴다. 주거 180, 상업 250 등은 맞지 않고, 500·1천은 도시지역 밖 농지·임야 기준이다(영 제9조제1항제2호)."}],"개념":[{"종류":"표","제목":"허가 면제 면적(영 제9조제1항)","머리":["지역","기준 면적"],"행":[["도시지역 주거지역","60제곱미터"],["도시지역 상업지역","150제곱미터"],["도시지역 공업지역","150제곱미터"],["도시지역 녹지지역","200제곱미터"],["도시지역 중 용도지역 지정이 없는 구역","60제곱미터"],["도시지역 외의 지역","250제곱미터(농지 500제곱미터, 임야 1천제곱미터)"]]}],"함정":"도시지역 밖의 기준(250, 농지 500, 임야 1천)과 도시지역 안의 기준을 섞어 쓴 선지가 있다. 도시지역은 용도지역별 네 값을 외운다.","개정":"허가 면제 면적은 영 제9조제1항에서 정한다(<개정 2022.2.28, 2023.10.4>). 국토교통부장관 또는 시·도지사가 허가구역을 지정하면서 기준면적의 10퍼센트 이상 300퍼센트 이하 범위에서 따로 정해 공고하면 그에 따른다."},"33회-2차-025":{"한줄":"이행명령의 이행기간은 3개월 이내이고 방치한 경우의 이행강제금은 토지 취득가액의 100분의 10이다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제16조제1항","원문":"① 법 제18조제1항 본문에 따른 이행명령은 문서로 하여야 하며, 이행기간은 3개월 이내로 정하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제16조제3항제1호","원문":"1. 토지거래계약허가를 받아 토지를 취득한 자가 당초의 목적대로 이용하지 아니하고 방치한 경우: 토지 취득가액의 100분의 10에 상당하는 금액"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제18조제2항","원문":"② 시장ㆍ군수 또는 구청장은 제1항에 따른 이행명령이 정하여진 기간에 이행되지 아니한 경우에는 토지 취득가액의 100분의 10의 범위에서 대통령령으로 정하는 금액의 이행강제금을 부과한다."}],"선지":[{"번호":1,"판정":"-","설명":"이행기간은 3개월 이내, 방치의 이행강제금은 100분의 10이다. 100분의 7은 임대하거나 다른 경우의 비율이다(영 제16조제3항)."},{"번호":2,"판정":"-","설명":"이행기간 3개월 이내, 이행강제금 100분의 10이다(영 제16조제1항, 제3항제1호)."},{"번호":3,"판정":"-","설명":"이행기간은 3개월 이내다. 6개월이 아니다(영 제16조제1항). 100분의 7도 맞지 않는다."},{"번호":4,"판정":"-","설명":"이행기간은 3개월 이내다. 6개월이 아니다(영 제16조제1항)."},{"번호":5,"판정":"-","설명":"이행기간은 3개월 이내이고 이행강제금은 100분의 10이다. 12개월, 100분의 15가 아니다. 법상 상한은 100분의 10이다(법 제18조제2항)."}],"개념":[{"종류":"표","제목":"이행강제금 금액(법 제18조제2항, 영 제16조제3항)","머리":["위반 유형","금액(토지 취득가액 기준)"],"행":[["당초 목적대로 이용하지 않고 방치","100분의 10"],["직접 이용하지 않고 임대","100분의 7"],["허가관청의 승인 없이 이용목적 변경","100분의 5"],["위 세 가지에 해당하지 않는 경우","100분의 7"]]},{"종류":"흐름","제목":"이행명령과 이행강제금(법 제18조, 영 제16조)","단계":[{"이름":"이행명령","설명":"문서로 하고 이행기간은 3개월 이내로 정한다(영 제16조제1항)"},{"이름":"계고","설명":"이행기간 내 이행하지 않으면 이행강제금을 부과·징수한다는 뜻을 미리 문서로 계고(영 제16조제5항)"},{"이름":"부과","설명":"이행명령이 이행되지 않으면 이행강제금 부과. 최초 이행명령이 있었던 날을 기준으로 1년에 한 번씩 반복 부과(법 제18조제3항)"},{"이름":"이의제기","설명":"부과처분을 고지받은 날부터 30일 이내 시장·군수·구청장에게(영 제16조제7항, 법 제18조제6항)"},{"이름":"이행 시","설명":"새로운 이행강제금 부과는 즉시 중지, 이미 부과된 이행강제금은 징수(법 제18조제5항). 의무기간이 지나면 부과 불가(제4항)"}]}],"함정":"방치의 이행강제금을 임대의 비율(100분의 7)로 쓰면 ①, 이행기간을 6개월로 늘리면 ③·④가 된다."},"33회-2차-028":{"한줄":"네 보기 중 권리·의무가 토지 소유권 변동과 동시에 승계인에게 이전한다는 보기만 옳다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제20조제1항","원문":"① 농지에 대하여 제11조에 따라 토지거래계약 허가를 받은 경우에는 「농지법」 제8조에 따른 농지취득자격증명을 받은 것으로 본다. 이 경우 시장ㆍ군수 또는 구청장은 「농업ㆍ농촌 및 식품산업 기본법」"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제14조제2항","원문":"② 다음 각 호의 경우에는 제11조를 적용하지 아니한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제11조제3항제12호","원문":"12. 국세 및 지방세의 체납처분 또는 강제집행을 하는 경우"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제18조제4항","원문":"④ 시장ㆍ군수 또는 구청장은 제17조제1항에 따른 이용 의무기간이 지난 후에는 이행강제금을 부과할 수 없다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제22조제1항","원문":"① 제10조부터 제20조까지에 따라 토지의 소유권자, 지상권자 등에게 발생되거나 부과된 권리ㆍ의무는 그 토지 또는 건축물에 관한 소유권이나 그 밖의 권리의 변동과 동시에 그 승계인에게 이전한다."}],"선지":[{"번호":1,"판정":"-","설명":"넷째 보기가 옳으므로 0개가 아니다(법 제22조제1항)."},{"번호":2,"판정":"-","설명":"옳은 보기는 넷째 하나뿐이다(법 제22조제1항)."},{"번호":3,"판정":"-","설명":"첫째~셋째는 틀리므로 2개가 될 수 없다."},{"번호":4,"판정":"-","설명":"첫째~셋째는 틀리므로 3개가 될 수 없다."},{"번호":5,"판정":"-","설명":"첫째~셋째는 틀리므로 4개가 될 수 없다."}],"보기판정":[{"기호":"첫째","판정":"틀림","설명":"토지거래계약 허가를 받은 농지는 농지취득자격증명을 받은 것으로 본다. 농지전용허가가 아니다(법 제20조제1항)."},{"기호":"둘째","판정":"틀림","설명":"국세 체납처분에는 허가 규정을 적용하지 않는다(법 제14조제2항제3호, 영 제11조제3항제12호)."},{"기호":"셋째","판정":"틀림","설명":"이용 의무기간이 지난 후에는 이행강제금을 부과할 수 없다(법 제18조제4항)."},{"기호":"넷째","판정":"옳음","설명":"토지 이용에 관한 의무는 소유권 변동과 동시에 승계인에게 이전한다(법 제22조제1항)."}],"개념":[{"종류":"표","제목":"토지거래계약 허가(법 제11조~제14조)","머리":["항목","내용"],"행":[["허가 대상","허가구역 안 토지의 소유권·지상권(취득을 목적으로 하는 권리 포함)을 대가를 받고 이전·설정하는 계약(예약 포함)"],["허가 절차","당사자 공동 신청. 허가관청은 신청서를 받은 날부터 15일 이내 허가·변경허가·불허가 처분(영 제8조제3항)"],["허가 없이 체결","계약은 효력이 발생하지 않는다(법 제11조제6항)"],["이의신청","처분을 받은 날부터 1개월 이내 시장·군수·구청장에게(법 제13조제1항)"],["매수청구","불허가처분을 통지받은 날부터 1개월 이내(법 제16조제1항)"],["적용 제외","수용, 민사집행법상 경매, 영 제11조제3항의 계약"]]},{"종류":"표","제목":"허가 규정 적용 제외와 승계","머리":["항목","내용","근거"],"행":[["허가 규정 적용 제외","공익사업 수용, 민사집행법상 경매, 영 제11조제3항의 계약(국세·지방세의 체납처분 또는 강제집행, 외국인등이 토지취득 허가를 받은 경우 등)","법 제14조제2항, 영 제11조제3항"],["농지","토지거래계약 허가를 받으면 농지법 제8조에 따른 농지취득자격증명을 받은 것으로 본다","법 제20조제1항"],["이행강제금","이용 의무기간이 지난 후에는 부과할 수 없다","법 제18조제4항"],["승계","제10조~제20조에 따라 토지 소유권자 등에게 발생·부과된 권리·의무는 소유권 변동과 동시에 승계인에게 이전","법 제22조제1항"]]}],"함정":"농지는 농지전용허가가 아니라 농지취득자격증명이 의제된다. 국세 체납처분은 허가 규정 적용 제외 대상이다."},"33회-2차-040":{"한줄":"양도형 분묘기지권은 특별한 사정이 없으면 성립한 때부터 지료 지급의무가 있다.","근거":[{"판례":"대법원 2021. 4. 29. 선고 2017다228007 전원합의체 판결","요지":"분묘기지권이 성립한 유형별로 지료 지급의무가 다르다. 토지 소유자의 승낙으로 성립한 경우 성립 당시 지료에 관한 약정이 있으면 그 효력이 분묘 기지의 승계인에게도 미친다. 자기 소유 토지에 분묘를 설치한 사람이 이장 특약 없이 토지를 양도하여 분묘기지권을 취득한 경우 특별한 사정이 없으면 성립한 때부터 지료를 지급해야 한다. 시효로 취득한 분묘기지권자는 토지 소유자가 지료를 청구한 날부터 지료를 지급해야 한다."},{"판례":"대법원 판례(장사 등에 관한 법률 시행과 분묘기지권의 시효취득)","요지":"장사 등에 관한 법률 시행일(2001. 1. 13.) 이전에 설치된 분묘는 시효취득이 가능하다. 시행일 이후 토지 소유자의 승낙 없이 설치한 분묘는 시효취득을 주장할 수 없다."},{"판례":"대법원 판례(분묘기지권의 성립과 범위)","요지":"분묘기지권은 봉분 등 외부에서 분묘의 존재를 인식할 수 있는 형태를 갖추고 시신이 안장되어 있어야 성립한다. 암장이나 장래의 묘소는 성립하지 않는다. 효력은 분묘 기지와 수호·제사에 필요한 범위의 주위 공지에 미치고, 기존 분묘 외에 새 분묘를 신설할 권능은 포함하지 않는다. 유골이 존재해 원상회복이 가능한 일시적 멸실이면 소멸하지 않는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"분묘기지권의 존속기간에는 지상권 존속기간 규정을 유추적용하지 않는다. 권리자가 분묘를 수호·봉사하며 분묘가 존속하는 동안 존속한다(판례). 30년이 아니다."},{"번호":2,"판정":"틀림","설명":"시행 전에 설치된 분묘는 시행 후에도 시효취득이 인정된다(판례). 제한되는 것은 시행일 이후 승낙 없이 설치한 분묘이다."},{"번호":3,"판정":"옳음","설명":"이장 특약 없이 토지를 양도해 분묘기지권을 취득한 경우 성립한 때부터 지료를 지급한다(대법원 2021. 4. 29. 선고 2017다228007 전원합의체 판결)."},{"번호":4,"판정":"틀림","설명":"시효취득형은 토지 소유자가 지료를 청구한 날부터 지료를 지급해야 한다(대법원 2021. 4. 29. 선고 2017다228007 전원합의체 판결)."},{"번호":5,"판정":"틀림","설명":"일시적 멸실이고 원상회복이 가능하면 분묘기지권은 소멸하지 않는다(판례)."}],"개념":[{"종류":"표","제목":"분묘기지권의 성립 유형과 지료(판례)","머리":["유형","성립","지료 지급의무"],"행":[["승낙형","토지 소유자의 승낙을 받아 분묘 설치","성립 당시 소유자와 분묘 수호·관리자가 지료에 관해 약정했다면 그 약정의 효력은 분묘 기지의 승계인에게도 미친다"],["양도형","자기 소유 토지에 분묘를 설치한 사람이 이장 특약 없이 토지를 양도","특별한 사정이 없으면 분묘기지권이 성립한 때부터 지료 지급의무가 있다"],["시효취득형","타인 토지에 승낙 없이 분묘를 설치하고 20년간 평온·공연하게 점유","토지 소유자가 지료를 청구한 날부터 지료를 지급할 의무가 있다"],["시효취득 제한","장사 등에 관한 법률 시행일(2001. 1. 13.) 이후 승낙 없이 설치한 분묘는 시효취득을 주장할 수 없다. 시행 전에 설치한 분묘는 시효취득이 가능하다","-"]]},{"종류":"표","제목":"분묘기지권의 내용(판례)","머리":["항목","내용"],"행":[["성질","지상권 유사의 관습상 물권. 등기 없이 성립하고 제3자에게 대항한다. 등기사항증명서로 확인할 수 없다"],["성립 요건","봉분 등 외부에서 분묘의 존재를 인식할 수 있는 형태를 갖추고 시신이 안장되어 있어야 한다. 암장·평장으로 외형이 없거나 장래의 묘소(가묘)는 불성립"],["존속","특별한 사정이 없으면 권리자가 분묘를 수호·봉사하고 분묘가 존속하는 동안 존속"],["범위","분묘 기지 자체와 수호·제사에 필요한 범위의 주위 공지. 기존 분묘 외에 새 분묘를 신설할 권능은 포함되지 않는다"],["멸실","유골이 존재하여 원상회복이 가능한 일시적 멸실이면 소멸하지 않는다"],["포기","권리자가 포기의 의사표시를 하면 소멸. 점유까지 포기해야 소멸하는 것은 아니다"]]}],"함정":"30년은 장사 등에 관한 법률상 분묘 설치기간(법 제19조)의 숫자이고 분묘기지권의 존속기간이 아니다. 시효취득형은 청구한 날부터, 양도형은 성립한 때부터라는 차이가 ③과 ④의 쟁점이다."},"33회-2차-029":{"한줄":"배우자 명의 등기는 조세 포탈 등의 목적이 없으면 유효하고(ㄴ), 3자간 등기명의신탁의 신탁자는 매도인을 대위하여 수탁자 명의 등기의 말소를 청구할 수 있다(ㄷ).","근거":[{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제2조제1호 나목","원문":"나. 부동산의 위치와 면적을 특정하여 2인 이상이 구분소유하기로 하는 약정을 하고 그 구분소유자의 공유로 등기하는 경우"},{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제8조","원문":"다음 각 호의 어느 하나에 해당하는 경우로서 조세 포탈, 강제집행의 면탈(免脫) 또는 법령상 제한의 회피를 목적으로 하지 아니하는 경우에는 제4조부터 제7조까지 및 제12조제1항부터 제3항까지를 적용하지 아니한다. 1. 종중(宗中)이 보유한 부동산에 관한 물권을 종중(종중과 그 대표자를 같이 표시하여 등기한 경우를 포함한다) 외의 자의 명의로 등기한 경우 2. 배우자 명의로 부동산에 관한 물권을 등기한 경우 3. 종교단체의 명의로 그 산하 조직이 보유한 부동산에 관한 물권을 등기한 경우"},{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조제2항","원문":"명의신탁약정에 따른 등기로 이루어진 부동산에 관한 물권변동은 무효로 한다. 다만, 부동산에 관한 물권을 취득하기 위한 계약에서 명의수탁자가 어느 한쪽 당사자가 되고 상대방 당사자는 명의신탁약정이 있다는 사실을 알지 못한 경우에는 그러하지 아니하다."},{"판례":"대법원 판례(3자간 등기명의신탁에서 신탁자의 구제)","요지":"명의신탁자는 매도인을 대위하여 명의수탁자 명의 등기의 말소를 청구할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄱ은 틀린 보기이고 옳은 ㄴ, ㄷ이 빠졌다. 구분소유적 공유 등기는 명의신탁약정이 아니다."},{"번호":2,"판정":"틀림","설명":"ㄴ은 옳은 보기이나 옳은 ㄷ이 빠졌다."},{"번호":3,"판정":"틀림","설명":"ㄱ은 틀린 보기이고 옳은 ㄴ이 빠졌다."},{"번호":4,"판정":"옳음","설명":"배우자 명의 등기의 특례(ㄴ)와 신탁자의 대위 말소청구(ㄷ)가 옳으므로 이 조합이 맞다."},{"번호":5,"판정":"틀림","설명":"ㄱ은 틀린 보기다. 세 보기를 모두 고르면 맞지 않다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"위치와 면적을 특정하여 2인 이상이 구분소유하기로 약정하고 구분소유자의 공유로 등기하는 경우는 명의신탁약정에서 제외된다(제2조제1호 나목). 이 법 위반이 아니고 등기는 유효하다."},{"기호":"ㄴ","판정":"옳음","설명":"배우자 명의 등기는 조세 포탈, 강제집행의 면탈, 법령상 제한의 회피를 목적으로 하지 않으면 제4조부터 제7조까지를 적용하지 않으므로 유효하다(제8조제2호)."},{"기호":"ㄷ","판정":"옳음","설명":"3자간 등기명의신탁에서 수탁자 명의 등기는 무효이므로 매매계약의 당사자인 신탁자가 매도인을 대위하여 말소를 청구할 수 있다."}],"개념":[{"종류":"표","제목":"부동산실명법 적용 제외 유형","머리":["유형","근거","효과"],"행":[["담보를 위한 이전·가등기","제2조제1호 가목","명의신탁약정이 아님"],["구분소유적 공유 등기","제2조제1호 나목","명의신탁약정이 아님. 유효"],["신탁재산인 사실의 등기","제2조제1호 다목","명의신탁약정이 아님"],["종중 부동산을 종중 외 명의로 등기","제8조제1호","목적이 없으면 제4조~제7조 적용 제외"],["배우자 명의 등기","제8조제2호","목적이 없으면 제4조~제7조 적용 제외"],["종교단체 산하 조직 부동산을 종교단체 명의로 등기","제8조제3호","목적이 없으면 제4조~제7조 적용 제외"]]},{"종류":"비교","제목":"제8조 특례의 적용과 배제","왼쪽":{"이름":"특례가 적용되는 경우","항목":["종중·배우자·종교단체 해당","조세 포탈, 강제집행의 면탈, 법령상 제한의 회피가 목적이 아님","명의신탁약정과 등기가 유효","과징금·형사처벌 대상이 아님"]},"오른쪽":{"이름":"특례가 배제되는 경우","항목":["위 목적 중 하나라도 있음","제4조 적용: 약정 무효, 등기 무효","제5조~제7조 적용: 과징금, 이행강제금, 형사처벌","배우자 명의라도 마찬가지"]}}],"함정":"ㄱ은 구분소유적 공유를 명의신탁으로 보고 무효로 처리한 보기다. 위치와 면적을 특정해 구분소유하기로 하고 공유로 등기하면 처음부터 명의신탁약정이 아니다."},"33회-2차-031":{"한줄":"권리금 규정은 환산보증금을 초과하는 임대차에도 적용되고(ㄱ), 임대인의 동의를 받은 전차인은 임차인을 대위하여 갱신요구권을 행사할 수 있다(ㄷ). 갱신거절 사유가 되는 차임 연체는 2기가 아니라 3기다(ㄴ).","근거":[{"법령":"상가건물 임대차보호법","조문":"제2조제3항","원문":"제1항 단서에도 불구하고 제3조, 제10조제1항, 제2항, 제3항 본문, 제10조의2부터 제10조의9까지의 규정, 제11조의2 및 제19조는 제1항 단서에 따른 보증금액을 초과하는 임대차에 대하여도 적용한다."},{"법령":"상가건물 임대차보호법","조문":"제10조의3제1항","원문":"권리금이란 임대차 목적물인 상가건물에서 영업을 하는 자 또는 영업을 하려는 자가 영업시설ㆍ비품, 거래처, 신용, 영업상의 노하우, 상가건물의 위치에 따른 영업상의 이점 등 유형ㆍ무형의 재산적 가치의 양도 또는 이용대가로서 임대인, 임차인에게 보증금과 차임 이외에 지급하는 금전 등의 대가를 말한다."},{"법령":"상가건물 임대차보호법","조문":"제10조제1항제1호","원문":"1. 임차인이 3기의 차임액에 해당하는 금액에 이르도록 차임을 연체한 사실이 있는 경우"},{"법령":"상가건물 임대차보호법","조문":"제13조제2항","원문":"임대인의 동의를 받고 전대차계약을 체결한 전차인은 임차인의 계약갱신요구권 행사기간 이내에 임차인을 대위(代位)하여 임대인에게 계약갱신요구권을 행사할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄱ은 옳은 보기이나 옳은 ㄷ이 빠졌다."},{"번호":2,"판정":"틀림","설명":"ㄴ은 틀린 보기이고 옳은 ㄱ, ㄷ이 빠졌다. 갱신거절 사유가 되는 연체는 3기다."},{"번호":3,"판정":"옳음","설명":"권리금 규정의 적용(ㄱ)과 전차인의 갱신요구권 대위 행사(ㄷ)가 옳으므로 이 조합이 맞다."},{"번호":4,"판정":"틀림","설명":"ㄴ은 틀린 보기다. 2기가 아니라 3기의 차임액에 이르러야 한다."},{"번호":5,"판정":"틀림","설명":"ㄴ은 틀린 보기다. 세 보기를 모두 고르면 맞지 않다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"환산보증금을 초과하는 임대차에도 권리금에 관한 제10조의3부터 제10조의9가 적용된다(제2조제3항)."},{"기호":"ㄴ","판정":"틀림","설명":"갱신거절 사유는 3기의 차임액에 해당하는 금액에 이르도록 차임을 연체한 사실이 있는 경우다(제10조제1항제1호). 2기가 아니다."},{"기호":"ㄷ","판정":"옳음","설명":"임대인의 동의를 받고 전대차계약을 체결한 전차인은 임차인의 갱신요구권 행사기간 이내에 임차인을 대위하여 갱신요구권을 행사할 수 있다(제13조제2항)."}],"개념":[{"종류":"표","제목":"임대인의 갱신거절 사유(제10조제1항 각 호)","머리":["호","사유"],"행":[["1","임차인이 3기의 차임액에 해당하는 금액에 이르도록 차임을 연체한 사실이 있는 경우"],["2","임차인이 거짓이나 그 밖의 부정한 방법으로 임차한 경우"],["3","서로 합의하여 임대인이 임차인에게 상당한 보상을 제공한 경우"],["4","임차인이 임대인의 동의 없이 목적 건물의 전부 또는 일부를 전대한 경우"],["5","임차인이 임차한 건물의 전부 또는 일부를 고의나 중대한 과실로 파손한 경우"],["6","임차한 건물의 전부 또는 일부가 멸실되어 임대차의 목적을 달성하지 못할 경우"],["7","철거·재건축을 위하여 목적 건물의 점유를 회복할 필요가 있는 경우(가·나·다목)"],["8","그 밖에 임차인이 임차인으로서의 의무를 현저히 위반하거나 임대차를 계속하기 어려운 중대한 사유가 있는 경우"]]},{"종류":"표","제목":"권리금 회수기회 보호(제10조의4, 제10조의5)","머리":["구분","내용"],"행":[["권리금","영업시설·비품, 거래처, 신용, 노하우, 위치에 따른 이점 등의 양도 또는 이용대가로 보증금과 차임 이외에 지급하는 금전 등(제10조의3제1항)"],["보호 기간","임대차기간이 끝나기 6개월 전부터 임대차 종료 시까지(제10조의4제1항)"],["방해 금지 행위","신규임차인에게 권리금 요구·수수, 권리금 지급 방해, 현저히 고액의 차임·보증금 요구, 정당한 사유 없는 계약 거절"],["손해배상 한도","신규임차인이 지급하기로 한 권리금과 임대차 종료 당시 권리금 중 낮은 금액(제10조의4제3항)"],["소멸시효","임대차가 종료한 날부터 3년(제10조의4제4항)"],["적용 제외","대규모점포·준대규모점포의 일부(전통시장 제외), 국유재산·공유재산(제10조의5)"]]}],"함정":"ㄴ은 주택임대차의 거절 사유(2기)와 상가건물의 거절 사유(3기)를 바꿔 놓은 보기다. 주택은 2기, 상가는 3기다. ㄱ은 보증금이 아무리 커도 권리금 규정은 적용된다는 점을 모르면 놓친다."},"33회-2차-032":{"한줄":"소액보증금 최우선변제를 받으려면 임차인이 주택에 대한 경매신청의 등기 전에 대항요건을 갖추어야 하므로(제8조제1항) ③이 틀린 설명이다.","근거":[{"법령":"주택임대차보호법","조문":"제2조","원문":"이 법은 주거용 건물(이하 \"주택\"이라 한다)의 전부 또는 일부의 임대차에 관하여 적용한다. 그 임차주택(賃借住宅)의 일부가 주거 외의 목적으로 사용되는 경우에도 또한 같다."},{"법령":"주택임대차보호법","조문":"제6조의3제2항","원문":"임차인은 제1항에 따른 계약갱신요구권을 1회에 한하여 행사할 수 있다. 이 경우 갱신되는 임대차의 존속기간은 2년으로 본다."},{"법령":"주택임대차보호법","조문":"제8조제1항","원문":"임차인은 보증금 중 일정액을 다른 담보물권자(擔保物權者)보다 우선하여 변제받을 권리가 있다. 이 경우 임차인은 주택에 대한 경매신청의 등기 전에 제3조제1항의 요건을 갖추어야 한다."},{"법령":"주택임대차보호법","조문":"제3조제4항","원문":"임차주택의 양수인(讓受人)(그 밖에 임대할 권리를 승계한 자를 포함한다)은 임대인(賃貸人)의 지위를 승계한 것으로 본다."},{"법령":"주택임대차보호법","조문":"제3조의3제5항","원문":"임차인은 임차권등기명령의 집행에 따른 임차권등기를 마치면 제3조제1항ㆍ제2항 또는 제3항에 따른 대항력과 제3조의2제2항에 따른 우선변제권을 취득한다. 다만, 임차인이 임차권등기 이전에 이미 대항력이나 우선변제권을 취득한 경우에는 그 대항력이나 우선변제권은 그대로 유지되며, 임차권등기 이후에는 제3조제1항ㆍ제2항 또는 제3항의 대항요건을 상실하더라도 이미 취득한 대항력이나 우선변제권을 상실하지 아니한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"주거용 건물의 전부 또는 일부의 임대차에 적용되고, 임차주택의 일부가 주거 외의 목적으로 사용되는 경우에도 적용된다(제2조)."},{"번호":2,"판정":"옳음","설명":"계약갱신요구권의 행사로 갱신되는 임대차의 존속기간은 2년으로 본다(제6조의3제2항)."},{"번호":3,"판정":"틀림","설명":"최우선변제를 받으려면 경매신청의 등기 전에 제3조제1항의 대항요건(주택의 인도와 주민등록)을 갖추어야 한다(제8조제1항)."},{"번호":4,"판정":"옳음","설명":"대항력을 갖춘 임차인의 임차주택 양수인은 임대인의 지위를 승계한 것으로 본다(제3조제4항)."},{"번호":5,"판정":"옳음","설명":"임차권등기를 마친 임차인은 이후 대항요건을 상실하더라도 이미 취득한 대항력 또는 우선변제권을 상실하지 않는다(제3조의3제5항)."}],"개념":[{"종류":"표","제목":"소액임차인의 범위와 최우선변제액(시행령 제10조·제11조)","머리":["지역","보증금 범위(제11조)","우선변제액 한도(제10조제1항)"],"행":[["서울특별시","1억6천500만원 이하","5천500만원"],["과밀억제권역(서울 제외), 세종특별자치시, 용인시, 화성시, 김포시","1억4천500만원 이하","4천800만원"],["광역시(과밀억제권역·군지역 제외), 안산시, 광주시, 파주시, 이천시, 평택시","8천500만원 이하","2천800만원"],["그 밖의 지역","7천500만원 이하","2천500만원"]]},{"종류":"표","제목":"주택임대차와 상가건물 임대차의 갱신 비교","머리":["구분","주택(주택임대차보호법)","상가건물(상가건물 임대차보호법)"],"행":[["갱신요구 시기","임대차기간 끝나기 6개월 전부터 2개월 전까지(제6조제1항, 제6조의3제1항)","만료 6개월 전부터 1개월 전까지(제10조제1항)"],["행사 횟수·한도","1회에 한함(제6조의3제2항)","전체 임대차기간 10년 이내(제10조제2항)"],["연체로 인한 거절 사유","2기의 차임액(제6조의3제1항제1호)","3기의 차임액(제10조제1항제1호)"],["갱신 시 존속기간","2년(제6조의3제2항)","전 임대차와 동일한 조건(제10조제3항)"],["묵시적 갱신 후 해지","임차인이 언제든지 통지, 3개월 후 효력(제6조의2)","임차인이 언제든지 통고, 3개월 후 효력(제10조제5항)"]]}],"함정":"③은 소액임차인에게 대항요건 시점의 제한이 있다는 점을 가린 선지다. 확정일자는 필요 없으나 경매신청의 등기 전에 인도와 주민등록을 마쳐야 한다. ②의 존속기간 2년은 갱신요구권에 의한 갱신의 경우다."},"33회-2차-030":{"한줄":"유치권자는 경매로 목적물을 취득한 매수인에게 인도를 거절할 수 있을 뿐 그 피담보채권의 변제를 청구할 수는 없다는 것이 판례이므로 ③이 틀린 설명이다.","근거":[{"법령":"민사집행법","조문":"민사집행법 제91조제2항","원문":"매각부동산 위의 모든 저당권은 매각으로 소멸된다."},{"법령":"민사집행법","조문":"민사집행법 제91조제3항","원문":"지상권ㆍ지역권ㆍ전세권 및 등기된 임차권은 저당권ㆍ압류채권ㆍ가압류채권에 대항할 수 없는 경우에는 매각으로 소멸된다."},{"법령":"민사집행법","조문":"민사집행법 제91조제4항","원문":"제3항의 경우 외의 지상권ㆍ지역권ㆍ전세권 및 등기된 임차권은 매수인이 인수한다. 다만, 그중 전세권의 경우에는 전세권자가 제88조에 따라 배당요구를 하면 매각으로 소멸된다."},{"법령":"민사집행법","조문":"민사집행법 제91조제5항","원문":"매수인은 유치권자(留置權者)에게 그 유치권(留置權)으로 담보하는 채권을 변제할 책임이 있다."},{"법령":"민사집행법","조문":"민사집행법 제135조","원문":"매수인은 매각대금을 다 낸 때에 매각의 목적인 권리를 취득한다."},{"판례":"대법원 판례(유치권자와 경매 매수인)","요지":"유치권자는 경매절차의 매수인에게 대하여 피담보채권의 변제를 청구할 권리가 없고, 그 변제를 받을 때까지 목적물의 인도를 거절할 수 있을 뿐이다."}],"선지":[{"번호":1,"판정":"옳음","설명":"매각부동산 위의 모든 저당권은 후순위 저당권자가 경매를 신청해도 매각으로 소멸한다(제91조제2항)."},{"번호":2,"판정":"옳음","설명":"저당권·압류채권·가압류채권에 대항할 수 없는 전세권과 등기된 임차권은 매각으로 소멸한다(제91조제3항)."},{"번호":3,"판정":"틀림","설명":"유치권자는 매수인에게 인도를 거절할 수 있을 뿐 피담보채권의 변제를 청구할 수 없다(판례). 제91조제5항은 매수인이 유치권자에게 변제할 책임을 진다고 정하나 이는 인도 거절을 받아들이는 부담을 말한다."},{"번호":4,"판정":"옳음","설명":"최선순위 전세권은 원칙적으로 인수되나 전세권자가 배당요구를 하면 매각으로 소멸한다(제91조제4항 단서)."},{"번호":5,"판정":"옳음","설명":"매수인은 매각대금을 다 낸 때에 매각의 목적인 권리를 취득한다(제135조)."}],"개념":[{"종류":"표","제목":"경매 매각으로 인한 권리의 소멸과 인수(제91조)","머리":["권리","소멸 / 인수","비고"],"행":[["저당권","소멸","모든 저당권(제2항)"],["전세권·지상권·지역권·등기된 임차권 중 저당권·압류채권·가압류채권에 대항할 수 없는 것","소멸","제3항"],["최선순위 전세권 등 그 밖의 용익권","인수","전세권은 배당요구하면 소멸(제4항 단서)"],["유치권","인수","인도 거절의 부담을 매수인이 받음(제5항)"]]},{"종류":"비교","제목":"유치권자가 매수인에게 주장할 수 있는 것","왼쪽":{"이름":"인정되는 것","항목":["피담보채권을 변제받을 때까지 목적물의 인도를 거절","매수인에게 대항할 수 있는 유치권일 것"]},"오른쪽":{"이름":"인정되지 않는 것","항목":["매수인에게 피담보채권의 변제 청구","경매개시결정 기입등기 후에 취득한 유치권으로 한 대항"]}}],"함정":"③은 제91조제5항의 문언(변제할 책임)을 그대로 읽으면 옳은 문장처럼 보인다. 판례는 유치권자에게 매수인에 대한 변제청구권이 없고 인도를 거절할 수 있을 뿐이라고 본다."},"33회-2차-035":{"한줄":"광업재단은 매수신청대리의 대상물이므로(규칙 제3조제4호) ㄱ은 옳다. ㄴ은 등록을 취소하는 사람이 시·도지사가 아니라 지방법원장이어서 틀리고, ㄷ은 폐업신고로 취소된 경우 3년 제한이 없어 틀리다.","근거":[{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"규칙 제3조","원문":"이 규칙에 의한 매수신청대리의 대상물은 다음 각 호와 같다. 1. 토지 2. 건물 그 밖의 토지의 정착물 3. 「입목에 관한 법률」에 따른 입목 4. 「공장 및 광업재단 저당법」에 따른 공장재단, 광업재단 5. 삭제<2017.5.25> 제2장 매수신청대리인 등록"},{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"규칙 제21조제1항","원문":"지방법원장은 다음 각 호의 어느 하나에 해당하는 경우에는 매수신청대리인 등록을 취소하여야 한다. 2. 법 제21조 또는 이 규칙 제13조의2제1항의 규정에 따라 폐업신고를 한 경우 4. 법 제38조의 규정에 따라 중개사무소 개설등록이 취소된 경우"},{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"규칙 제6조제1호","원문":"1. 매수신청대리인 등록이 취소된 후 3년이 지나지 아니한 자. 단, 제21조제1항제2호에 의한 등록 취소는 제외한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"ㄱ만 옳은 보기다. 광업재단도 대상물이고(제3조제4호), ㄴ·ㄷ은 틀린 보기다."},{"번호":2,"판정":"틀림","설명":"ㄴ은 틀린 보기다. 매수신청대리인 등록을 취소하는 사람은 시·도지사가 아니라 지방법원장이다."},{"번호":3,"판정":"틀림","설명":"ㄷ은 틀린 보기이고 ㄱ만 옳다. 폐업신고로 인한 등록취소는 3년 결격기간에서 제외된다."},{"번호":4,"판정":"틀림","설명":"ㄴ, ㄷ 모두 틀린 보기다. 옳은 ㄱ이 빠졌다."},{"번호":5,"판정":"틀림","설명":"ㄴ, ㄷ이 틀린 보기이므로 세 보기를 모두 고르면 맞지 않다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"「공장 및 광업재단 저당법」에 따른 공장재단, 광업재단은 매수신청대리의 대상물이다(규칙 제3조제4호)."},{"기호":"ㄴ","판정":"틀림","설명":"중개사무소 개설등록이 취소되면 지방법원장이 매수신청대리인 등록을 취소한다(규칙 제21조제1항제4호). 시·도지사가 아니다."},{"기호":"ㄷ","판정":"틀림","설명":"폐업신고(규칙 제21조제1항제2호)에 따른 등록취소는 3년 결격 규정에서 제외되므로 3년이 지나지 않아도 다시 등록할 수 있다(규칙 제6조제1호 단서)."}],"개념":[{"종류":"표","제목":"매수신청대리의 대상물(규칙 제3조)","머리":["호","대상물"],"행":[["1","토지"],["2","건물 그 밖의 토지의 정착물"],["3","「입목에 관한 법률」에 따른 입목"],["4","「공장 및 광업재단 저당법」에 따른 공장재단, 광업재단"]]},{"종류":"표","제목":"등록 취소와 재등록 제한","머리":["구분","내용","근거"],"행":[["등록취소 권한자","지방법원장","규칙 제21조"],["필요적 취소 사유","폐업신고, 공인중개사 자격취소, 중개사무소 개설등록 취소, 등록 당시 요건·결격사유 흠결 등","규칙 제21조제1항"],["재등록 제한","등록이 취소된 후 3년이 지나지 않은 사람은 등록 불가","규칙 제6조제1호 본문"],["재등록 제한의 예외","폐업신고(제21조제1항제2호)로 취소된 경우는 3년 제한에서 제외","규칙 제6조제1호 단서"]]}],"함정":"ㄴ은 등록을 취소하는 주체를 시·도지사로 바꿔 놓았다. 중개사무소 개설등록은 등록관청이 취소하지만 매수신청대리인 등록은 지방법원장이 취소한다. ㄷ은 폐업신고로 인한 취소가 재등록 제한에서 빠진다는 단서를 놓치게 만든다."}};